/**
 * 実績（トロフィー）: キャリアモードとクラブ経営モード。
 * 判定は今の GameState だけで行う。解除した記録は画面側が端末に残す（stores/achievementStore.ts）。
 * 格: bronze（まずはここ）・silver（やりこみ）・gold（頂点）。
 */
import type { GameState } from './models/game'
import type { Player } from './models/player'
import { ovr } from './player/overall'
import { careerRank } from './career/rank'
