export type AchievementTier = 'bronze' | 'silver' | 'gold'

export interface AchievementDef {
  id: string
  mode: 'club' | 'career'
  name: string
  desc: string
  tier: AchievementTier
  check: (s: GameState) => boolean
}

// ---------------------------------------------------------------- キャリアモード

const hero = (s: GameState): Player => s.players[s.career!.playerId]
const leagueOf = (s: GameState) => {
  const p = hero(s)
  return p.teamId >= 0 ? s.teams[p.teamId].league : undefined
}
/** 通算（過去のシーズン＋今季）。league を渡すとそのリーグだけ */
const total = (s: GameState, key: 'gp' | 'pts', league?: string) => {
  const p = hero(s)
  const past = p.history.filter((h) => !league || h.league === league).reduce((n, h) => n + h.stats[key], 0)
  return past + (!league || leagueOf(s) === league ? p.stats[key] : 0)
}
const awards = (s: GameState, name: string) => s.awards.filter((a) => a.playerId === s.career!.playerId && a.award === name).length
const awardLike = (s: GameState, pred: (name: string) => boolean) => s.awards.some((a) => a.playerId === s.career!.playerId && pred(a.award))
const titleIn = (s: GameState, short: string) => s.career!.log.some((l) => l.notes.includes(`${short} 優勝`))
const homes = (s: GameState) => s.career!.ownedHomes ?? []

