// ---------------------------------------------------------------- クラブ経営モード

const club = (s: GameState) => s.club!
const cteam = (s: GameState) => s.teams[s.club!.teamId]
const wins = (s: GameState) => club(s).history.reduce((n, h) => n + h.w, 0) + (s.leagues[cteam(s).league].standings[cteam(s).id]?.w ?? 0)
const titles = (s: GameState, name: string) => club(s).history.filter((h) => h.note.includes(name) && !h.note.includes('準優勝')).length
const inSeries = (s: GameState, round: number) => s.series.some((x) => x.league === 'NBA' && x.round >= round && (x.hi === club(s).teamId || x.lo === club(s).teamId))

