export const ACHIEVEMENTS: AchievementDef[] = [...CAREER.map((a) => ({ ...a, mode: 'career' as const })), ...CLUB.map((a) => ({ ...a, mode: 'club' as const }))]
export const ACHIEVEMENT_BY_ID = Object.fromEntries(ACHIEVEMENTS.map((a) => [a.id, a])) as Record<string, AchievementDef>

/** 今の状態で条件を満たしていて、まだ解除していない実績 */
export function newAchievements(state: GameState, have: ReadonlySet<string>): AchievementDef[] {
  return ACHIEVEMENTS.filter((a) => a.mode === state.mode && !have.has(a.id) && (state.mode === 'career' ? !!state.career : !!state.club) && safe(a, state))
}

function safe(a: AchievementDef, s: GameState): boolean {
  try {
    return a.check(s)
  } catch {
    return false
  }
}
