/**
 * 画面の背景: 画面ごとの写真を暗くぼかして敷き、チームの色の光と縁の暗がりを重ねる。
 * 写真がまだなければ、アリーナの照明と床の木目で代わりにする。
 */
import { bgUrl } from '../components/portraits'
import type { ScreenId } from '../../stores/uiStore'
import { SCENE_OF } from './menu'

/** #rrggbb → rgba（チームの色の光） */
function glow(hex: string | undefined, alpha: number): string | undefined {
  if (!hex || !/^#[0-9a-f]{6}$/i.test(hex)) return undefined
  const n = parseInt(hex.slice(1), 16)
  return `rgba(${(n >> 16) & 255}, ${(n >> 8) & 255}, ${n & 255}, ${alpha})`
}

export function SceneBackground({ screen, scene, color }: { screen?: ScreenId; scene?: string; color?: string }) {
  const id = scene ?? (screen ? SCENE_OF[screen] : undefined)
  const url = id ? bgUrl(id) : undefined
  return (
    <div className="scene" aria-hidden style={{ ['--club-glow' as string]: glow(color, 0.3) }}>
      <div className="scene-fallback" />
      {url && <div className="scene-img" style={{ backgroundImage: `url(${url})` }} />}
      <div className="scene-glow" />
      <div className="scene-veil" />
    </div>
  )
}
