/** 確認のダイアログ（#overlay-root に描く）。決める操作は右、やめるは左。 */
import { createPortal } from 'react-dom'

export function ConfirmDialog({
  open,
  title,
  text,
  ok,
  cancel = 'やめる',
  onOk,
  onCancel,
}: {
  open: boolean
  title: string
  text?: string
  ok: string
  cancel?: string
  onOk: () => void
  onCancel: () => void
}) {
  const root = open ? document.getElementById('overlay-root') : null
  if (!root) return null
  return createPortal(
    <div className="anim-fade absolute inset-0 z-[60] flex items-center justify-center bg-black/55 p-4" onClick={onCancel}>
      <div className="panel w-[22rem] max-w-full p-4 text-center" onClick={(e) => e.stopPropagation()}>
        <div className="text-[0.95rem] font-black">{title}</div>
        {text && <p className="mt-1 text-[0.78rem] text-ink-dim">{text}</p>}
        <div className="mt-3 flex gap-2">
          <button className="btn btn-ghost flex-1" onClick={onCancel}>
            {cancel}
          </button>
          <button className="btn btn-gold flex-1" onClick={onOk}>
            {ok}
          </button>
        </div>
      </div>
    </div>,
    root,
  )
}
