/**
 * 新しく始めるときのセーブの保存先: スロットの一覧と選択（はじめは空いているスロット）と、上書きの確認。
 * 画面には SlotPicker（components）と、返す dialog を置く。go(fn) は、データのあるスロットなら確認してから fn を呼ぶ。
 */
import { useEffect, useState } from 'react'
import { SLOT_COUNT, listSlots, type SaveSlotMeta } from '../../persistence/db'
import { flushSave } from '../../stores/gameStore'
import { ConfirmDialog } from '../components/ConfirmDialog'

/** スロットの一覧と選択。go(fn) は、上書きになるなら確認してから fn を呼ぶ */
export function useSlotChoice() {
  const [slots, setSlots] = useState<SaveSlotMeta[] | null>(null)
  const [picked, setPicked] = useState<number | null>(null)
  const [ask, setAsk] = useState<(() => void) | null>(null)
  useEffect(() => {
    void flushSave()
      .then(() => listSlots())
      .then(setSlots)
      .catch(() => setSlots([]))
  }, [])
  const used = new Map((slots ?? []).map((s) => [s.id, s]))
  // 選んでいなければ、空いているいちばん小さいスロット（全部埋まっていれば、いちばん古いもの）
  const firstEmpty = Array.from({ length: SLOT_COUNT }, (_, i) => i + 1).find((n) => !used.has(n))
  const oldest = [...used.values()].sort((a, b) => a.updatedAt - b.updatedAt)[0]?.id ?? 1
  const slot = picked ?? firstEmpty ?? oldest
  const current = used.get(slot)
  const go = (fn: () => void) => (current ? setAsk(() => fn) : fn())
  const dialog = (
    <ConfirmDialog
      open={!!ask}
      title={`スロット ${slot} を上書きしますか？`}
      text={current ? `「${current.title}」（${current.mode === 'career' ? 'キャリア' : 'クラブ'}・${current.dateLabel}）のセーブが消えます。元には戻せません。` : ''}
      ok="上書きして始める"
      onOk={() => {
        const fn = ask
        setAsk(null)
        fn?.()
      }}
      onCancel={() => setAsk(null)}
    />
  )
  return { slots, slot, setSlot: setPicked, current, go, dialog }
}
