/**
 * 画面の中の状態を、画面のスタックの自分の場所に覚えておく（M24）。
 * 選手の詳細などへ行って「戻る」と、しぼり込み・並び・タブ・スクロールの位置が元のまま。
 * 左のナビから開き直したときも、その画面の前回の状態から（アプリを閉じるまで）。
 */
import { useCallback, useEffect, useState } from 'react'
import { rememberScreen, seedScreen, useUi, type Screen } from '../../stores/uiStore'

/** この画面のスタックの中の場所（開いたときのもの） */
function useOwnEntry(): Screen {
  const [entry] = useState(() => {
    const stack = useUi.getState().stack
    const e = stack[stack.length - 1]
    seedScreen(e)
    return e
  })
  useEffect(() => {
    markVisited(entry)
  }, [entry])
  return entry
}

function markVisited(entry: Screen) {
  entry.visited = true
}

/**
 * useState と同じ使い方。戻ってきたとき・開き直したときは前の値から始まる。
 * override: 画面を開いたときの指定（ホームの知らせから「売る」タブへ、など）。開いた最初の 1 回だけ、覚えた値より優先する
 */
export function useScreenState<T>(key: string, initial: T | (() => T), override?: T) {
  const entry = useOwnEntry()
  const [value, setValue] = useState<T>(() =>
    override !== undefined && !entry.visited ? override : entry.memo && key in entry.memo ? (entry.memo[key] as T) : typeof initial === 'function' ? (initial as () => T)() : initial,
  )
  useEffect(() => {
    rememberScreen(entry, key, value)
  }, [entry, key, value])
  return [value, setValue] as const
}

/** 一覧のスクロールの位置を覚えて戻す（スクロールする要素の ref に渡す） */
export function useScrollMemo(key: string) {
  const entry = useOwnEntry()
  return useCallback(
    (el: HTMLElement | null) => {
      if (!el) return
      const top = entry.memo?.[`scroll:${key}`]
      if (typeof top === 'number' && top > 0) requestAnimationFrame(() => (el.scrollTop = top))
      // 画面を離れるときに外された一覧は、位置 0 のスクロールが起きることがあるので数えない
      el.onscroll = () => {
        if (el.isConnected) rememberScreen(entry, `scroll:${key}`, el.scrollTop)
      }
      return () => {
        el.onscroll = null
      }
    },
    [entry, key],
  )
}
