/** 表示の書式（お金・能力の色など）。お金は内部はすべて万円。 */

/** 万円 → 「1.2億」「3,500万」（円は付けない） */
export function formatMoneyShort(man: number): string {
  const sign = man < 0 ? '-' : ''
  const a = Math.abs(man)
  if (a >= 10000) {
    const oku = a / 10000
    return `${sign}${oku >= 100 ? Math.round(oku).toLocaleString('ja-JP') : oku.toFixed(oku >= 10 ? 1 : 2).replace(/\.?0+$/, '')}億`
  }
  return `${sign}${Math.round(a).toLocaleString('ja-JP')}万`
}

/** 1 ドル = 150 円（NBA の年俸の表示用。内部は万円） */
export const YEN_PER_DOLLAR = 150

/** 万円 → 「$45.0M」「$850K」 */
export function formatDollars(man: number): string {
  const usd = (man * 10000) / YEN_PER_DOLLAR
  if (Math.abs(usd) >= 1e6) return `$${(usd / 1e6).toFixed(1)}M`
  return `$${Math.round(usd / 1000)}K`
}

/** 能力値（1-99）の色。ランク S〜G にそろえる（90/80/70/60/50/40/30） */
export function attrColor(v: number): string {
  if (v >= 90) return '#ffd34d'
  if (v >= 80) return '#ff9d4d'
  if (v >= 70) return '#3ddc84'
  if (v >= 60) return '#7dd3fc'
  if (v >= 50) return '#e8eef6'
  if (v >= 40) return '#a8b4c4'
  return '#7a8698'
}
