/** 実績の一覧（タイトル・設定から）。解除した記録は端末に残る（どのセーブで解除しても）。 */
import { useState } from 'react'
import { ACHIEVEMENTS, type AchievementTier } from '../../engine/achievements'
import { useAchievements } from '../../stores/achievementStore'
import { useUi } from '../../stores/uiStore'
import { Icon } from '../components/Icon'
import { Medal } from '../achievements/AchievementWatcher'
import { TIER_COLOR, TIER_NAME } from '../achievements/tier'

const TIERS: AchievementTier[] = ['gold', 'silver', 'bronze']

export function AchievementsScreen() {
  const pop = useUi((s) => s.pop)
  const unlocked = useAchievements((s) => s.unlocked)
  const [mode, setMode] = useState<'club' | 'career'>('career')
  const list = ACHIEVEMENTS.filter((a) => a.mode === mode)
  const got = list.filter((a) => unlocked[a.id])
  return (
    <div className="absolute inset-0 flex flex-col">
      <header className="topbar safe-px flex shrink-0 items-center gap-3" style={{ boxSizing: 'content-box' }}>
        <button className="flex h-10 w-10 items-center justify-center rounded-lg text-ink-dim hover:bg-black/5" onClick={pop} aria-label="戻る">
          <Icon name="back" className="h-5 w-5" />
        </button>
        <h1 className="text-[1.05rem] font-extrabold">実績</h1>
        <span className="num text-[0.8rem] text-ink-dim">
          {Object.keys(unlocked).filter((id) => ACHIEVEMENTS.some((a) => a.id === id)).length} / {ACHIEVEMENTS.length}
        </span>
        <div className="seg ml-auto">
          <button aria-selected={mode === 'career'} onClick={() => setMode('career')}>
            キャリア
          </button>
          <button aria-selected={mode === 'club'} onClick={() => setMode('club')}>
            クラブ
          </button>
        </div>
      </header>
      <div className="safe-px safe-pb flex min-h-0 flex-1 flex-col gap-2 p-3">
        <div className="flex shrink-0 items-center gap-3 text-[0.74rem] text-ink-dim">
          <span>
            {mode === 'career' ? 'キャリアモード' : 'クラブモード'} <b className="num text-ink">{got.length}</b> / {list.length}
          </span>
          {TIERS.map((t) => (
            <span key={t} className="flex items-center gap-1">
              <Medal color={TIER_COLOR[t]} className="h-4 w-4" />
              {TIER_NAME[t]} {got.filter((a) => a.tier === t).length}/{list.filter((a) => a.tier === t).length}
            </span>
          ))}
        </div>
        <div className="scroll-y grid min-h-0 flex-1 grid-cols-2 content-start gap-1.5 pr-1">
          {[...list]
            .sort((a, b) => Number(!!unlocked[b.id]) - Number(!!unlocked[a.id]) || TIERS.indexOf(b.tier) - TIERS.indexOf(a.tier))
            .map((a) => {
              const u = unlocked[a.id]
              return (
                <div key={a.id} className={`flex items-center gap-2.5 rounded-lg px-2.5 py-1.5 ${u ? 'bg-black/[0.04]' : 'bg-black/[0.05]'}`} style={u ? { boxShadow: `inset 3px 0 0 ${TIER_COLOR[a.tier]}` } : undefined}>
                  <Medal color={TIER_COLOR[a.tier]} dim={!u} className="h-8 w-8 shrink-0" />
                  <div className="min-w-0 flex-1">
                    <div className={`text-[0.82rem] font-black ${u ? '' : 'text-ink-dim'}`}>{a.name}</div>
                    <div className="text-[0.72rem] text-ink-dim">{a.desc}</div>
                  </div>
                  <span className="num shrink-0 text-[0.68rem] text-ink-mute">{u ? u.at : TIER_NAME[a.tier]}</span>
                </div>
              )
            })}
        </div>
      </div>
    </div>
  )
}
