/** 能力のレーダーチャート。現在値と、見えているなら上限を重ねて描く。 */

function points(values: number[], max: number, cx: number, cy: number, r: number): string {
  const n = values.length
  return values
    .map((v, i) => {
      const a = (Math.PI * 2 * i) / n - Math.PI / 2
      const len = (Math.max(0, v) / max) * r
      return `${(cx + Math.cos(a) * len).toFixed(1)},${(cy + Math.sin(a) * len).toFixed(1)}`
    })
    .join(' ')
}

export function RadarChart({
  labels,
  values,
  potential,
  max = 99,
  color = '#f5c542',
  className,
}: {
  labels: string[]
  values: number[]
  potential?: number[]
  max?: number
  color?: string
  className?: string
}) {
  const size = 200
  const cx = size / 2
  const cy = size / 2 + 2
  const r = size * 0.34
  const n = labels.length
  return (
    <svg viewBox={`0 0 ${size} ${size}`} className={className} aria-hidden>
      {[0.25, 0.5, 0.75, 1].map((s) => (
        <polygon key={s} points={points(Array(n).fill(max * s), max, cx, cy, r)} fill={s === 1 ? 'rgba(40,60,90,0.03)' : 'none'} stroke="rgba(40,60,90,0.16)" strokeWidth="1" />
      ))}
      {labels.map((_, i) => {
        const a = (Math.PI * 2 * i) / n - Math.PI / 2
        return <line key={i} x1={cx} y1={cy} x2={cx + Math.cos(a) * r} y2={cy + Math.sin(a) * r} stroke="rgba(40,60,90,0.12)" />
      })}
      {potential && <polygon points={points(potential, max, cx, cy, r)} fill="#3aa0ff" opacity="0.14" stroke="#3aa0ff" strokeWidth="1.2" strokeDasharray="3 2" />}
      <polygon points={points(values, max, cx, cy, r)} fill={color} fillOpacity="0.32" stroke={color} strokeWidth="2" strokeLinejoin="round" />
      {labels.map((label, i) => {
        const a = (Math.PI * 2 * i) / n - Math.PI / 2
        const lx = cx + Math.cos(a) * (r + 20)
        const ly = cy + Math.sin(a) * (r + 15)
        return (
          <g key={label}>
            <text x={lx} y={ly - 5} textAnchor="middle" dominantBaseline="middle" fontSize="11" fill="#5b6778" fontWeight="700">
              {label}
            </text>
            <text x={lx} y={ly + 8} textAnchor="middle" dominantBaseline="middle" fontSize="12" fill="#1b2536" fontWeight="800">
              {Math.round(values[i])}
            </text>
          </g>
        )
      })}
    </svg>
  )
}
