/** 年俸の表示（NBA と育成リーグはドル、それ以外は円）。内部は万円。 */
import type { LeagueId } from '../engine'
import { formatDollars, formatMoneyShort } from './format'

export function salaryLabel(man: number, league?: LeagueId): string {
  if (league === 'NCAA') return '-'
  if (league === 'NBA' || league === 'DEV') return formatDollars(man)
  return `${formatMoneyShort(man)}円`
}

/** NBA の年俸を「$45.0M（67.5 億円）」で */
export function salaryBoth(man: number): string {
  return `${formatDollars(man)}（${formatMoneyShort(man)}円）`
}
