/**
 * チームの総合力の見える化（チームの画面の「戦力」タブ。2026-11-14）: 戦力とリーグの順位・リーグのチームの棒グラフ・
 * 先発と控え・分野 6 つ（リーグの平均の印と順位）・ポジションごとの上位 2 人。中身は engine/team/strength.ts
 */
import type { Team } from '../../engine'
import { leaguePowers, teamStrength } from '../../engine/team/strength'
import { useGameState } from '../../stores/gameStore'
import { useUi } from '../../stores/uiStore'
import { OvrBadge, PosBadge } from './common'
import { Term } from './Term'

/** 順位の色（上位 4 分の 1 は金、半分まで緑、下位 4 分の 1 は赤） */
function rankTone(rank: number, n: number): string {
  return rank <= Math.ceil(n / 4) ? 'text-gold' : rank <= Math.ceil(n / 2) ? 'text-good' : rank > n - Math.ceil(n / 4) ? 'text-bad' : 'text-ink-dim'
}

/** 強み・弱みの一言 */
function verdict(rank: number, n: number): string {
  return rank <= Math.ceil(n / 4) ? '強み' : rank > n - Math.ceil(n / 4) ? '弱み' : ''
}

export function TeamStrengthView({ team }: { team: Team }) {
  const state = useGameState()
  const push = useUi((s) => s.push)
  const s = teamStrength(state, team)
  const all = leaguePowers(state, team.league)
  const lo = Math.floor(Math.min(...all.map((x) => x.power)) - 3)
  const hi = Math.ceil(Math.max(...all.map((x) => x.power)) + 1)
  const w = (v: number) => `${Math.max(3, ((v - lo) / (hi - lo)) * 100)}%`
  // 分野の棒は 30〜90 の幅で
  const aw = (v: number) => `${Math.max(2, Math.min(100, ((v - 30) / 60) * 100))}%`
  const strong = s.areas.filter((a) => verdict(a.rank, s.n) === '強み').map((a) => a.label)
  const weak = s.areas.filter((a) => verdict(a.rank, s.n) === '弱み').map((a) => a.label)
  return (
    <div className="flex gap-3 p-2">
      {/* 左: 戦力とリーグの中の位置 */}
      <div className="w-[15rem] shrink-0">
        <div className="text-[0.66rem] text-ink-dim">
          <Term id="teamPower">戦力</Term>（上位 8 人の総合値の平均）
        </div>
        <div className="flex items-end gap-2">
          <div className="num text-[2rem] font-black leading-none">{s.power.toFixed(1)}</div>
          <div className="whitespace-nowrap pb-0.5 text-[0.8rem]">
            リーグ <b className={`num text-[1.1rem] ${rankTone(s.rank, s.n)}`}>{s.rank}</b> 位<span className="text-ink-dim"> / {s.n}</span>
          </div>
        </div>
        <div className="num mt-1 grid grid-cols-2 gap-1 text-[0.72rem]">
          <div className="stat-chip px-2 py-1">
            先発 5 人 <b>{s.starters.toFixed(1)}</b>
          </div>
          <div className="stat-chip px-2 py-1">
            控え <b>{s.bench.toFixed(1)}</b> <span className={rankTone(s.benchRank, s.n)}>（{s.benchRank} 位）</span>
          </div>
        </div>
        <div className="mt-1 text-[0.68rem] leading-snug text-ink-dim">
          リーグの平均 {s.leagueAvg.toFixed(1)}（いちばん上 {s.leagueMax.toFixed(1)}・下 {s.leagueMin.toFixed(1)}）
          {strong.length > 0 && (
            <>
              <br />
              強み: <b className="text-good">{strong.join('・')}</b>
            </>
          )}
          {weak.length > 0 && (
            <>
              <br />
              弱み: <b className="text-bad">{weak.join('・')}</b>
            </>
          )}
        </div>
        <div className="mt-2 text-[0.66rem] font-black text-ink-dim">リーグの戦力の順</div>
        <div className="mt-0.5 space-y-[0.12rem]">
          {all.map((x, i) => {
            const t = state.teams[x.teamId]
            const me = t.id === team.id
            return (
              <button key={t.id} className={`flex w-full items-center gap-1 rounded px-0.5 text-left ${me ? 'bg-gold/15' : 'hover:bg-black/[0.04]'}`} onClick={() => !me && push({ id: 'team', params: { teamId: t.id, tab: 'strength' } })}>
                <span className="num w-4 text-right text-[0.58rem] text-ink-mute">{i + 1}</span>
                <span className={`w-[4.2rem] truncate text-[0.6rem] ${me ? 'font-black' : 'text-ink-dim'}`}>{t.short}</span>
                <span className="relative h-[0.5rem] flex-1 rounded-full bg-black/[0.06]">
                  <span className="absolute inset-y-0 left-0 rounded-full" style={{ width: w(x.power), background: me ? t.colors.primary : '#9aa6b6' }} />
                </span>
                <span className={`num w-7 text-right text-[0.6rem] ${me ? 'font-black' : 'text-ink-dim'}`}>{x.power.toFixed(1)}</span>
              </button>
            )
          })}
        </div>
      </div>
      {/* 右: 分野とポジション */}
      <div className="min-w-0 flex-1">
        <div className="text-[0.74rem] font-black">
          分野ごとの力 <span className="font-normal text-ink-dim">（上位 8 人の能力の平均。｜はリーグの平均）</span>
        </div>
        <div className="mt-1 space-y-1.5">
          {s.areas.map((a) => (
            <div key={a.id}>
              <div className="flex items-baseline gap-1.5 text-[0.74rem]">
                <span className="w-[5.6rem] shrink-0 font-bold">{a.label}</span>
                <span className="relative h-[0.6rem] flex-1 rounded-full bg-black/[0.07]">
                  <span className="absolute inset-y-0 left-0 rounded-full" style={{ width: aw(a.value), background: a.value >= a.avg ? '#22b06a' : '#e0a21b' }} />
                  <span className="absolute top-[-0.2rem] h-[1rem] w-[2px] bg-ink/70" style={{ left: aw(a.avg) }} title={`リーグの平均 ${a.avg.toFixed(1)}`} />
                </span>
                <span className="num w-7 text-right font-black">{Math.round(a.value)}</span>
                <span className={`num w-[3.2rem] text-right text-[0.68rem] font-black ${rankTone(a.rank, s.n)}`}>
                  {a.rank} 位{verdict(a.rank, s.n) && <span className="ml-0.5">{verdict(a.rank, s.n) === '強み' ? '◎' : '▼'}</span>}
                </span>
              </div>
              <div className="pl-[6rem] text-[0.58rem] text-ink-mute">{a.note}</div>
            </div>
          ))}
        </div>
        <div className="mt-2 text-[0.74rem] font-black">
          ポジションごと <span className="font-normal text-ink-dim">（そのポジションの上位 2 人。薄い札は 2 つ目のポジション）</span>
        </div>
        <div className="mt-1 grid grid-cols-5 gap-1">
          {s.positions.map((x) => (
            <div key={x.pos} className="stat-chip flex flex-col items-center gap-0.5 px-1 py-1">
              <PosBadge pos={x.pos} />
              {x.players.length === 0 && <span className="text-[0.62rem] font-bold text-bad">いない</span>}
              {x.players.map((q) => (
                <button key={q.id} className="flex w-full items-center gap-1" onClick={() => push({ id: 'player', params: { playerId: q.id } })}>
                  <span className={q.sub ? 'opacity-60' : ''}>
                    <OvrBadge value={q.ovr} size="sm" />
                  </span>
                  <span className="min-w-0 flex-1 truncate text-left text-[0.6rem]">{q.short}</span>
                </button>
              ))}
            </div>
          ))}
        </div>
      </div>
    </div>
  )
}

/** ホームの小さな札: 戦力・リーグの順位・リーグの中の位置の棒（押すとチームの「戦力」タブ） */
export function TeamStrengthChip({ team }: { team: Team }) {
  const state = useGameState()
  const push = useUi((s) => s.push)
  const all = leaguePowers(state, team.league)
  const i = all.findIndex((x) => x.teamId === team.id)
  const me = all[i]
  const lo = all[all.length - 1].power
  const hi = all[0].power
  const pos = hi > lo ? ((me.power - lo) / (hi - lo)) * 100 : 50
  return (
    <button className="stat-chip block w-full px-2 py-1 text-left" onClick={() => push({ id: 'team', params: { teamId: team.id, tab: 'strength' } })}>
      <span className="flex items-center justify-between text-[0.75rem]">
        <span>
          <Term id="teamPower">戦力</Term> <b className="num">{me.power.toFixed(1)}</b>
        </span>
        <span className="num">
          リーグ <b className={rankTone(i + 1, all.length)}>{i + 1}</b> 位 / {all.length}
        </span>
      </span>
      <span className="relative mt-1 block h-[0.45rem] rounded-full bg-gradient-to-r from-bad/30 via-black/10 to-good/40">
        <span className="absolute top-1/2 h-[0.75rem] w-[0.75rem] -translate-x-1/2 -translate-y-1/2 rounded-full border-2 border-white shadow" style={{ left: `${pos}%`, background: team.colors.primary }} />
      </span>
      <span className="mt-0.5 flex justify-between text-[0.56rem] text-ink-mute">
        <span>リーグの最下位 {lo.toFixed(1)}</span>
        <span>1 位 {hi.toFixed(1)}</span>
      </span>
    </button>
  )
}

