import { useEffect } from 'react'
import { sound, type Scene } from './sound'

/** 画面や重ね物が出ているあいだの BGM。消えたら、その前の場面の曲に戻す */
export function useMusic(scene: Scene, active = true) {
  useEffect(() => {
    if (!active) return
    const prev = sound.current
    sound.setScene(scene)
    return () => {
      if (sound.current === scene) sound.setScene(prev === scene || prev === 'none' ? 'menu' : prev)
    }
  }, [scene, active])
}
