/**
 * NBA ドラフトの指名リスト（クラブ経営・NBA に入ったあと）。
 *   候補が決まる第 40 週からドラフトの第 51 週まで、指名したい選手を順に並べておく。
 *   指名の番が来たら、リストの上から残っている選手を指名する（competition/draft.ts の runDraft。いなければ AI と同じ選び方）。
 *   2 巡目は登録に空きがあれば本契約、いっぱいなら（提携先があれば）2way。
 */
import { NBA_DRAFT_WEEK, absWeekOf, ageAt } from '../core/calendar'
import { draftValue } from '../competition/draft'
import { sortedStandings } from '../competition/standings'
import type { GameState } from '../models/game'
import type { Player } from '../models/player'

/** リストに入れられる人数 */
export const BOARD_MAX = 12

/** 指名リストを作れる（NBA のクラブで、候補が決まってからドラフトまで） */
export function boardOpen(state: GameState): boolean {
  const c = state.club
  return !!c && state.teams[c.teamId].league === 'NBA' && state.draftPool.length > 0 && state.week <= NBA_DRAFT_WEEK
}

/** 候補（世間の評価の順。予想の順位つき） */
export function draftProspects(state: GameState): { p: Player; mock: number }[] {
  const abs = absWeekOf(state.season, state.week)
  return state.draftPool
    .map((id) => state.players[id])
    .filter((p) => p && !p.isPlayer)
    .map((p) => ({ p, v: draftValue(p, ageAt(abs, p.birthAbs), p.teamId >= 0 && state.teams[p.teamId].league === 'NCAA') }))
    .sort((a, b) => b.v - a.v)
    .map(({ p }, i) => ({ p, mock: i + 1 }))
}

export function toggleBoard(state: GameState, id: number): string | null {
  const c = state.club!
  const b = (c.draftBoard ??= [])
  const i = b.indexOf(id)
  if (i >= 0) {
    b.splice(i, 1)
    return null
  }
  if (b.length >= BOARD_MAX) return `リストは ${BOARD_MAX} 人まで`
  b.push(id)
  return null
}

export function moveBoard(state: GameState, id: number, dir: -1 | 1) {
  const b = state.club!.draftBoard ?? []
  const i = b.indexOf(id)
  const j = i + dir
  if (i < 0 || j < 0 || j >= b.length) return
  ;[b[i], b[j]] = [b[j], b[i]]
}

/** 1 巡目の指名の見込み（成績の悪い順。ロッタリーの前の目安） */
export function projectedPick(state: GameState): number {
  const c = state.club!
  return sortedStandings(state.leagues.NBA).reverse().indexOf(c.teamId) + 1
}
