/**
 * ゲームの画面と重ね物。タイトル画面と分けて、あとから読み込む（React.lazy）。
 * ゲームの処理（engine・gameStore）はここから読むので、タイトルが出るまでに読み込むコードが小さくなる。
 */
import { useEffect } from 'react'
import { useGame } from './stores/gameStore'
import { createWorld } from './engine'
import { useCurrentScreen, useUi } from './stores/uiStore'
import { TitleScreen } from './ui/screens/TitleScreen'
import { GalleryScreen } from './ui/screens/GalleryScreen'
import { SettingsScreen } from './ui/screens/SettingsScreen'
import { LoadScreen } from './ui/screens/LoadScreen'
import { PlaceholderScreen } from './ui/screens/PlaceholderScreen'
import { ErrorDialog } from './ui/ErrorDialog'
import { GlossaryScreen } from './ui/screens/GlossaryScreen'
import { LeagueScreen } from './ui/screens/LeagueScreen'
import { TeamScreen } from './ui/screens/TeamScreen'
import { PlayerScreen } from './ui/screens/PlayerScreen'
import { MatchLabScreen } from './ui/screens/MatchLabScreen'
import { WorldHomeScreen } from './ui/screens/WorldHomeScreen'
import { AutoProgress } from './ui/home/AutoProgress'
import { CareerNewScreen } from './ui/screens/CareerNewScreen'
import { CareerHomeScreen } from './ui/screens/CareerHomeScreen'
import { GrowthScreen } from './ui/screens/GrowthScreen'
import { PeopleScreen } from './ui/screens/PeopleScreen'
import { CareerScreen } from './ui/screens/CareerScreen'
import { AllStarScreen } from './ui/screens/AllStarScreen'
import { LifeScreen } from './ui/screens/LifeScreen'
import { CareerEndScreen } from './ui/screens/CareerEndScreen'
import { AchievementsScreen } from './ui/screens/AchievementsScreen'
import { ClubNewScreen } from './ui/screens/ClubNewScreen'
import { ClubHomeScreen } from './ui/screens/ClubHomeScreen'
import { ClubScreen } from './ui/screens/ClubScreen'
import { TacticsScreen } from './ui/screens/TacticsScreen'
import { TrainingScreen } from './ui/screens/TrainingScreen'
import { TransferScreen } from './ui/screens/TransferScreen'
import { AchievementWatcher } from './ui/achievements/AchievementWatcher'

/** ゲームが始まっていなくても開ける画面 */
const NO_GAME = new Set(['title', 'careerNew', 'clubNew', 'load', 'gallery', 'glossary', 'achievements', 'settings'])

/** ワールドを見る（タイトルから。キャリアモードができるまでの確認用）: 保存しないワールドを作ってリーグの画面へ */
function NewWorld() {
  useEffect(() => {
    useGame.getState().start(createWorld({ seed: Date.now() % 1_000_000_007, mode: 'career' }), 0, false)
    useUi.getState().reset({ id: 'home' })
  }, [])
  return <div className="absolute inset-0 flex items-center justify-center text-[0.9rem] text-ink-dim">ワールドを作っています…</div>
}

/** キャリア: 所属チームの画面（所属・日程のナビ） */
function OwnTeam({ tab }: { tab: 'roster' | 'schedule' }) {
  const state = useGame((s) => s.state)
  const id = state?.club ? state.club.teamId : state?.career ? state.players[state.career.playerId].teamId : -1
  useEffect(() => {
    if (id >= 0) useUi.getState().reset({ id: 'team', params: { teamId: id, tab } })
  }, [id, tab])
  if (id < 0) return <PlaceholderScreen id={tab} />
  return null
}

function Screens() {
  const screen = useCurrentScreen()
  const hasGame = useGame((s) => !!s.state)
  const career = useGame((s) => !!s.state?.career)
  const club = useGame((s) => !!s.state?.club)
  const own = career || club
  if (screen.params?.newWorld && !hasGame) return <NewWorld />
  if (!NO_GAME.has(screen.id) && !hasGame) return <TitleScreen />
  switch (screen.id) {
    case 'title':
      return <TitleScreen />
    case 'load':
      return <LoadScreen />
    case 'gallery':
      return <GalleryScreen />
    case 'settings':
      return <SettingsScreen />
    case 'glossary':
      return <GlossaryScreen />
    case 'achievements':
      return <AchievementsScreen />
    case 'league':
      return <LeagueScreen />
    case 'team':
      return <TeamScreen />
    case 'player':
      return <PlayerScreen />
    case 'matchLab':
      return <MatchLabScreen />
    case 'home':
      return club ? <ClubHomeScreen /> : career ? <CareerHomeScreen /> : <WorldHomeScreen />
    case 'careerNew':
      return <CareerNewScreen />
    case 'clubNew':
      return <ClubNewScreen />
    case 'club':
      return club ? <ClubScreen /> : <PlaceholderScreen id="club" />
    case 'tactics':
      return club ? <TacticsScreen /> : <PlaceholderScreen id="tactics" />
    case 'training':
      return club ? <TrainingScreen /> : <PlaceholderScreen id="training" />
    case 'transfer':
      return club ? <TransferScreen /> : <PlaceholderScreen id="transfer" />
    case 'growth':
      return career ? <GrowthScreen /> : <PlaceholderScreen id="growth" />
    case 'people':
      return career ? <PeopleScreen /> : <PlaceholderScreen id="people" />
    case 'career':
      return career ? <CareerScreen /> : <PlaceholderScreen id="career" />
    case 'life':
      return career ? <LifeScreen /> : <PlaceholderScreen id="life" />
    case 'careerEnd':
      return career ? <CareerEndScreen /> : <TitleScreen />
    case 'allStar':
      return career ? <AllStarScreen /> : <PlaceholderScreen id="home" />
    case 'roster':
      return own ? <OwnTeam tab="roster" /> : <PlaceholderScreen id="roster" />
    case 'schedule':
      return own ? <OwnTeam tab="schedule" /> : <LeagueScreen />
    default:
      return <PlaceholderScreen id={screen.id} />
  }
}

/** タイトル以外の画面（タイトルは App が直接出す）と、どの画面でも出す重ね物 */
export default function GameLayer() {
  const screen = useCurrentScreen()
  return (
    <>
      {screen.id !== 'title' && <Screens key={screen.uid ?? screen.id} />}
      <ErrorDialog />
      <AutoProgress />
      <AchievementWatcher />
    </>
  )
}
