/**
 * 人物の画像（public/chars/）。画像がなければ fallback を出す（写真ができるまではイニシャルのアイコンなど）。
 * URL の解決は portraits.ts。
 */
import { useState, type ReactNode } from 'react'
import { portraitUrl, type PortraitKind } from './portraits'

export function Portrait({
  id,
  kind = 'face',
  alt,
  className = '',
  fallback,
  position,
}: {
  id: string
  kind?: PortraitKind
  alt?: string
  className?: string
  fallback?: ReactNode
  /** object-position（上半身の顔を上に寄せるなど） */
  position?: string
}) {
  const url = portraitUrl(id, kind)
  const [failed, setFailed] = useState(false)
  if (!url || failed) return <div className={`portrait-frame ${className}`}>{fallback}</div>
  return (
    <div className={`portrait-frame ${className}`}>
      <img
        src={url}
        alt={alt ?? ''}
        draggable={false}
        loading="lazy"
        decoding="async"
        style={position ? { objectPosition: position } : undefined}
        onError={() => setFailed(true)}
      />
    </div>
  )
}

/** 写真がない人の代わり: 名前の頭文字の丸いアイコン（色は名前から決める） */
export function Initials({ name, className = '', color }: { name: string; className?: string; color?: string }) {
  let h = 0
  for (const ch of name) h = (h * 31 + ch.charCodeAt(0)) >>> 0
  const bg = color ?? `hsl(${h % 360} 45% 38%)`
  const text = name.replace(/[・\s]/g, '').slice(0, 1)
  return (
    <div className={`flex items-center justify-center font-black text-white ${className}`} style={{ background: `linear-gradient(160deg, ${bg}, #0a0f1e)`, containerType: 'size' }}>
      <span style={{ fontSize: '46cqmin' }} className="drop-shadow">
        {text}
      </span>
    </div>
  )
}
