/**
 * 練習試合（Match Lab）: 好きな 2 チームを選んで、観戦か結果だけ。試合エンジンの確認にも使う。
 * params: home・away（チームの id）・watch=1 ですぐ観戦
 */
import { useMemo, useState } from 'react'
import { teamPower, type LeagueId } from '../../engine'
import { exhibitionSetup } from '../../engine/match/setup'
import { MatchEngine } from '../../engine/match/engine'
import type { MatchSetup } from '../../engine/match/types'
import { useGameState } from '../../stores/gameStore'
import { useCurrentScreen, useUi } from '../../stores/uiStore'
import { AppShell } from '../layout/AppShell'
import { TeamDot } from '../components/common'
import { BoxScore, MatchView } from '../match/MatchView'
import { useScreenState } from '../hooks/useScreenState'
import { Icon } from '../components/Icon'

const LEAGUES: [LeagueId, string][] = [
  ['NBA', 'NBA'],
  ['JBL1', 'JBL1'],
  ['JBL2', 'JBL2'],
  ['JBL3', 'JBL3'],
  ['NCAA', '大学'],
  ['DEV', '育成'],
]

function TeamPicker({ label, value, onPick }: { label: string; value: number; onPick: (id: number) => void }) {
  const state = useGameState()
  const [lg, setLg] = useState<LeagueId>(state.teams[value]?.league ?? 'NBA')
  const ids = state.leagues[lg].teamIds
  return (
    <div className="panel flex min-h-0 min-w-0 flex-1 flex-col p-2">
      <div className="mb-1 flex items-center gap-2">
        <div className="panel-head">{label}</div>
        <div className="seg scroll-x ml-auto">
          {LEAGUES.map(([id, name]) => (
            <button key={id} aria-selected={lg === id} onClick={() => setLg(id)} className="!min-h-[2.2rem] !px-2 !text-[0.78rem]">
              {name}
            </button>
          ))}
        </div>
      </div>
      <div className="scroll-y min-h-0 flex-1">
        {ids.map((id) => {
          const t = state.teams[id]
          return (
            <button key={id} className={`cv-row flex w-full items-center gap-2 rounded-lg px-2 py-1.5 text-left ${value === id ? 'bg-orange/25' : 'hover:bg-black/5'}`} onClick={() => onPick(id)}>
              <TeamDot colors={t.colors} abbr={t.abbr} className="h-6 w-6 text-[0.5rem]" />
              <span className="min-w-0 flex-1 truncate text-[0.85rem] font-bold">{t.name}</span>
              <span className="num text-[0.75rem] text-ink-dim">{teamPower(state, t).toFixed(1)}</span>
            </button>
          )
        })}
      </div>
    </div>
  )
}

export function MatchLabScreen() {
  const state = useGameState()
  const screen = useCurrentScreen()
  const pop = useUi((s) => s.pop)
  const [home, setHome] = useScreenState<number>('home', Number(screen.params?.home ?? state.leagues.NBA.teamIds[0]))
  const [away, setAway] = useScreenState<number>('away', Number(screen.params?.away ?? state.leagues.NBA.teamIds[1]))
  const [seed, setSeed] = useState(1)
  const [mode, setMode] = useState<'pick' | 'watch' | 'result'>(screen.params?.watch ? 'watch' : 'pick')
  const [result, setResult] = useState<MatchEngine | null>(null)
  const setup = useMemo<MatchSetup>(() => exhibitionSetup(state, home, away, 7000 + seed), [state, home, away, seed])

  if (mode === 'watch')
    return (
      <MatchView
        key={`${home}:${away}:${seed}`}
        setup={setup}
        onFinish={(_s, engine) => {
          setResult(engine)
          setMode('result')
        }}
      />
    )

  if (mode === 'result' && result) {
    const [h, a] = result.teams
    return (
      <AppShell title="試合結果" current="matchLab" back>
        <div className="absolute inset-0 flex flex-col gap-2 p-2">
          <div className="vs-band flex shrink-0 items-center justify-center gap-6 py-3">
            <span className="text-[1rem] font-black">{h.name}</span>
            <span className="num text-[2rem] font-black">
              {h.score} - {a.score}
            </span>
            <span className="text-[1rem] font-black">{a.name}</span>
            {result.ot > 0 && <span className="text-[0.8rem] font-bold text-gold">延長 {result.ot}</span>}
          </div>
          <div className="panel scroll-y min-h-0 flex-1">
            <BoxScore engine={result} />
          </div>
          <div className="flex shrink-0 justify-end gap-2">
            <button className="btn btn-ghost" onClick={() => setMode('pick')}>
              チームを選び直す
            </button>
            <button
              className="btn btn-gold"
              onClick={() => {
                setSeed((s) => s + 1)
                setMode('watch')
              }}
            >
              もう一試合 観戦
            </button>
          </div>
        </div>
      </AppShell>
    )
  }

  return (
    <AppShell title="練習試合" current="matchLab" back>
      <div className="absolute inset-0 flex flex-col gap-2 p-2">
        <div className="flex min-h-0 flex-1 gap-2">
          <TeamPicker label="ホーム" value={home} onPick={setHome} />
          <TeamPicker label="アウェイ" value={away} onPick={setAway} />
        </div>
        <div className="flex shrink-0 items-center justify-end gap-2">
          <span className="mr-auto text-[0.75rem] text-ink-dim">ルールはホームのリーグのもの（NBA 48 分・国内 40 分・大学は前後半）。右の数字は戦力。</span>
          <button className="btn btn-ghost" onClick={pop}>
            戻る
          </button>
          <button
            className="btn btn-ghost"
            disabled={home === away}
            onClick={() => {
              const e = new MatchEngine(exhibitionSetup(state, home, away, 7000 + seed))
              e.simulate()
              setResult(e)
              setSeed((s) => s + 1)
              setMode('result')
            }}
          >
            結果だけ
          </button>
          <button className="btn btn-gold" disabled={home === away} onClick={() => setMode('watch')}>
            <Icon name="play" className="h-5 w-5" />
            観戦する
          </button>
        </div>
      </div>
    </AppShell>
  )
}
