/**
 * 主人公の顔の写真を選び直す（ホームの写真を押すと開く）。
 * 前の版の不具合で写真が外れたセーブも、ここで選び直せる。
 */
import { createPortal } from 'react-dom'
import { useGame, useGameState } from '../../stores/gameStore'
import { useOverlayRoot } from '../stage/overlayRoot'
import { genIds } from '../components/portraits'
import { Portrait } from '../components/Portrait'

export function FacePicker({ onClose }: { onClose: () => void }) {
  const state = useGameState()
  const mutate = useGame((s) => s.mutate)
  const root = useOverlayRoot()
  const c = state.career
  if (!root || !c) return null
  const p = state.players[c.playerId]
  const faces = genIds('protag')
  return createPortal(
    <div className="anim-fade absolute inset-0 z-50 flex items-center justify-center bg-black/55 p-4" onClick={onClose}>
      <div className="panel panel-solid w-[34rem] max-w-full p-3" onClick={(e) => e.stopPropagation()}>
        <div className="mb-2 text-[0.95rem] font-black">顔の写真を選ぶ</div>
        <div className="grid grid-cols-6 gap-2">
          {faces.map((id) => (
            <button
              key={id}
              onClick={() => {
                mutate((st) => void (st.players[st.career!.playerId].photo = id))
                onClose()
              }}
              className={`overflow-hidden rounded-xl border-2 ${p.photo === id ? 'border-gold' : 'border-transparent'}`}
            >
              <Portrait id={id} kind="face" className="aspect-square w-full" />
            </button>
          ))}
        </div>
        <div className="mt-2 text-right">
          <button className="btn btn-ghost btn-sm" onClick={onClose}>
            閉じる
          </button>
        </div>
      </div>
    </div>,
    root,
  )
}
