              <ListHead right="希望の年俸" rank />
              {fa.length === 0 && <EmptyNote willing={willing} />}
              {fa.map((p) => (
                <PlayerRow key={p.id} p={p} rank={rankIfJoined(state, p)} label={c.rookies.includes(p.id) ? '新人' : undefined} right={askOf(state, p, 'fa').refuse ? <span className="text-ink-mute">興味なし</span> : quotaProblem(state, p) ? <span className="text-ink-mute">{quotaProblem(state, p)}</span> : <>希望 {yen(askOf(state, p, 'fa').salary)}</>} onTalk={() => setTalk({ id: p.id, kind: 'fa' })} />
              ))}
