/**
 * クラブ経営の会話の画面（state.club.scenes を順に出す）。見た目はキャリアの会話（TalkScene）と同じ。
 * 話し手: オーナー・HC（スタッフの写真）・選手（選手の写真）・登場人物（藤堂・水瀬）・引退した選手（id に写真と名前）・あなた
 */
import { useEffect, useState } from 'react'
import { createPortal } from 'react-dom'
import { CAST_BY_ID } from '../../engine/data/cast'
import { applyClubChoice, ownerName } from '../../engine/club/story'
import { clubTalkOf } from '../../engine/club/storyTalks'
import type { TalkChoice } from '../../engine/career/talks'
import type { GameState } from '../../engine'
import { useGame, useGameState } from '../../stores/gameStore'
import { useOverlayRoot } from '../stage/overlayRoot'
import { Initials, Portrait } from '../components/Portrait'
import { playerPhoto } from '../components/playerPhoto'
import { staffPhoto } from '../components/staffPhoto'

/** 話し手の名前と写真 */
function speakerOf(state: GameState, who: string): { name: string; photo: string } {
  const c = state.club!
  if (who === 'me') return { name: 'あなた（GM）', photo: '' }
  if (who === 'owner') {
    const name = ownerName(state)
    return { name: `オーナー・${name}`, photo: staffPhoto(name) }
  }
  if (who === 'hc') {
    const name = c.staff.hc?.name ?? 'HC'
    return { name: `HC・${name}`, photo: staffPhoto(name) }
  }
  if (who.startsWith('p:')) {
    const p = state.players[Number(who.slice(2))]
    return p ? { name: p.name, photo: playerPhoto(state, p) } : { name: '', photo: '' }
  }
  if (who.startsWith('x:')) {
    const [, photo, ...name] = who.split(':')
    return { name: name.join(':'), photo }
  }
  const cast = CAST_BY_ID[who]
  if (cast) return { name: who === 'todo_maiko' ? `アドバイザー・${cast.name}` : cast.name, photo: who }
  return { name: who, photo: '' }
}

export function ClubTalkScene() {
  const state = useGameState()
  const mutate = useGame((s) => s.mutate)
  const root = useOverlayRoot()
  const [i, setI] = useState(0)
  const [reply, setReply] = useState<string | null>(null)
  const [chosen, setChosen] = useState(false)
  const c = state.club
  const pending = c?.scenes?.[0]
  const talk = pending ? clubTalkOf(pending.id, state) : null
  // 中身のない場面（選手がもういない など）は捨てる
  useEffect(() => {
    if (pending && !talk) mutate((st) => void st.club!.scenes!.shift())
  }, [pending, talk, mutate])
  if (!c || !pending || !root || !talk) return null
  const finish = () => {
    mutate((st) => {
      const cc = st.club!
      const t = cc.scenes!.shift()
      if (t) cc.sceneSeen = [...(cc.sceneSeen ?? []), t.id].slice(-300)
    })
    setI(0)
    setReply(null)
    setChosen(false)
  }
  const choose = (ch: TalkChoice) => {
    setChosen(true)
    setReply(ch.reply)
    mutate((st) => applyClubChoice(st, pending.id, ch.effect))
  }
  const lines = talk.lines
  const line = lines[Math.min(i, lines.length - 1)]
  const atEnd = i >= lines.length - 1
  const sp = speakerOf(state, line.who)
  const showChoices = atEnd && talk.choices && !chosen
  const next = () => {
    if (reply !== null) return finish()
    if (!atEnd) setI(i + 1)
    else if (!talk.choices) finish()
  }
  return createPortal(
    <div className="anim-fade absolute inset-0 z-50 flex flex-col justify-end bg-black/55" onClick={next}>
      <div className="safe-px safe-pb relative flex items-end gap-3 pb-3">
        <div className="anim-rise relative h-[15rem] w-[11.5rem] shrink-0 overflow-hidden rounded-2xl border border-gold/40 shadow-2xl">
          <Portrait id={sp.photo} kind="bust" className="h-full w-full" position="50% 15%" fallback={<Initials name={line.who === 'me' ? 'GM' : sp.name || '?'} className="h-full w-full" />} />
        </div>
        <div className="panel panel-solid min-w-0 flex-1 p-4" onClick={(e) => (showChoices ? e.stopPropagation() : undefined)}>
          <div className="mb-1 flex items-center gap-2">
            <span className="text-[0.75rem] font-bold text-ink-mute">{talk.title}</span>
            <span className="ml-auto text-[0.7rem] text-ink-mute">
              {Math.min(i + 1, lines.length)} / {lines.length}
            </span>
          </div>
          <div className="text-[0.9rem] font-black text-gold">{sp.name}</div>
          <p className="mt-1 min-h-[3.2rem] text-[1rem] leading-relaxed">{reply ?? line.text}</p>
          {showChoices ? (
            <div className="mt-2 flex gap-2">
              {talk.choices!.map((ch) => (
                <button
                  key={ch.label}
                  className="btn btn-gold btn-sm flex-1"
                  onClick={(e) => {
                    e.stopPropagation()
                    choose(ch)
                  }}
                >
                  {ch.label}
                </button>
              ))}
            </div>
          ) : (
            <div className="mt-1 text-right text-[0.72rem] text-ink-mute">タップで次へ ▶</div>
          )}
        </div>
      </div>
    </div>,
    root,
  )
}
