/**
 * 成長見込みと総合値の見える化の部品（2026-11-14）。
 *   見込みの計算と覚えておく分は outlookData.ts（outlookOf・useLevels・expPhase）
 *   OutlookChip: 一覧の「見込み」（↗ いちばん高くなる総合値・→ いまが完成形・↘ 2 年後）
 *   OutlookChart: 年齢ごとの総合値（これまでの経歴の実線と、見込みの点線）。リーグの水準の線つき
 *   OvrGauge: 総合値の目盛り（3 部・2 部・1 部・NBA の水準とスター）に、いまと見込みの印
 *   ExpCurve: 主人公の成長タイプの経験点の入り方（年齢ごと）
 */
import { GROWTH_DEFS, ovr, type GrowthType, type Player } from '../../engine'
import { expMulAt } from '../../engine/career/growth'
import { outlookLabel, type GrowthOutlook } from '../../engine/player/projection'
import { STAR_OVR, ovrLevelLabel } from '../../engine/team/strength'
import { useGameState } from '../../stores/gameStore'
import { outlookOf, useLevels } from './outlookData'

const TONE = { gold: 'text-gold', good: 'text-good', blue: 'text-accent', dim: 'text-ink-dim', bad: 'text-bad' } as const

/** 一覧の見込み: ↗72（いちばん高くなる総合値）・→60・↘57（2 年後） */
export function OutlookChip({ p, className = 'text-[0.78rem]' }: { p: Player; className?: string }) {
  const state = useGameState()
  const o = outlookOf(state, p)
  if (!o) return <span className="text-[0.7rem] text-ink-mute">{p.isPlayer ? '-' : '？'}</span>
  const l = outlookLabel(o)
  const est = !!state.club && p.teamId !== state.club.teamId
  const up = o.peak > o.now
  const down = !up && o.in2 < o.now
  const v = up ? o.peak : down ? o.in2 : o.now
  const title = up ? `見込み: ${o.peakAge} 歳ごろに総合 ${o.peak}（${l.text}）` : down ? `見込み: 2 年後に総合 ${o.in2}（${l.text}）` : `見込み: ${l.text}`
  return (
    <span className={`num inline-flex items-center font-black ${TONE[l.tone]} ${className}`} title={title + (est ? '・スカウトの見立て' : '')}>
      {est && <span className="text-[0.6rem] font-normal text-ink-mute">≈</span>}
      {up ? '↗' : down ? '↘' : '→'}
      {v}
    </span>
  )
}

/** 見込みの一言（選手の画面の札） */
export function OutlookText({ o }: { o: GrowthOutlook }) {
  const l = outlookLabel(o)
  return (
    <span>
      <span className={`font-black ${TONE[l.tone]}`}>{l.text}</span>
      {o.peak > o.now ? (
        <span className="text-ink-dim">
          {' '}
          — {o.peakAge} 歳ごろに <b className="num text-ink">{o.peak}</b>
        </span>
      ) : (
        o.in2 < o.now && (
          <span className="text-ink-dim">
            {' '}
            — 2 年後に <b className="num text-ink">{o.in2}</b>
          </span>
        )
      )}
    </span>
  )
}

const G_LO = 40
const G_HI = 96

/** 総合値の目盛り: リーグの水準の印と、いま（●）・見込み（◇） */
export function OvrGauge({ value, peak, className = '' }: { value: number; peak?: number; className?: string }) {
  const levels = useLevels()
  const x = (v: number) => `${((Math.max(G_LO, Math.min(G_HI, v)) - G_LO) / (G_HI - G_LO)) * 100}%`
  const marks = [...levels.map((l) => ({ label: l.label, value: l.value })), { label: 'スター', value: STAR_OVR }]
  return (
    <div className={className}>
      <div className="flex items-baseline justify-between text-[0.7rem]">
        <span className="font-black text-orange">{ovrLevelLabel(levels, value)}</span>
        {peak !== undefined && peak > value && <span className="text-ink-dim">見込み {ovrLevelLabel(levels, peak)}</span>}
      </div>
      <div className="relative mt-1 h-2 rounded-full" style={{ background: 'linear-gradient(90deg,#8792a3 0%,#2a7fdc 30%,#1f9d5a 50%,#e0560f 72%,#e0a21b 100%)' }}>
        {marks.map((m) => (
          <span key={m.label} className="absolute top-[-0.15rem] h-[0.8rem] w-px bg-ink/50" style={{ left: x(m.value) }} />
        ))}
        {peak !== undefined && peak > value && (
          <>
            <span className="absolute top-1/2 h-[0.18rem] -translate-y-1/2 bg-white/80" style={{ left: x(value), width: `calc(${x(peak)} - ${x(value)})` }} />
            <span className="absolute top-1/2 h-[0.7rem] w-[0.7rem] -translate-x-1/2 -translate-y-1/2 rotate-45 border-2 border-ink bg-white" style={{ left: x(peak) }} title={`見込み ${peak}`} />
          </>
        )}
        <span className="absolute top-1/2 h-[0.85rem] w-[0.85rem] -translate-x-1/2 -translate-y-1/2 rounded-full border-2 border-white bg-ink shadow" style={{ left: x(value) }} title={`いま ${value}`} />
      </div>
      <div className="relative mt-0.5 h-[0.8rem] text-[0.55rem] text-ink-mute">
        {marks.map((m) => (
          <span key={m.label} className="num absolute -translate-x-1/2 whitespace-nowrap" style={{ left: x(m.value) }}>
            {m.label}
          </span>
        ))}
      </div>
    </div>
  )
}

/** 年齢ごとの総合値: これまで（経歴の各シーズン）と見込み（点線） */
export function OutlookChart({ p, o, className = '' }: { p: Player; o: GrowthOutlook | null; className?: string }) {
  const levels = useLevels()
  const past = p.history.map((h) => ({ age: h.age, v: h.ovr }))
  const now = { age: o?.age ?? past[past.length - 1]?.age ?? 18, v: ovr(p) }
  const future = o ? o.path.map((v, i) => ({ age: o.age + i, v })) : []
  const pts = [...past, now, ...future]
  const a0 = Math.min(...pts.map((q) => q.age))
  const a1 = Math.max(a0 + 4, ...pts.map((q) => q.age))
  const vals = pts.map((q) => q.v)
  const lo = Math.max(30, Math.floor((Math.min(...vals) - 4) / 5) * 5)
  const hi = Math.min(99, Math.ceil((Math.max(...vals, lo + 20) + 4) / 5) * 5)
  const W = 300
  const H = 150
  const L = 22
  const B = 16
  const X = (age: number) => L + ((age - a0) / (a1 - a0)) * (W - L - 6)
  const Y = (v: number) => 6 + (1 - (v - lo) / (hi - lo)) * (H - B - 6)
  const line = (q: { age: number; v: number }[]) => q.map((r, i) => `${i ? 'L' : 'M'}${X(r.age).toFixed(1)},${Y(r.v).toFixed(1)}`).join(' ')
  const peak = o && o.peak > o.now ? { age: o.peakAge, v: o.peak } : null
  const ticks: number[] = []
  for (let a = Math.ceil(a0 / 2) * 2; a <= a1; a += a1 - a0 > 12 ? 4 : 2) ticks.push(a)
  return (
    <svg viewBox={`0 0 ${W} ${H}`} className={className} role="img" aria-label="年齢ごとの総合値の見込み">
      {/* リーグの水準 */}
      {[...levels.map((l) => ({ label: l.label, value: l.value })), { label: 'スター', value: STAR_OVR }]
        .filter((l) => l.value > lo && l.value < hi)
        .map((l) => (
          <g key={l.label}>
            <line x1={L} x2={W - 6} y1={Y(l.value)} y2={Y(l.value)} stroke="#14284b" strokeOpacity="0.14" strokeDasharray="3 3" />
            {/* 上のはしに近い線は、名前を線の下に */}
            <text x={W - 7} y={Y(l.value) < 16 ? Y(l.value) + 8 : Y(l.value) - 2} textAnchor="end" fontSize="7.5" fill="#14284b" fillOpacity="0.5">
              {l.label}の水準 {Math.round(l.value)}
            </text>
          </g>
        ))}
      {/* 目盛り */}
      {[lo, Math.round((lo + hi) / 2), hi].map((v) => (
        <text key={v} x={L - 3} y={Y(v) + 3} textAnchor="end" fontSize="8" fill="#14284b" fillOpacity="0.55">
          {v}
        </text>
      ))}
      {ticks.map((a) => (
        <text key={a} x={X(a)} y={H - 4} textAnchor={X(a) > W - 20 ? 'end' : 'middle'} fontSize="8" fill="#14284b" fillOpacity="0.55">
          {a}歳
        </text>
      ))}
      <line x1={L} x2={W - 6} y1={H - B} y2={H - B} stroke="#14284b" strokeOpacity="0.25" />
      {/* 見込み（点線）とこれまで（実線） */}
      {future.length > 1 && <path d={line(future)} fill="none" stroke="#f26a12" strokeWidth="2" strokeDasharray="4 3" />}
      {past.length > 0 && <path d={line([...past, now])} fill="none" stroke="#2b84e0" strokeWidth="2.2" />}
      {past.map((q) => (
        <circle key={`p${q.age}`} cx={X(q.age)} cy={Y(q.v)} r="2" fill="#2b84e0" />
      ))}
      <circle cx={X(now.age)} cy={Y(now.v)} r="3.6" fill="#14284b" stroke="#fff" strokeWidth="1.5" />
      <text x={X(now.age)} y={Y(now.v) + 12} textAnchor="middle" fontSize="8.5" fontWeight="900" fill="#14284b">
        いま {now.v}
      </text>
      {peak && (
        <>
          <rect x={X(peak.age) - 3.5} y={Y(peak.v) - 3.5} width="7" height="7" transform={`rotate(45 ${X(peak.age)} ${Y(peak.v)})`} fill="#fff" stroke="#f26a12" strokeWidth="1.8" />
          <text x={X(peak.age)} y={Y(peak.v) - 7} textAnchor="middle" fontSize="8.5" fontWeight="900" fill="#d4540a">
            {peak.age}歳 {peak.v}
          </text>
        </>
      )}
    </svg>
  )
}

/** 主人公: 成長タイプの経験点の入り方（年齢ごとの倍率）と、いまの年齢 */
export function ExpCurve({ type, age, className = '' }: { type: GrowthType; age: number; className?: string }) {
  const W = 300
  const H = 110
  const L = 22
  const B = 16
  const a0 = 18
  const a1 = 38
  const X = (a: number) => L + ((a - a0) / (a1 - a0)) * (W - L - 6)
  const top = 1.8
  const Y = (m: number) => 6 + (1 - m / top) * (H - B - 6)
  const pts: string[] = []
  for (let a = a0; a <= a1; a += 0.5) pts.push(`${pts.length ? 'L' : 'M'}${X(a).toFixed(1)},${Y(Math.min(top, expMulAt(type, a))).toFixed(1)}`)
  const d = GROWTH_DEFS[type]
  return (
    <svg viewBox={`0 0 ${W} ${H}`} className={className} role="img" aria-label="経験点の入り方">
      <rect x={X(d.peakEnd)} y={6} width={W - 6 - X(d.peakEnd)} height={H - B - 6} fill="#e2484e" fillOpacity="0.07" />
      <text x={X(d.peakEnd) + 3} y={15} fontSize="8" fill="#e2484e" fillOpacity="0.8">
        {d.peakEnd} 歳から衰えが始まる
      </text>
      <line x1={L} x2={W - 6} y1={Y(1)} y2={Y(1)} stroke="#14284b" strokeOpacity="0.15" strokeDasharray="3 3" />
      <text x={L - 3} y={Y(1) + 3} textAnchor="end" fontSize="8" fill="#14284b" fillOpacity="0.55">
        ×1
      </text>
      {[18, 22, 26, 30, 34, 38].map((a) => (
        <text key={a} x={X(a)} y={H - 4} textAnchor="middle" fontSize="8" fill="#14284b" fillOpacity="0.55">
          {a}歳
        </text>
      ))}
      <path d={pts.join(' ')} fill="none" stroke="#f26a12" strokeWidth="2.2" />
      {age >= a0 && age <= a1 && (
        <>
          <circle cx={X(age)} cy={Y(Math.min(top, expMulAt(type, age)))} r="3.6" fill="#14284b" stroke="#fff" strokeWidth="1.5" />
          <text x={X(age)} y={Y(Math.min(top, expMulAt(type, age))) - 6} textAnchor="middle" fontSize="8.5" fontWeight="900" fill="#14284b">
            いま ×{expMulAt(type, age).toFixed(2)}
          </text>
        </>
      )}
    </svg>
  )
}
