/** 小さな共通部品。 */
import { FLAGS, NATION_NAME, POSITION_DEFS, attrRank, type Nation, type Position } from '../../engine'
import { attrColor } from '../format'

export function OvrBadge({ value, size = 'md' }: { value: number; size?: 'sm' | 'md' | 'lg' }) {
  const v = Math.round(value)
  const bg =
    v >= 85
      ? 'linear-gradient(180deg,#ffe08a,#e0a21b)'
      : v >= 75
        ? 'linear-gradient(180deg,#ffb36b,#e0560f)'
        : v >= 65
          ? 'linear-gradient(180deg,#5ef0a0,#1f9d5a)'
          : v >= 55
            ? 'linear-gradient(180deg,#7cc4ff,#2a7fdc)'
            : v >= 45
              ? 'linear-gradient(180deg,#94a3b8,#5b6b80)'
              : 'linear-gradient(180deg,#6b7787,#465262)'
  const cls = size === 'lg' ? 'h-12 w-12 text-[1.5rem] rounded-xl' : size === 'sm' ? 'h-6 w-7 text-[0.78rem] rounded-md' : 'h-8 w-9 text-[0.95rem] rounded-lg'
  return (
    <span className={`num inline-flex shrink-0 items-center justify-center font-black ${v >= 85 ? 'text-[#2a1a00]' : 'text-white'} ${cls}`} style={{ background: bg, boxShadow: 'inset 0 1px 0 rgba(255,255,255,0.35), 0 1px 2px rgba(0,0,0,0.4)' }}>
      {v}
    </span>
  )
}

export function PosBadge({ pos, dim = false }: { pos: Position; dim?: boolean }) {
  const d = POSITION_DEFS[pos]
  return (
    <span className="inline-flex h-[1.35rem] min-w-[2.1rem] shrink-0 items-center justify-center rounded px-1 text-[0.76rem] font-black text-white" style={{ background: d.color, opacity: dim ? 0.55 : 1, textShadow: '0 1px 0 rgba(0,0,0,0.35)' }}>
      {pos}
    </span>
  )
}

export function Flag({ nation, className = 'h-[0.9rem] w-[1.35rem]' }: { nation: Nation; className?: string }) {
  const f = FLAGS[nation]
  const n = f.colors.length
  return (
    <svg viewBox="0 0 30 20" className={`${className} shrink-0 rounded-[2px] shadow-[0_0_0_1px_rgba(0,0,0,0.35)]`} aria-label={NATION_NAME[nation]}>
      {f.colors.map((c, i) => (f.dir === 'h' ? <rect key={i} x="0" y={(20 / n) * i} width="30" height={20 / n + 0.2} fill={c} /> : <rect key={i} x={(30 / n) * i} y="0" width={30 / n + 0.2} height="20" fill={c} />))}
      {f.cross && (
        <g fill={f.cross}>
          <rect x="9" y="0" width="4" height="20" />
          <rect x="0" y="8" width="30" height="4" />
        </g>
      )}
      {f.disc && <circle cx="15" cy="10" r="5" fill={f.disc} />}
    </svg>
  )
}

/** 調子（0-100）を 5 段階の矢印で */
export function ConditionArrow({ value }: { value: number }) {
  const lv = value >= 80 ? 4 : value >= 60 ? 3 : value >= 40 ? 2 : value >= 20 ? 1 : 0
  const rot = [90, 45, 0, -45, -90][lv]
  const color = ['#5b8def', '#7dd3fc', '#e8eef6', '#ffb020', '#ff5a5f'][lv]
  const label = ['絶不調', '不調', '普通', '好調', '絶好調'][lv]
  return (
    <svg viewBox="0 0 20 20" className="h-[1.1rem] w-[1.1rem] shrink-0" aria-label={label}>
      <g transform={`rotate(${rot} 10 10)`}>
        <path d="M3 10 H15 M11 5.5 L15.5 10 L11 14.5" stroke={color} strokeWidth="2.6" fill="none" strokeLinecap="round" strokeLinejoin="round" />
      </g>
    </svg>
  )
}

/** 横棒（能力値など） */
export function StatBar({ value, max = 99 }: { value: number; max?: number }) {
  return (
    <div className="relative h-[0.42rem] w-full overflow-hidden rounded-full bg-black/10">
      <div className="absolute inset-y-0 left-0 rounded-full" style={{ width: `${(value / max) * 100}%`, background: attrColor(value) }} />
    </div>
  )
}

/** 能力のランク（S〜G） */
export function RankChip({ value, className = '' }: { value: number; className?: string }) {
  return (
    <span className={`num inline-flex h-[1.15rem] w-[1.15rem] shrink-0 items-center justify-center rounded text-[0.74rem] font-black leading-none text-[#0b1320] ${className}`} style={{ background: attrColor(value) }}>
      {attrRank(value)}
    </span>
  )
}

/** ★（0.5 刻み、最大 5） */
export function Stars({ value, className = 'text-[0.85rem]' }: { value: number; className?: string }) {
  const full = Math.floor(value)
  const half = value - full >= 0.5
  return (
    <span className={`inline-flex tracking-[-0.05em] ${className}`} aria-label={`★${value}`}>
      {Array.from({ length: 5 }, (_, i) => (
        <span key={i} className={i < full ? 'text-gold' : i === full && half ? 'text-gold/60' : 'text-black/15'}>
          ★
        </span>
      ))}
    </span>
  )
}

/** チームの色の丸（ロゴの代わり。実在のロゴは使わない） */
export function TeamDot({ colors, abbr, className = 'h-7 w-7 text-[0.6rem]' }: { colors: { primary: string; secondary: string }; abbr: string; className?: string }) {
  return (
    <span className={`inline-flex shrink-0 items-center justify-center rounded-full font-black ${className}`} style={{ background: `linear-gradient(140deg, ${colors.primary} 55%, ${colors.secondary} 55%)`, color: '#fff', letterSpacing: '-0.06em', textShadow: '0 1px 2px rgba(0,0,0,0.8)', boxShadow: '0 0 0 1.5px rgba(255,255,255,0.25)' }}>
      {abbr.slice(0, 3)}
    </span>
  )
}
