/** 登場人物の図鑑（生成した写真の確認も兼ねる）。写真がまだの人は頭文字で出す。 */
import { useState } from 'react'
import { HEIR_HEROINES, JP_HEROINES, PEOPLE, US_HEROINES, type CastDef } from '../../engine/data/cast'
import { Initials, Portrait } from '../components/Portrait'
import { genIds } from '../components/portraits'
import { SideSheet } from '../layout/SideSheet'
import { Icon } from '../components/Icon'
import { useUi } from '../../stores/uiStore'

type Tab = 'jp' | 'us' | 'heir' | 'people' | 'faces'

const TABS: [Tab, string][] = [
  ['jp', `日本のヒロイン ${JP_HEROINES.length}`],
  ['us', `アメリカのヒロイン ${US_HEROINES.length}`],
  ['heir', `二代目のヒロイン ${HEIR_HEROINES.length}`],
  ['people', `人物 ${PEOPLE.length}`],
  ['faces', '顔の写真'],
]

const GEN_SETS: [string, string][] = [
  ['protag', '主人公の顔（キャリアモードの作成で選ぶ）'],
  ['pool', '一般の選手・スタッフ（主人公や自クラブに近い主力に使う）'],
]

function CastCard({ c, onOpen }: { c: CastDef; onOpen: () => void }) {
  const tall = c.kind === 'heroine'
  return (
    <button className="panel card-hover overflow-hidden text-left" onClick={onOpen}>
      <Portrait id={c.id} kind={tall ? 'bust' : 'photo'} className={tall ? 'aspect-[3/4] w-full' : 'aspect-[3/2] w-full'} position="50% 20%" fallback={<Initials name={c.name} className="h-full w-full" />} />
      <div className="px-2 py-1.5">
        <div className="truncate text-[0.9rem] font-black">{c.name}</div>
        <div className="truncate text-[0.72rem] text-ink-dim">
          {c.role}・{c.age}歳{c.gen === 2 ? '（二代目）' : ''}
        </div>
      </div>
    </button>
  )
}

export function GalleryScreen() {
  const pop = useUi((s) => s.pop)
  const [tab, setTab] = useState<Tab>('jp')
  const [sel, setSel] = useState<CastDef | null>(null)
  const list = tab === 'jp' ? JP_HEROINES : tab === 'us' ? US_HEROINES : tab === 'heir' ? HEIR_HEROINES : tab === 'people' ? PEOPLE : []

  return (
    <div className="absolute inset-0 flex flex-col">
      <header className="topbar safe-px flex shrink-0 items-center gap-3" style={{ boxSizing: 'content-box' }}>
        <button className="flex h-10 w-10 items-center justify-center rounded-lg text-ink-dim hover:bg-black/5" onClick={pop} aria-label="戻る">
          <Icon name="back" className="h-5 w-5" />
        </button>
        <h1 className="text-[1.05rem] font-extrabold">ギャラリー</h1>
        <div className="seg scroll-x ml-auto max-w-[70%]" role="tablist">
          {TABS.map(([id, label]) => (
            <button key={id} role="tab" aria-selected={tab === id} onClick={() => setTab(id)}>
              {label}
            </button>
          ))}
        </div>
      </header>

      <div className="scroll-y safe-px safe-pb min-h-0 flex-1 pt-3">
        {tab !== 'faces' && (
          <div className={`grid gap-2.5 ${tab === 'people' ? 'grid-cols-5' : 'grid-cols-7'}`}>
            {list.map((c) => (
              <CastCard key={c.id} c={c} onOpen={() => setSel(c)} />
            ))}
          </div>
        )}
        {tab === 'faces' &&
          GEN_SETS.map(([set, label]) => {
            const ids = genIds(set)
            return (
              <div key={set} className="mb-4">
                <div className="panel-head mb-1.5">
                  {label}（{ids.length}）
                </div>
                {ids.length === 0 ? (
                  <div className="panel-flat p-3 text-[0.8rem] text-ink-dim">写真はまだ作っています。</div>
                ) : (
                  <div className="grid grid-cols-10 gap-1.5">
                    {ids.map((id) => (
                      <Portrait key={id} id={id} kind="face" className="aspect-square w-full rounded-lg" />
                    ))}
                  </div>
                )}
              </div>
            )
          })}
      </div>

      <SideSheet open={!!sel} onClose={() => setSel(null)} title={sel?.name} width="46%">
        {sel && (
          <div className="flex gap-3 p-3">
            <Portrait id={sel.id} kind="bust" className="aspect-[3/4] w-[11rem] shrink-0 rounded-lg" position="50% 15%" fallback={<Initials name={sel.name} className="h-full w-full" />} />
            <div className="min-w-0 text-[0.85rem]">
              <div className="text-[0.75rem] text-ink-dim">{sel.kana}</div>
              <div className="mt-1 font-black text-gold">{sel.role}</div>
              <div className="text-ink-dim">
                {sel.age}歳{sel.gen === 2 ? '（二代目が 18 歳のとき）・二代目のキャリアで' : ''}・{sel.region === 'jp' ? '日本で会える' : sel.region === 'us' ? 'アメリカで会える' : 'どこでも会える'}
              </div>
              <p className="mt-2 leading-relaxed">{sel.intro}</p>
            </div>
          </div>
        )}
      </SideSheet>
    </div>
  )
}
