/**
 * 右から出るシート。#stage 内の #overlay-root に描くので、画面を回転していても一緒に回る。
 */
import { useEffect, type ReactNode } from 'react'
import { createPortal } from 'react-dom'
import { Icon } from '../components/Icon'

export function SideSheet({
  open,
  onClose,
  title,
  width = '58%',
  children,
}: {
  open: boolean
  onClose: () => void
  title?: ReactNode
  width?: string
  children: ReactNode
}) {
  useEffect(() => {
    if (!open) return
    const onKey = (e: KeyboardEvent) => e.key === 'Escape' && onClose()
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [open, onClose])
  const root = open ? document.getElementById('overlay-root') : null
  if (!root) return null
  return createPortal(
    <div className="absolute inset-0 z-40">
      <div className="anim-fade absolute inset-0 bg-black/55" onClick={onClose} />
      <section
        className="anim-sheet panel panel-solid safe-r absolute inset-y-0 right-0 flex flex-col !rounded-none !rounded-l-xl"
        style={{ width, minWidth: '20rem', maxWidth: '100%', boxSizing: 'content-box' }}
        role="dialog"
      >
        <header className="flex h-[2.9rem] shrink-0 items-center gap-2 border-b border-line/60 px-3">
          <div className="min-w-0 flex-1 truncate font-extrabold">{title}</div>
          <button className="flex h-10 w-10 items-center justify-center rounded-lg text-ink-dim hover:bg-black/5" onClick={onClose} aria-label="閉じる">
            <Icon name="close" className="h-5 w-5" />
          </button>
        </header>
        <div className="scroll-y safe-b min-h-0 flex-1">{children}</div>
      </section>
    </div>,
    root,
  )
}
