/**
 * キャリアの晴れ舞台:
 *   ドラフトの夜（名乗り出た年。1 位から順に発表し、主人公の名前で止まる）
 *   年間表彰式（シーズンの終わり。主人公のリーグの賞を順に。主人公の受賞は金色）
 */
import { useEffect, useState } from 'react'
import { createPortal } from 'react-dom'
import type { LeagueId } from '../../engine'
import { useGame, useGameState } from '../../stores/gameStore'
import { useOverlayRoot } from '../stage/overlayRoot'
import { TeamDot } from '../components/common'
import { Term } from '../components/Term'
import { sound } from '../audio/sound'
import { useMusic } from '../audio/useMusic'

export function DraftNight() {
  const state = useGameState()
  const mutate = useGame((s) => s.mutate)
  const root = useOverlayRoot()
  const c = state.career!
  const year = state.startYear + state.season
  const log = state.draftLog
  const show = c.declared === state.season - 1 && log.length > 0 && c.draftNightSeen !== year && state.week <= 2
  const mine = log.findIndex((d) => d.playerId === c.playerId)
  const stopAt = mine >= 0 ? mine : log.length - 1
  const [n, setN] = useState(0)
  useMusic('ceremony', show)
  useEffect(() => {
    if (!show || n > stopAt) return
    const t = setTimeout(() => {
      setN((x) => x + 1)
      if (n === stopAt && mine >= 0) sound.play('fanfare')
    }, n < 5 ? 900 : 380)
    return () => clearTimeout(t)
  }, [show, n, stopAt, mine])
  if (!show || !root) return null
  const close = () => mutate((st) => void (st.career!.draftNightSeen = year))
  const shown = log.slice(0, n)
  const done = n > stopAt
  return createPortal(
    <div className="anim-fade absolute inset-0 z-[60] flex flex-col bg-[radial-gradient(60%_80%_at_50%_0%,rgba(255,214,90,0.28),transparent),#fbf8f1] p-4">
      <div className="flex items-center gap-2">
        <div className="logo text-[1.8rem]">DRAFT NIGHT</div>
        <div className="text-[0.85rem] text-ink-dim">
          {year} <Term id="draft">NBA ドラフト</Term>
        </div>
        <button className="btn btn-ghost btn-sm ml-auto" onClick={() => setN(stopAt + 1)}>
          とばす
        </button>
      </div>
      <div className="scroll-y mt-2 grid min-h-0 flex-1 grid-cols-3 content-start gap-1.5">
        {shown.map((d) => {
          const t = state.teams[d.teamId]
          const me = d.playerId === c.playerId
          return (
            <div key={d.pick} className={`flex items-center gap-2 rounded-lg px-2 py-1 text-[0.8rem] ${me ? 'crown-pop col-span-3 border border-gold bg-gold/20 py-3 text-[1.2rem] font-black text-gold' : 'bg-black/5'}`}>
              <span className="num w-8 text-ink-dim">{d.pick}</span>
              <TeamDot colors={t.colors} abbr={t.abbr} className={me ? 'h-10 w-10 text-[0.7rem]' : 'h-6 w-6 text-[0.5rem]'} />
              <span className="min-w-0 flex-1 truncate">{d.name}</span>
              <span className="truncate text-[0.7rem] text-ink-mute">{t.short}</span>
            </div>
          )
        })}
      </div>
      {done && (
        <div className="mt-2 flex items-center gap-3">
          <div className="flex-1 text-[0.95rem] font-black">{mine >= 0 ? `${log[mine].pick} 位で名前が呼ばれた！` : '最後まで、名前は呼ばれなかった……'}</div>
          <button className="btn btn-gold" onClick={close}>
            次へ
          </button>
        </div>
      )}
    </div>,
    root,
  )
}

const ORDER: Record<string, number> = { MVP: 0, 新人王: 1, 最優秀守備選手: 2, シックスマン賞: 3, MIP: 4, 得点王: 5, 'オール NBA 1st': 6, 'オール NBA 2nd': 7, 'オール NBA 3rd': 8, 年間最優秀選手: 0 }

export function AwardsCeremony() {
  const state = useGameState()
  const mutate = useGame((s) => s.mutate)
  const root = useOverlayRoot()
  const c = state.career!
  const p = state.players[c.playerId]
  const season = state.season - 1
  const h = p.history.find((x) => x.season === season)
  const league: LeagueId | undefined = h?.league
  const list = state.awards.filter((a) => a.season === season && a.league === league && a.award in ORDER).sort((a, b) => ORDER[a.award] - ORDER[b.award])
  const mine = list.filter((a) => a.playerId === p.id)
  const show = state.week <= 1 && season >= 0 && c.ceremonySeen !== season && list.length > 0
  useMusic('ceremony', show)
  useEffect(() => {
    if (show && mine.length) sound.play('fanfare')
  }, [show, mine.length])
  if (!show || !root || !league) return null
  return createPortal(
    <div className="anim-fade absolute inset-0 z-[58] flex items-center justify-center bg-black/75 p-4">
      <div className="panel panel-solid panel-hero flex max-h-full w-[40rem] max-w-full flex-col p-4">
        <div className="flex items-center gap-2">
          <span className="text-[1.4rem]">🏆</span>
          <div className="text-[1.1rem] font-black">
            {state.leagues[league].name} <Term id="awards">年間表彰</Term>
          </div>
          <span className="text-[0.8rem] text-ink-dim">
            {state.startYear + season}-{String((state.startYear + season + 1) % 100).padStart(2, '0')}
          </span>
        </div>
        {mine.length > 0 && (
          <div className="crown-pop mt-2 rounded-xl border border-gold bg-gold/15 p-3 text-center">
            <div className="text-[0.8rem] text-gold">おめでとう！</div>
            <div className="text-[1.3rem] font-black">{mine.map((a) => a.award).join('・')}</div>
          </div>
        )}
        <div className="scroll-y mt-2 min-h-0 flex-1 text-[0.82rem]">
          {list.map((a, i) => (
            <div key={i} className={`flex gap-2 border-b border-line/30 py-1 ${a.playerId === p.id ? 'font-black text-gold' : ''}`}>
              <span className="w-[8rem] shrink-0 text-ink-dim">{a.award}</span>
              <span className="min-w-0 flex-1 truncate">
                {a.name}
                <span className="text-ink-mute">（{a.teamName}）</span>
              </span>
              <span className="shrink-0 text-[0.72rem] text-ink-dim">{a.line}</span>
            </div>
          ))}
        </div>
        <button className="btn btn-gold mt-3" onClick={() => mutate((st) => void (st.career!.ceremonySeen = season))}>
          閉じる
        </button>
      </div>
    </div>,
    root,
  )
}
