export function menuGroups(state: GameState): MenuGroup[] {
  return state.mode === 'career' ? CAREER_MENU : CLUB_MENU
}

/** ナビとメニューの知らせの数（返事を待っているもの）。キーは画面 か 画面:タブ */
export function badgesOf(state: GameState): Partial<Record<string, number>> {
  const c = state.club
  if (!c) return {}
  const offers = new Set(c.sponsorOffers.map((o) => o.slot)).size
  return { club: offers, 'club:sponsor': offers, transfer: c.bids.length, 'transfer:bids': c.bids.length }
}
