/**
 * 実績の見張り: ゲームの状態が変わるたびに条件を見て、解除したら上に知らせる（#overlay-root に描く）。
 * 古いセーブを開いたときなど、一度にたくさん解除したら 1 つにまとめて知らせる。
 */
import { useEffect, useState } from 'react'
import { createPortal } from 'react-dom'
import { newAchievements, type AchievementDef } from '../../engine/achievements'
import { useGame } from '../../stores/gameStore'
import { useAchievements } from '../../stores/achievementStore'
import { useOverlayRoot } from '../stage/overlayRoot'
import { sound } from '../audio/sound'
import { TIER_COLOR } from './tier'

type Toast = { key: number; title: string; sub: string; color: string }

export function AchievementWatcher() {
  const version = useGame((s) => s.version)
  const state = useGame((s) => s.state)
  const ephemeral = useGame((s) => s.ephemeral)
  const unlock = useAchievements((s) => s.unlock)
  const [queue, setQueue] = useState<Toast[]>([])
  const root = useOverlayRoot()

  // 状態が変わったら判定する（描画のあとに少し遅らせ、週送りの連続でも重くならないように）
  useEffect(() => {
    // 保存しないワールド（確認用・開発用）では解除しない
    if (!state || ephemeral) return
    const id = setTimeout(() => {
      const have = new Set(Object.keys(useAchievements.getState().unlocked))
      const got: AchievementDef[] = newAchievements(state, have)
      if (!got.length) return
      unlock(got.map((a) => a.id))
      const toasts: Toast[] =
        got.length > 3
          ? [{ key: Date.now(), title: `実績を ${got.length} 個解除しました`, sub: 'タイトルの「実績」で見られます', color: TIER_COLOR.gold }]
          : got.map((a, i) => ({ key: Date.now() + i, title: a.name, sub: a.desc, color: TIER_COLOR[a.tier] }))
      setQueue((q) => [...q, ...toasts])
    }, 400)
    return () => clearTimeout(id)
  }, [version, state, ephemeral, unlock])

  // 先頭を 3.2 秒出して次へ
  const head = queue[0]
  useEffect(() => {
    if (!head) return
    sound.play('fanfare')
    const id = setTimeout(() => setQueue((q) => q.slice(1)), 3200)
    return () => clearTimeout(id)
  }, [head])

  if (!head || !root) return null
  return createPortal(
    <button key={head.key} className="anim-rise absolute left-1/2 top-3 z-[80] flex -translate-x-1/2 items-center gap-2.5 rounded-xl border bg-[#0b1320]/95 px-4 py-2 text-left shadow-xl" style={{ borderColor: head.color }} onClick={() => setQueue((q) => q.slice(1))}>
      <Medal color={head.color} className="h-8 w-8 shrink-0" />
      <span>
        <span className="block text-[0.7rem] font-bold" style={{ color: head.color }}>
          実績解除
        </span>
        <span className="block text-[0.9rem] font-black text-white">{head.title}</span>
        <span className="block text-[0.72rem] text-white/70">{head.sub}</span>
      </span>
    </button>,
    root,
  )
}

/** メダル（実績の格の色） */
export function Medal({ color, className = '', dim }: { color: string; className?: string; dim?: boolean }) {
  return (
    <svg viewBox="0 0 32 32" className={className} aria-hidden style={{ opacity: dim ? 0.35 : 1 }}>
      <path d="M10 2h5l3 8h-5zM22 2h-5l-3 8h5z" fill={dim ? '#66788e' : '#3aa0ff'} />
      <circle cx="16" cy="20" r="10" fill={dim ? '#2a3a4e' : color} stroke="#0b1320" strokeWidth="1.5" />
      <path d="M16 13.5l1.9 3.9 4.3.6-3.1 3 .7 4.3-3.8-2-3.8 2 .7-4.3-3.1-3 4.3-.6z" fill={dim ? '#66788e' : '#fff8e1'} />
    </svg>
  )
}
