import { useState, type ReactNode } from 'react'
import { useSettings } from '../../stores/settingsStore'
import { useUi } from '../../stores/uiStore'
import { slotMeta, useGame } from '../../stores/gameStore'
import { SLOT_COUNT, saveGame } from '../../persistence/db'
import { exportSave, readSaveFile } from '../saveFile'
import { AppShell } from '../layout/AppShell'
import { Icon } from '../components/Icon'
import { getStageInfo } from '../stage/stageInfo'

function Row({ label, note, children }: { label: string; note?: string; children: ReactNode }) {
  return (
    <div className="flex min-h-[3.4rem] items-center gap-3 border-b border-line/40 px-3 py-2 last:border-b-0">
      <div className="min-w-0 flex-1">
        <div className="text-[0.92rem] font-bold">{label}</div>
        {note && <div className="text-[0.78rem] text-ink-dim">{note}</div>}
      </div>
      {children}
    </div>
  )
}

function Toggle({ on, onChange }: { on: boolean; onChange: (v: boolean) => void }) {
  return (
    <button
      role="switch"
      aria-checked={on}
      onClick={() => onChange(!on)}
      className={`relative h-8 w-14 shrink-0 rounded-full border transition-colors ${on ? 'border-gold bg-gold/80' : 'border-line bg-black/[0.06]'}`}
    >
      <span className={`absolute top-1 h-6 w-6 rounded-full bg-white shadow transition-all ${on ? 'left-7' : 'left-1'}`} />
    </button>
  )
}

export function SettingsScreen() {
  const pop = useUi((st) => st.pop)
  const inGame = useGame((g) => !!g.state)
  // ゲーム中は左のナビを出す（タブから開くので、戻る先がなくてもホームなどへ移れるように）
  if (inGame) {
    return (
      <AppShell title="設定" current="settings" back>
        <div className="scroll-y safe-pb absolute inset-0 px-3 pt-3">
          <SettingsBody />
        </div>
      </AppShell>
    )
  }
  return (
    <div className="absolute inset-0 flex flex-col">
      <header className="topbar safe-px flex shrink-0 items-center gap-2" style={{ boxSizing: 'content-box' }}>
        <button className="flex h-10 w-10 items-center justify-center rounded-lg text-ink-dim hover:bg-black/5" onClick={pop} aria-label="戻る">
          <Icon name="back" className="h-5 w-5" />
        </button>
        <h1 className="text-[1.05rem] font-extrabold">設定</h1>
      </header>
      <div className="scroll-y safe-px safe-pb min-h-0 flex-1 pt-3">
        <SettingsBody />
      </div>
    </div>
  )
}

/** セーブの書き出し・読み込み（バックアップ・機種変更・不具合の調査用） */
function SaveDataPanel() {
  const game = useGame((g) => g.state)
  const slotId = useGame((g) => g.slotId)
  const [slot, setSlot] = useState(1)
  const [msg, setMsg] = useState<string | null>(null)
  const onFile = async (file: File | undefined) => {
    if (!file) return
    try {
      const state = await readSaveFile(file)
      await saveGame(slot, state, slotMeta(state))
      setMsg(`スロット ${slot} に読み込みました。「つづきから」で遊べます。`)
    } catch (e) {
      setMsg(`読み込めませんでした: ${e instanceof Error ? e.message : String(e)}`)
    }
  }
  return (
    <div className="panel col-span-2">
      <div className="panel-head px-3 pt-2.5">セーブデータ</div>
      <Row label="書き出す" note="遊んでいるセーブをファイルにします（バックアップや不具合の調査に）">
        <button className="btn btn-ghost btn-sm" disabled={!game} onClick={() => game && void exportSave(game, `court-crown-slot${slotId}`)}>
          書き出す
        </button>
      </Row>
      <Row label="読み込む" note="書き出したファイルを、選んだスロットに入れます（そのスロットは上書き）">
        <div className="seg">
          {Array.from({ length: SLOT_COUNT }, (_, i) => i + 1).map((n) => (
            <button key={n} aria-selected={slot === n} onClick={() => setSlot(n)}>
              {n}
            </button>
          ))}
        </div>
        <label className="btn btn-ghost btn-sm cursor-pointer">
          ファイルを選ぶ
          <input type="file" accept="application/json,.json" className="hidden" onChange={(e) => void onFile(e.target.files?.[0])} />
        </label>
      </Row>
      {msg && <div className="px-3 pb-2 text-[0.78rem] text-gold">{msg}</div>}
    </div>
  )
}

/** 画面の大きさの段 */
const UI_SCALES: [number, string][] = [
  [0.85, '小さく'],
  [0.92, '少し小さく'],
  [1, 'ふつう'],
  [1.08, '少し大きく'],
  [1.16, '大きく'],
]

function SettingsBody() {
  const s = useSettings()
  const st = getStageInfo()
  return (
    <div className="mx-auto grid max-w-[52rem] grid-cols-2 gap-3">
      <div className="panel">
        <div className="panel-head px-3 pt-2.5">画面</div>
        <Row label="縦持ちの回転方向を逆にする" note="縦に持ったとき、画面を逆向きに回して表示します">
          <Toggle on={s.rotateFlip} onChange={(v) => s.set({ rotateFlip: v })} />
        </Row>
        <Row label="全画面・横向きロック" note="対応ブラウザでは最初のタップで全画面にします">
          <Toggle on={s.autoFullscreen} onChange={(v) => s.set({ autoFullscreen: v })} />
        </Row>
        <div className="border-b border-line/40 px-3 py-2">
          <div className="text-[0.92rem] font-bold">画面の大きさ</div>
          <div className="text-[0.78rem] text-ink-dim">文字とボタンの大きさ。小さくすると 1 画面に多く入ります（iPad などで見にくいとき）</div>
          <div className="seg mt-1.5 w-full">
            {UI_SCALES.map(([v, label]) => (
              <button key={v} className="min-w-0 flex-1 !px-1" aria-selected={Math.abs(s.uiScale - v) < 0.001} onClick={() => s.set({ uiScale: v })}>
                {label}
              </button>
            ))}
          </div>
        </div>
        <div className="px-3 pb-2 text-[0.74rem] text-ink-mute num">
          画面 {st.w}×{st.h}
          {st.rotation !== 0 && `（${st.rotation}° 回転表示中）`}
        </div>
      </div>
      <div className="panel">
        <div className="panel-head px-3 pt-2.5">サウンド・試合</div>
        <Row label="BGM の音量">
          <input type="range" min={0} max={1} step={0.05} value={s.bgmVolume} onChange={(e) => s.set({ bgmVolume: +e.target.value })} className="w-32 accent-[#f5c542]" />
        </Row>
        <Row label="効果音の音量">
          <input type="range" min={0} max={1} step={0.05} value={s.seVolume} onChange={(e) => s.set({ seVolume: +e.target.value })} className="w-32 accent-[#f5c542]" />
        </Row>
        <Row label="試合の再生速度（初期値）">
          <div className="seg">
            {([1, 2, 4, 8] as const).map((v) => (
              <button key={v} aria-selected={s.matchSpeed === v} onClick={() => s.set({ matchSpeed: v })}>
                ×{v}
              </button>
            ))}
          </div>
        </Row>
      </div>
      <div className="panel">
        <div className="panel-head px-3 pt-2.5">1か月オートで止まる出来事</div>
        <Row label="長期のケガ" note="全治 4 週以上のケガ">
          <Toggle on={s.autoStop.injury} onChange={(v) => s.set({ autoStop: { ...s.autoStop, injury: v } })} />
        </Row>
        <Row label="オファー・スポンサー" note="契約の話・スポンサーの申し出">
          <Toggle on={s.autoStop.offer} onChange={(v) => s.set({ autoStop: { ...s.autoStop, offer: v } })} />
        </Row>
        <Row label="出来事・出会い" note="人との出来事や、返事が要る相談">
          <Toggle on={s.autoStop.event} onChange={(v) => s.set({ autoStop: { ...s.autoStop, event: v } })} />
        </Row>
        <div className="px-3 pb-2 text-[0.72rem] text-ink-mute">シーズン末・プレーオフ・ドラフトではいつも止まります</div>
      </div>
      <div className="panel">
        <div className="panel-head px-3 pt-2.5">説明</div>
        <Row label="説明を出す" note="画面を初めて開いたときや、ドラフトなどの制度に初めて出会ったときに説明します">
          <Toggle on={s.showTips} onChange={(v) => s.set({ showTips: v })} />
        </Row>
        <Row label="用語の下線" note="用語に点線の下線を付け、タップで解説を出します">
          <Toggle on={s.termHints} onChange={(v) => s.set({ termHints: v })} />
        </Row>
        <Row label="説明をもう一度見る">
          <button className="btn btn-ghost btn-sm" onClick={() => s.set({ showTips: true, tipsSeen: [] })}>
            最初から
          </button>
        </Row>
        <Row label="用語集" note="ポジション・ルール・制度の解説">
          <button className="btn btn-ghost btn-sm" onClick={() => useUi.getState().push({ id: 'glossary' })}>
            見る
          </button>
        </Row>
      </div>
      <SaveDataPanel />
    </div>
  )
}
