/** リーグの画面の「全日本選手権」と「東アジア」のタブ: 回戦ごとの組み合わせ、グループの順位とファイナル 4 */
import { CUP_NAME, CUP_ROUNDS, CUP_WEEKS } from '../../engine/competition/cup'
import { EACC_DRAW_WEEK, EACC_FINAL_WEEK, EACC_GROUP_WEEKS, EACC_NAME, EACC_TITLE_WEEK, eaccTable, sideName, type EaccSide } from '../../engine/competition/eacc'
import { useGameState } from '../../stores/gameStore'
import { useUi } from '../../stores/uiStore'

const LG = { JBL1: '1部', JBL2: '2部', JBL3: '3部' } as Record<string, string>

/** 自分のチーム（クラブ経営のクラブか、キャリアの主人公のチーム） */
function useMine(): number {
  const state = useGameState()
  if (state.club) return state.club.teamId
  if (state.career) return state.players[state.career.playerId]?.teamId ?? -1
  return -1
}

export function CupView() {
  const state = useGameState()
  const push = useUi((s) => s.push)
  const mine = useMine()
  const cup = state.cup
  const past = (state.cupHistory ?? []).slice(-5).reverse()
  return (
    <div className="space-y-3 p-3 text-[0.82rem]">
      <p className="text-[0.75rem] text-ink-dim">
        国内の 1〜3 部の 48 クラブのトーナメント（1 試合で勝ち抜け）。1 回戦は 2 部と 3 部、2 回戦から 1 部が出る。準々決勝までは下の部のクラブのホーム、準々決勝からは中立地。番狂わせが起きやすい大会。日程は第 {CUP_WEEKS.join('・')} 週。
      </p>
      {!cup && <div className="text-ink-dim">今季の{CUP_NAME}は、第 {CUP_WEEKS[0]} 週に始まります。</div>}
      {cup &&
        [...CUP_ROUNDS.keys()]
          .filter((r) => cup.games.some((g) => g.r === r))
          .reverse()
          .map((r) => (
            <div key={r}>
              <div className="panel-head mb-1">
                {CUP_ROUNDS[r]}（第 {CUP_WEEKS[r]} 週）
              </div>
              <div className="grid grid-cols-2 gap-x-4 gap-y-0.5">
                {cup.games
                  .filter((g) => g.r === r)
                  .map((g) => {
                    const me = g.home === mine || g.away === mine
                    const side = (id: number, lg: string) => (
                      <button className={`truncate text-left ${g.winner === id ? 'font-black' : g.winner !== undefined ? 'text-ink-mute' : ''}`} onClick={() => push({ id: 'team', params: { teamId: id } })}>
                        {state.teams[id].short}
                        <span className="ml-0.5 text-[0.62rem] text-ink-mute">{LG[lg] ?? ''}</span>
                      </button>
                    )
                    return (
                      <div key={g.fixtureId} className={`flex items-center gap-1 rounded px-1 ${me ? 'bg-gold/15' : ''}`}>
                        <span className="min-w-0 flex-1 text-right">{side(g.home, g.homeLg)}</span>
                        <span className="num w-16 text-center font-bold">{g.hs !== undefined ? `${g.hs}-${g.as}` : 'vs'}</span>
                        <span className="min-w-0 flex-1">{side(g.away, g.awayLg)}</span>
                      </div>
                    )
                  })}
              </div>
            </div>
          ))}
      {past.length > 0 && (
        <div>
          <div className="panel-head mb-1">歴代の決勝</div>
          {past.map((h) => (
            <div key={h.season} className="text-[0.78rem]">
              {state.startYear + h.season} 年度: <b>{h.championName}</b>（準優勝 {h.runnerUpName}）
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

export function EaccView() {
  const state = useGameState()
  const mine = useMine()
  const e = state.eacc
  const qual = state.eaccQual
  const name = (s: EaccSide) => (e ? sideName(state, e, s) : '')
  return (
    <div className="space-y-3 p-3 text-[0.82rem]">
      <p className="text-[0.75rem] text-ink-dim">
        前のシーズンの国内 1 部の優勝クラブと、レギュラーシーズンの上位のクラブが出場。韓国・中国・フィリピン・台湾のクラブとグループで戦い（第 {EACC_GROUP_WEEKS.join('・')} 週）、上位 2 つがファイナル 4（中立地。第 {EACC_FINAL_WEEK} 週に準決勝・第 {EACC_TITLE_WEEK} 週に決勝）へ。クラブ経営では、自分のクラブの試合をホームから観戦できます。
      </p>
      {qual && qual.season > state.season && (
        <div className="rounded-lg bg-gold/10 px-2 py-1 text-[0.78rem]">
          来季の出場権: <b>{qual.teams.map((id) => state.teams[id].name).join('・')}</b>
        </div>
      )}
      {!e || e.season !== state.season ? (
        <div className="text-ink-dim">今季の{EACC_NAME}は、第 {EACC_DRAW_WEEK} 週に組み合わせが決まり、第 {EACC_GROUP_WEEKS[0]} 週に始まります。</div>
      ) : (
        <>
          <div className="grid grid-cols-2 gap-3">
            {(['A', 'B'] as const).map((grp) => (
              <div key={grp}>
                <div className="panel-head mb-1">グループ {grp}</div>
                {eaccTable(e, grp).map((row, i) => (
                  <div key={i} className={`flex items-center gap-2 rounded px-1 ${row.side.team === mine && mine >= 0 ? 'bg-gold/15' : ''} ${i < 2 ? 'font-bold' : ''}`}>
                    <span className="num w-4 text-ink-dim">{i + 1}</span>
                    <span className="min-w-0 flex-1 truncate">{name(row.side)}</span>
                    <span className="num">
                      {row.w}-{row.l}
                    </span>
                    <span className="num w-10 text-right text-[0.72rem] text-ink-dim">{row.diff > 0 ? `+${row.diff}` : row.diff}</span>
                  </div>
                ))}
              </div>
            ))}
          </div>
          <div>
            <div className="panel-head mb-1">試合</div>
            {[...e.games].reverse().map((g, i) => (
              <div key={i} className="flex items-center gap-2 text-[0.78rem]">
                <span className="w-16 text-[0.68rem] text-ink-mute">{g.stage === 'F' ? '決勝' : g.stage === 'SF' ? '準決勝' : `グループ ${g.stage}`}</span>
                <span className={`min-w-0 flex-1 truncate text-right ${g.hs > g.as ? 'font-black' : ''}`}>{name(g.home)}</span>
                <span className="num w-14 text-center font-bold">
                  {g.hs}-{g.as}
                </span>
                <span className={`min-w-0 flex-1 truncate ${g.as > g.hs ? 'font-black' : ''}`}>{name(g.away)}</span>
              </div>
            ))}
            {e.champion && (
              <div className="mt-1 font-black text-gold">
                優勝: {name(e.champion)}
              </div>
            )}
          </div>
        </>
      )}
    </div>
  )
}
