/**
 * キャリアモードの作成（ユーザーの要望: ポジション・プレースタイルなどに解説を）。
 *   1 ポジション → 2 プレースタイル → 3 体格 → 4 成長 → 5 顔と名前。どの項目もカードに解説を出し、右に見込み（能力のレーダー・得意と苦手・伸ばしたい能力）
 */
import { useMemo, useState } from 'react'
import {
  ATTR_DEFS,
  ATTR_KEYS,
  GROWTH_DEFS,
  GROWTH_TYPES,
  PLAY_STYLES,
  PLAY_STYLE_DEFS,
  POSITIONS,
  POSITION_DEFS,
  POS_WEIGHTS,
  RADAR_AXES,
  bodyNotes,
  jpNamePool,
  posHeight,
  radarValues,
  rawOvr,
  typicalWeight,
  type GrowthType,
  type PlayStyle,
  type Position,
} from '../../engine'
import { protagonistAttrs } from '../../engine/career/create'
import { useGame } from '../../stores/gameStore'
import { useCurrentScreen, useUi } from '../../stores/uiStore'
import { startHeir } from '../../engine/career/heir'
import { SlotPicker } from '../components/SlotPicker'
import { useSlotChoice } from '../hooks/useSlotChoice'
import { Icon } from '../components/Icon'
import { Initials, Portrait } from '../components/Portrait'
import { genIds } from '../components/portraits'
import { RadarChart } from '../components/RadarChart'
import { OvrBadge, PosBadge } from '../components/common'
import { Term, TermHelp } from '../components/Term'

type Step = 0 | 1 | 2 | 3 | 4
const STEPS = ['ポジション', 'プレースタイル', '体格', '成長', '顔と名前']
const FACE_IDS = ['p01', 'p02', 'p03', 'p04', 'p05', 'p06', 'p07', 'p08', 'p09', 'p10', 'p11', 'p12']

const GROWTH_NOTE: Record<GrowthType, string> = {
  ultraEarly: '10 代のうちから急に伸びる。若くして活躍できるが、衰えも早い',
  early: '若いうちに伸びる。早く NBA に届きやすい',
  normal: 'バランス型。20 代の後半に頂点',
  late: 'ゆっくり伸びて、長く活躍する。最初は我慢の時期',
  ultraLate: '若いうちは苦労するが、30 代でも伸び続ける大器晩成',
}

function Card({ selected, onClick, children, dim }: { selected: boolean; onClick: () => void; children: React.ReactNode; dim?: boolean }) {
  return (
    <button onClick={onClick} className={`card-hover rounded-xl border p-2.5 text-left transition-colors ${selected ? 'border-gold bg-gold/15 shadow-[0_0_1rem_rgba(245,197,66,0.25)]' : 'border-line/60 bg-black/[0.05] hover:bg-black/5'} ${dim ? 'opacity-70' : ''}`}>
      {children}
    </button>
  )
}

function Slider({ label, term, value, min, max, onChange, unit, mark }: { label: string; term: string; value: number; min: number; max: number; onChange: (v: number) => void; unit: string; mark?: number }) {
  return (
    <div className="panel-flat p-3">
      <div className="flex items-center gap-2">
        <span className="text-[0.95rem] font-black">
          <Term id={term}>{label}</Term>
        </span>
        <span className="num ml-auto text-[1.4rem] font-black text-gold">
          {value}
          <span className="ml-0.5 text-[0.8rem] text-ink-dim">{unit}</span>
        </span>
      </div>
      <input type="range" min={min} max={max} value={value} onChange={(e) => onChange(Number(e.target.value))} className="mt-1 w-full accent-[#ff7a1a]" />
      <div className="num flex justify-between text-[0.7rem] text-ink-mute">
        <span>{min}</span>
        {mark !== undefined && <span>標準 {mark}</span>}
        <span>{max}</span>
      </div>
    </div>
  )
}

export function CareerNewScreen() {
  const pop = useUi((s) => s.pop)
  const reset = useUi((s) => s.reset)
  const newCareer = useGame((s) => s.newCareer)
  const mutate = useGame((s) => s.mutate)
  // 二代目（引退の総括の「子どもの世代へ」から）: 親の姓と子の名前、親のポジションと背の高さ（少し高く）を目安に
  const heirIndex = useCurrentScreen().params?.heir as number | undefined
  const gameState = useGame((s) => s.state)
  const heir = heirIndex !== undefined && gameState?.career ? { parent: gameState.players[gameState.career.playerId], child: gameState.career.children?.[heirIndex] } : null
  const startPos: Position = heir ? (heir.parent.pos as Position) : 'SG'
  const startH = heir ? Math.min(posHeight(startPos) + 10, heir.parent.heightCm + 2) : Math.round(posHeight('SG') - 4)
  const [step, setStep] = useState<Step>(0)
  const [pos, setPos] = useState<Position>(startPos)
  const [style, setStyle] = useState<PlayStyle>(heir ? (heir.parent.style as PlayStyle) : 'scorer')
  const [height, setHeight] = useState(startH)
  const [wing, setWing] = useState(startH + 6)
  const [weight, setWeight] = useState(typicalWeight(startH, startPos))
  const [growth, setGrowth] = useState<GrowthType | 'auto'>('normal')
  const [mode, setMode] = useState<'easy' | 'careful'>('easy')
  const [face, setFace] = useState('p01')
  const pool = jpNamePool()
  const [name, setName] = useState(heir?.child ? `${heir.parent.short} ${heir.child.name}` : '朝倉 翔')
  const { slots, slot, setSlot, current: slotCurrent, go, dialog: slotDialog } = useSlotChoice()
  const faces = genIds('protag')

  const choosePos = (p: Position) => {
    setPos(p)
    // ポジションに合わせて、体格とスタイルを目安へ（日本人は少し小柄）
    const h = Math.round(posHeight(p) - 4)
    setHeight(h)
    setWing(h + 6)
    setWeight(typicalWeight(h, p))
    if (!PLAY_STYLE_DEFS[style].positions.includes(p)) setStyle(PLAY_STYLES.find((s) => PLAY_STYLE_DEFS[s].positions[0] === p) ?? PLAY_STYLES.find((s) => PLAY_STYLE_DEFS[s].positions.includes(p))!)
  }

  const attr = useMemo(() => protagonistAttrs({ pos, style, heightCm: height, wingspanCm: wing, weightKg: weight }), [pos, style, height, wing, weight])
  const ovr = Math.round(rawOvr(attr, pos))
  const ranked = [...ATTR_KEYS].filter((k) => POS_WEIGHTS[pos][k] >= 0.5).sort((a, b) => attr[b] - attr[a])
  const strong = ranked.slice(0, 3)
  const weak = ranked.slice(-2)
  const notes = bodyNotes(height, wing, weight, pos)
  const randomName = () => {
    const r = (a: string[]) => a[Math.floor(Math.random() * a.length)]
    setName(`${r(pool.family)} ${r(pool.given)}`)
  }
  const start = () => {
    // 二代目: 同じ世界・同じセーブのまま、子のキャリアに入れ替える
    if (heir && heirIndex !== undefined) {
      mutate((st) => startHeir(st, heirIndex, { name: name.trim() || `${heir.parent.short} ${heir.child?.name ?? ''}`, pos, style, heightCm: height, wingspanCm: wing, weightKg: weight, growth, growthMode: mode, photo: faces.includes(face) ? face : undefined }))
      reset({ id: 'home' })
      return
    }
    go(() => {
      newCareer({ seed: Math.floor(Math.random() * 1_000_000_000), name: name.trim() || '朝倉 翔', pos, style, heightCm: height, wingspanCm: wing, weightKg: weight, growth, growthMode: mode, photo: faces.includes(face) ? face : undefined }, slot)
      reset({ id: 'home' })
    })
  }

  return (
    <div className="absolute inset-0 flex flex-col">
      <header className="topbar safe-px flex shrink-0 items-center gap-2" style={{ boxSizing: 'content-box' }}>
        <button className="flex h-10 w-10 items-center justify-center rounded-lg text-ink-dim hover:bg-black/5" onClick={() => (step > 0 ? setStep((step - 1) as Step) : pop())} aria-label="戻る">
          <Icon name="back" className="h-5 w-5" />
        </button>
        <h1 className="text-[1.05rem] font-extrabold">{heir ? `二代目 ── ${heir.child?.name ?? ''}を作る（父・${heir.parent.name}）` : 'キャリアモード ── 選手を作る'}</h1>
        <div className="ml-auto flex gap-1">
          {STEPS.map((s, i) => (
            <button key={s} onClick={() => setStep(i as Step)} className={`rounded-full px-2.5 py-1 text-[0.75rem] font-bold ${i === step ? 'bg-gold text-[#2a1a00]' : i < step ? 'bg-gold/20 text-gold' : 'bg-black/[0.06] text-ink-mute'}`}>
              {i + 1}. {s}
            </button>
          ))}
        </div>
      </header>
      <div className="safe-px safe-pb flex min-h-0 flex-1 gap-2 pt-2">
        {/* 左: 選ぶ */}
        <div className="scroll-y min-w-0 flex-1 pr-1">
          {step === 0 && (
            <>
              <p className="mb-2 text-[0.82rem] text-ink-dim">
                まずはポジション。コートでの役割が決まります。迷ったら、身長の目安と「向いている人」を見てください。<Term id="pos:PG">用語の説明</Term>はいつでも点線の言葉を押すと出ます。
              </p>
              <div className="grid grid-cols-1 gap-2">
                {POSITIONS.map((p) => {
                  const d = POSITION_DEFS[p]
                  return (
                    <Card key={p} selected={pos === p} onClick={() => choosePos(p)}>
                      <div className="flex items-start gap-3">
                        <div className="flex w-[5.5rem] shrink-0 flex-col items-center gap-1">
                          <PosBadge pos={p} />
                          <span className="text-[0.72rem] font-bold text-ink-dim">{d.name}</span>
                        </div>
                        <div className="min-w-0 flex-1">
                          <div className="text-[0.95rem] font-black text-gold">{d.role}</div>
                          <div className="text-[0.8rem] leading-snug">{d.job}</div>
                          <div className="mt-1 flex flex-wrap gap-x-3 text-[0.72rem] text-ink-dim">
                            <span>大事な能力: {d.keyAttrs.join('・')}</span>
                            <span>
                              <Term id="height">身長</Term>の目安: {d.height[0]}〜{d.height[1]}cm
                            </span>
                          </div>
                          <div className="text-[0.72rem] text-orange">向いている人: {d.suits}</div>
                        </div>
                      </div>
                    </Card>
                  )
                })}
              </div>
            </>
          )}
          {step === 1 && (
            <>
              <p className="mb-2 text-[0.82rem] text-ink-dim">プレースタイルは、どんな選手を目指すか。最初の能力の形と、おまかせの練習が変わります。{POSITION_DEFS[pos].name}に合うものに「おすすめ」が付いています。</p>
              <div className="grid grid-cols-2 gap-2">
                {[...PLAY_STYLES]
                  .sort((a, b) => Number(PLAY_STYLE_DEFS[b].positions.includes(pos)) - Number(PLAY_STYLE_DEFS[a].positions.includes(pos)))
                  .map((s) => {
                    const d = PLAY_STYLE_DEFS[s]
                    const fit = d.positions.includes(pos)
                    return (
                      <Card key={s} selected={style === s} onClick={() => setStyle(s)} dim={!fit}>
                        <div className="flex items-center gap-2">
                          <span className="text-[1rem] font-black">{d.name}</span>
                          {fit && <span className="rounded bg-orange/25 px-1.5 text-[0.68rem] font-black text-orange">おすすめ</span>}
                          <span className="ml-auto flex gap-0.5">
                            {d.positions.map((p) => (
                              <PosBadge key={p} pos={p} dim={p !== pos} />
                            ))}
                          </span>
                        </div>
                        <div className="text-[0.8rem] font-bold text-gold">{d.catch}</div>
                        <div className="mt-0.5 text-[0.76rem] leading-snug">{d.desc}</div>
                        <div className="mt-1 text-[0.7rem] text-ink-dim">大事な能力: {d.keyAttrs.join('・')}</div>
                      </Card>
                    )
                  })}
              </div>
            </>
          )}
          {step === 2 && (
            <>
              <p className="mb-2 text-[0.82rem] text-ink-dim">体格はバスケでとても大事です。背が高いほどゴール下とリバウンドに強く、低いほど速く動けます。動かすと右の能力が変わります。</p>
              <div className="grid grid-cols-1 gap-2">
                <Slider label="身長" term="height" value={height} min={Math.round(posHeight(pos) - 16)} max={Math.round(posHeight(pos) + 10)} onChange={setHeight} unit="cm" mark={Math.round(posHeight(pos))} />
                <Slider label="ウイングスパン（腕の長さ）" term="wingspan" value={wing} min={height - 6} max={height + 16} onChange={setWing} unit="cm" mark={height + 6} />
                <Slider label="体重" term="weight" value={weight} min={typicalWeight(height, pos) - 16} max={typicalWeight(height, pos) + 18} onChange={setWeight} unit="kg" mark={typicalWeight(height, pos)} />
                <div className="panel-flat p-3 text-[0.82rem]">
                  <div className="mb-1 font-black text-gold">この体格だと</div>
                  {notes.map((n) => (
                    <div key={n}>・{n}</div>
                  ))}
                </div>
              </div>
            </>
          )}
          {step === 3 && (
            <>
              <div className="mb-1 flex items-center gap-1 text-[0.9rem] font-black">
                <Term id="growthType">成長タイプ</Term>（いつ伸びるか）
              </div>
              <div className="grid grid-cols-3 gap-2">
                {[...GROWTH_TYPES, 'auto' as const].map((g) => (
                  <Card key={g} selected={growth === g} onClick={() => setGrowth(g)}>
                    <div className="text-[0.95rem] font-black">{g === 'auto' ? 'おまかせ' : GROWTH_DEFS[g].name}</div>
                    <div className="text-[0.75rem] font-bold text-gold">{g === 'auto' ? 'どれになるかは始めてから' : `ピーク ${GROWTH_DEFS[g].peak}`}</div>
                    <div className="mt-0.5 text-[0.72rem] leading-snug text-ink-dim">{g === 'auto' ? 'ふつうは「標準」が多い。運しだいで早熟や晩成に' : GROWTH_NOTE[g]}</div>
                  </Card>
                ))}
              </div>
              <div className="mb-1 mt-3 flex items-center gap-1 text-[0.9rem] font-black">
                <Term id="growthMode">育成のしかた</Term>
              </div>
              <div className="grid grid-cols-2 gap-2">
                <Card selected={mode === 'easy'} onClick={() => setMode('easy')}>
                  <div className="text-[0.95rem] font-black">かんたん</div>
                  <div className="text-[0.75rem] leading-snug text-ink-dim">練習で得た経験点を、ポジションで大事な能力へ自動で振ります。はじめての人におすすめ</div>
                </Card>
                <Card selected={mode === 'careful'} onClick={() => setMode('careful')}>
                  <div className="text-[0.95rem] font-black">じっくり</div>
                  <div className="text-[0.75rem] leading-snug text-ink-dim">たまった経験点を、どの能力に使うか自分で決めます。思いどおりの選手を作りたい人に</div>
                </Card>
              </div>
            </>
          )}
          {step === 4 && (
            <>
              <div className="panel-flat mb-2 flex items-center gap-2 p-3">
                <span className="text-[0.9rem] font-black">名前</span>
                <input value={name} onChange={(e) => setName(e.target.value)} maxLength={12} className="min-w-0 flex-1 rounded-lg border border-line bg-black/[0.06] px-3 py-2 text-[1rem] font-bold outline-none focus:border-gold" />
                <button className="btn btn-ghost btn-sm" onClick={randomName}>
                  ランダム
                </button>
              </div>
              <div className="mb-1 text-[0.9rem] font-black">顔</div>
              <div className="grid grid-cols-6 gap-2">
                {FACE_IDS.map((id) => (
                  <button key={id} onClick={() => setFace(id)} className={`overflow-hidden rounded-xl border-2 ${face === id ? 'border-gold shadow-[0_0_0.8rem_rgba(245,197,66,0.4)]' : 'border-transparent'}`}>
                    <Portrait id={id} kind="face" className="aspect-square w-full" fallback={<Initials name={name || '主'} className="h-full w-full" color={`hsl(${FACE_IDS.indexOf(id) * 30} 45% 35%)`} />} />
                  </button>
                ))}
              </div>
              {faces.length === 0 && <div className="mt-1 text-[0.72rem] text-ink-mute">顔の写真はまだ作っています。できあがると、ここで選んだ番号の写真になります。</div>}
              {!heir && (
                <>
                  <div className="mb-1 mt-3 text-[0.9rem] font-black">保存先</div>
                  <SlotPicker slots={slots} slot={slot} onChange={setSlot} />
                </>
              )}
            </>
          )}
        </div>
        {/* 右: 見込み */}
        <div className="panel panel-hero flex w-[19rem] shrink-0 flex-col gap-1.5 p-3">
          <div className="flex items-center gap-2">
            <Portrait id={face} kind="face" className="h-14 w-14 shrink-0 rounded-xl" fallback={<Initials name={name || '主'} className="h-full w-full" />} />
            <div className="min-w-0 flex-1">
              <div className="truncate text-[1rem] font-black">{name || '（名前）'}</div>
              <div className="flex items-center gap-1 text-[0.75rem]">
                <PosBadge pos={pos} />
                <span className="font-bold text-orange">{PLAY_STYLE_DEFS[style].name}</span>
                <TermHelp id={`style:${style}`} />
              </div>
              <div className="num text-[0.72rem] text-ink-dim">
                {height}cm・{weight}kg・18歳
              </div>
            </div>
            <OvrBadge value={ovr} size="lg" />
          </div>
          <RadarChart labels={RADAR_AXES.map((a) => a.label)} values={radarValues(attr)} className="mx-auto h-[10.5rem] w-[10.5rem]" color="#ff7a1a" />
          <div className="text-[0.75rem]">
            <span className="font-black text-good">得意 </span>
            {strong.map((k) => `${ATTR_DEFS[k].label} ${Math.round(attr[k])}`).join('・')}
          </div>
          <div className="text-[0.75rem]">
            <span className="font-black text-bad">苦手 </span>
            {weak.map((k) => `${ATTR_DEFS[k].label} ${Math.round(attr[k])}`).join('・')}
          </div>
          <div className="text-[0.72rem] leading-snug text-ink-dim">
            <span className="font-black text-gold">伸ばしたい能力 </span>
            {PLAY_STYLE_DEFS[style].grow}
          </div>
          {step === 4 && !heir && (
            <div className="mt-auto text-[0.72rem] text-ink-dim">
              保存先: スロット {slot}
              {slotCurrent ? <span className="ml-1 font-bold text-bad">（「{slotCurrent.title}」を上書き）</span> : <span className="ml-1 font-bold text-good">（空き）</span>}
            </div>
          )}
          <div className={`flex gap-2 ${step === 4 ? '' : 'mt-auto'}`}>
            {step < 4 ? (
              <button className="btn btn-gold flex-1" onClick={() => setStep((step + 1) as Step)}>
                次へ（{STEPS[step + 1]}）
              </button>
            ) : (
              <button className="btn btn-gold flex-1" onClick={start}>
                この選手で始める
              </button>
            )}
          </div>
        </div>
      </div>
      {slotDialog}
    </div>
  )
}
