/**
 * はじめの一歩（ホームの右上の案内）: 最初の数週でやってみてほしいこと。済んだかは state.tutorial（セーブごと）。
 *   week・watch・outing・auto は gameStore の週の進行で、画面を開く手順は AppShell で済ませる。
 */
import type { ScreenId } from '../../stores/uiStore'

export interface StepDef {
  id: string
  title: string
  hint: string
  /** この画面を開くと済む（「開く」のボタンも出す） */
  screen?: ScreenId
}

export const CAREER_STEPS: StepDef[] = [
  { id: 'week', title: '過ごし方を選んで進める', hint: '「今週の過ごし方」で練習を選んで「次へ進む」。練習の種類で、たまる経験点が変わります。疲れたら休養を。' },
  { id: 'watch', title: '試合を観戦する', hint: '試合のある週は「試合へ」→「観戦する」。ボールが回ってきた見せ場で、◎ を選ぶと決まりやすい。' },
  { id: 'growth', title: '育成の画面を見る', hint: '経験点で能力が伸びます。「かんたん」なら自動、「じっくり」なら自分で選んで上げる。', screen: 'growth' },
  { id: 'outing', title: '「おでかけ」で人に会う', hint: '過ごし方の「おでかけ」で行き先を選ぶと、誰かに会えます。絆が深まると特別な話が聞けます。' },
  { id: 'life', title: 'くらしの画面を見る', hint: '住まい・車・自己投資・サイドビジネス。稼いだお金の使い道はここ。', screen: 'life' },
  { id: 'auto', title: '慣れたら「1か月オート」', hint: '4 週まとめて進めます。返事の要る話や大事な出来事が来たら止まります。' },
]

export const CLUB_STEPS: StepDef[] = [
  { id: 'tactics', title: '作戦と序列を見る', hint: '序列はおまかせのままでも大丈夫。作戦は「おすすめの作戦」に理由つきで出ます。', screen: 'tactics' },
  { id: 'training', title: '練習の強さと重点', hint: '強いほど伸びますが、ケガと疲れも増えます。重点の種類の能力が伸びやすくなります。', screen: 'training' },
  { id: 'transfer', title: '「補強・編成」で選手を獲る', hint: '獲りたい選手の「交渉する」→ 年俸と年数を決めて話す。所属なしの選手は移籍金がいりません。まずは手薄なポジションから。', screen: 'transfer' },
  { id: 'club', title: 'クラブの画面を見る', hint: '施設・アリーナ・スタッフ・スポンサー・お金。昇格には席数のライセンスが要ります。', screen: 'club' },
  { id: 'watch', title: '試合を観戦して指示を出す', hint: '試合の週は「試合へ」→「観戦する」。タイムアウト・交代・作戦の変更ができます。' },
  { id: 'auto', title: '慣れたら「1か月オート」', hint: '4 週まとめて進めます。資金とオーナーの信頼はときどき確かめて。' },
]

/** 開くと済む手順（モードと画面から） */
export function screenStep(club: boolean, screen: string | undefined): string | undefined {
  return (club ? CLUB_STEPS : CAREER_STEPS).find((s) => s.screen === screen)?.id
}
