/** セーブデータの書き出しと読み込み（バックアップ・不具合の調査用）。 */
import type { GameState } from '../engine'
import { migrate } from '../engine/core/migrations'

/** JSON ファイルにして渡す（iPhone では共有シート、PC ではダウンロード）。extra はエラーの内容など（ファイルの頭に入れる） */
export async function exportSave(state: GameState, name: string, extra?: Record<string, unknown>) {
  const json = JSON.stringify({ app: 'court-crown', exportedAt: new Date().toISOString(), ...extra, state })
  const file = new File([json], `${name}.json`, { type: 'application/json' })
  const nav = navigator as Navigator & { canShare?: (d: ShareData) => boolean }
  if (nav.canShare?.({ files: [file] })) {
    try {
      await nav.share({ files: [file], title: 'COURT CROWN のセーブ' })
      return
    } catch {
      // 共有をやめた・使えない → ダウンロードにする
    }
  }
  const url = URL.createObjectURL(file)
  const a = document.createElement('a')
  a.href = url
  a.download = file.name
  a.click()
  setTimeout(() => URL.revokeObjectURL(url), 5000)
}

/** 書き出したファイルを読む（古い形式なら今の形に直す） */
export async function readSaveFile(file: File): Promise<GameState> {
  const data = JSON.parse(await file.text()) as { state?: GameState } & Partial<GameState>
  const st = (data.state ?? data) as GameState
  if (!st || typeof st.seed !== 'number' || !st.mode) throw new Error('COURT CROWN のセーブデータではありません')
  return migrate(st)
}
