/** 育成: 経験点で能力を上げる（じっくり。かんたんでも見られて、自分で上げることもできる）と、特殊能力の条件と進み具合。 */
import { ATTR_DEFS, ovr, type AttrKey } from '../../engine'
import { EXP_DEFS, EXP_KINDS } from '../../engine/data/career'
import { attrCost, raiseAttr } from '../../engine/career/growth'
import { useGame, useGameState } from '../../stores/gameStore'
import { AppShell } from '../layout/AppShell'
import { OvrBadge, RankChip, StatBar } from '../components/common'
import { Term, TermHelp } from '../components/Term'
import { SkillTab } from '../career/SkillProgress'
import { useCurrentScreen } from '../../stores/uiStore'
import { useScreenState } from '../hooks/useScreenState'

type Tab = 'attr' | 'skill'

export function GrowthScreen() {
  const state = useGameState()
  const mutate = useGame((s) => s.mutate)
  const c = state.career!
  const p = state.players[c.playerId]
  const screen = useCurrentScreen()
  const [tab, setTab] = useScreenState<Tab>('tab', 'attr', screen.params?.tab as Tab | undefined)
  const raise = (k: AttrKey, n = 1) =>
    mutate((st) => {
      for (let i = 0; i < n; i++) if (!raiseAttr(st, k)) break
    })
  return (
    <AppShell title="育成" current="growth" right={<span className="text-[0.8rem] text-ink-dim">育成のしかた: {c.growthMode === 'easy' ? 'かんたん（自動で振る）' : 'じっくり（自分で振る）'}</span>}>
      <div className="absolute inset-0 flex flex-col gap-2 p-2">
        <div className="flex shrink-0 items-center gap-2">
          <div className="seg shrink-0" role="tablist">
            <button role="tab" aria-selected={tab === 'attr'} onClick={() => setTab('attr')}>
              能力
            </button>
            <button role="tab" aria-selected={tab === 'skill'} onClick={() => setTab('skill')}>
              特殊能力 {p.skills.length}
            </button>
          </div>
          {tab === 'skill' && <div className="text-[0.8rem] text-ink-dim">成績で身につく特殊能力の条件と、今季の成績での進み具合です。 <TermHelp id="skillGain" /></div>}
          {tab === 'attr' && <OvrBadge value={ovr(p)} size="lg" />}
          {tab === 'attr' && (
            <div className="text-[0.8rem] text-ink-dim">
              練習と試合で<Term id="growthMode">経験点</Term>がたまります。能力が高いほど、1 上げるのに多く要ります（85 からは特に）。種類の能力がすべて 99
              になると、その種類の経験点は半分がほかの種類に回ります。
            </div>
          )}
          {tab === 'attr' && (
            <div className="seg ml-auto">
              <button aria-selected={c.growthMode === 'easy'} onClick={() => mutate((st) => void (st.career!.growthMode = 'easy'))}>
                かんたん
              </button>
              <button aria-selected={c.growthMode === 'careful'} onClick={() => mutate((st) => void (st.career!.growthMode = 'careful'))}>
                じっくり
              </button>
            </div>
          )}
        </div>
        {tab === 'skill' && <SkillTab state={state} />}
        {tab === 'attr' && (
          <div className="scroll-y grid min-h-0 flex-1 grid-cols-5 gap-2">
            {EXP_KINDS.map((kind) => (
              <div key={kind} className="panel flex flex-col p-2">
                <div className="mb-1 flex items-center justify-between">
                  <span className="text-[0.85rem] font-black" style={{ color: EXP_DEFS[kind].color }}>
                    {EXP_DEFS[kind].name}
                  </span>
                  <span className="num text-[1rem] font-black">{Math.floor(c.exp[kind])}</span>
                </div>
                {EXP_DEFS[kind].attrs.map((k) => {
                  const v = Math.round(p.attr[k])
                  const cost = attrCost(v)
                  const can = c.exp[kind] >= cost && v < 99
                  return (
                    <div key={k} className="border-t border-line/30 py-1.5">
                      <div className="flex items-center gap-1 text-[0.78rem]">
                        <span className="min-w-0 flex-1 truncate">
                          <Term id={`attr:${k}`}>{ATTR_DEFS[k].label}</Term>
                        </span>
                        <RankChip value={v} />
                        <span className="num w-6 text-right font-black">{v}</span>
                      </div>
                      <StatBar value={v} />
                      <div className="mt-1 flex items-center gap-1">
                        <span className="num text-[0.66rem] text-ink-mute">費用 {cost}</span>
                        <button className="btn btn-ghost btn-sm ml-auto !min-h-[1.9rem] !px-2 !text-[0.72rem]" disabled={!can} onClick={() => raise(k)}>
                          +1
                        </button>
                        <button className="btn btn-ghost btn-sm !min-h-[1.9rem] !px-2 !text-[0.72rem]" disabled={!can} onClick={() => raise(k, 5)}>
                          +5
                        </button>
                      </div>
                    </div>
                  )
                })}
              </div>
            ))}
          </div>
        )}
      </div>
    </AppShell>
  )
}
