/** 週を進めている間の進み具合（1 か月・シーズン末まで）。画面が止まって見えないように */
import { createPortal } from 'react-dom'
import { useGame } from '../../stores/gameStore'
import { useOverlayRoot } from '../stage/overlayRoot'

export function AutoProgress() {
  const progress = useGame((s) => s.progress)
  const root = useOverlayRoot()
  if (!progress || progress.total <= 1 || !root) return null
  const pct = Math.round((progress.done / progress.total) * 100)
  return createPortal(
    <div className="absolute inset-0 z-[55] flex items-center justify-center bg-black/45">
      <div className="panel panel-solid w-[22rem] p-4 text-center">
        <div className="text-[0.95rem] font-black">日程を進めています…</div>
        <div className="mt-3 h-2.5 overflow-hidden rounded-full bg-black/10">
          <div className="h-full rounded-full bg-gradient-to-r from-orange to-gold transition-[width] duration-150" style={{ width: `${pct}%` }} />
        </div>
        <div className="num mt-1.5 text-[0.75rem] text-ink-dim">
          {progress.done} / {progress.total} 週
        </div>
      </div>
    </div>,
    root,
  )
}
