/**
 * 成長見込みと総合値の目盛りのデータ（部品は Outlook.tsx）。
 *   outlookOf: 選手の成長見込み（engine/player/projection.ts）。伸びしろが見えない選手（クラブ経営のほかのクラブで調べていない）と主人公は null。
 *     同じ週・同じ伸びしろ・同じ練習なら同じなので覚えておく（一覧で何度も描く）
 *   useLevels: リーグの水準（3 部・2 部・1 部・NBA）
 *   expPhase: 主人公のいまの時期（経験点の入り方と衰え）
 */
import { ageCurve, nowAbs, ovr, type GameState, type GrowthType, type Player } from '../../engine'
import { expMulAt } from '../../engine/career/growth'
import { clubGrowthBias } from '../../engine/club/effects'
import { potShown } from '../../engine/club/transfer'
import { growthOutlook, type GrowthOutlook } from '../../engine/player/projection'
import { leagueLevels } from '../../engine/team/strength'
import { useGameState } from '../../stores/gameStore'

const cache = new Map<string, GrowthOutlook>()

/** full なら 36 歳までの全部（グラフ）、でなければ下がり始めるまで（一覧） */
export function outlookOf(state: GameState, p: Player, full = false): GrowthOutlook | null {
  if (p.isPlayer || p.retired) return null
  const pot = potShown(state, p)
  if (pot === null) return null
  const mine = !!state.club && p.teamId === state.club.teamId
  const bias = mine ? clubGrowthBias(state, p) : undefined
  const key = `${full ? 'f' : 's'}:${p.id}:${nowAbs(state)}:${pot}:${ovr(p)}:${bias ? bias.mul.toFixed(3) + Object.values(bias.attr ?? {}).map((v) => v.toFixed(2)).join(',') : ''}`
  let o = cache.get(key)
  if (!o) {
    if (cache.size > 4000) cache.clear()
    o = growthOutlook(p, nowAbs(state), { pot, bias, short: !full })
    cache.set(key, o)
  }
  return o
}

/** リーグの水準（目盛り）。画面ごとに 1 回 */
export function useLevels() {
  const state = useGameState()
  return leagueLevels(state)
}

/** 主人公のいまの時期（経験点の倍率と衰え）の一言 */
export function expPhase(type: GrowthType, age: number): string {
  const m = expMulAt(type, age)
  const { down } = ageCurve(type, age)
  if (down > 0) return '衰えが始まっている（経験点で能力を保つ時期）'
  if (m >= 1.3) return 'いちばん伸びる時期'
  if (m >= 0.9) return 'よく伸びる時期'
  if (expMulAt(type, age + 2) > m) return 'これから伸びる時期'
  return '伸びがゆるやかになってきた'
}
