/**
 * クラブ経営: クラブ。施設・アリーナ・スタッフ・スポンサー・お金・記録のタブ。
 * 工事は施設とアリーナで 1 つずつ同時に進められる（費用はその場で払う）。
 */
import { useState } from 'react'
import { createPortal } from 'react-dom'
import { absWeekOf } from '../../engine'
import { FACILITY_DEFS, FACILITY_IDS, GOODS_CAMPAIGNS, GRADE_NAMES, HOMETOWNS, HOMETOWN_BY_ID, SUB_TOWNS, subTownUpkeep, type SubTown, LICENSE_SEATS, SEAT_STEPS, SPONSOR_SLOTS, SPONSOR_SLOT_DEFS, STAFF_DEFS, STAFF_ROLES, TICKET_LEVELS } from '../../engine/data/club'
import { acceptSponsor, attendance, goodsCost, goodsIncome, goodsMul, startGoods, ticketPrice, canBuild, clubTeam, facilityUpgrade, gradeUpgrade, hireStaff, ledgerNet, seatUpgrade, sponsorValue, staffCandidates, startBuild, yearlyOutlook } from '../../engine/club/manage'
import type { ClubLedger, StaffRole } from '../../engine/models/club'
import { applyExpansion, canApply, expansionChecks } from '../../engine/club/nba'
import { FAN_REACH, FAN_TITLE, fanCeiling, nearFanCeiling, subTownFans, subTownsOf } from '../../engine/club/fans'
import { RELOCATION, cancelRelocation, closeSubTown, openSubTown, planRelocation, relocationProblem, subTownFee, subTownProblem, subTownSlots } from '../../engine/club/hometown'
import { ConfirmDialog } from '../components/ConfirmDialog'
import { useGame, useGameState } from '../../stores/gameStore'
import { useCurrentScreen } from '../../stores/uiStore'
import { AppShell } from '../layout/AppShell'
import { useScreenState } from '../hooks/useScreenState'
import { Term, TermHelp } from '../components/Term'
import { formatMoneyShort } from '../format'
import { staffPhoto } from '../components/staffPhoto'
import { Initials, Portrait } from '../components/Portrait'

type Tab = 'facility' | 'arena' | 'sales' | 'staff' | 'sponsor' | 'money' | 'history' | 'nba'
const TABS: [Tab, string][] = [
  ['facility', '施設'],
  ['arena', 'アリーナ'],
  ['sales', 'ファン・チケット'],
  ['staff', 'スタッフ'],
  ['sponsor', 'スポンサー'],
  ['money', 'お金'],
  ['history', '記録'],
  ['nba', 'NBA 参入'],
]

const yen = (man: number) => `${formatMoneyShort(Math.round(man))}円`

function Lv({ n, max = 5 }: { n: number; max?: number }) {
  return (
    <span className="flex gap-0.5">
      {Array.from({ length: max }, (_, i) => (
        <span key={i} className={`h-2.5 w-4 rounded-sm ${i < n ? 'bg-gold' : 'bg-black/10'}`} />
      ))}
    </span>
  )
}

function FacilityTab() {
  const state = useGameState()
  const mutate = useGame((s) => s.mutate)
  const c = state.club!
  const free = canBuild(state, 'facility')
  return (
    <>
      <p className="mb-2 text-[0.78rem] text-ink-dim">
        <Term id="facility">施設</Term>はレベルを上げるほど効きます（最大 5）。工事は施設 1 つずつ。毎年の維持費もかかります。
      </p>
      <div className="grid grid-cols-2 gap-2">
        {FACILITY_IDS.map((id) => {
          const d = FACILITY_DEFS[id]
          const lv = c.facilities[id]
          const u = facilityUpgrade(state, id)
          const building = c.building.find((b) => b.facility === id)
          return (
            <div key={id} className="panel-flat flex flex-col gap-1 p-2.5">
              <div className="flex items-center gap-2">
                <span className="text-[0.95rem] font-black">{d.name}</span>
                <span className="num text-[0.75rem] text-ink-dim">Lv{lv}</span>
                <span className="ml-auto">
                  <Lv n={lv} />
                </span>
              </div>
              <div className="text-[0.72rem] text-ink-dim">{d.desc}</div>
              <div className="text-[0.72rem]">
                いま: <span className="font-bold text-good">{lv > 0 ? d.effect(lv) : 'なし'}</span>
                {u && <span className="ml-2 text-ink-dim">→ Lv{u.to}: {d.effect(u.to)}</span>}
              </div>
              {building ? (
                <div className="mt-auto text-[0.75rem] font-bold text-orange">工事中（あと {building.doneAbs - absWeekOf(state.season, state.week)} 週）</div>
              ) : u ? (
                <button className="btn btn-ghost btn-sm mt-auto" disabled={!free || c.money < u.cost} onClick={() => mutate((st) => void startBuild(st, 'facility', id))}>
                  Lv{u.to} にする（{yen(u.cost)}・{u.weeks} 週）
                </button>
              ) : (
                <div className="mt-auto text-[0.75rem] text-gold">最高のレベル</div>
              )}
            </div>
          )
        })}
      </div>
      {!free && <div className="mt-2 text-[0.72rem] text-ink-mute">いまは別の施設の工事中です。</div>}
    </>
  )
}

const man = (n: number) => `${(n / 10000).toLocaleString()} 万`

/** ファンの数と天井（街のファン＋上の部・優勝で広がる街の外のファン） */
function FansPanel() {
  const state = useGameState()
  const c = state.club!
  const team = clubTeam(state)
  const town = HOMETOWN_BY_ID[c.hometown]
  const f = fanCeiling(state)
  const near = nearFanCeiling(state)
  const lg = team.league
  const ways: string[] = []
  if (!f.nba) {
    if ((c.subTowns?.length ?? 0) < subTownSlots(state)) ways.push('近くの街でもホームの試合を開く（下）')
    if (lg === 'JBL3') ways.push(`2 部に上がる +${man(FAN_REACH.JBL2 ?? 0)}`)
    if (lg !== 'JBL1') ways.push(`1 部に上がる +${man((FAN_REACH.JBL1 ?? 0) - (FAN_REACH[lg] ?? 0))}`)
    if (f.titles < FAN_TITLE.max) ways.push(`1 部の優勝 +${man(FAN_TITLE.jbl1)}`, `全日本選手権・東アジアの優勝 +${man(FAN_TITLE.cup)}`)
  }
  return (
    <div>
      <div className="panel-head mb-1">
        <Term id="fans">ファン</Term>
      </div>
      <div className="flex items-baseline gap-2 text-[0.8rem]">
        <span className="num text-[1.2rem] font-black">{c.fans.toLocaleString()}</span>人
        <span className="text-ink-dim">
          ／ 天井 <span className="num font-bold text-ink">{f.total.toLocaleString()}</span> 人
        </span>
        {near && <span className="font-black text-orange">天井に近い</span>}
      </div>
      <div className="my-1 h-2 overflow-hidden rounded-full bg-black/10">
        <div className={`h-full rounded-full ${near ? 'bg-orange' : 'bg-gold'}`} style={{ width: `${Math.min(100, (c.fans / f.total) * 100)}%` }} />
      </div>
      <div className="num text-[0.72rem] text-ink-dim">
        {f.nba ? (
          <>NBA のチームなので、日本じゅうから応援されます（{man(f.total)}人まで）。</>
        ) : (
          <>
            天井の内訳: 街のファン（{town.city}の人口 {town.pop} 万の 3 割）{f.local.toLocaleString()}
            {f.sub > 0 && <>・近くの街（{subTownsOf(state).map((t) => t.city).join('・')}）{f.sub.toLocaleString()}</>}・街の外（{state.leagues[lg].name}）{f.reach.toLocaleString()}・優勝 {f.titles.toLocaleString()}
          </>
        )}
      </div>
      {ways.length > 0 && (
        <div className="mt-0.5 text-[0.72rem]">
          <span className="font-bold">天井を広げるには</span>: {ways.join('・')}（優勝のぶんは {man(FAN_TITLE.max)}まで。シーズンの終わりに記録に残ったもの）
        </div>
      )}
      <p className="mt-0.5 text-[0.68rem] text-ink-mute">ファンは人気が高いほど増え、天井に近づくほどゆっくりになります。観客とグッズの売り上げのもと。降格して天井が下がると、超えたぶんは少しずつ減ります。</p>
    </div>
  )
}

/** 近くの街でもホームの試合を開く（ホームタウンを広げる） */
function SubTownsPanel() {
  const state = useGameState()
  const mutate = useGame((s) => s.mutate)
  const c = state.club!
  const town = HOMETOWN_BY_ID[c.hometown]
  const [closing, setClosing] = useState<SubTown | null>(null)
  const [msg, setMsg] = useState<string | null>(null)
  const open = c.subTowns ?? []
  const nba = clubTeam(state).league === 'NBA'
  if (nba && !open.length) return null
  const fee = subTownFee(state)
  return (
    <div>
      <div className="panel-head mb-1">
        <Term id="subTown">ホームタウンを広げる</Term>
        {!nba && <span className="num ml-1 text-[0.75rem] text-ink-dim">（{open.length} / {subTownSlots(state)}）</span>}
      </div>
      <p className="mb-1 text-[0.72rem] text-ink-dim">
        {nba
          ? 'NBA では日本じゅうから応援されるので、近くの街の効き目はありません（会場費もかかりません）。'
          : `${town.city}の近くの街でも、ホームの試合を年に数試合開きます。その街の人口の 15% ぶんファンの天井が上がり、スポンサーの相場も少し上がります。2 部で 1 つ、1 部で 2 つまで。開く費用は 1 つ目 5,000 万円・2 つ目 1 億円、毎年の会場費は維持費に入ります。`}
      </p>
      {msg && <div className="mb-1 text-[0.75rem] font-bold text-bad">{msg}</div>}
      <div className="grid grid-cols-3 gap-2">
        {(SUB_TOWNS[c.hometown] ?? []).map((t) => {
          const on = open.includes(t.id)
          const why = on ? null : subTownProblem(state, t.id)
          if (nba && !on) return null
          return (
            <div key={t.id} className={`flex flex-col rounded-xl border px-2.5 py-2 ${on ? 'border-gold bg-gold/15' : 'border-line/60 bg-black/[0.03]'}`}>
              <div className="flex items-baseline gap-1">
                <span className="text-[0.9rem] font-black">{t.city}</span>
                <span className="num text-[0.68rem] text-ink-dim">人口 {t.pop} 万</span>
                {on && <span className="ml-auto text-[0.68rem] font-black text-gold">開いている</span>}
              </div>
              <div className="num text-[0.7rem]">ファンの天井 +{subTownFans(t).toLocaleString()} 人</div>
              <div className="num mb-1 text-[0.7rem]">会場費 年 {yen(subTownUpkeep(t))}</div>
              {on ? (
                <button className="btn btn-ghost btn-sm mt-auto" onClick={() => setClosing(t)}>
                  やめる
                </button>
              ) : (
                <button className="btn btn-gold btn-sm mt-auto" disabled={!!why} onClick={() => mutate((st) => setMsg(openSubTown(st, t.id)))}>
                  <span className="text-[0.72rem]">{why ?? `開く（${yen(fee)}）`}</span>
                </button>
              )}
            </div>
          )
        })}
      </div>
      <ConfirmDialog
        open={!!closing}
        title={`${closing?.city ?? ''}でのホームの試合をやめますか？`}
        text="開いたときの費用は戻りません。もう一度開くときは、また費用がかかります。天井を超えたぶんのファンは少しずつ減ります。"
        ok="やめる"
        cancel="続ける"
        onOk={() => {
          const t = closing
          setClosing(null)
          if (t) mutate((st) => closeSubTown(st, t.id))
        }}
        onCancel={() => setClosing(null)}
      />
    </div>
  )
}

/** ホームタウンを別の街へ移す（移転。決めておいて、シーズンの終わりに移る） */
function RelocationPanel() {
  const state = useGameState()
  const mutate = useGame((s) => s.mutate)
  const c = state.club!
  const town = HOMETOWN_BY_ID[c.hometown]
  const [open, setOpen] = useState(false)
  if (clubTeam(state).league === 'NBA') return null
  const r = c.relocation
  return (
    <div>
      <div className="panel-head mb-1">
        <Term id="relocation">ホームタウンを移す（移転）</Term>
      </div>
      {r ? (
        <div className="flex items-center gap-2 rounded-lg bg-orange/10 px-2 py-1.5 text-[0.78rem]">
          <span className="flex-1">
            シーズンの終わりに<span className="font-black">{HOMETOWN_BY_ID[r.to].city}</span>へ移転します（移転費 {yen(r.fee)} は払ってあります。取り消すと戻ります）。
          </span>
          <button className="btn btn-ghost btn-sm shrink-0" onClick={() => mutate((st) => cancelRelocation(st))}>
            取り消す
          </button>
        </div>
      ) : (
        <div className="flex items-center gap-2">
          <p className="flex-1 text-[0.72rem] text-ink-dim">
            {town.city}から別の街へクラブを移します（移るのはシーズンの終わり）。ファンは 3 割しか残らず、人気 −{RELOCATION.pop}・オーナーの信頼 −{RELOCATION.trust}、移転費 {yen(RELOCATION.fee)}。アリーナの席数はそのままで、近くの街はやめることになります。気軽には使えない最後の手段です。
          </p>
          <button className="btn btn-ghost btn-sm shrink-0" onClick={() => setOpen(true)}>
            移転先を見る
          </button>
        </div>
      )}
      {open && <RelocateDialog onClose={() => setOpen(false)} />}
    </div>
  )
}

function RelocateDialog({ onClose }: { onClose: () => void }) {
  const state = useGameState()
  const mutate = useGame((s) => s.mutate)
  const c = state.club!
  const [pick, setPick] = useState<string | null>(null)
  const [msg, setMsg] = useState<string | null>(null)
  const root = document.getElementById('overlay-root')
  if (!root) return null
  const to = pick ? HOMETOWN_BY_ID[pick] : undefined
  const why = pick ? relocationProblem(state, pick) : null
  return createPortal(
    <div className="anim-fade absolute inset-0 z-[60] flex items-center justify-center bg-black/55 p-3" onClick={onClose}>
      <div className="panel flex max-h-full w-[46rem] max-w-full flex-col gap-2 p-3" onClick={(e) => e.stopPropagation()}>
        <div className="text-[0.95rem] font-black">移転先を選ぶ</div>
        <div className="scroll-y grid min-h-0 flex-1 grid-cols-3 gap-1.5">
          {HOMETOWNS.filter((h) => h.id !== c.hometown).map((h) => (
            <button key={h.id} onClick={() => setPick(h.id)} className={`rounded-lg border px-2 py-1.5 text-left ${pick === h.id ? 'border-gold bg-gold/15' : 'border-line/60 bg-black/[0.03]'}`}>
              <span className="flex items-baseline gap-1">
                <span className="text-[0.85rem] font-black">{h.city}</span>
                <span className="text-[0.64rem] text-ink-dim">{h.pref}</span>
                <span className="num ml-auto text-[0.64rem] text-ink-dim">人口 {h.pop} 万・熱 {'★'.repeat(h.passion)}</span>
              </span>
              <span className="block text-[0.62rem] leading-snug text-ink-dim">{h.desc}</span>
            </button>
          ))}
        </div>
        <div className="flex items-center gap-2 border-t border-line/40 pt-2 text-[0.75rem]">
          <div className="flex-1">
            {to ? (
              <>
                <span className="font-black">{to.city}</span>へ移ると: チーム名は「{to.city}・{clubTeam(state).nickname}」・街のファンの天井 {(to.pop * 3000).toLocaleString()} 人・残るファン 約 {Math.round(c.fans * RELOCATION.fanKeep).toLocaleString()} 人・人気 −{RELOCATION.pop}・信頼 −{RELOCATION.trust}・移転費 {yen(RELOCATION.fee)}
              </>
            ) : (
              <span className="text-ink-dim">移転先の街を選んでください。移るのはシーズンの終わりで、それまでは取り消せます。</span>
            )}
            {msg && <div className="font-bold text-bad">{msg}</div>}
          </div>
          <button className="btn btn-ghost btn-sm shrink-0" onClick={onClose}>
            閉じる
          </button>
          <button
            className="btn btn-gold btn-sm shrink-0"
            disabled={!pick || !!why}
            onClick={() =>
              mutate((st) => {
                const e = planRelocation(st, pick!)
                setMsg(e)
                if (!e) onClose()
              })
            }
          >
            <span className="text-[0.75rem]">{why ?? '移転を決める'}</span>
          </button>
        </div>
      </div>
    </div>,
    root,
  )
}

/** ファンの数、近くの街、移転、チケットの値段の段、グッズの企画 */
function SalesTab() {
  const state = useGameState()
  const mutate = useGame((s) => s.mutate)
  const c = state.club!
  const team = clubTeam(state)
  const [msg, setMsg] = useState<string | null>(null)
  const now = absWeekOf(state.season, state.week)
  const level = c.ticketLevel ?? 1
  const avgOpp = { rep: 40 } as Parameters<typeof attendance>[1]
  const active = c.goods && c.goods.until >= now ? GOODS_CAMPAIGNS.find((g) => g.id === c.goods!.id) : undefined
  return (
    <div className="space-y-3">
      <FansPanel />
      <SubTownsPanel />
      <RelocationPanel />
      <div>
        <div className="panel-head mb-1">
          <Term id="ticketLevel">チケットの値段</Term>
        </div>
        <p className="mb-1 text-[0.72rem] text-ink-dim">ホームの試合の観客と収入、人気が変わります（{team.arena.name}・{team.arena.capacity.toLocaleString()} 席。見込みはふつうの相手のとき）。</p>
        <div className="grid grid-cols-4 gap-2">
          {TICKET_LEVELS.map((t, i) => {
            const att = attendance(state, avgOpp, 1, 1, t)
            const per = att * ticketPrice(state, t)
            return (
              <button key={t.name} onClick={() => mutate((st) => void (st.club!.ticketLevel = i))} className={`rounded-xl border px-2.5 py-2 text-left ${level === i ? 'border-gold bg-gold/15' : 'border-line/60 bg-black/[0.03]'}`}>
                <div className="text-[0.9rem] font-black">{t.name}</div>
                <div className="num text-[0.7rem]">
                  観客 {att.toLocaleString()} 人{att >= team.arena.capacity ? '（満員）' : ''}
                </div>
                <div className="num text-[0.7rem]">1 試合 {yen(per)}</div>
                <div className="mt-0.5 text-[0.64rem] leading-snug text-ink-dim">{t.desc}</div>
              </button>
            )
          })}
        </div>
      </div>
      <div>
        <div className="panel-head mb-1">
          グッズの企画（今の売り上げ 年 {yen(goodsIncome(state))}
          {goodsMul(state) > 1 ? `・企画で ×${goodsMul(state)}` : ''}）
        </div>
        {active && (
          <div className="mb-1 rounded-lg bg-gold/10 px-2 py-1 text-[0.78rem]">
            「{active.name}」を売っています（あと {c.goods!.until - now + 1} 週）
          </div>
        )}
        {msg && <div className="mb-1 text-[0.75rem] font-bold text-bad">{msg}</div>}
        <div className="grid grid-cols-3 gap-2">
          {GOODS_CAMPAIGNS.map((g) => {
            const cost = goodsCost(state, g.id)
            return (
              <div key={g.id} className="panel-flat flex flex-col gap-1 p-2.5">
                <div className="text-[0.88rem] font-black">{g.name}</div>
                <div className="text-[0.68rem] leading-snug text-ink-dim">{g.desc}</div>
                <div className="num text-[0.72rem]">
                  売り上げ ×{g.mul}・{g.weeks} 週{g.pop ? `・人気 +${g.pop}` : ''}
                </div>
                <button className="btn btn-ghost btn-sm mt-auto" disabled={!!active || c.money < cost} onClick={() => mutate((st) => setMsg(startGoods(st, g.id)))}>
                  始める（{yen(cost)}）
                </button>
              </div>
            )
          })}
        </div>
        <p className="mt-1 text-[0.68rem] text-ink-mute">費用は、期間中に増える売り上げの 6 割。広報室のレベルとファンの数が多いほど売り上げも費用も大きくなります。</p>
      </div>
    </div>
  )
}

function ArenaTab() {
  const state = useGameState()
  const mutate = useGame((s) => s.mutate)
  const c = state.club!
  const team = clubTeam(state)
  const free = canBuild(state, 'arena')
  const seat = seatUpgrade(state)
  const grade = gradeUpgrade(state)
  const out = yearlyOutlook(state)
  return (
    <div className="grid grid-cols-2 gap-2">
      <div className="panel-flat flex flex-col gap-1.5 p-3">
        <div className="text-[1.05rem] font-black">{team.arena.name}</div>
        <div className="num text-[0.85rem]">
          {team.arena.capacity.toLocaleString()} 席・<Term id="arenaGrade">格</Term> {c.arenaGrade}（{GRADE_NAMES[c.arenaGrade]}）
        </div>
        <div className="text-[0.78rem] text-ink-dim">観客の見込み 1 試合 {out.perGame.toLocaleString()} 人（ファン・人気・格・相手で変わる。席数が上限）</div>
        <div className="mt-1 text-[0.78rem]">
          <Term id="license">ライセンス</Term>:
          {(['JBL2', 'JBL1'] as const).map((lg) => (
            <span key={lg} className={`ml-2 font-bold ${team.arena.capacity >= (LICENSE_SEATS[lg] ?? 0) ? 'text-good' : 'text-bad'}`}>
              {lg === 'JBL2' ? '2 部' : '1 部'} {(LICENSE_SEATS[lg] ?? 0).toLocaleString()} 席 {team.arena.capacity >= (LICENSE_SEATS[lg] ?? 0) ? '✓' : '✕'}
            </span>
          ))}
        </div>
        <div className="mt-1 text-[0.7rem] text-ink-mute">席数の段: {SEAT_STEPS.map((s) => s.seats.toLocaleString()).join(' → ')}</div>
      </div>
      <div className="flex flex-col gap-2">
        <div className="panel-flat flex flex-col gap-1 p-3">
          <div className="text-[0.9rem] font-black">増席</div>
          {seat ? (
            <>
              <div className="text-[0.75rem] text-ink-dim">
                {seat.label}: {team.arena.capacity.toLocaleString()} → {seat.seats.toLocaleString()} 席
              </div>
              <button className="btn btn-ghost btn-sm" disabled={!free || c.money < seat.cost} onClick={() => mutate((st) => void startBuild(st, 'seats'))}>
                工事する（{yen(seat.cost)}・{seat.weeks} 週）
              </button>
            </>
          ) : (
            <div className="text-[0.75rem] text-gold">これ以上は広げられません</div>
          )}
        </div>
        <div className="panel-flat flex flex-col gap-1 p-3">
          <div className="text-[0.9rem] font-black">格を上げる</div>
          {grade ? (
            <>
              <div className="text-[0.75rem] text-ink-dim">
                {GRADE_NAMES[c.arenaGrade]} → {GRADE_NAMES[grade.to]}（観客・チケットの値段・人気が上がる）
              </div>
              <button className="btn btn-ghost btn-sm" disabled={!free || c.money < grade.cost} onClick={() => mutate((st) => void startBuild(st, 'grade'))}>
                工事する（{yen(grade.cost)}・{grade.weeks} 週）
              </button>
            </>
          ) : (
            <div className="text-[0.75rem] text-gold">最高の格</div>
          )}
        </div>
        {!free && <div className="text-[0.72rem] text-orange">アリーナは工事中です: {c.building.filter((b) => b.kind !== 'facility').map((b) => `${b.label}（あと ${b.doneAbs - absWeekOf(state.season, state.week)} 週）`).join('・')}</div>}
      </div>
    </div>
  )
}

function StaffTab() {
  const state = useGameState()
  const mutate = useGame((s) => s.mutate)
  const c = state.club!
  return (
    <div className="space-y-3">
      <p className="text-[0.78rem] text-ink-dim">
        <Term id="staffHC">スタッフ</Term>と契約すると、契約金として年俸の半分をその場で払います。候補はシーズンごとに変わります。今の人とは契約を終えます。
      </p>
      {STAFF_ROLES.map((role: StaffRole) => {
        const d = STAFF_DEFS[role]
        const cur = c.staff[role]
        return (
          <div key={role} className="panel-flat p-2.5">
            <div className="flex items-center gap-2">
              <span className="text-[0.95rem] font-black">{d.name}</span>
              <span className="text-[0.72rem] text-ink-dim">{d.desc}</span>
            </div>
            <div className="mt-1 flex items-center gap-2 text-[0.8rem]">
              {cur && <Portrait id={staffPhoto(cur.name)} kind="face" className="face-round h-9 w-9 shrink-0" fallback={<Initials name={cur.name} className="h-full w-full" />} />}
              {cur ? (
                <span>
                  いま: <span className="font-black">{cur.name}</span>（腕 <span className="num font-black text-gold">{cur.skill}</span>・{cur.note}・年俸 {yen(cur.salary)}・残り {cur.years} 年）<span className={`ml-1 ${cur.skill >= 50 ? 'text-good' : 'text-bad'}`}>{d.effect(cur.skill)}</span>
                </span>
              ) : (
                <span className="font-bold text-bad">空いています</span>
              )}
            </div>
            <div className="mt-1 grid grid-cols-5 gap-1">
              {staffCandidates(state, role).map((s) => (
                <button key={s.name} disabled={c.money < s.salary / 2 || cur?.name === s.name} onClick={() => mutate((st) => void hireStaff(st, s))} className="rounded-lg border border-line/50 bg-black/[0.04] px-1.5 py-1 text-left hover:bg-black/5 disabled:opacity-45">
                  <div className="flex items-center gap-1">
                    <Portrait id={staffPhoto(s.name)} kind="face" className="face-round h-6 w-6 shrink-0" fallback={<Initials name={s.name} className="h-full w-full" />} />
                    <span className="truncate text-[0.74rem] font-black">{s.name}</span>
                  </div>
                  <div className="num text-[0.68rem]">
                    腕 <span className="font-black text-gold">{s.skill}</span>・{s.years} 年
                  </div>
                  <div className="num text-[0.64rem] text-ink-dim">年 {yen(s.salary)}</div>
                  <div className="truncate text-[0.6rem] text-ink-mute">{s.note}</div>
                </button>
              ))}
            </div>
          </div>
        )
      })}
    </div>
  )
}

function SponsorTab() {
  const state = useGameState()
  const mutate = useGame((s) => s.mutate)
  const c = state.club!
  return (
    <div className="grid grid-cols-2 gap-2">
      {SPONSOR_SLOTS.map((slot) => {
        const d = SPONSOR_SLOT_DEFS[slot]
        const cur = c.sponsors.find((s) => s.slot === slot)
        const offers = c.sponsorOffers.filter((o) => o.slot === slot)
        return (
          <div key={slot} className={`panel-flat flex flex-col gap-1 p-2.5 ${cur ? 'border-gold/50' : ''}`}>
            <div className="flex items-center gap-2">
              <span className="text-[0.92rem] font-black">{d.name}</span>
              <span className="num ml-auto text-[0.68rem] text-ink-dim">相場 年 {yen(sponsorValue(state, slot))}</span>
            </div>
            <div className="text-[0.7rem] text-ink-dim">{d.desc}</div>
            {cur ? (
              <div className="text-[0.8rem]">
                <span className="font-black">{cur.company}</span>・年 <span className="num font-black text-gold">{yen(cur.annual)}</span>
                <span className="text-ink-dim">（{cur.until <= state.season ? '今季まで' : `あと ${cur.until - state.season + 1} シーズン`}）</span>
              </div>
            ) : offers.length ? (
              offers.map((o) => (
                <button key={o.id} className="btn btn-ghost btn-sm justify-between" onClick={() => mutate((st) => void acceptSponsor(st, o.id))}>
                  <span>{o.company}</span>
                  <span className="num">
                    年 {yen(o.annual)}・{o.until - state.season + 1} 年
                  </span>
                </button>
              ))
            ) : (
              <div className="text-[0.75rem] text-ink-mute">話を待っています（空いた枠には 8 週ごとに話が来ます）</div>
            )}
          </div>
        )
      })}
      <div className="col-span-2 text-[0.7rem] text-ink-mute">
        <Term id="sponsor">スポンサー</Term>の相場は、リーグ・人気・街の大きさ・広報室で決まります。長い契約は少し安くなります。
      </div>
    </div>
  )
}

const LEDGER_ROWS: [keyof ClubLedger, string, 1 | -1][] = [
  ['ticket', '入場料', 1],
  ['dist', '配分金', 1],
  ['sponsor', 'スポンサー', 1],
  ['goods', 'グッズ', 1],
  ['prize', '賞金', 1],
  ['wages', '選手の年俸', -1],
  ['staff', 'スタッフの年俸', -1],
  ['upkeep', '施設とアリーナの維持費', -1],
  ['travel', '遠征費', -1],
  ['build', '工事', -1],
  ['transfer', '移籍金・契約解除', 1],
  ['other', '運営費・契約金など', 1],
]

function MoneyTab() {
  const state = useGameState()
  const c = state.club!
  const out = yearlyOutlook(state)
  const season = c.ledger.filter((l) => Math.floor(l.abs / 52) === state.season)
  const sum = (k: keyof ClubLedger) => season.reduce((s, l) => s + l[k], 0)
  const total = season.reduce((s, l) => s + ledgerNet(l), 0)
  return (
    <div className="grid grid-cols-2 gap-3">
      <div>
        <div className="panel-head mb-1">今シーズン（ここまで）</div>
        <table className="num w-full text-[0.8rem]">
          <tbody>
            {LEDGER_ROWS.map(([k, label, sign]) => (
              <tr key={k} className="border-b border-line/30">
                <td className="py-0.5">{label}</td>
                <td className={`text-right ${sign < 0 || sum(k) < 0 ? 'text-bad' : ''}`}>{yen(sign * sum(k))}</td>
              </tr>
            ))}
            <tr>
              <td className="py-1 font-black">収支</td>
              <td className={`text-right font-black ${total >= 0 ? 'text-gold' : 'text-bad'}`}>{yen(total)}</td>
            </tr>
          </tbody>
        </table>
      </div>
      <div>
        <div className="panel-head mb-1">1 年の見込み（今の状態のまま）</div>
        <table className="num w-full text-[0.8rem]">
          <tbody>
            {(
              [
                ['入場料', out.ticket],
                [<Term id="distribution">配分金</Term>, out.dist],
                ['スポンサー', out.sponsor],
                ['グッズ', out.goods],
                ['選手の年俸', -out.wages],
                ['スタッフの年俸', -out.staff],
                ['維持費', -out.upkeep],
                ['遠征費', -out.travel],
                ['運営費', -out.ops],
              ] as [React.ReactNode, number][]
            ).map(([label, v], i) => (
              <tr key={i} className="border-b border-line/30">
                <td className="py-0.5">{label}</td>
                <td className={`text-right ${v < 0 ? 'text-bad' : ''}`}>{yen(v)}</td>
              </tr>
            ))}
            <tr>
              <td className="py-1 font-black">1 年の収支</td>
              <td className={`text-right font-black ${out.net >= 0 ? 'text-gold' : 'text-bad'}`}>{yen(out.net)}</td>
            </tr>
          </tbody>
        </table>
        <div className="mt-2 text-[0.7rem] text-ink-mute">
          資金がマイナスのまま 8 週続くと<Term id="bailout">オーナーが立て直します</Term>（あと {Math.max(0, 2 - c.bailouts)} 回まで）。
        </div>
      </div>
    </div>
  )
}

function NbaTab() {
  const state = useGameState()
  const mutate = useGame((s) => s.mutate)
  const c = state.club!
  const team = clubTeam(state)
  const checks = expansionChecks(state)
  if (team.league === 'NBA')
    return (
      <div className="panel-flat p-4 text-[0.85rem]">
        <div className="text-[1.1rem] font-black text-gold">{team.name}は NBA のチーム</div>
        <div className="mt-1 text-ink-dim">
          {state.startYear + (c.nba?.joined ?? state.season)} 年から NBA で戦っています（{state.leagues.NBA.teamIds.length} チーム・{team.conf === 'W' ? '西' : '東'}カンファレンス・{team.div}）。登録は 15 人、外国籍の枠はありません。FA は<Term id="salaryCap">サラリーキャップ</Term>の空きか最低保証だけ、<Term id="luxuryTax">ぜいたく税</Term>はシーズンの終わりに。選手はトレードで集めます（「補強・編成」の画面）。
        </div>
      </div>
    )
  return (
    <div className="grid grid-cols-2 gap-3">
      <div>
        <div className="panel-head mb-1">
          <Term id="expansion">拡張参入</Term>の条件
        </div>
        {checks.map((x) => (
          <div key={x.label} className="flex items-center gap-2 border-b border-line/30 py-1 text-[0.82rem]">
            <span className={`w-5 text-center font-black ${x.ok ? 'text-good' : 'text-bad'}`}>{x.ok ? '○' : '×'}</span>
            <span className="flex-1">{x.label}</span>
            <span className="num text-ink-dim">{x.now}</span>
          </div>
        ))}
      </div>
      <div className="flex flex-col gap-2 text-[0.8rem] leading-relaxed">
        <div className="panel-flat p-3">
          NBA は、新しいチームを 2 つずつ迎えます。条件をすべて満たしたら申請でき、シーズンの終わりに審査があります。承認されると参入金を払い、次のシーズンから NBA へ（ナッシュビルのチームも一緒に加わります）。
          <br />
          参入した年は、ほかのチームの守られていない選手から指名できる「エクスパンションドラフト」があります（第 13 週まで）。
        </div>
        {c.nba?.approved !== undefined ? (
          <div className="font-black text-gold">承認されました。次のシーズンから NBA です。</div>
        ) : c.nba ? (
          <div className="font-black text-gold">申請しました。シーズンの終わりに審査があります（条件を満たしたままにしておく）。</div>
        ) : (
          <button className="btn btn-gold h-[3rem]" disabled={!canApply(state)} onClick={() => mutate((st) => void applyExpansion(st))}>
            NBA への参入を申請する
          </button>
        )}
      </div>
    </div>
  )
}

function HistoryTab() {
  const state = useGameState()
  const c = state.club!
  if (!c.history.length) return <div className="text-[0.82rem] text-ink-dim">まだ記録はありません（シーズンの終わりに残ります）。</div>
  const titles = c.history.filter((h) => h.note.includes('優勝') && !h.note.includes('準優勝'))
  const best = [...c.history].sort((a, b) => b.w / Math.max(1, b.w + b.l) - a.w / Math.max(1, a.w + a.l))[0]
  return (
    <div className="space-y-3">
      <div className="num grid grid-cols-4 gap-2 text-[0.8rem]">
        <div className="stat-chip px-2 py-1">シーズン <span className="font-black">{c.history.length}</span></div>
        <div className="stat-chip px-2 py-1">優勝 <span className="font-black text-gold">{titles.length}</span></div>
        <div className="stat-chip px-2 py-1">最高の成績 <span className="font-black">{best.w}-{best.l}</span>（{state.startYear + best.season}）</div>
        <div className="stat-chip px-2 py-1">ファンの最多 <span className="font-black">{Math.max(...c.history.map((h) => h.fans)).toLocaleString()}</span></div>
      </div>
      {(c.retiredNumbers?.length ?? 0) > 0 && (
        <div>
          <div className="panel-head mb-1">永久欠番</div>
          <div className="flex flex-wrap gap-1.5">
            {c.retiredNumbers!.map((r) => (
              <div key={r.number} className="stat-chip flex items-center gap-2 px-2 py-1">
                <span className="num text-[1.3rem] font-black text-gold">{r.number}</span>
                <span className="text-[0.75rem]">
                  {r.name}
                  <span className="ml-1 text-[0.66rem] text-ink-dim">{state.startYear + r.season} 年度</span>
                </span>
              </div>
            ))}
          </div>
        </div>
      )}
      {c.legends.length > 0 && (
        <div>
          <div className="panel-head mb-1">クラブの殿堂</div>
          <div className="grid grid-cols-3 gap-1.5">
            {c.legends.map((l) => (
              <div key={l.name + l.season} className="panel-flat px-2 py-1.5 text-[0.75rem]">
                <div className="font-black text-gold">
                  {l.name}
                  {l.youth && <span className="ml-1 rounded bg-orange/25 px-1 text-[0.6rem] text-orange">ユース出身</span>}
                </div>
                <div className="num text-ink-dim">
                  {l.pos}・{l.seasons} シーズン・{l.pts.toLocaleString()} 点・{l.reb.toLocaleString()} リバウンド・{l.ast.toLocaleString()} アシスト
                </div>
              </div>
            ))}
          </div>
        </div>
      )}
    <table className="num w-full text-[0.8rem]">
      <thead className="text-[0.7rem] text-ink-dim">
        <tr>
          <th className="text-left">年</th>
          <th className="text-left">リーグ</th>
          <th>順位</th>
          <th>勝敗</th>
          <th>ファン</th>
          <th className="text-right">資金</th>
          <th />
        </tr>
      </thead>
      <tbody>
        {[...c.history].reverse().map((h) => (
          <tr key={h.season} className="border-b border-line/30">
            <td className="py-0.5">{state.startYear + h.season}</td>
            <td>{h.league}</td>
            <td className="text-center">{h.rank}</td>
            <td className="text-center">
              {h.w}-{h.l}
            </td>
            <td className="text-center">{h.fans.toLocaleString()}</td>
            <td className="text-right">{yen(h.money)}</td>
            <td className="pl-2 font-bold text-gold">{h.note}</td>
          </tr>
        ))}
      </tbody>
    </table>
    </div>
  )
}

export function ClubScreen() {
  const state = useGameState()
  const screen = useCurrentScreen()
  const [tab, setTab] = useScreenState<Tab>('tab', 'facility', screen.params?.tab as Tab | undefined)
  const team = clubTeam(state)
  const c = state.club!
  return (
    <AppShell
      title="クラブ"
      current="club"
      color={team.colors.primary}
      right={
        <span className={`num text-[0.85rem] font-bold ${c.money < 0 ? 'text-bad' : 'text-gold'}`}>
          資金 {yen(c.money)} <TermHelp id="bailout" />
        </span>
      }
    >
      <div className="absolute inset-0 flex flex-col gap-2 p-2">
        <div className="seg shrink-0 self-start">
          {TABS.map(([id, label]) => (
            <button key={id} aria-selected={tab === id} onClick={() => setTab(id)}>
              {label}
              {id === 'sponsor' && c.sponsorOffers.length > 0 && <span className="ml-1 rounded-full bg-gold px-1.5 text-[0.62rem] font-black text-[#2a1a00]">!</span>}
            </button>
          ))}
        </div>
        <div className="panel scroll-y min-h-0 flex-1 p-3">
          {tab === 'facility' && <FacilityTab />}
          {tab === 'arena' && <ArenaTab />}
          {tab === 'sales' && <SalesTab />}
          {tab === 'staff' && <StaffTab />}
          {tab === 'sponsor' && <SponsorTab />}
          {tab === 'money' && <MoneyTab />}
          {tab === 'history' && <HistoryTab />}
          {tab === 'nba' && <NbaTab />}
        </div>
      </div>
    </AppShell>
  )
}
