/**
 * 説明（チュートリアル）: 画面を初めて開いたとき・制度に初めて出会ったときに、代理人の藤堂がひとこと説明する。
 * 見たものは端末に覚える（settingsStore の tipsSeen）。設定でオフにしたり、もう一度見たりできる。
 * 中身は tips.ts（画面の id か「sys:制度」の id）。
 */
import { createPortal } from 'react-dom'
import { Portrait, Initials } from '../components/Portrait'
import { useSettings } from '../../stores/settingsStore'
import { useOverlayRoot } from '../stage/overlayRoot'
import { TIPS } from './tips'

export function Tip({ id: screen, club = false }: { id: string; club?: boolean }) {
  const show = useSettings((s) => s.showTips)
  const seen = useSettings((s) => s.tipsSeen)
  const set = useSettings((s) => s.set)
  const root = useOverlayRoot()
  // クラブ経営は「club:画面」を先に。どちらのモードでも同じ説明（用語集など）は共通の id
  const id = club && TIPS[`club:${screen}`] ? `club:${screen}` : screen
  const base = TIPS[id]
  if (!base || (club && base.careerOnly) || !show || seen.includes(id) || !root) return null
  // クラブ経営では、藤堂は代理人ではなく経営のアドバイザー
  const tip = club && base.speaker === 'todo_maiko' ? { ...base, speakerName: 'アドバイザーの藤堂' } : base
  const close = () => set({ tipsSeen: [...seen, id] })
  return createPortal(
    <div className="anim-rise pointer-events-none absolute left-[5.4rem] right-3 top-[3.4rem] z-40 flex items-start gap-2">
      <Portrait id={tip.speaker} kind="face" className="face-round pointer-events-auto h-12 w-12 shrink-0 border-2 border-gold/70" fallback={<Initials name={tip.speakerName} className="h-full w-full" />} />
      <div className="panel pointer-events-auto max-w-[34rem] flex-1 rounded-tl-none p-3 shadow-2xl">
        <div className="mb-0.5 text-[0.78rem] font-black text-gold">
          {tip.speakerName}より ── {tip.title}
        </div>
        {tip.lines.map((l, i) => (
          <p key={i} className="text-[0.8rem] leading-snug">
            {l}
          </p>
        ))}
        <div className="mt-2 flex gap-2">
          <button className="btn btn-gold btn-sm flex-1" onClick={close}>
            わかった
          </button>
          <button className="btn btn-ghost btn-sm" onClick={() => set({ showTips: false })}>
            説明はもういい
          </button>
        </div>
      </div>
    </div>,
    root,
  )
}
