/**
 * 試合の流れのグラフ: 1 分ごとの点差（自分のチームが上）。リードしている時間は自分の色、されている時間は相手の色で塗る。
 * クォーター（大学はハーフ）の区切りに縦の線、最大のリードを右に出す。
 */
import { RULES } from '../../engine/data/rules'
import type { Fixture } from '../../engine/models/league'
import type { GameState } from '../../engine'

export function FlowGraph({ state, f, teamId }: { state: GameState; f: Fixture; teamId: number }) {
  const flow = f.result?.flow
  if (!flow || flow.length < 4) return null
  const home = f.home === teamId
  const m = flow.map((v) => (home ? v : -v))
  const rules = RULES[state.leagues[f.league].rules]
  const me = state.teams[teamId]
  const opp = state.teams[home ? f.away : f.home]
  const W = 200
  const H = 44
  const top = Math.max(8, ...m.map((v) => Math.abs(v)))
  const x = (i: number) => (i / (m.length - 1)) * W
  const y = (v: number) => H / 2 - (v / top) * (H / 2 - 2)
  const line = m.map((v, i) => `${x(i).toFixed(1)},${y(v).toFixed(1)}`).join(' ')
  const area = `0,${H / 2} ${line} ${W},${H / 2}`
  const reg = rules.periodMin * rules.periods
  const marks = Array.from({ length: rules.periods - 1 }, (_, k) => ((k + 1) * rules.periodMin) / Math.max(reg, m.length - 1))
  const bestLead = Math.max(0, ...m)
  const worst = Math.min(0, ...m)
  const myColor = me.colors.primary
  const oppColor = opp.colors.primary === myColor ? '#94a3b8' : opp.colors.primary
  return (
    <div className="mt-1.5">
      <div className="flex items-center justify-between text-[0.66rem] text-ink-dim">
        <span>試合の流れ（{opp.short}戦・上が{me.short}のリード）</span>
        <span className="num">
          最大リード <b className="text-good">{bestLead}</b>・最大ビハインド <b className="text-bad">{-worst}</b>
        </span>
      </div>
      <svg viewBox={`0 0 ${W} ${H}`} preserveAspectRatio="none" className="h-[3.4rem] w-full rounded-md bg-black/[0.035]">
        <defs>
          <clipPath id={`up${f.id}`}>
            <rect x="0" y="0" width={W} height={H / 2} />
          </clipPath>
          <clipPath id={`dn${f.id}`}>
            <rect x="0" y={H / 2} width={W} height={H / 2} />
          </clipPath>
        </defs>
        <polygon points={area} fill={myColor} opacity="0.55" clipPath={`url(#up${f.id})`} />
        <polygon points={area} fill={oppColor} opacity="0.45" clipPath={`url(#dn${f.id})`} />
        <line x1="0" y1={H / 2} x2={W} y2={H / 2} stroke="#1b2536" strokeOpacity="0.35" strokeWidth="0.5" />
        {marks.map((r, i) => (
          <line key={i} x1={r * W} y1="0" x2={r * W} y2={H} stroke="#1b2536" strokeOpacity="0.18" strokeWidth="0.5" strokeDasharray="1.5 1.5" />
        ))}
        <polyline points={line} fill="none" stroke="#1b2536" strokeOpacity="0.7" strokeWidth="0.8" vectorEffect="non-scaling-stroke" />
      </svg>
    </div>
  )
}
