/**
 * クラブ経営の会話の台詞（その場で組み立てる）。場面の id は story.ts で積む。
 *   owner:goal|mid|end|bailout  オーナー
 *   hc:start|slump|streak       HC（slump は選択）
 *   join:<選手>                  入団のあいさつ（性格で台詞が変わる）
 *   ask|leave:<選手>:<週>        出番が欲しい・移籍したい（選択）
 *   promise:<選手>:<守った>       約束の結果
 *   cap:<シーズン>:<選手>        主将の相談（選択）
 *   retire:<シーズン数>:<殿堂>:<写真>:<名前>  引退のあいさつ（選手はもういないので、写真と名前を id に持つ）
 *   ev:<種類>[:<選手>]:<週>      出来事（選択）
 * 台詞の who: owner・hc・cast の id・p:<選手>・x:<写真>:<名前>・me（あなた）
 */
import type { GameState } from '../models/game'
import type { Personality } from '../data/personality'
import type { Talk, TalkLine } from '../career/talks'
import { ovr } from '../player/overall'
import { absWeekOf, ageAt } from '../core/calendar'
import { sortedStandings } from '../competition/standings'
import { clubTeam } from './manage'
import { ADV, HC, OWNER, REPORTER, eventCost, hcReport, moodOf, ownerName, pid } from './story'
import { CUP_NAME, CUP_ROUNDS } from '../competition/cup'
import { EACC_NAME } from '../competition/eacc'

const L = (who: string, ...texts: string[]): TalkLine[] => texts.map((t) => (t.startsWith('me:') ? { who: 'me', text: t.slice(3) } : { who, text: t }))
const nowAbs = (s: GameState) => absWeekOf(s.season, s.week)
/** NBA の年俸の表示（万円 → $。1$ = 150 円） */
const fmtSal = (man: number) => `$${((man * 10000) / 150 / 1e6).toFixed(1)}M`
const yen = (v: number) => (v >= 10000 ? `${(v / 10000).toLocaleString(undefined, { maximumFractionDigits: 1 })} 億円` : `${v.toLocaleString()} 万円`)

const JOIN: Record<Personality, string> = {
  hot: 'このチームで、誰よりも走ります！ よろしくお願いします！',
  cool: '……よろしく。結果で応えます',
  mood: 'ロッカールームを明るくするのは得意です。任せてください！',
  effort: '毎日の練習を大事にします。よろしくお願いします',
  genius: 'いいチームですね。僕が入れば、もっと強くなりますよ',
  mypace: 'のんびりやらせてもらいます。……試合では、ちゃんとやりますよ',
  leader: 'チームのために声を出します。若い選手のことも任せてください',
  shy: 'よ、よろしくお願いします……がんばります',
}

const ASK: Record<Personality, string> = {
  hot: '試合に出たいんです！ ベンチで見ているだけなんて、耐えられません',
  cool: '今の出場時間には、納得していません。理由を聞かせてもらえますか',
  mood: '最近ちょっと元気が出なくて……。もう少し、コートに立ちたいです',
  effort: '練習では誰にも負けていないつもりです。もっと試合で試させてください',
  genius: '僕を使わないのは、チームにとって損だと思いますけどね',
  mypace: 'まあ、べつにいいんですけど……もう少し出番があると、うれしいかな',
  leader: 'チームのためなら何でもします。でも、もっとコートで引っ張りたい',
  shy: 'あの……すみません。もう少しだけ、試合に出たいです……',
}

export function clubTalkOf(id: string, state: GameState): Talk | null {
  const c = state.club
  if (!c) return null
  const team = clubTeam(state)
  const parts = id.split(':')
  const [kind, a] = parts
  const player = (n: string) => state.players[Number(n)]
  if (kind === 'owner') {
    const g = c.owner.goal
    const o = OWNER
    if (a === 'goal') {
      const trust = c.owner.trust
      return {
        title: 'オーナーとの面談',
        lines: L(
          o,
          `${team.short}のオーナーの${ownerName(state)}だ。今季の目標は「${g?.text ?? '一歩ずつ'}」。`,
          trust >= 70 ? '君の手腕には期待している。思い切ってやってくれ' : trust >= 40 ? '言葉より結果だ。数字で示してくれ' : '正直に言おう。これが最後のチャンスだと思ってくれ',
          'me:分かりました。必ず応えます',
        ),
      }
    }
    if (a === 'mid') {
      const lg = state.leagues[team.league]
      const ids = team.league === 'NBA' ? lg.teamIds.filter((x) => state.teams[x].conf === team.conf) : lg.teamIds
      const rank = sortedStandings(lg, ids).indexOf(team.id) + 1
      const goalRank = g?.kind === 'title' ? 1 : (g?.rank ?? 99)
      const ok = rank <= goalRank
      return {
        title: 'オーナーの途中の評価',
        lines: L(o, `シーズンも後半だな。今は ${rank} 位か。`, ok ? '順調だ。この調子で頼むぞ' : `目標（${g?.text ?? ''}）まで、まだ遠い。後半戦で巻き返してくれ`),
      }
    }
    if (a === 'end') {
      const res = parts[3]
      return {
        title: 'シーズンを終えて',
        lines: L(o, c.owner.last ?? c.owner.result ?? 'お疲れさま。', res === 'ok' ? 'よくやってくれた。来季も頼むぞ' : res === 'near' ? '惜しかったな。次こそは頼む' : '……期待していただけに、残念だ'),
      }
    }
    if (a === 'tax') {
      const tax = Number(parts[3])
      const ok = parts[4] === '1'
      return { title: 'ぜいたく税', lines: L(o, `今季はぜいたく税を ${yen(tax)} 払った。`, ok ? '勝つための投資だ。結果が出たなら、文句はない' : '……税金まで払って、この結果か。来季は年俸の使い方を考えてくれ（信頼が下がった）') }
    }
    if (a === 'bailout') return { title: '資金難', lines: L(o, 'また資金が足りなくなったそうだな。今回は私が出そう', '……だが、次はないと思ってくれ', 'me:申し訳ありません。立て直します') }
  }
  if (kind === 'hc') {
    const hc = c.staff.hc?.name ?? 'HC'
    if (a === 'start') {
      const r = hcReport(state)
      return {
        title: 'HC の見立て',
        lines: L(
          HC,
          `HC の${hc}です。今季の戦力は、リーグ ${r.teams} チームの中で ${r.rank} 番手くらいでしょう。`,
          `いちばん手薄なのは ${r.weak}。「補強・編成」で補強できると助かります`,
          c.training.intensity === 2 ? '練習は厳しめにしています。ケガには気をつけます' : '練習の強さは、様子を見ながら決めましょう',
        ),
      }
    }
    if (a === 'slump')
      return {
        title: '連敗',
        lines: L(HC, '5 連敗です……。選手たちも下を向いています', '練習のやり方を変えますか？'),
        choices: [
          { label: '練習を厳しくする', reply: '分かりました。明日から鍛え直します', effect: 'hard' },
          { label: '選手を信じる', reply: 'そう伝えます。きっと選手たちも応えてくれます', effect: 'trust' },
        ],
      }
    if (a === 'streak') return { title: '連勝', lines: L(HC, '7 連勝です！ 選手たちの顔つきが変わってきました', 'この勢いを、最後まで続けましょう') }
  }
  if (kind === 'join') {
    const p = player(a)
    if (!p) return null
    const youth = c.youthGrads.includes(p.id)
    return {
      title: '入団のあいさつ',
      lines: L(pid(p.id), youth ? `${p.name}です。ユースから上がってきました。ずっと、このユニフォームを着たかったんです` : `${p.name}です。${p.pos} でプレーします`, JOIN[p.personality]),
    }
  }
  if (kind === 'ask') {
    const p = player(a)
    if (!p || p.teamId !== c.teamId) return null
    return {
      title: '出番の相談',
      lines: L(pid(p.id), ASK[p.personality]),
      choices: [
        { label: '出番を約束する', reply: '本当ですか！ ……期待に応えます（序列で先発に入れた。5 週後に確かめに来る）', effect: 'promise' },
        { label: '今は我慢してくれ', reply: '……分かりました（気持ちが少し沈んだ）', effect: 'wait' },
        { label: '移籍先を探そう', reply: '……ありがとうございます。新しい場所で、がんばります（申し入れが来やすくなる）', effect: 'list' },
      ],
    }
  }
  if (kind === 'leave') {
    const p = player(a)
    if (!p || p.teamId !== c.teamId) return null
    return {
      title: '移籍の申し出',
      lines: L(pid(p.id), '話があります。……移籍させてください', 'ここでは、もう自分の居場所が見つからないんです'),
      choices: [
        { label: '移籍を認める', reply: '……今まで、ありがとうございました（申し入れが来やすくなる）', effect: 'list' },
        { label: '残ってほしい', reply: '……考えておきます（気持ちが沈んだ）', effect: 'stay' },
      ],
    }
  }
  if (kind === 'promise') {
    const p = player(a)
    if (!p) return null
    return parts[2] === '1'
      ? { title: '約束', lines: L(pid(p.id), '約束を守ってくれて、ありがとうございます', 'この信頼には、コートで応えます') }
      : { title: '約束', lines: L(pid(p.id), '……出番を約束してくれましたよね', '正直、がっかりしました（気持ちが大きく沈んだ）') }
  }
  if (kind === 'cap') {
    const p = player(parts[2])
    if (!p) return null
    return {
      title: '主将の相談',
      lines: L(pid(p.id), `主将の${p.short}です。チームのことで、話があります`, '出番のことで、不満をためている選手が何人かいます。このままだと、まとまりがなくなりそうで'),
      choices: [
        { label: '全員と話をする', reply: 'ありがとうございます。みんな、きっと喜びます（チームの気持ちが上がった）', effect: 'talk' },
        { label: '結果がすべてだ', reply: '……分かりました。そう伝えます', effect: 'none' },
      ],
    }
  }
  if (kind === 'retire') {
    const seasons = Number(a)
    const legend = parts[2] === '1'
    const who = `x:${parts[3]}:${parts.slice(4).join(':')}`
    const name = parts.slice(4).join(':')
    return {
      title: '引退',
      lines: L(who, `${name}です。今季限りで、ユニフォームを脱ぐことにしました`, `${seasons} シーズン、このクラブでプレーできて幸せでした`, ...(legend ? ['クラブの殿堂に入れてもらえるなんて……。一生の誇りです'] : []), 'me:お疲れさまでした。ありがとう'),
    }
  }
  if (kind === 'trade') {
    const o = c.tradeOffer
    if (!o || String(o.id) !== a) return null
    const ot = state.teams[o.teamId]
    const desc = (ids: number[]) => ids.map((x) => { const p = state.players[x]; return `${p.name}（${p.pos}・総合 ${ovr(p)}・${ageAt(nowAbs(state), p.birthAbs)} 歳・${fmtSal(p.contract.salary)}）` }).join('、')
    return {
      title: 'トレードの話',
      lines: L(ADV, `${ot.name}から、トレードの話が来ているわ`, `向こうが欲しいのは ${desc(o.give)}`, `代わりに出してくるのは ${desc(o.get)}。2 週のうちに返事をしてほしいって`),
      choices: [
        { label: 'トレードを受ける', reply: '分かった。すぐに手続きをするわ', effect: 'yes' },
        { label: '断る', reply: '分かった。丁寧に断っておくわ', effect: 'no' },
      ],
    }
  }
  if (kind === 'fa') {
    const p = player(parts[2])
    if (!p) return null
    if (a === 'won') return { title: '大物 FA', lines: L(pid(p.id), `${p.name}です。${Number(parts[3]) > 0 ? `ほかに ${parts[3]} チームから話をもらいましたが` : ''}……このチームで勝ちたいと思いました`, 'よろしくお願いします。優勝しましょう') }
    const t = state.teams[Number(parts[3])]
    return { title: '大物 FA', lines: L(ADV, `${p.name}は、${t?.name ?? 'ほかのチーム'}を選んだわ`, '年俸か、チームの強さか、出番か……。次はもっといい条件を用意しましょう') }
  }
  if (kind === 'allstar') {
    const names = state.awards.filter((x) => x.season === Number(a) && x.award === 'オールスター' && state.players[x.playerId]?.teamId === c.teamId).map((x) => x.name)
    if (!names.length) return null
    return { title: 'オールスター', lines: L(HC, `オールスターに、うちから ${names.join('・')} が選ばれました！`, 'リーグじゅうに、うちの選手の名前が知られる。チームの誇りです') }
  }
  if (kind === 'awards') {
    const won = state.awards.filter((x) => x.season === Number(a) && x.league === 'NBA' && x.award !== 'オールスター' && state.players[x.playerId]?.teamId === c.teamId)
    if (!won.length) return null
    return { title: '年間表彰', lines: L(HC, `年間表彰の発表がありました。${won.map((x) => `${x.name}が${x.award}`).join('、')}！`, 'NBA で、うちの選手が認められた。最高のシーズンでした') }
  }
  if (kind === 'jersey') {
    const num = a
    const name = parts.slice(3).join(':')
    return {
      title: '永久欠番',
      lines: L(OWNER, `${name}が引退したな。クラブの殿堂にも入った`, `背番号 ${num} を永久欠番にしようと思うが、どうだ？ 誰もその番号をつけられなくなる`),
      choices: [
        { label: '永久欠番にする', reply: `よし。${num} 番は、ずっと${name}のものだ`, effect: 'yes' },
        { label: '番号は残す', reply: 'そうか。いつか、あの番号を継ぐ選手が出てくるといいな', effect: 'no' },
      ],
    }
  }
  if (kind === 'cup') {
    if (a === 'upset') {
      const loser = state.teams[Number(parts[4])]
      const r = Number(parts[3])
      return {
        title: CUP_NAME,
        lines: L(HC, `${loser?.name ?? '格上のクラブ'}（${loser ? state.leagues[loser.league].name : ''}）に勝ちました！ ${CUP_NAME}の${CUP_ROUNDS[r]}を突破です`, 'ジャイアントキリングだ、と記者たちが騒いでいますよ'),
      }
    }
    if (a === 'champ') return { title: `${CUP_NAME}優勝`, lines: L(OWNER, `${CUP_NAME}の優勝、おめでとう！`, '日本一のクラブだ。……今日のことは、クラブの歴史にずっと残るぞ', 'me:選手たちのおかげです') }
  }
  if (kind === 'eacc') {
    const e = state.eacc
    if (a === 'start' && e) {
      const grp = e.groups.A.some((x) => x.team === c.teamId) ? 'A' : 'B'
      const rivals = e.groups[grp].filter((x) => x.team === undefined).map((x) => e.foreign[x.foreign!].name)
      return {
        title: EACC_NAME,
        lines: L(ADV, `${EACC_NAME}が始まったわ。同じ組は${rivals.join('・')}`, 'グループの上位 2 つに入れば、3 月のファイナル 4。アジアの強豪と戦えるのは、選手にもクラブにもいい経験になるわ。試合の週は、ホームから観戦もできるわよ'),
      }
    }
    if (a === 'champ') return { title: '東アジアの頂点', lines: L(OWNER, '東アジアの頂点だ！ 君にクラブを任せて、本当によかった', 'この勢いで、いつかは世界へ……そう思わせてくれる', 'me:まだ先があります。次の目標を目指しましょう') }
  }
  if (kind === 'ev') {
    const cost = eventCost(state)
    const ev = a
    if (ev === 'booster')
      return {
        title: 'ブースターの要望',
        lines: L(ADV, 'ブースターの会から要望が来ているわ。「ホームの試合の演出を、もっと派手にしてほしい」って', `お金はかかるけど（${yen(cost)}）、ファンは確実に増えるわね`),
        choices: [
          { label: '演出に投資する', reply: '手配しておくわ。次のホームゲームが楽しみね', effect: 'yes' },
          { label: '今は見送る', reply: '分かった。ブースターの会には、うまく伝えておくわ', effect: 'no' },
        ],
      }
    if (ev === 'sponsor') {
      const p = player(parts[2])
      if (!p) return null
      return {
        title: 'スポンサーのお願い',
        lines: L(ADV, `スポンサーから、${p.name}を週末のイベントに出してほしいって`, `謝礼は ${yen(Math.round(cost * 0.6))}。ただ、本人は少し疲れるわね`),
        choices: [
          { label: '出てもらう', reply: '伝えておくわ。スポンサーも喜ぶわね', effect: 'yes' },
          { label: '断る', reply: '分かった。試合に集中させましょう', effect: 'no' },
        ],
      }
    }
    if (ev === 'festival')
      return {
        title: '地元のお祭り',
        lines: L(ADV, '地元のお祭りに、選手みんなで来てほしいって声がかかってるわ', '街の人と近くなれるけど、選手は少し疲れるわね'),
        choices: [
          { label: 'みんなで参加する', reply: 'いいわね。法被も用意しておくわ', effect: 'yes' },
          { label: '今回は見送る', reply: '分かった。またの機会にしましょう', effect: 'no' },
        ],
      }
    if (ev === 'clinic')
      return {
        title: 'バスケ教室',
        lines: L(ADV, '地元の小学校から、選手を呼んでバスケ教室を開いてほしいって', `費用は ${yen(Math.round(cost * 0.3))}。未来のファン、未来の選手が育つわ`),
        choices: [
          { label: '開く', reply: '子どもたち、きっと大喜びよ', effect: 'yes' },
          { label: '見送る', reply: '分かった。学校には丁寧に伝えておくわ', effect: 'no' },
        ],
      }
    if (ev === 'trouble')
      return {
        title: '設備のトラブル',
        lines: L(ADV, 'アリーナの空調が壊れたわ', `すぐ直すなら ${yen(Math.round(cost * 0.5))}。後回しにすると、お客さんの評判が落ちるわね`),
        choices: [
          { label: 'すぐ直す', reply: '業者を呼んでおくわ', effect: 'yes' },
          { label: '後回しにする', reply: '……分かった。しばらくは我慢してもらいましょう', effect: 'no' },
        ],
      }
    if (ev === 'sns') {
      const p = player(parts[2])
      if (!p) return null
      return {
        title: 'SNS の炎上',
        lines: L(pid(p.id), 'すみません……。SNS の投稿が、炎上してしまいました', '悪気はなかったんです。でも、言い方がまずかったみたいで'),
        choices: [
          { label: '謝罪させる', reply: '……はい。きちんと謝ります（人気が少し下がり、本人は少し沈んだ）', effect: 'apologize' },
          { label: 'かばう', reply: '……ありがとうございます。この恩は忘れません（人気が下がったが、本人の気持ちが上がった）', effect: 'protect' },
        ],
      }
    }
    if (ev === 'interview')
      return {
        title: '取材',
        lines: L(REPORTER, `バスケ専門誌の水瀬です。${team.short}の今季の目標を聞かせてください`),
        choices: [
          { label: '優勝を狙う', reply: '強気ですね。記事の見出しはそれでいきます（人気とオーナーの信頼が上がった）', effect: 'title' },
          { label: '一歩ずつ', reply: '堅実ですね。選手たちも安心すると思います（チームの気持ちが少し上がった）', effect: 'step' },
        ],
      }
  }
  return null
}

/** 気持ちの段（画面の顔） */
export function moodFace(m: number): { face: string; label: string; tone: 'good' | 'mid' | 'bad' } {
  return m >= 65 ? { face: '😊', label: '満足', tone: 'good' } : m >= 35 ? { face: '😐', label: 'ふつう', tone: 'mid' } : { face: '😠', label: '不満', tone: 'bad' }
}

/** 主力の気持ちの平均（ホームに出す） */
export function teamMood(state: GameState): number {
  const team = clubTeam(state)
  const top = [...team.roster].sort((x, y) => ovr(state.players[y]) - ovr(state.players[x])).slice(0, 10)
  return top.reduce((s, id) => s + moodOf(state, id), 0) / Math.max(1, top.length)
}
