/** 選手の写真の id（主人公は年齢で年を重ねた姿に。28 歳から p01@28 など）。ゲーム側の画面だけで使う（engine を読むので） */
import { ageOf, type GameState, type Player } from '../../engine'
import { genPhotoFor } from './portraits'

export function playerPhoto(state: GameState, p: Player): string {
  if (!p.photo) return ''
  return p.isPlayer ? genPhotoFor(p.photo, ageOf(state, p)) : p.photo
}
