/** クラブ経営の晴れ舞台の中身（Celebration と、シーズンのまとめの出す順番で使う） */
import { clubTeam } from '../../engine/club/manage'
import type { GameState } from '../../engine'

export interface Moment {
  title: string
  sub: string
  big: boolean
}

/** 前のシーズンの優勝・昇格・NBA 参入（まだ見ていなければ） */
export function momentOf(state: GameState): Moment | null {
  const c = state.club!
  const team = clubTeam(state)
  const last = c.history[c.history.length - 1]
  if (!last || last.season !== state.season - 1 || c.celebrated === last.season) return null
  if (c.nba?.joined === state.season) return { title: 'NBA へ！', sub: `${team.name}は ${state.leagues.NBA.teamIds.length} チームの一員として、世界最高のリーグに挑む`, big: true }
  const titles = last.note
    .split('・')
    .filter((n) => (n.endsWith('優勝') && !n.includes('準優勝')) || n === '東アジア王者')
    .map((n) => (n === '東アジア王者' ? '東アジアのクラブ選手権' : n.replace(/優勝$/, '')))
  if (last.league === 'NBA' && titles.some((t) => t.includes('NBA'))) return { title: '世界一！', sub: `${team.name}が NBA の頂点に立った`, big: true }
  if (titles.length) return { title: '優勝！', sub: `${team.name}が${titles.join('と')}を制した`, big: true }
  const promoted = state.news.some((n) => n.season === last.season && n.text.startsWith(team.name) && n.text.endsWith('へ昇格'))
  if (promoted) return { title: '昇格！', sub: `${team.name}は ${state.leagues[team.league].name}へ`, big: false }
  return null
}
