function fromDefs(): GlossaryEntry[] {
  const out: GlossaryEntry[] = []
  for (const p of POSITIONS) {
    const d = POSITION_DEFS[p]
    out.push(T(`pos:${p}`, `${p}（${d.name}）`, 'position', d.role, `${d.job}\n大事な能力: ${d.keyAttrs.join('・')}\n身長の目安: ${d.height[0]}〜${d.height[1]}cm\n向いている人: ${d.suits}`))
  }
  for (const s of PLAY_STYLES) {
    const d = PLAY_STYLE_DEFS[s]
    out.push(T(`style:${s}`, d.name, 'style', d.catch, `${d.desc}\n大事な能力: ${d.keyAttrs.join('・')}\n向いているポジション: ${d.positions.join('・')}\n${d.grow}`))
  }
  for (const k of ATTR_KEYS) out.push(T(`attr:${k}`, ATTR_DEFS[k].label, 'attr', ATTR_DEFS[k].desc.split('。')[0], ATTR_DEFS[k].desc))
  for (const s of SKILL_IDS) out.push(T(`skill:${s}`, SKILL_DEFS[s].name, 'skill', SKILL_DEFS[s].bad ? '短所' : '特殊能力', SKILL_DEFS[s].desc))
  return out
}

