/** 人間関係: 出会った人・絆・紹介。まだ会っていない人は「？」（おでかけで出会える）。 */
import { useState } from 'react'
import { CAST, CAST_BY_ID, type CastDef } from '../../engine/data/cast'
import { PLACES } from '../../engine/data/career'
import { castRole, sameGeneration } from '../../engine/career/castLines'
import { romanceHint } from '../../engine/career/romance'
import { RIVAL, rivalPlayer } from '../../engine/career/rival'
import { ovr } from '../../engine'
import { useGameState } from '../../stores/gameStore'
import { AppShell } from '../layout/AppShell'
import { Initials, Portrait } from '../components/Portrait'

export function PeopleScreen() {
  const state = useGameState()
  const c = state.career!
  const [sel, setSel] = useState<CastDef | null>(null)
  const met = CAST.filter((x) => c.met.includes(x.id))
  // まだ会っていない人は、今の主人公の世代で会える人だけ（初代に二代目のヒロインを、二代目に親の世代の仲間を出さない）
  const unknown = CAST.filter((x) => !c.met.includes(x.id) && sameGeneration(state, x.id))
  // 同じ名前の場所（日米の空港のラウンジ）は 1 つに
  const where = (id: string) => [...new Set(PLACES.filter((p) => p.cast.includes(id)).map((p) => p.name))]
  return (
    <AppShell title="人間関係" current="people">
      <div className="absolute inset-0 flex gap-2 p-2">
        <div className="scroll-y min-w-0 flex-1">
          <div className="panel-head mb-1.5">出会った人（{met.length}）</div>
          <div className="grid grid-cols-5 gap-2">
            {met.map((x) => {
              const b = c.bonds[x.id] ?? 0
              return (
                <button key={x.id} className={`panel card-hover overflow-hidden text-left ${sel?.id === x.id ? 'ring-2 ring-gold' : ''}`} onClick={() => setSel(x)}>
                  <Portrait id={x.id} kind="face" className="aspect-square w-full" fallback={<Initials name={x.name} className="h-full w-full" />} />
                  <div className="px-2 py-1">
                    <div className="truncate text-[0.8rem] font-black">{x.name}</div>
                    <div className="truncate text-[0.65rem] text-ink-dim">{castRole(state, x.id)}</div>
                    <div className="mt-0.5 h-1 overflow-hidden rounded-full bg-black/10">
                      <div className="h-full rounded-full bg-gradient-to-r from-pink-400 to-gold" style={{ width: `${b}%` }} />
                    </div>
                  </div>
                </button>
              )
            })}
          </div>
          {unknown.length > 0 && (
            <>
              <div className="panel-head mb-1.5 mt-3">まだ会っていない人（{unknown.length}）</div>
              <div className="grid grid-cols-8 gap-1.5">
                {unknown.map((x) => (
                  <div key={x.id} className="panel-flat flex aspect-square items-center justify-center text-[1.4rem] font-black text-ink-mute" title={x.region === 'us' ? 'アメリカで会える' : '日本で会える'}>
                    ？
                  </div>
                ))}
              </div>
              <div className="mt-1 text-[0.72rem] text-ink-mute">過ごし方の「おでかけ」で、いろいろな場所に行くと出会えます。アメリカの人は、大学か NBA に行ってから。</div>
            </>
          )}
        </div>
        <div className="panel panel-hero flex w-[17rem] shrink-0 flex-col gap-2 p-3">
          {sel ? (
            <>
              <Portrait id={sel.id} kind="bust" className="aspect-[3/4] w-full rounded-xl" position="50% 15%" fallback={<Initials name={sel.name} className="h-full w-full" />} />
              <div>
                <div className="text-[1rem] font-black">{CAST_BY_ID[sel.id].name}</div>
                <div className="text-[0.75rem] font-bold text-gold">{castRole(state, sel.id)}</div>
                <div className="text-[0.72rem] text-ink-dim">
                  絆 {Math.round(c.bonds[sel.id] ?? 0)}・会える場所: {where(sel.id).join('・') || '試合や出来事で'}
                </div>
                <p className="mt-1 text-[0.8rem] leading-relaxed">{sel.intro}</p>
                {sel.id === RIVAL && (() => {
                  const leo = rivalPlayer(state)
                  const t = leo && leo.teamId >= 0 ? state.teams[leo.teamId] : undefined
                  return (
                    <p className="mt-1.5 rounded-lg bg-orange/10 px-2 py-1 text-[0.72rem] leading-snug">
                      直接対決 <b className="num">{c.rival?.w ?? 0} 勝 {c.rival?.l ?? 0} 敗</b>
                      {leo && (
                        <>
                          ・今は {t ? `${t.name}（${state.leagues[t.league].short}）` : leo.retired ? '引退' : '所属なし'}・総合 <b className="num">{ovr(leo)}</b>
                        </>
                      )}
                    </p>
                  )
                })()}
                {romanceHint(state, sel.id) && <p className="mt-1.5 rounded-lg bg-pink/10 px-2 py-1 text-[0.72rem] leading-snug text-pink">♥ {romanceHint(state, sel.id)}</p>}
              </div>
            </>
          ) : (
            <div className="text-[0.85rem] text-ink-dim">人を選ぶと、紹介と絆が見られます。絆が 30・60 になると、特別な話が聞けます。恋愛が進められる人は、デート 3 回・絆 80 で大切な話があるかも。</div>
          )}
        </div>
      </div>
    </AppShell>
  )
}
