/**
 * クラブ経営の晴れ舞台: シーズンの終わりの優勝・昇格と、NBA への参入。
 * 新しいシーズンのホームで 1 回だけ出す（club.celebrated にシーズンを残す）。
 */
import { useEffect } from 'react'
import { createPortal } from 'react-dom'
import { clubTeam } from '../../engine/club/manage'
import { useGame, useGameState } from '../../stores/gameStore'
import { useOverlayRoot } from '../stage/overlayRoot'
import { sound } from '../audio/sound'
import { useMusic } from '../audio/useMusic'
import { momentOf } from './moment'

export function Celebration() {
  const state = useGameState()
  const mutate = useGame((s) => s.mutate)
  const root = useOverlayRoot()
  const m = momentOf(state)
  useMusic('ceremony', !!m)
  useEffect(() => {
    if (m) sound.play('fanfare')
  }, [m])
  if (!m || !root) return null
  const team = clubTeam(state)
  const close = () => mutate((st) => void (st.club!.celebrated = st.season - 1))
  return createPortal(
    <div className="anim-fade absolute inset-0 z-[60] flex items-center justify-center bg-black/70" onClick={close}>
      {m.big && (
        <div className="pointer-events-none absolute inset-0 overflow-hidden">
          {Array.from({ length: 36 }, (_, i) => (
            <span
              key={i}
              className="absolute top-[-1rem] block h-3 w-1.5 rounded-sm"
              style={{ left: `${(i * 37) % 100}%`, background: i % 3 === 0 ? team.colors.primary : i % 3 === 1 ? '#f5c542' : team.colors.secondary, animation: `confetti ${2.4 + (i % 5) * 0.35}s linear ${(i % 7) * 0.2}s infinite` }}
            />
          ))}
        </div>
      )}
      <div className="crown-pop panel panel-hero relative w-[30rem] max-w-[92%] p-6 text-center">
        <div className="mx-auto mb-2 flex h-16 w-16 items-center justify-center rounded-2xl text-[1.1rem] font-black" style={{ background: team.colors.primary, color: team.colors.secondary }}>
          {team.abbr}
        </div>
        <div className="shine-sweep text-[2.6rem] font-black text-gold">{m.title}</div>
        <div className="mt-1 text-[0.95rem]">{m.sub}</div>
        <button className="btn btn-gold mt-4 w-full" onClick={close}>
          つづける
        </button>
      </div>
    </div>,
    root,
  )
}
