/** キャリアの総括（引退のあと）: 評価 G〜S・殿堂入り・通算・表彰・歩んだチーム・家族・日本代表。 */
import { useState } from 'react'
import { careerSummary } from '../../engine/career/retire'
import { heirCandidates, heirSeason } from '../../engine/career/heir'
import { CAST_BY_ID } from '../../engine/data/cast'
import { useGame, useGameState } from '../../stores/gameStore'
import { useUi } from '../../stores/uiStore'
import { Initials, Portrait } from '../components/Portrait'
import { Term } from '../components/Term'
import { bizLifetime, childPlaysLabel } from '../../engine/career/lifePlus'
import { HOBBY_BY_ID, TRIP_BY_ID } from '../../engine/data/careerLife'
import { formatMoneyShort } from '../format'
import { useMusic } from '../audio/useMusic'

const GRADE_COLOR: Record<string, string> = { S: '#ffd34d', A: '#ff9d4d', B: '#3ddc84', C: '#7dd3fc', D: '#e8eef6', E: '#a8b4c4', F: '#7a8698', G: '#5b6677' }

/** 子どもの世代へ: バスケを続けた息子で、同じ世界のキャリアを始める（18 歳になるまで世界を早送り） */
function HeirPanel() {
  const state = useGameState()
  const advance = useGame((s) => s.advance)
  const busy = useGame((s) => s.progress !== null)
  const push = useUi((s) => s.push)
  const [ask, setAsk] = useState<number | null>(null)
  const [running, setRunning] = useState(false)
  const cands = heirCandidates(state)
  const kids = state.career?.children ?? []
  if (!cands.length)
    return kids.length ? <div className="mr-auto max-w-[30rem] text-[0.72rem] leading-snug text-ink-dim">子どもの世代へ: バスケを続けた息子（8 歳の誕生日に「やってみたい」と言った子）がいれば、その子のキャリアを始められます（このゲームのリーグは男子だけです）。</div> : null
  const go = async (index: number) => {
    setRunning(true)
    // 18 歳になるシーズンのはじめまで（シーズンの終わりで advance は止まるので、くり返す）
    const target = heirSeason(useGame.getState().state!, index)
    for (let guard = 0; guard < 30 && useGame.getState().state!.season < target; guard++) await advance(52)
    setRunning(false)
    push({ id: 'careerNew', params: { heir: index } })
  }
  const pick = cands.find((x) => x.index === ask)
  return (
    <>
      <div className="mr-auto flex items-center gap-2">
        {cands.map((x) => (
          <button key={x.index} className="btn btn-gold" disabled={busy || running} onClick={() => setAsk(x.index)}>
            {x.name}（{x.age} 歳）の世代へ
          </button>
        ))}
      </div>
      {pick && !running && (
        <div className="anim-fade absolute inset-0 z-50 flex items-center justify-center bg-black/60 p-4" onClick={() => setAsk(null)}>
          <div className="panel panel-solid w-[30rem] max-w-full p-4" onClick={(e) => e.stopPropagation()}>
            <div className="text-[1rem] font-black">{pick.name}のキャリアを始める</div>
            <p className="mt-1 text-[0.82rem] leading-relaxed">
              {pick.name}が 18 歳になるまで、世界を {pick.seasons} シーズン進めます（{Math.max(1, Math.round(pick.seasons * 0.2))} 分ほど）。そのあと、{pick.name}のポジションや体格を決めて、同じ世界で二代目のキャリアが始まります。
            </p>
            <ul className="mt-1 list-disc pl-5 text-[0.75rem] leading-snug text-ink-dim">
              <li>親の評価に応じて、知名度・NBA の注目度・伸びやすさを少し受け継ぎます。家と、仕送り（貯金の一部）も</li>
              <li>親は節目に話しに来ます。親の世代のヒロインや仲間とは年が離れているので、会えません</li>
              <li>今のセーブは、二代目のキャリアに入れ替わります（親の記録は総括に残ります）</li>
            </ul>
            <div className="mt-3 flex gap-2">
              <button className="btn btn-ghost flex-1" onClick={() => setAsk(null)}>
                やめる
              </button>
              <button className="btn btn-gold flex-1" onClick={() => void go(pick.index)}>
                進める
              </button>
            </div>
          </div>
        </div>
      )}
      {running && (
        <div className="absolute inset-0 z-50 flex items-center justify-center bg-black/60">
          <div className="panel panel-solid px-5 py-4 text-center text-[0.9rem] font-black">
            {pick?.name ?? '子ども'}が大きくなるまで、世界を進めています…
            <div className="mt-1 text-[0.75rem] font-normal text-ink-dim">{state.startYear + state.season} 年度</div>
          </div>
        </div>
      )}
    </>
  )
}

export function CareerEndScreen() {
  const state = useGameState()
  const reset = useUi((s) => s.reset)
  const close = useGame((s) => s.close)
  const c = state.career!
  const p = state.players[c.playerId]
  const s = careerSummary(state)
  useMusic('ending')
  return (
    <div className="absolute inset-0 flex flex-col bg-[radial-gradient(70%_90%_at_50%_0%,rgba(255,214,90,0.16),transparent),#fbf8f1]">
      <div className="safe-px safe-pb flex min-h-0 flex-1 gap-3 pt-3">
        <div className="panel panel-hero flex w-[17rem] shrink-0 flex-col items-center gap-2 p-3 text-center">
          <Portrait id={p.photo ? `${p.photo}@28` : ''} kind="bust" className="aspect-[3/4] w-[11rem] rounded-xl" position="50% 15%" fallback={<Portrait id={p.photo ?? ''} kind="bust" className="h-full w-full" fallback={<Initials name={p.short} className="h-full w-full" />} />} />
          <div className="text-[1.2rem] font-black">{p.name}</div>
          <div className="text-[0.75rem] text-ink-dim">
            {state.startYear + (c.startSeason ?? 0)}〜{state.startYear + (c.retiredAt ?? state.season)} 年・{s.seasons} シーズン
          </div>
          <div className="crown-pop flex items-center gap-2">
            <span className="text-[0.8rem] text-ink-dim">キャリアの評価</span>
            <span className="text-[3rem] font-black" style={{ color: GRADE_COLOR[s.grade] }}>
              {s.grade}
            </span>
          </div>
          {s.hallOfFame && <div className="shine-sweep rounded-full bg-gold px-4 py-1 text-[0.9rem] font-black text-[#2a1a00]">殿堂入り</div>}
          {(c.lineage?.length ?? 0) > 0 && (
            <div className="w-full rounded-lg bg-black/[0.04] px-2 py-1 text-left text-[0.72rem] leading-snug">
              <div className="font-black text-gold">{(c.lineage?.length ?? 0) + 1} 代目</div>
              {c.lineage!.map((l, i) => (
                <div key={i}>
                  {i === c.lineage!.length - 1 ? '父' : `${c.lineage!.length - i} 代前`}・{l.name}（評価 {l.grade}
                  {l.allStar ? `・オールスター ${l.allStar} 回` : ''}
                  {l.rings ? `・優勝 ${l.rings} 回` : ''}
                  {l.hallOfFame ? '・殿堂入り' : ''}）
                </div>
              ))}
            </div>
          )}
        </div>
        <div className="scroll-y min-w-0 flex-1 space-y-2">
          <div className="panel p-3">
            <div className="panel-head mb-1">
              <Term id="nba">NBA</Term> 通算
            </div>
            <div className="num grid grid-cols-4 gap-2 text-center">
              {(
                [
                  ['シーズン', s.nbaSeasons],
                  ['試合', s.games],
                  ['得点', s.points],
                  ['リバウンド', s.rebounds],
                  ['アシスト', s.assists],
                  ['オールスター', s.allStar],
                  ['オール NBA', s.allNba],
                  ['優勝', s.rings],
                ] as [string, number][]
              ).map(([k, v]) => (
                <div key={k} className="stat-chip px-2 py-1.5">
                  <div className="text-[0.7rem] text-ink-dim">{k}</div>
                  <div className="text-[1.2rem] font-black">{v.toLocaleString()}</div>
                </div>
              ))}
            </div>
          </div>
          <div className="panel p-3 text-[0.82rem]">
            <div className="panel-head mb-1">表彰</div>
            {s.awards.length ? s.awards.join('・') : 'なし'}
          </div>
          <div className="panel p-3 text-[0.82rem]">
            <div className="panel-head mb-1">歩んだチーム</div>
            {s.teams.join(' → ')}
          </div>
          <div className="grid grid-cols-2 gap-2">
            <div className="panel p-3 text-[0.82rem]">
              <div className="panel-head mb-1">日本代表</div>
              {c.national ? `${c.national.caps} 試合・${c.national.pts} 得点。${c.national.events.filter((e) => !e.includes('予選')).slice(-3).join('、')}` : '選ばれなかった'}
            </div>
            <div className="panel p-3 text-[0.82rem]">
              <div className="panel-head mb-1">家族</div>
              {c.spouse ? `${CAST_BY_ID[c.spouse].name}と結婚` : 'ひとり'}
              {(c.children ?? []).map((x) => (
                <div key={x.name} className="text-[0.78rem]">
                  {x.name}
                  <span className="ml-1 text-ink-dim">{childPlaysLabel(x.plays) || '育ち盛り'}</span>
                </div>
              ))}
            </div>
          </div>
          <div className="panel p-3 text-[0.82rem]">
            <div className="panel-head mb-1">くらし</div>
            <div className="num grid grid-cols-2 gap-2">
              <div className="stat-chip px-2 py-1">
                事業の通算 <b>{formatMoneyShort(bizLifetime(state))}円</b>
              </div>
              <div className="stat-chip px-2 py-1">
                旅 <b>{c.album?.length ?? 0}</b> 回{c.album?.length ? `（最後は${TRIP_BY_ID[c.album[c.album.length - 1].trip]?.name ?? ''}）` : ''}
              </div>
              <div className="stat-chip px-2 py-1">
                社会貢献 <b className="text-gold">{s.legacy}</b> 点・寄付 <b>{formatMoneyShort(c.donated ?? 0)}円</b>
              </div>
              <div className="stat-chip px-2 py-1">
                趣味 <b>{(c.hobbies ?? []).map((h) => `${HOBBY_BY_ID[h.id].name}（${Math.round(h.skill)}）`).join('・') || 'なし'}</b>
              </div>
            </div>
          </div>
        </div>
      </div>
      <div className="safe-px safe-pb flex shrink-0 items-center justify-end gap-2 pb-3">
        <HeirPanel />
        <button
          className="btn btn-ghost"
          onClick={() => {
            close()
            reset({ id: 'title' })
          }}
        >
          タイトルへ
        </button>
      </div>
    </div>
  )
}
