/** 処理中のエラーを表示する（内容を送ってもらえるように）。ゲームは直前のセーブに戻してある。 */
import { createPortal } from 'react-dom'
import { useGame } from '../stores/gameStore'
import { exportSave } from './saveFile'

export function ErrorDialog() {
  const error = useGame((s) => s.error)
  const clear = useGame((s) => s.clearError)
  const state = useGame((s) => s.state)
  const root = document.getElementById('overlay-root')
  if (!error || !root) return null
  return createPortal(
    <div className="anim-fade absolute inset-0 z-[70] flex items-center justify-center bg-black/70 p-4">
      <div className="panel flex max-h-full w-[40rem] max-w-full flex-col p-4">
        <div className="text-[1rem] font-black text-bad">エラーが起きました（{error.where}）</div>
        <p className="mt-1 text-[0.78rem] text-ink-dim">{error.restored ? 'ゲームは直前のセーブの状態に戻しました。' : 'ゲームはそのまま続けられます。'}この画面のスクリーンショットか、下の「セーブを書き出す」のファイル（エラーの内容も入っています）を送ってもらえると、原因を調べられます。</p>
        <div className="mt-2 text-[0.8rem] font-bold">{error.message}</div>
        <div className="num text-[0.76rem] text-ink-dim">
          シーズン {error.season + 1}・第 {error.week + 1} 週
        </div>
        {error.screens && <div className="text-[0.66rem] break-all text-ink-mute">画面: {error.screens}</div>}
        <pre className="scroll-y mt-1 max-h-[8rem] whitespace-pre-wrap break-all rounded-lg bg-black/10 p-2 text-[0.68rem] leading-snug text-ink-dim">{error.stack}</pre>
        <div className="mt-3 flex gap-2">
          {state && (
            <button className="btn btn-ghost flex-1" onClick={() => void exportSave(state, `court-crown-error-s${error.season + 1}w${error.week + 1}`, { error: { ...error, userAgent: navigator.userAgent, url: location.href } })}>
              セーブを書き出す
            </button>
          )}
          <button className="btn btn-gold flex-1" onClick={clear}>
            閉じる
          </button>
        </div>
      </div>
    </div>,
    root,
  )
}
