/** キャリア: 契約の話（オファー）・シーズンごとの成績・今の契約と表彰。 */
import { acceptOffer } from '../../engine/career/create'
import { useGame, useGameState } from '../../stores/gameStore'
import { useCurrentScreen, useUi } from '../../stores/uiStore'
import { AppShell } from '../layout/AppShell'
import { TeamDot } from '../components/common'
import { Term } from '../components/Term'
import { useScreenState } from '../hooks/useScreenState'
import { RANKS, RANK_DEFS, careerRank } from '../../engine/career/rank'
import { NBA_TRADE_DEADLINE_WEEK } from '../../engine'
import { salaryLabel } from '../money'

type Tab = 'offers' | 'log' | 'contract'

export function CareerScreen() {
  const state = useGameState()
  const mutate = useGame((s) => s.mutate)
  const screen = useCurrentScreen()
  const reset = useUi((s) => s.reset)
  const [tab, setTab] = useScreenState<Tab>('tab', 'log', screen.params?.tab as Tab | undefined)
  const c = state.career!
  const p = state.players[c.playerId]
  const team = p.teamId >= 0 ? state.teams[p.teamId] : undefined
  const awards = state.awards.filter((a) => a.playerId === p.id)
  const rings = c.log.filter((l) => l.notes.includes('NBA 優勝')).length
  const rank = careerRank(state)
  const canRequest = team?.league === 'NBA' && state.week <= NBA_TRADE_DEADLINE_WEEK
  const CONTRACT: Record<string, string> = { rookie: 'ルーキー契約', standard: '通常の契約', max: 'マックス契約', min: '最低保証', twoWay: '2way 契約', dev: '育成リーグの契約', pro: 'プロ契約', college: '奨学金', none: 'なし' }
  const TERM: Record<string, string> = { rookie: 'rookieContract', max: 'maxContract', min: 'minContract', twoWay: 'twoWay', college: 'scholarship', dev: 'devLeague' }
  return (
    <AppShell title="キャリア" current="career">
      <div className="absolute inset-0 flex flex-col gap-2 p-2">
        <div className="seg shrink-0 self-start">
          <button aria-selected={tab === 'offers'} onClick={() => setTab('offers')}>
            契約の話 {c.offers.length > 0 && `（${c.offers.length}）`}
          </button>
          <button aria-selected={tab === 'log'} onClick={() => setTab('log')}>
            成績
          </button>
          <button aria-selected={tab === 'contract'} onClick={() => setTab('contract')}>
            契約・表彰
          </button>
        </div>
        <div className="panel scroll-y min-h-0 flex-1 p-3">
          {tab === 'offers' &&
            (c.offers.length === 0 ? (
              <div className="text-[0.85rem] text-ink-dim">いまは話が来ていません。契約の最後の年や、活躍して注目されると届きます。</div>
            ) : (
              <div className="grid grid-cols-2 gap-2">
                {c.offers.map((o) => {
                  const t = state.teams[o.teamId]
                  const nba = t.league === 'NBA' || t.league === 'DEV'
                  return (
                    <div key={o.id} className="panel-flat flex items-center gap-2 p-2.5">
                      <TeamDot colors={t.colors} abbr={t.abbr} className="h-10 w-10 text-[0.6rem]" />
                      <div className="min-w-0 flex-1">
                        <div className="truncate text-[0.95rem] font-black">{t.name}</div>
                        <div className="text-[0.72rem] text-ink-dim">
                          {state.leagues[t.league].name}・{o.kind === 'renew' ? '契約の更新' : '新しいチーム'}
                          {o.contract && (
                            <>
                              ・<Term id={TERM[o.contract] ?? 'nba'}>{CONTRACT[o.contract]}</Term>
                            </>
                          )}
                        </div>
                        <div className="num text-[0.78rem] font-bold text-gold">
                          年俸 {salaryLabel(o.salary, t.league)}・{o.years}年
                        </div>
                        <div className="truncate text-[0.7rem] italic text-ink-mute">「{o.pitch}」</div>
                      </div>
                      <button
                        className={`btn btn-sm ${nba ? 'btn-gold' : 'btn-ghost'}`}
                        onClick={() => {
                          mutate((st) => acceptOffer(st, o.id))
                          reset({ id: 'home' })
                        }}
                      >
                        契約する
                      </button>
                    </div>
                  )
                })}
              </div>
            ))}
          {tab === 'log' && (
            <table className="num w-full text-center text-[0.82rem]">
              <thead className="text-[0.7rem] text-ink-dim">
                <tr>
                  <th className="text-left">シーズン</th>
                  <th>年齢</th>
                  <th className="text-left">チーム</th>
                  <th>総合</th>
                  <th>試合</th>
                  <th>得点</th>
                  <th>REB</th>
                  <th>AST</th>
                  <th className="text-left">できごと</th>
                </tr>
              </thead>
              <tbody>
                {c.log.length === 0 && (
                  <tr>
                    <td colSpan={9} className="py-3 text-ink-dim">
                      シーズンが終わると、ここに記録が残ります。
                    </td>
                  </tr>
                )}
                {c.log.map((l) => (
                  <tr key={l.season} className="border-t border-line/30">
                    <td className="py-1 text-left">
                      {state.startYear + l.season}-{String((state.startYear + l.season + 1) % 100).padStart(2, '0')}
                    </td>
                    <td>{l.age}</td>
                    <td className="text-left">
                      {l.teamName}
                      <span className="text-ink-mute">（{l.league}）</span>
                    </td>
                    <td className="font-bold">{l.ovr}</td>
                    <td>{l.gp}</td>
                    <td className="font-black">{l.ppg.toFixed(1)}</td>
                    <td>{l.rpg.toFixed(1)}</td>
                    <td>{l.apg.toFixed(1)}</td>
                    <td className="text-left text-[0.72rem] text-gold">{l.notes.join('・')}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
          {tab === 'contract' && (
            <div className="grid grid-cols-2 gap-3 text-[0.85rem]">
              <div className="panel-flat p-3">
                <div className="panel-head mb-1">今の契約</div>
                {team ? (
                  <>
                    <div className="font-black">{team.name}</div>
                    <div className="text-ink-dim">
                      <Term id={TERM[p.contract.kind] ?? 'freeAgent'}>{CONTRACT[p.contract.kind]}</Term>・年俸 {salaryLabel(p.contract.salary, team.league)}
                      {p.contract.kind !== 'college' && `・残り ${p.contract.years} 年`}
                    </div>
                  </>
                ) : (
                  <div className="text-ink-dim">
                    <Term id="freeAgent">所属なし（FA）</Term>
                  </div>
                )}
                {p.draft && (
                  <div className="mt-1 text-ink-dim">
                    <Term id="draft">ドラフト</Term>: {p.draft.year}年 {p.draft.round}巡目 {p.draft.pick}位（{state.teams[p.draft.teamId].name}）
                  </div>
                )}
              </div>
              <div className="panel-flat col-span-2 p-3">
                <div className="panel-head mb-1">ランク</div>
                <div className="flex items-stretch gap-1">
                  {RANKS.map((r) => (
                    <div key={r} className={`flex-1 rounded-lg p-1.5 text-center ${r === rank ? 'ring-2 ring-gold' : 'opacity-60'}`} style={{ background: RANK_DEFS[r].color + '33' }}>
                      <div className="text-[1.1rem] font-black" style={{ color: RANK_DEFS[r].color }}>
                        {r}
                      </div>
                      <div className="text-[0.66rem] leading-tight">{RANK_DEFS[r].label}</div>
                    </div>
                  ))}
                </div>
                <div className="mt-1 text-[0.75rem] text-ink-dim">優勝リング: <span className="font-black text-gold">{rings}</span></div>
              </div>
              {canRequest && (
                <div className="panel-flat col-span-2 flex items-center gap-2 p-3">
                  <div className="min-w-0 flex-1 text-[0.8rem]">
                    <div className="font-black"><Term id="trade">トレード</Term>を要求する</div>
                    <div className="text-ink-dim">出場時間に不満があるとき、別のチームへ移りたいと伝えます（2 月のトレード期限まで）。行き先は選べません。</div>
                  </div>
                  <button className="btn btn-ghost btn-sm" onClick={() => mutate((st) => void (st.career!.tradeRequest = !st.career!.tradeRequest))}>
                    {c.tradeRequest ? '要求を取り下げる' : '要求する'}
                  </button>
                </div>
              )}
              <div className="panel-flat p-3">
                <div className="panel-head mb-1">
                  <Term id="awards">表彰</Term>
                </div>
                {awards.length === 0 ? (
                  <div className="text-ink-dim">まだありません。</div>
                ) : (
                  awards.map((a, i) => (
                    <div key={i}>
                      <span className="text-gold">{state.startYear + a.season}</span> {state.leagues[a.league].short} {a.award}
                    </div>
                  ))
                )}
              </div>
            </div>
          )}
        </div>
      </div>
    </AppShell>
  )
}
