/**
 * 総合力の見える化（2026-11-14、ユーザーの「総合力を分かりやすく見える化して」）。乱数なし。
 *   チーム: 戦力（上位 8 人の総合値の平均＝ query.ts の teamPower）とリーグの順位、先発 5 人・控え（6〜10 番手）、
 *     分野 6 つ（外のシュート・中の攻め・組み立て・外の守り・中の守り・リバウンド。上位 8 人の能力の平均）とリーグの平均・順位、
 *     ポジションごとの上位 2 人
 *   選手: 総合値の目盛り（リーグごとの水準＝そのリーグのチームの戦力の平均）と一言（「1 部の主力級」など）
 */
import type { AttrKey } from '../data/attributes'
import { POSITIONS, type Position } from '../data/positions'
import type { GameState } from '../models/game'
import type { LeagueId, Team } from '../models/league'
import type { Player } from '../models/player'
import { ovr, ovrAt } from '../player/overall'
import { rosterOf, teamPower } from '../query'

export const AREAS: { id: string; label: string; attrs: Partial<Record<AttrKey, number>>; note: string }[] = [
  { id: 'outside', label: '外のシュート', attrs: { three: 2, mid: 1 }, note: '3P とミドル' },
  { id: 'inside', label: '中の攻め', attrs: { close: 1, layup: 1, dunk: 0.6, post: 0.8 }, note: 'ゴール下・レイアップ・ダンク・ポスト' },
  { id: 'play', label: '組み立て', attrs: { handle: 1, pass: 1, vision: 1, iq: 1 }, note: 'ドリブル・パス・視野・バスケ IQ' },
  { id: 'perD', label: '外の守り', attrs: { perD: 2, steal: 1, quick: 1 }, note: '外角守備・スティール・クイックネス' },
  { id: 'intD', label: '中の守り', attrs: { intD: 2, block: 1.2, strength: 0.8 }, note: '内角守備・ブロック・筋力' },
  { id: 'reb', label: 'リバウンド', attrs: { dreb: 1.5, oreb: 1, jump: 0.5 }, note: 'リバウンドとジャンプ力' },
]

function areaScore(ps: Player[], attrs: Partial<Record<AttrKey, number>>): number {
  if (!ps.length) return 0
  const keys = Object.keys(attrs) as AttrKey[]
  const wsum = keys.reduce((s, k) => s + attrs[k]!, 0)
  return ps.reduce((s, p) => s + keys.reduce((t, k) => t + p.attr[k] * attrs[k]!, 0) / wsum, 0) / ps.length
}

const top = (state: GameState, t: Team) => rosterOf(state, t).sort((a, b) => ovr(b) - ovr(a))
const mean = (v: number[]) => (v.length ? v.reduce((s, x) => s + x, 0) / v.length : 0)
const rankOf = (mine: number, all: number[]) => 1 + all.filter((v) => v > mine + 1e-9).length

export interface TeamStrength {
  power: number
  rank: number
  /** リーグのチーム数 */
  n: number
  leagueAvg: number
  /** リーグのいちばん上と下の戦力 */
  leagueMax: number
  leagueMin: number
  /** 先発 5 人（総合値の上位 5 人）と控え（6〜10 番手）の平均、控えのリーグの順位 */
  starters: number
  bench: number
  benchRank: number
  areas: { id: string; label: string; note: string; value: number; rank: number; avg: number; max: number }[]
  positions: { pos: Position; players: { id: number; name: string; short: string; ovr: number; sub: boolean }[] }[]
}

export function teamStrength(state: GameState, team: Team): TeamStrength {
  const teams = state.leagues[team.league].teamIds.map((id) => state.teams[id])
  const sorted = new Map(teams.map((t) => [t.id, top(state, t)]))
  const ps = sorted.get(team.id) ?? top(state, team)
  const powers = teams.map((t) => teamPower(state, t))
  const benchOf = (v: Player[]) => mean(v.slice(5, 10).map(ovr))
  const benches = teams.map((t) => benchOf(sorted.get(t.id)!))
  const power = teamPower(state, team)
  const bench = benchOf(ps)
  const areas = AREAS.map((a) => {
    const all = teams.map((t) => areaScore(sorted.get(t.id)!.slice(0, 8), a.attrs))
    const value = areaScore(ps.slice(0, 8), a.attrs)
    return { id: a.id, label: a.label, note: a.note, value, rank: rankOf(value, all), avg: mean(all), max: Math.max(...all) }
  })
  const positions = POSITIONS.map((pos) => ({
    pos,
    players: ps
      .filter((p) => p.pos === pos || p.pos2 === pos)
      .map((p) => ({ id: p.id, name: p.name, short: p.short, ovr: p.pos === pos ? ovr(p) : ovrAt(p, pos), sub: p.pos !== pos }))
      .sort((a, b) => b.ovr - a.ovr)
      .slice(0, 2),
  }))
  return {
    power,
    rank: rankOf(power, powers),
    n: teams.length,
    leagueAvg: mean(powers),
    leagueMax: Math.max(...powers),
    leagueMin: Math.min(...powers),
    starters: mean(ps.slice(0, 5).map(ovr)),
    bench,
    benchRank: rankOf(bench, benches),
    areas,
    positions,
  }
}

/** リーグのチームを戦力の順に（見える化の棒グラフ） */
export function leaguePowers(state: GameState, league: LeagueId): { teamId: number; power: number }[] {
  return state.leagues[league].teamIds.map((id) => ({ teamId: id, power: teamPower(state, state.teams[id]) })).sort((a, b) => b.power - a.power)
}

// ---------------------------------------------------------------- 選手の総合値の目盛り

/** 目盛りに使うリーグ（下から）。水準はそのリーグのチームの戦力（上位 8 人の平均）の平均 */
export const LEVEL_LEAGUES: { id: LeagueId; label: string }[] = [
  { id: 'JBL3', label: '3 部' },
  { id: 'JBL2', label: '2 部' },
  { id: 'JBL1', label: '1 部' },
  { id: 'NBA', label: 'NBA' },
]
/** NBA のスター（オールスター級）の目安 */
export const STAR_OVR = 88

export function leagueLevels(state: GameState): { id: LeagueId; label: string; value: number }[] {
  return LEVEL_LEAGUES.filter((l) => state.leagues[l.id]).map((l) => ({ ...l, value: mean(state.leagues[l.id].teamIds.map((id) => teamPower(state, state.teams[id]))) }))
}

/** 総合値の一言: 通用するいちばん上のリーグ（水準 −2 から）と、主力級（水準 +4 から） */
export function ovrLevelLabel(levels: { label: string; value: number }[], o: number): string {
  if (o >= STAR_OVR) return 'NBA のスター級'
  let best: { label: string; value: number } | undefined
  for (const l of levels) if (o >= l.value - 2) best = l
  if (!best) return `${levels[0]?.label ?? '国内'}を目指す段階`
  return o >= best.value + 4 ? `${best.label}の主力級` : `${best.label}で通用する`
}
