/**
 * 選手の画面（params.playerId）: 体格・総合値（リーグの水準の目盛り）・伸びしろと成長見込み・能力（レーダーと一覧。総合値に効く能力に ◎○）・
 * 特殊能力・成長（年齢ごとの総合値のグラフ。主人公は経験点の入り方）・成績。用語はタップで解説。
 */
import {
  ATTR_CATS,
  ATTR_DEFS,
  ATTR_KEYS,
  GROWTH_DEFS,
  NATION_NAME,
  PERSONALITY_DEFS,
  PLAY_STYLE_DEFS,
  POSITION_DEFS,
  RADAR_AXES,
  SKILL_DEFS,
  POS_WEIGHTS,
  ageOf,
  ovr,
  radarValues,
  type Stats,
} from '../../engine'
import { useGameState } from '../../stores/gameStore'
import { useCurrentScreen, useUi } from '../../stores/uiStore'
import { AppShell } from '../layout/AppShell'
import { potShown } from '../../engine/club/transfer'
import { Flag, OvrBadge, PosBadge, RankChip, StatBar, Stars, TeamDot } from '../components/common'
import { Initials, Portrait } from '../components/Portrait'
import { RadarChart } from '../components/RadarChart'
import { Term, TermHelp } from '../components/Term'
import { useScreenState } from '../hooks/useScreenState'
import { salaryLabel } from '../money'
import { playerPhoto } from '../components/playerPhoto'
import { ExpCurve, OutlookChart, OutlookText, OvrGauge } from '../components/Outlook'
import { expPhase, outlookOf } from '../components/outlookData'

type Tab = 'attr' | 'skill' | 'growth' | 'stats'

/** 伸びしろ（総合値の上限の目安）を ★ に */
function potStars(pot: number): number {
  return Math.max(0.5, Math.min(5, Math.round(((pot - 45) / 10) * 2) / 2))
}

function avg(s: Stats, k: keyof Stats): string {
  return s.gp ? (s[k] / s.gp).toFixed(1) : '-'
}
function pct(m: number, a: number): string {
  return a ? `${((m / a) * 100).toFixed(1)}` : '-'
}

function StatsRow({ label, s }: { label: string; s: Stats }) {
  return (
    <tr className="border-t border-line/30">
      <td className="py-1 pl-2 text-left text-[0.75rem]">{label}</td>
      <td>{s.gp}</td>
      <td>{avg(s, 'min')}</td>
      <td className="font-bold">{avg(s, 'pts')}</td>
      <td>{s.gp ? ((s.oreb + s.dreb) / s.gp).toFixed(1) : '-'}</td>
      <td>{avg(s, 'ast')}</td>
      <td>{avg(s, 'stl')}</td>
      <td>{avg(s, 'blk')}</td>
      <td>{pct(s.fgm, s.fga)}</td>
      <td>{pct(s.tpm, s.tpa)}</td>
      <td className="pr-2">{pct(s.ftm, s.fta)}</td>
    </tr>
  )
}

export function PlayerScreen() {
  const state = useGameState()
  const screen = useCurrentScreen()
  const push = useUi((s) => s.push)
  const p = state.players[Number(screen.params?.playerId ?? 0)]
  const [tab, setTab] = useScreenState<Tab>('tab', 'attr', screen.params?.tab as Tab | undefined)
  if (!p) return null
  const team = p.teamId >= 0 ? state.teams[p.teamId] : undefined
  const o = ovr(p)
  const color = team?.colors.primary ?? '#ff7a1a'
  const outlook = outlookOf(state, p, true)
  const age = ageOf(state, p)
  // 総合値に大きく効く能力（そのポジションの重み 1.2 以上 ◎・0.8 以上 ○）
  const weight = POS_WEIGHTS[p.pos]
  return (
    <AppShell title={p.name} current="league" back color={color}>
      <div className="absolute inset-0 flex gap-2 p-2">
        {/* 左: 選手の札 */}
        <div className="panel panel-hero scroll-y flex w-[17rem] shrink-0 flex-col gap-2 p-3">
          <div className="flex gap-2.5">
            <Portrait id={playerPhoto(state, p)} kind="face" className="h-[6.2rem] w-[6.2rem] shrink-0 rounded-xl" fallback={<Initials name={p.short} className="h-full w-full" color={color} />} />
            <div className="min-w-0 flex-1">
              <div className="text-[1.05rem] font-black leading-tight">{p.name}</div>
              <div className="mt-0.5 flex items-center gap-1.5 text-[0.75rem] text-ink-dim">
                <Flag nation={p.nation} />
                {NATION_NAME[p.nation]}・{ageOf(state, p)}歳
              </div>
              <div className="mt-1 flex items-center gap-1">
                <Term id={`pos:${p.pos}`}>
                  <PosBadge pos={p.pos} />
                </Term>
                {p.pos2 && (
                  <Term id={`pos:${p.pos2}`}>
                    <PosBadge pos={p.pos2} dim />
                  </Term>
                )}
                <span className="ml-1 text-[0.75rem] text-ink-dim">#{p.jersey}</span>
              </div>
              <div className="mt-1 text-[0.8rem] font-bold text-orange">
                <Term id={`style:${p.style}`}>{PLAY_STYLE_DEFS[p.style].name}</Term>
              </div>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <OvrBadge value={o} size="lg" />
            <div>
              <div className="text-[0.72rem] text-ink-dim">
                <Term id="ovr">総合値</Term>（{POSITION_DEFS[p.pos].name}）
              </div>
              <div className="flex items-center gap-1 text-[0.72rem] text-ink-dim">
                <Term id="potential">伸びしろ</Term>
                {(() => {
                  const v = potShown(state, p)
                  if (v === null) return <span className="text-ink-mute">？（「補強・編成」の画面で調べられる）</span>
                  const est = !!state.club && p.teamId !== state.club.teamId
                  return (
                    <>
                      <Stars value={potStars(v)} />
                      {est && <span className="text-ink-mute">（スカウトの見立て）</span>}
                    </>
                  )
                })()}
              </div>
            </div>
          </div>
          <OvrGauge value={o} peak={outlook && outlook.peak > o ? outlook.peak : undefined} />
          <button className="stat-chip px-2 py-1 text-left" onClick={() => setTab('growth')}>
            {/* ボタンは font: inherit なので、文字の大きさは中に */}
            <span className="block text-[0.72rem] leading-snug">
              <Term id="growthOutlook">成長見込み</Term>:{' '}
              {p.isPlayer ? <span className="text-ink-dim">自分の育成で伸ばす（{expPhase(p.growth, age)}）</span> : outlook ? <OutlookText o={outlook} /> : <span className="text-ink-mute">？（伸びしろを調べると分かる）</span>}
            </span>
          </button>
          {team && (
            <button className="stat-chip flex items-center gap-2 px-2 py-1.5 text-left" onClick={() => push({ id: 'team', params: { teamId: team.id } })}>
              <TeamDot colors={team.colors} abbr={team.abbr} />
              <span className="min-w-0">
                <span className="block truncate text-[0.85rem] font-bold">{team.name}</span>
                <span className="block text-[0.7rem] text-ink-dim">
                  {state.leagues[team.league].name}・年俸 {salaryLabel(p.contract.salary, team.league)}
                  {p.contract.kind !== 'college' && p.contract.years > 0 && `・残り${p.contract.years}年`}
                </span>
              </span>
            </button>
          )}
          {!team && <div className="stat-chip px-2 py-1.5 text-[0.8rem] text-ink-dim"><Term id="freeAgent">所属なし（FA）</Term></div>}
          <div className="grid grid-cols-3 gap-1.5 text-center text-[0.72rem]">
            <div className="stat-chip px-1 py-1">
              <div className="text-ink-dim">
                <Term id="height">身長</Term>
              </div>
              <div className="num text-[0.95rem] font-black">{p.heightCm}</div>
            </div>
            <div className="stat-chip px-1 py-1">
              <div className="text-ink-dim">
                <Term id="wingspan">腕の長さ</Term>
              </div>
              <div className="num text-[0.95rem] font-black">{p.wingspanCm}</div>
            </div>
            <div className="stat-chip px-1 py-1">
              <div className="text-ink-dim">
                <Term id="weight">体重</Term>
              </div>
              <div className="num text-[0.95rem] font-black">{p.weightKg}</div>
            </div>
          </div>
          <div className="text-[0.75rem] leading-relaxed text-ink-dim">
            <div>
              <Term id="growthType">成長タイプ</Term>: {GROWTH_DEFS[p.growth].name}（ピーク {GROWTH_DEFS[p.growth].peak}）
            </div>
            <div>
              性格: {PERSONALITY_DEFS[p.personality].name}（{PERSONALITY_DEFS[p.personality].blurb}）
            </div>
            {p.draft && (
              <div>
                <Term id="draft">ドラフト</Term>: {p.draft.year}年 {p.draft.round}巡目 {p.draft.pick}位
              </div>
            )}
          </div>
        </div>

        {/* 右: 能力・特殊能力・成績 */}
        <div className="flex min-w-0 flex-1 flex-col gap-2">
          <div className="seg shrink-0 self-start" role="tablist">
            <button role="tab" aria-selected={tab === 'attr'} onClick={() => setTab('attr')}>
              能力
            </button>
            <button role="tab" aria-selected={tab === 'skill'} onClick={() => setTab('skill')}>
              特殊能力 {p.skills.length}
            </button>
            <button role="tab" aria-selected={tab === 'growth'} onClick={() => setTab('growth')}>
              成長
            </button>
            <button role="tab" aria-selected={tab === 'stats'} onClick={() => setTab('stats')}>
              成績
            </button>
          </div>
          <div className="panel scroll-y min-h-0 flex-1 p-2">
            {tab === 'attr' && (
              <div className="flex gap-2">
                <div className="flex shrink-0 flex-col items-center">
                <RadarChart labels={RADAR_AXES.map((a) => a.label)} values={radarValues(p.attr)} color="#ff7a1a" className="h-[13rem] w-[13rem] shrink-0" />
                  <div className="w-[12.5rem] text-[0.62rem] leading-snug text-ink-dim">
                    <b className="text-gold">◎</b>・<b className="text-gold">○</b> は {POSITION_DEFS[p.pos].name}の<Term id="ovr">総合値</Term>に大きく効く能力。ここを伸ばすと総合値が上がりやすい。
                  </div>
                </div>
                <div className="grid min-w-0 flex-1 grid-cols-2 gap-x-3 gap-y-2">
                  {ATTR_CATS.map((c) => (
                    <div key={c.id}>
                      <div className="mb-0.5 text-[0.72rem] font-black text-gold">{c.label}</div>
                      {ATTR_KEYS.filter((k) => ATTR_DEFS[k].cat === c.id).map((k) => (
                        <div key={k} className="flex items-center gap-1.5 py-[0.1rem] text-[0.8rem]">
                          <span className="w-[0.8rem] shrink-0 text-center text-[0.66rem] font-black text-gold">{weight[k] >= 1.2 ? '◎' : weight[k] >= 0.8 ? '○' : ''}</span>
                          <span className="w-[6.2rem] shrink-0 truncate">
                            <Term id={`attr:${k}`}>{ATTR_DEFS[k].label}</Term>
                          </span>
                          <RankChip value={p.attr[k]} />
                          <span className="num w-6 text-right font-bold">{Math.round(p.attr[k])}</span>
                          <StatBar value={p.attr[k]} />
                        </div>
                      ))}
                    </div>
                  ))}
                </div>
              </div>
            )}
            {tab === 'skill' && (
              <div className="grid grid-cols-2 gap-2">
                {p.skills.length === 0 && <div className="p-2 text-[0.85rem] text-ink-dim">特殊能力はまだありません。</div>}
                {p.skills.map((s) => (
                  <div key={s} className={`panel-flat flex items-start gap-2 p-2.5 ${SKILL_DEFS[s].bad ? 'border-bad/40' : ''}`}>
                    <span className={`mt-0.5 rounded px-1.5 text-[0.7rem] font-black ${SKILL_DEFS[s].bad ? 'bg-bad/25 text-bad' : 'bg-gold/20 text-gold'}`}>{SKILL_DEFS[s].bad ? '短所' : '特能'}</span>
                    <div className="min-w-0">
                      <div className="flex items-center gap-1 font-black">
                        {SKILL_DEFS[s].name}
                        <TermHelp id={`skill:${s}`} />
                      </div>
                      <div className="text-[0.75rem] text-ink-dim">{SKILL_DEFS[s].desc}</div>
                    </div>
                  </div>
                ))}
              </div>
            )}
            {tab === 'growth' && (
              <div className="flex gap-3">
                <div className="min-w-0 flex-1">
                  <div className="text-[0.74rem] font-black">
                    年齢ごとの総合値 <span className="font-normal text-ink-dim">（実線: これまで・点線: 見込み）</span>
                  </div>
                  <OutlookChart p={p} o={outlook} className="w-full" />
                </div>
                <div className="w-[15rem] shrink-0 space-y-1.5 text-[0.72rem] leading-snug">
                  {p.isPlayer ? (
                    <>
                      <div className="font-black">経験点の入り方（成長タイプ: {GROWTH_DEFS[p.growth].name}）</div>
                      <ExpCurve type={p.growth} age={age} className="w-full" />
                      <div className="text-ink-dim">
                        主人公は練習と試合でたまる経験点で能力を上げます。いまは<b className="text-ink">{expPhase(p.growth, age)}</b>。ピークは {GROWTH_DEFS[p.growth].peak}、{GROWTH_DEFS[p.growth].peakEnd} 歳を過ぎると衰えが始まります（経験点で保てる）。
                      </div>
                    </>
                  ) : outlook ? (
                    <>
                      <div>
                        <Term id="growthOutlook">成長見込み</Term>: <OutlookText o={outlook} />
                      </div>
                      <div className="num grid grid-cols-4 gap-1 text-center">
                        {outlook.path.slice(0, 8).map((v, i) => (
                          <div key={i} className="stat-chip px-1 py-0.5">
                            <div className="text-[0.6rem] text-ink-dim">{i === 0 ? 'いま' : `${outlook.age + i}歳`}</div>
                            <div className={`font-black ${v > o ? 'text-good' : v < o ? 'text-bad' : ''}`}>{v}</div>
                          </div>
                        ))}
                      </div>
                      <div className="text-[0.66rem] text-ink-dim">
                        成長タイプ（{GROWTH_DEFS[p.growth].name}・ピーク {GROWTH_DEFS[p.growth].peak}）・<Term id="potential">伸びしろ</Term>・性格から、試合にふつうに出た場合を計算した目安です。出場時間・ケガでずれます。
                        {state.club && p.teamId === state.club.teamId && ' 練習場・コーチ・練習の重点も入っています。'}
                        {state.club && p.teamId !== state.club.teamId && ' 伸びしろはスカウトの見立てです。'}
                      </div>
                    </>
                  ) : (
                    <div className="text-ink-dim">伸びしろが分からないので、見込みは出せません。「補強・編成」の画面で調べると分かります。</div>
                  )}
                </div>
              </div>
            )}
            {tab === 'stats' && (
              <table className="num w-full text-center text-[0.8rem]">
                <thead className="text-[0.7rem] text-ink-dim">
                  <tr>
                    <th className="text-left pl-2">シーズン</th>
                    <th>試合</th>
                    <th>
                      <Term id="minutes">分</Term>
                    </th>
                    <th>
                      <Term id="ppg">得点</Term>
                    </th>
                    <th>
                      <Term id="rpg">REB</Term>
                    </th>
                    <th>
                      <Term id="apg">AST</Term>
                    </th>
                    <th>
                      <Term id="spg">STL</Term>
                    </th>
                    <th>BLK</th>
                    <th>
                      <Term id="fgPct">FG%</Term>
                    </th>
                    <th>
                      <Term id="tpPct">3P%</Term>
                    </th>
                    <th className="pr-2">
                      <Term id="ftPct">FT%</Term>
                    </th>
                  </tr>
                </thead>
                <tbody>
                  <StatsRow label="今季" s={p.stats} />
                  {p.history
                    .slice()
                    .reverse()
                    .map((h) => (
                      <StatsRow key={`${h.season}:${h.teamId}`} label={`${state.startYear + h.season}-${String((state.startYear + h.season + 1) % 100).padStart(2, '0')} ${h.teamName}`} s={h.stats} />
                    ))}
                </tbody>
              </table>
            )}
          </div>
        </div>
      </div>
    </AppShell>
  )
}
