/**
 * クラブ経営: 作戦と序列。左に序列（先発の 5 人・交代で使う人数の線。おまかせか自分で）、
 * 右に作戦（おすすめと理由・おまかせ・ペース・攻めの重心・セット・守り・出場の人数）。おすすめは engine/club/advice.ts
 */
import { ovr, type Tactics } from '../../engine'
import { clubDepth, depthAuto } from '../../engine/club/effects'
import { recommendDepth, recommendTactics } from '../../engine/club/advice'
import { clubTeam, moveDepth } from '../../engine/club/manage'
import { useGame, useGameState } from '../../stores/gameStore'
import { useUi } from '../../stores/uiStore'
import { AppShell } from '../layout/AppShell'
import { ConditionArrow, OvrBadge, PosBadge } from '../components/common'
import { Term, TermHelp } from '../components/Term'
import { moodOf } from '../../engine/club/story'
import { gameDaySize } from '../../engine/match/rotation'
import { moodFace } from '../../engine/club/storyTalks'

type Opt<K extends keyof Tactics> = { key: K; label: string; term: string; opts: [Tactics[K], string, string][] }

const OPTIONS: [Opt<'pace'>, Opt<'focus'>, Opt<'set'>, Opt<'defense'>, Opt<'rotation'>] = [
  {
    key: 'pace',
    label: 'ペース',
    term: 'pace',
    opts: [
      ['slow', 'ゆっくり', '攻めの回数を減らす。強い相手に（番狂わせが起きやすい）'],
      ['normal', 'ふつう', ''],
      ['fast', '速く', '速攻を増やす。体力を使う'],
    ],
  },
  {
    key: 'focus',
    label: '攻めの重心',
    term: 'offFocus',
    opts: [
      ['inside', 'インサイド', 'ゴール下とポスト'],
      ['balanced', 'バランス', ''],
      ['outside', 'アウトサイド', '3P を多く打つ'],
    ],
  },
  {
    key: 'set',
    label: '主なセット',
    term: 'pnr',
    opts: [
      ['pnr', 'ピック&ロール', 'スクリーンを使った 2 人の攻め'],
      ['motion', 'モーション', 'パスと動きで崩す'],
      ['iso', 'アイソレーション', 'エースの 1 対 1'],
      ['post', 'ポストアップ', 'ゴール下の大きな選手から'],
    ],
  },
  {
    key: 'defense',
    label: '守り',
    term: 'manD',
    opts: [
      ['man', 'マンツーマン', '1 人が 1 人を守る'],
      ['zone23', '2-3 ゾーン', 'ゴール下を固める'],
      ['zone32', '3-2 ゾーン', '外のシュートに強い'],
      ['press', 'プレス', '前から奪いに行く。体力を使う'],
    ],
  },
  {
    key: 'rotation',
    label: '出場の人数',
    term: 'rotation',
    opts: [
      ['tight', '8 人', '主力を長く使う'],
      ['normal', '9 人', ''],
      ['deep', '10 人', '控えも使って疲れを分ける'],
    ],
  },
]

export function TacticsScreen() {
  const state = useGameState()
  const mutate = useGame((s) => s.mutate)
  const push = useUi((s) => s.push)
  const team = clubTeam(state)
  const ids = clubDepth(state)
  const size = team.tactics.rotation === 'tight' ? 8 : team.tactics.rotation === 'deep' ? 10 : 9
  const c = state.club!
  const auto = depthAuto(state)
  const advice = recommendTactics(state)
  const opp = advice.opp !== undefined ? state.teams[advice.opp] : undefined
  const same = (Object.keys(advice.tactics) as (keyof Tactics)[]).every((k) => team.tactics[k] === advice.tactics[k])
  // 先発にケガ人（自分で並べているとき）
  const hurtStarter = !auto && ids.slice(0, 5).some((id) => state.players[id].injury)
  return (
    <AppShell title="作戦と序列" current="tactics" color={team.colors.primary}>
      <div className="absolute inset-0 flex gap-2 p-2">
        <div className="panel scroll-y flex min-w-0 flex-1 flex-col p-2">
          <div className="mb-1 flex items-center gap-2 px-1">
            <span className="panel-head">
              <Term id="depth">序列</Term>
            </span>
            <div className="seg ml-1" role="tablist">
              <button
                role="tab"
                aria-selected={auto}
                onClick={() =>
                  mutate((st) => {
                    st.club!.autoDepth = true
                  })
                }
              >
                おまかせ
              </button>
              <button
                role="tab"
                aria-selected={!auto}
                onClick={() =>
                  mutate((st) => {
                    st.club!.depth = clubDepth(st)
                    st.club!.autoDepth = false
                  })
                }
              >
                自分で
              </button>
            </div>
            {!auto && (
              <button
                className="btn btn-blue btn-sm ml-auto"
                onClick={() =>
                  mutate((st) => {
                    st.club!.depth = recommendDepth(st)
                  })
                }
              >
                おすすめに並べる
              </button>
            )}
          </div>
          <div className={`mb-1 px-1 text-[0.68rem] leading-snug ${hurtStarter ? 'font-bold text-bad' : 'text-ink-dim'}`}>
            {auto
              ? '試合のたびに、ケガ・調子・疲れを見て並べ直します（先発はポジションの並びと外国籍の枠も考えます）。▲▼で動かすと「自分で」に変わります。'
              : hurtStarter
                ? '先発にケガをしている選手がいます。「おすすめに並べる」か、▲▼で入れ替えてください。'
                : '上の 5 人が先発。▲▼で入れ替え。ケガの選手は試合に出ません。'}
          </div>
          {ids.map((id, i) => {
            const p = state.players[id]
            return (
              <div key={id}>
                {i === 5 && <div className="my-1 border-t border-dashed border-gold/40 text-center text-[0.62rem] text-gold/70">ここまで先発</div>}
                {i === size && <div className="my-1 border-t border-dashed border-line text-center text-[0.62rem] text-ink-mute">ここから下は、ふだんは出ない</div>}
                {i === gameDaySize(team.league) && (
                  <div className="my-1 border-t border-dashed border-bad/40 text-center text-[0.62rem] text-bad">ここから下は試合のベンチに入らない（出られるのは上から {gameDaySize(team.league)} 人）</div>
                )}
                <div className={`flex items-center gap-2 rounded-lg px-2 py-1 ${i < 5 ? 'bg-gold/[0.06]' : ''} ${p.injury ? 'opacity-50' : ''}`}>
                  <span className="num w-5 text-center text-[0.75rem] font-black text-ink-dim">{i + 1}</span>
                  <PosBadge pos={p.pos} />
                  <button className="min-w-0 flex-1 truncate text-left text-[0.85rem] font-bold" onClick={() => push({ id: 'player', params: { playerId: id } })}>
                    {p.name}
                    {p.nation !== 'JP' && <span className="ml-1 text-[0.62rem] font-normal text-ink-mute">{['PH', 'KR', 'CN'].includes(p.nation) ? 'アジア枠' : '外国籍'}</span>}
                    {p.injury && <span className="ml-1 text-[0.65rem] font-normal text-bad">ケガ（{p.injury.weeks} 週）</span>}
                  </button>
                  <span className="text-[0.8rem]" title={`気持ち ${Math.round(moodOf(state, id))}`}>
                    {moodFace(moodOf(state, id)).face}
                  </span>
                  <ConditionArrow value={p.condition} />
                  <span className="num w-10 text-right text-[0.68rem] text-ink-dim">疲 {Math.round(p.fatigue)}</span>
                  <OvrBadge value={ovr(p)} size="sm" />
                  <button className="btn btn-ghost btn-sm !h-7 !px-2" disabled={i === 0} onClick={() => mutate((st) => moveDepth(st, ids, id, -1))} aria-label="上へ">
                    ▲
                  </button>
                  <button className="btn btn-ghost btn-sm !h-7 !px-2" disabled={i === ids.length - 1} onClick={() => mutate((st) => moveDepth(st, ids, id, 1))} aria-label="下へ">
                    ▼
                  </button>
                </div>
              </div>
            )
          })}
        </div>
        <div className="panel scroll-y w-[22rem] shrink-0 space-y-2 p-3">
          <div className="panel-flat space-y-1 p-2">
            <div className="flex items-center gap-2">
              <span className="text-[0.82rem] font-black text-gold">おすすめの作戦</span>
              <span className="min-w-0 flex-1 truncate text-[0.66rem] text-ink-dim">{opp ? `次の相手: ${opp.name}` : '次の試合はまだありません'}</span>
            </div>
            {(Object.keys(advice.reasons) as (keyof Tactics)[]).map((k) => {
              const o = OPTIONS.find((x) => x.key === k)!
              const label = (o.opts as [unknown, string, string][]).find(([v]) => v === advice.tactics[k])?.[1]
              return (
                <div key={k} className="text-[0.66rem] leading-snug">
                  <span className="font-black">{o.label}: </span>
                  <span className={`font-black ${team.tactics[k] === advice.tactics[k] ? 'text-good' : 'text-orange'}`}>{label}</span>
                  <span className="text-ink-dim"> — {advice.reasons[k]}</span>
                </div>
              )
            })}
            <div className="flex items-center gap-2 pt-1">
              <button
                className="btn btn-blue btn-sm"
                disabled={same}
                onClick={() =>
                  mutate((st) => {
                    st.teams[team.id].tactics = { ...advice.tactics }
                  })
                }
              >
                {same ? 'おすすめどおり' : 'おすすめにする'}
              </button>
              <label className="flex items-center gap-1 text-[0.68rem]">
                <input
                  type="checkbox"
                  checked={!!c.autoTactics}
                  onChange={(e) =>
                    mutate((st) => {
                      st.club!.autoTactics = e.target.checked
                    })
                  }
                />
                試合ごとにおまかせ
              </label>
            </div>
            {c.autoTactics && <div className="text-[0.62rem] leading-snug text-ink-mute">試合のたびに、その相手に合わせたおすすめの作戦で戦います（下の作戦は、おまかせを外したときに使います）。</div>}
          </div>
          <div className="panel-head">作戦</div>
          {OPTIONS.map((o) => (
            <div key={o.key}>
              <div className="flex items-center gap-1 text-[0.8rem] font-black">
                {o.label} <TermHelp id={o.term} />
              </div>
              <div className="mt-0.5 grid grid-cols-2 gap-1">
                {o.opts.map(([v, label, note]) => {
                  const sel = team.tactics[o.key] === v
                  const rec = advice.tactics[o.key] === v
                  return (
                    <button key={String(v)} onClick={() => mutate((st) => void ((st.teams[team.id].tactics as unknown as Record<string, unknown>)[o.key] = v))} className={`rounded-lg border px-2 py-1 text-left ${sel ? 'border-gold bg-gold/15' : 'border-line/50 bg-black/[0.04]'}`}>
                      <div className="flex items-center gap-1 text-[0.78rem] font-black">
                        {label}
                        {rec && <span className="rounded bg-[#2a7fdc]/15 px-1 text-[0.56rem] font-black text-[#1f5fae]">おすすめ</span>}
                      </div>
                      {note && <div className="text-[0.62rem] leading-tight text-ink-dim">{note}</div>}
                    </button>
                  )
                })}
              </div>
            </div>
          ))}
          <div className="text-[0.68rem] leading-snug text-ink-mute">
            国内リーグでは、<Term id="foreignQuota">外国籍</Term>の選手はコートに同時に 3 人まで（アジア枠は数えない）。先発に 3 人とも並べられます。
          </div>
        </div>
      </div>
    </AppShell>
  )
}
