/** 用語集: 分類のタブ・言葉の検索・一覧と解説。params.id で特定の用語を開く。 */
import { useMemo } from 'react'
import { GLOSSARY, GLOSSARY_BY_ID, GLOSSARY_CATS, type GlossaryCat } from '../../engine/data/glossary'
import { AppShell } from '../layout/AppShell'
import { useCurrentScreen } from '../../stores/uiStore'
import { useScreenState, useScrollMemo } from '../hooks/useScreenState'
import { Icon } from '../components/Icon'

export function GlossaryScreen() {
  const screen = useCurrentScreen()
  const start = (screen.params?.id as string | undefined) ?? undefined
  const [cat, setCat] = useScreenState<GlossaryCat | 'all'>('cat', 'position', start ? 'all' : undefined)
  const [sel, setSel] = useScreenState<string>('sel', 'pos:PG', start)
  const [q, setQ] = useScreenState('q', '')
  const listRef = useScrollMemo('list')
  const list = useMemo(() => {
    const k = q.trim()
    return GLOSSARY.filter((g) => (cat === 'all' || g.cat === cat) && (!k || g.term.includes(k) || g.short.includes(k) || g.body.includes(k) || (g.sub ?? '').toLowerCase().includes(k.toLowerCase())))
  }, [cat, q])
  const g = GLOSSARY_BY_ID[sel] ?? list[0]
  return (
    <AppShell title="用語集" current="glossary" back>
      <div className="absolute inset-0 flex gap-2 p-2">
        {/* 分類 */}
        <div className="scroll-y flex w-[9.5rem] shrink-0 flex-col gap-1">
          <label className="panel-flat flex items-center gap-1.5 px-2 py-1.5">
            <Icon name="help" className="h-4 w-4 shrink-0 text-ink-dim" />
            <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="言葉で探す" className="w-full min-w-0 bg-transparent text-[0.85rem] outline-none placeholder:text-ink-mute" />
          </label>
          {[{ id: 'all' as const, label: 'すべて' }, ...GLOSSARY_CATS].map((c) => (
            <button key={c.id} className={`rounded-lg px-2.5 py-2 text-left text-[0.85rem] font-bold ${cat === c.id ? 'bg-gold/20 text-gold' : 'text-ink-dim hover:bg-black/5'}`} onClick={() => setCat(c.id)}>
              {c.label}
              <span className="ml-1 text-[0.7rem] opacity-70">{c.id === 'all' ? GLOSSARY.length : GLOSSARY.filter((x) => x.cat === c.id).length}</span>
            </button>
          ))}
        </div>
        {/* 一覧 */}
        <div ref={listRef} className="scroll-y panel w-[15rem] shrink-0 p-1">
          {list.map((x) => (
            <button key={x.id} className={`cv-row block w-full rounded-lg px-2.5 py-1.5 text-left ${g?.id === x.id ? 'bg-orange/20' : 'hover:bg-black/5'}`} onClick={() => setSel(x.id)}>
              <div className="truncate text-[0.88rem] font-black">{x.term}</div>
              <div className="truncate text-[0.7rem] text-ink-dim">{x.short}</div>
            </button>
          ))}
          {list.length === 0 && <div className="p-3 text-[0.8rem] text-ink-dim">見つかりませんでした</div>}
        </div>
        {/* 解説 */}
        <div className="scroll-y panel panel-hero min-w-0 flex-1 p-4">
          {g && (
            <>
              <div className="text-[0.75rem] font-bold text-ink-mute">{GLOSSARY_CATS.find((c) => c.id === g.cat)?.label}</div>
              <div className="text-[1.4rem] font-black leading-tight">{g.term}</div>
              {g.sub && <div className="text-[0.78rem] text-ink-mute">{g.sub}</div>}
              <div className="mt-1 text-[0.95rem] font-bold text-orange">{g.short}</div>
              <p className="mt-3 whitespace-pre-line text-[0.92rem] leading-relaxed">{g.body}</p>
              {g.see && g.see.length > 0 && (
                <div className="mt-4">
                  <div className="panel-head mb-1.5">関連する言葉</div>
                  <div className="flex flex-wrap gap-1.5">
                    {g.see.map((s) => (
                      <button key={s} className="rounded-full border border-line px-3 py-1.5 text-[0.8rem] font-bold text-ink-dim hover:text-gold" onClick={() => setSel(s)}>
                        {GLOSSARY_BY_ID[s]?.term ?? s}
                      </button>
                    ))}
                  </div>
                </div>
              )}
            </>
          )}
        </div>
      </div>
    </AppShell>
  )
}
