/**
 * 試合の観戦（2D・上から）。エンジンを 1 ポゼッションずつ進め、choreo.ts の動きを描く。
 * 再生は VIEW_RATE 倍（×1 で 48 分の試合が約 16 分）。速度は ×1・×2・×4・×8。「最後まで」で結果へ。
 * 実況と点は、ボールがリングに届くころに出す（先に結果が見えないように）。
 * control（クラブ経営）: 自分のチームに、タイムアウト・交代・作戦を指示できる（次のデッドボールで）。
 */
import { useEffect, useMemo, useRef, useState } from 'react'
import { RULES, type RuleSet } from '../../engine'
import { MatchEngine } from '../../engine/match/engine'
import { Choreographer } from '../../engine/match/choreo'
import { comment, type CommentLine } from '../../engine/match/commentary'
import type { Beat, GameEvent, MatchSetup, MatchSummary, Moment, MomentOption, PossLog, SimTeam, Trace } from '../../engine/match/types'
import { CourtRenderer, colorsClash, lerpBeat } from './court'
import { sound } from '../audio/sound'
import { useMusic } from '../audio/useMusic'
import { useSettings } from '../../stores/settingsStore'
import { Icon } from '../components/Icon'
import { SideSheet } from '../layout/SideSheet'

/** ×1 での再生の倍率（試合の秒 / 実際の秒） */
const VIEW_RATE = 3

interface Playing {
  log: PossLog
  beats: Beat[]
  /** 実況の出来事と、出す時刻 */
  timed: { t: number; e: GameEvent }[]
  end: number
  /** どこまで出したか */
  shown: number
  cueIdx: number
  /** ポゼッションのはじめの点 */
  base: [number, number]
}

function periodName(rules: RuleSet, p: number): string {
  if (p > rules.periods) return `延長${p - rules.periods > 1 ? p - rules.periods : ''}`
  return rules.periods === 2 ? (p === 1 ? '前半' : '後半') : `第${p}クォーター`
}

function fmtClock(sec: number): string {
  const s = Math.max(0, sec)
  if (s < 60) return s.toFixed(1)
  return `${Math.floor(s / 60)}:${String(Math.floor(s % 60)).padStart(2, '0')}`
}

/** 出来事と、流れ（Trace）の時刻を種類の順に結ぶ */
function timeEvents(events: GameEvent[], marks: { t: number; a: Trace['a'] }[]): { t: number; e: GameEvent }[] {
  const kindOf: Partial<Record<GameEvent['k'], Trace['a']>> = { shot: 'shot', ft: 'ft', reb: 'reb', tov: 'tov', foul: 'foul' }
  const used = new Set<number>()
  return events.map((e) => {
    const a = kindOf[e.k]
    if (!a) return { t: 0, e }
    const i = marks.findIndex((m, j) => m.a === a && !used.has(j))
    if (i < 0) return { t: 0, e }
    used.add(i)
    return { t: marks[i].t, e }
  })
}

export interface MomentResult {
  tried: number
  won: number
}

export function MatchView({ setup, onFinish, focusPlayerId, control }: { setup: MatchSetup; onFinish: (s: MatchSummary, engine: MatchEngine, moments: MomentResult) => void; focusPlayerId?: number; control?: 0 | 1 }) {
  const rules = RULES[setup.rules]
  const engine = useMemo(() => new MatchEngine(setup, { live: true }), [setup])
  const looks = useMemo(() => {
    const m = new Map<number, { pos: SimTeam['players'][number]['pos']; jersey: number; name: string; side: 0 | 1 }>()
    engine.teams.forEach((t, side) => t.players.forEach((p) => m.set(p.id, { pos: p.pos, jersey: p.jersey, name: p.short, side: side as 0 | 1 })))
    return m
  }, [engine])
  const choreo = useMemo(() => new Choreographer((id) => looks.get(id)!, rules, rules.periods), [looks, rules])
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const wrapRef = useRef<HTMLDivElement>(null)
  const startSpeed = useSettings((s) => s.matchSpeed)
  const [speed, setSpeed] = useState<number>(startSpeed)
  const [paused, setPaused] = useState(false)
  const [boxOpen, setBoxOpen] = useState(false)
  const [coachOpen, setCoachOpen] = useState(false)
  /** 指示を出したら画面を描き直す */
  const [, setTick] = useState(0)
  const [hud, setHud] = useState({ score: [0, 0] as [number, number], period: 1, clock: rules.periodMin * 60, shot: rules.shotClock as number, lines: [] as CommentLine[] })
  const [done, setDone] = useState(false)
  /** 見せ場（選ぶまで止める） */
  const [moment, setMoment] = useState<Moment | null>(null)
  const choiceRef = useRef<MomentOption['id'] | null>(null)
  const momentsRef = useRef<MomentResult>({ tried: 0, won: 0 })
  const [lastMoment, setLastMoment] = useState<{ success: boolean; label: string } | null>(null)
  const speedRef = useRef(speed)
  const pausedRef = useRef(paused)
  useEffect(() => {
    speedRef.current = speed
  }, [speed])
  useEffect(() => {
    pausedRef.current = paused || boxOpen || coachOpen || !!moment
  }, [paused, boxOpen, coachOpen, moment])
  useMusic('match')

  const home = engine.teams[0]
  const away = engine.teams[1]
  const awayColor = colorsClash(home.colors.primary, away.colors.primary) ? { primary: away.colors.secondary, secondary: away.colors.primary } : away.colors

  useEffect(() => {
    const canvas = canvasRef.current!
    const wrap = wrapRef.current!
    const renderer = new CourtRenderer(canvas, rules, { ...home.colors, numbers: [] }, { ...awayColor, numbers: [] })
    let w = 0
    let h = 0
    const fit = () => {
      w = wrap.clientWidth
      h = wrap.clientHeight
      renderer.resize(canvas, w, h, Math.min(2, window.devicePixelRatio || 1))
    }
    fit()
    const ro = new ResizeObserver(fit)
    ro.observe(wrap)

    const nameOf = (id: number) => looks.get(id)?.name ?? '?'
    const teamName = (s: 0 | 1) => engine.teams[s].short
    let cur: Playing | null = null
    let play = 0
    let last = performance.now()
    let raf = 0
    let finished = false
    const score: [number, number] = [0, 0]
    let lines: CommentLine[] = []
    let lastDribble = 0
    let lastPeriod = 1
    let hudClock = -1

    const next = (): boolean => {
      // 見せ場: 選択を待つ（選んだら次のフレームで進む）
      const m = focusPlayerId !== undefined ? engine.peekMoment() : null
      if (m && !choiceRef.current) {
        if (!pausedRef.current) setMoment(m)
        return true
      }
      const choice = choiceRef.current ?? undefined
      choiceRef.current = null
      const log = engine.step(choice)
      if (!log) return false
      if (log.moment) {
        momentsRef.current.tried++
        if (log.moment.success) momentsRef.current.won++
        const label = m?.options.find((o) => o.id === log.moment!.choice)?.label ?? ''
        setTimeout(() => setLastMoment({ success: log.moment!.success, label }), 1200)
      }
      if (log.period !== lastPeriod) {
        choreo.resetPositions()
        lastPeriod = log.period
      }
      const { beats, marks } = choreo.build(log)
      const timed = timeEvents(log.events, marks)
      cur = { log, beats, timed, end: (beats[beats.length - 1]?.t ?? log.dur) + 0.25, shown: 0, cueIdx: 0, base: [...score] as [number, number] }
      play = 0
      return true
    }

    const frame = (now: number) => {
      raf = requestAnimationFrame(frame)
      const dt = Math.min(0.1, (now - last) / 1000)
      last = now
      if (!pausedRef.current && !finished) play += dt * VIEW_RATE * speedRef.current
      if (!cur || play >= cur.end) {
        if (!finished && !pausedRef.current) {
          const before = cur
          if (!next()) {
            finished = true
            sound.play('buzzer')
            setDone(true)
            onFinish(engine.summary(), engine, momentsRef.current)
          } else if (cur === before) return
        }
      }
      if (!cur) return
      const c: Playing = cur
      // 実況と点（時刻が来たものから）
      let changed = false
      while (c.shown < c.timed.length && c.timed[c.shown].t <= play) {
        const { e } = c.timed[c.shown++]
        if (e.k === 'shot' && e.made) score[e.side] += e.pts
        if (e.k === 'ft' && e.made) score[e.side] += 1
        if (e.k === 'shot' && e.made && (e.pts === 3 || e.dunk)) sound.play('cheer')
        if (e.k === 'end') sound.play('buzzer')
        const line = comment(e, nameOf, teamName, (p) => periodName(rules, p))
        if (line) lines = [...lines.slice(-5), line]
        changed = true
      }
      // 効果音
      while (c.cueIdx < c.beats.length && c.beats[c.cueIdx].t <= play) {
        const cue = c.beats[c.cueIdx++].cue
        if (cue === 'dribble' && now - lastDribble > 260) {
          sound.play('dribble')
          lastDribble = now
        } else if (cue === 'swish') sound.play('swish')
        else if (cue === 'rim') sound.play('rim')
        else if (cue === 'dunk') sound.play('dunk')
        else if (cue === 'whistle') sound.play('whistle')
        else if (cue === 'steal') sound.play('squeak')
      }
      // 位置
      const bs = c.beats
      let i = 0
      while (i < bs.length - 1 && bs[i + 1].t <= play) i++
      const a = bs[i]
      const b = bs[Math.min(bs.length - 1, i + 1)]
      const st = lerpBeat(a, b, play)
      const numbers = c.log.lineup.map((id) => looks.get(id)?.jersey ?? 0)
      const focus = focusPlayerId !== undefined ? c.log.lineup.indexOf(focusPlayerId) : -1
      renderer.draw({ pos: st.pos, ball: st.ball, holder: st.holder, focus, numbers }, w, h)
      // 時計（ピリオドの残り・ショットクロック）
      const clock = c.log.clock - Math.min(play, c.log.dur)
      const reb = c.timed.find((x) => x.e.k === 'reb' && x.e.off && x.t <= play)
      const shot = reb ? Math.max(0, 14 - (play - reb.t)) : Math.max(0, rules.shotClock - play)
      if (changed || Math.floor(clock * 10) !== Math.floor(hudClock * 10)) {
        hudClock = clock
        setHud({ score: [...score] as [number, number], period: c.log.period, clock, shot, lines })
      }
    }
    raf = requestAnimationFrame(frame)
    return () => {
      cancelAnimationFrame(raf)
      ro.disconnect()
    }
    // エンジンは setup ごとに 1 つ（作り直さない）
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [engine])

  /** 最後まで（結果だけ） */
  const skip = () => {
    // 残りの見せ場は、いちばん見込みの高い手で自動に
    for (;;) {
      const m = focusPlayerId !== undefined ? engine.peekMoment() : null
      const best = m ? [...m.options].sort((a, b) => b.pct - a.pct)[0].id : undefined
      const log = engine.step(best)
      if (!log) break
      if (log.moment) {
        momentsRef.current.tried++
        if (log.moment.success) momentsRef.current.won++
      }
    }
    setMoment(null)
    if (!done) {
      setDone(true)
      onFinish(engine.summary(), engine, momentsRef.current)
    }
  }
  const choose = (id: MomentOption['id']) => {
    choiceRef.current = id
    setMoment(null)
  }

  // コートをタップで一時停止・再開
  const tapCourt = () => setPaused((p) => !p)

  return (
    <div className="absolute inset-0 flex flex-col bg-[#e9edf2]">
      {/* 上: 点と時計 */}
      <div className="safe-px safe-t flex h-[3.2rem] shrink-0 items-center gap-3" style={{ boxSizing: 'content-box' }}>
        <div className="flex min-w-0 flex-1 items-center justify-end gap-2">
          <span className="truncate text-[0.9rem] font-bold">{home.name}</span>
          <span className="h-6 w-1.5 rounded" style={{ background: home.colors.primary }} />
          <span className="num w-[3.2rem] text-right text-[1.6rem] font-black">{hud.score[0]}</span>
        </div>
        <div className="num flex w-[8.5rem] shrink-0 flex-col items-center leading-tight">
          <span className="text-[0.7rem] font-bold text-ink-dim">{periodName(rules, hud.period)}</span>
          <span className="flex items-baseline gap-2">
            <span className="text-[1.2rem] font-black text-gold">{fmtClock(hud.clock)}</span>
            <span className={`rounded bg-black/50 px-1 text-[0.8rem] font-black ${hud.shot <= 5 ? 'text-bad' : 'text-orange'}`}>{Math.ceil(hud.shot)}</span>
          </span>
        </div>
        <div className="flex min-w-0 flex-1 items-center gap-2">
          <span className="num w-[3.2rem] text-[1.6rem] font-black">{hud.score[1]}</span>
          <span className="h-6 w-1.5 rounded" style={{ background: awayColor.primary }} />
          <span className="truncate text-[0.9rem] font-bold">{away.name}</span>
        </div>
      </div>
      {/* コート */}
      <div ref={wrapRef} className="relative min-h-0 flex-1" onPointerUp={tapCourt}>
        <canvas ref={canvasRef} className="absolute inset-0 h-full w-full" />
        {paused && !done && !moment && <div className="pointer-events-none absolute inset-0 flex items-center justify-center text-[1.4rem] font-black text-[#1b2536]/75">一時停止中（タップで再開）</div>}
        {lastMoment && (
          <div className="anim-rise pointer-events-none absolute left-1/2 top-3 -translate-x-1/2 rounded-full px-4 py-1.5 text-[0.95rem] font-black shadow-xl" style={{ background: lastMoment.success ? 'linear-gradient(90deg,#f5c542,#ff7a1a)' : 'rgba(30,40,70,0.9)', color: lastMoment.success ? '#2a1a00' : '#cbd5e1' }} onAnimationEnd={() => setTimeout(() => setLastMoment(null), 1600)}>
            {lastMoment.success ? `成功！ ${lastMoment.label}` : `失敗… ${lastMoment.label}`}
          </div>
        )}
        {moment && (
          <div className="anim-fade absolute inset-0 flex items-end justify-center bg-black/45 pb-3" onPointerUp={(e) => e.stopPropagation()}>
            <div className="panel panel-solid panel-hero w-[36rem] max-w-[95%] p-3">
              <div className="mb-1 flex items-center gap-2">
                <span className="rounded bg-gold px-2 py-0.5 text-[0.75rem] font-black text-[#2a1a00]">{moment.clutch ? '勝負どころ！' : '見せ場'}</span>
                <span className="text-[0.85rem] font-bold">ボールが回ってきた。どうする？</span>
              </div>
              <div className="grid grid-cols-3 gap-2">
                {moment.options.map((o) => (
                  <button key={o.id} className="btn btn-ghost !h-auto flex-col !items-start !gap-0.5 !py-2 text-left" onClick={() => choose(o.id)}>
                    <span className="flex w-full items-center gap-2">
                      <span className={`text-[1.3rem] font-black ${o.mark === '◎' ? 'text-gold' : o.mark === '○' ? 'text-orange' : 'text-ink-dim'}`}>{o.mark}</span>
                      <span className="text-[0.92rem] font-black">{o.label}</span>
                    </span>
                    <span className="whitespace-normal text-[0.7rem] font-normal text-ink-dim">{o.note}</span>
                  </button>
                ))}
              </div>
              <div className="mt-1 text-[0.68rem] text-ink-mute">◎ 決まりやすい ○ ふつう △ 難しい（能力と、マークする相手で変わる）</div>
            </div>
          </div>
        )}
      </div>
      {/* 下: 実況と操作 */}
      <div className="safe-px safe-b flex h-[4.4rem] shrink-0 items-center gap-2" style={{ boxSizing: 'content-box' }}>
        <div className="min-w-0 flex-1 overflow-hidden text-[0.8rem] leading-snug">
          {hud.lines.slice(-2).map((l, i, arr) => (
            <div key={`${i}:${l.text}`} className={`truncate ${i === arr.length - 1 ? 'text-ink' : 'text-ink-mute'} ${l.big && i === arr.length - 1 ? 'font-black text-gold' : ''}`}>
              {l.text}
            </div>
          ))}
        </div>
        <div className="seg shrink-0">
          {[1, 2, 4, 8].map((v) => (
            <button key={v} aria-selected={speed === v} onClick={() => setSpeed(v)}>
              ×{v}
            </button>
          ))}
        </div>
        <button className="btn btn-ghost btn-sm" onClick={() => setPaused((p) => !p)} aria-label={paused ? '再開' : '一時停止'}>
          <Icon name={paused ? 'play' : 'grid'} className="h-4 w-4" />
          {paused ? '再開' : '停止'}
        </button>
        {control !== undefined && (
          <button className="btn btn-blue btn-sm" onClick={() => setCoachOpen(true)} disabled={done}>
            指示
            {(engine.requests(control).timeout || engine.requests(control).subs.length > 0) && <span className="rounded-full bg-gold px-1.5 text-[0.65rem] font-black text-[#2a1a00]">待</span>}
          </button>
        )}
        <button className="btn btn-ghost btn-sm" onClick={() => setBoxOpen(true)}>
          成績
        </button>
        <button className="btn btn-gold btn-sm" onClick={skip} disabled={done}>
          <Icon name="forward" className="h-4 w-4" />
          最後まで
        </button>
      </div>
      <SideSheet open={boxOpen} onClose={() => setBoxOpen(false)} title="ボックススコア" width="72%">
        <BoxScore engine={engine} />
      </SideSheet>
      {control !== undefined && (
        <SideSheet open={coachOpen} onClose={() => setCoachOpen(false)} title="監督の指示" width="78%">
          <CoachPanel engine={engine} side={control} onChange={() => setTick((t) => t + 1)} />
        </SideSheet>
      )}
    </div>
  )
}

/** ボックススコア（両チーム） */
export function BoxScore({ engine }: { engine: MatchEngine }) {
  return (
    <div className="space-y-3 p-2">
      {engine.teams.map((t, side) => (
        <div key={side}>
          <div className="mb-1 flex items-center gap-2 px-1 text-[0.85rem] font-black">
            <span className="h-4 w-1.5 rounded" style={{ background: t.colors.primary }} />
            {t.name}
            <span className="num ml-auto text-[1rem]">{t.score}</span>
          </div>
          <table className="num w-full text-center text-[0.75rem]">
            <thead className="text-[0.66rem] text-ink-dim">
              <tr>
                <th className="text-left">選手</th>
                <th>分</th>
                <th>得点</th>
                <th>REB</th>
                <th>AST</th>
                <th>STL</th>
                <th>BLK</th>
                <th>FG</th>
                <th>3P</th>
                <th>FT</th>
                <th>TO</th>
                <th>PF</th>
                <th>+/-</th>
              </tr>
            </thead>
            <tbody>
              {t.players
                .filter((p) => p.box.secs > 0)
                .sort((a, b) => Number(b.box.started) - Number(a.box.started) || b.box.secs - a.box.secs)
                .map((p) => (
                  <tr key={p.id} className="border-t border-line/30">
                    <td className="max-w-[8rem] truncate py-0.5 text-left">
                      <span className="text-ink-mute">{p.jersey} </span>
                      {p.short}
                      {p.box.started && <span className="ml-0.5 text-[0.6rem] text-gold">先</span>}
                    </td>
                    <td>{Math.round(p.box.secs / 60)}</td>
                    <td className="font-black">{p.box.pts}</td>
                    <td>{p.box.oreb + p.box.dreb}</td>
                    <td>{p.box.ast}</td>
                    <td>{p.box.stl}</td>
                    <td>{p.box.blk}</td>
                    <td>
                      {p.box.fgm}-{p.box.fga}
                    </td>
                    <td>
                      {p.box.tpm}-{p.box.tpa}
                    </td>
                    <td>
                      {p.box.ftm}-{p.box.fta}
                    </td>
                    <td>{p.box.tov}</td>
                    <td className={p.box.pf >= 5 ? 'text-bad' : ''}>{p.box.pf}</td>
                    <td className={p.box.pm > 0 ? 'text-good' : p.box.pm < 0 ? 'text-bad' : ''}>{p.box.pm > 0 ? `+${p.box.pm}` : p.box.pm}</td>
                  </tr>
                ))}
            </tbody>
          </table>
        </div>
      ))}
    </div>
  )
}

const TACTIC_OPTS = {
  pace: [
    ['slow', 'ゆっくり'],
    ['normal', 'ふつう'],
    ['fast', '速く'],
  ],
  focus: [
    ['inside', 'インサイド'],
    ['balanced', 'バランス'],
    ['outside', '3P'],
  ],
  defense: [
    ['man', 'マンツー'],
    ['zone23', '2-3 ゾーン'],
    ['zone32', '3-2 ゾーン'],
    ['press', 'プレス'],
  ],
} as const

/** 監督の指示（クラブ経営の観戦）: タイムアウト・交代（出す選手 → 入れる選手）・作戦・交代のおまかせ */
function CoachPanel({ engine, side, onChange }: { engine: MatchEngine; side: 0 | 1; onChange: () => void }) {
  const t = engine.teams[side]
  const req = engine.requests(side)
  const [outId, setOutId] = useState<number | null>(null)
  const foulOut = RULES[engine.setup.rules].foulOut
  const court = t.court.map((i) => t.players[i])
  const bench = t.players.filter((_, i) => !t.court.includes(i))
  const pendingOut = new Set(req.subs.map((s) => s.out))
  const pendingIn = new Set(req.subs.map((s) => s.in))
  const row = (p: SimTeam['players'][number], onCourt: boolean) => {
    const sel = outId === p.id
    const disabled = !onCourt && (outId === null || p.out || p.fouls >= foulOut || pendingIn.has(p.id))
    return (
      <button
        key={p.id}
        disabled={disabled}
        onClick={() => {
          if (onCourt) setOutId(sel ? null : p.id)
          else if (outId !== null && engine.requestSub(side, outId, p.id)) {
            setOutId(null)
            onChange()
          }
        }}
        className={`flex w-full items-center gap-2 rounded-lg border px-2 py-1 text-left text-[0.8rem] ${sel ? 'border-gold bg-gold/15' : 'border-line/40 bg-black/[0.04]'} ${disabled ? 'opacity-45' : 'hover:bg-black/5'}`}
      >
        <span className="num w-6 text-center font-black text-ink-dim">{p.jersey}</span>
        <span className="w-7 text-[0.68rem] font-bold text-orange">{p.pos}</span>
        <span className="min-w-0 flex-1 truncate font-bold">
          {p.short}
          {p.foreignSlot && <span className="ml-1 text-[0.62rem] text-ink-mute">外</span>}
        </span>
        <span className="h-1.5 w-12 overflow-hidden rounded-full bg-black/50">
          <span className="block h-full rounded-full" style={{ width: `${p.energy}%`, background: p.energy > 70 ? '#3ddc84' : p.energy > 50 ? '#ffb020' : '#ff5a5f' }} />
        </span>
        <span className={`num w-10 text-right text-[0.7rem] ${p.fouls >= foulOut - 1 ? 'font-black text-bad' : 'text-ink-dim'}`}>F{p.fouls}</span>
        <span className="num w-9 text-right text-[0.72rem]">{p.box.pts}点</span>
        {(pendingOut.has(p.id) || pendingIn.has(p.id)) && <span className="rounded bg-gold px-1 text-[0.6rem] font-black text-[#2a1a00]">{pendingOut.has(p.id) ? '下がる' : '入る'}</span>}
      </button>
    )
  }
  return (
    <div className="flex h-full gap-3 p-3">
      <div className="scroll-y min-w-0 flex-1 space-y-1">
        <div className="panel-head">コート（下げる選手を選ぶ）</div>
        {court.map((p) => row(p, true))}
        <div className="panel-head pt-1">ベンチ（入れる選手を選ぶ）</div>
        {bench.map((p) => row(p, false))}
      </div>
      <div className="flex w-[15rem] shrink-0 flex-col gap-2">
        <button
          className="btn btn-gold"
          disabled={t.timeouts <= 0 || req.timeout}
          onClick={() => {
            engine.callTimeout(side)
            onChange()
          }}
        >
          {req.timeout ? 'タイムアウトを待っています' : `タイムアウト（残り ${t.timeouts}）`}
        </button>
        <div className="text-[0.68rem] leading-snug text-ink-mute">タイムアウトと交代は、次にボールが止まったときに行います。タイムアウトは相手の流れを止め、コートの 5 人の体力が少し戻ります。</div>
        {(Object.keys(TACTIC_OPTS) as (keyof typeof TACTIC_OPTS)[]).map((k) => (
          <div key={k}>
            <div className="text-[0.72rem] font-bold text-ink-dim">{k === 'pace' ? 'ペース' : k === 'focus' ? '攻めの重心' : '守り'}</div>
            <div className="seg mt-0.5 flex">
              {TACTIC_OPTS[k].map(([v, label]) => (
                <button
                  key={v}
                  className="flex-1 !px-1 text-[0.72rem]"
                  aria-selected={t.tactics[k] === v}
                  onClick={() => {
                    engine.setTactics(side, { [k]: v })
                    onChange()
                  }}
                >
                  {label}
                </button>
              ))}
            </div>
          </div>
        ))}
        <label className="mt-1 flex items-center gap-2 text-[0.78rem]">
          <input
            type="checkbox"
            checked={!t.manual}
            onChange={(e) => {
              engine.setAutoSubs(side, e.target.checked)
              onChange()
            }}
          />
          交代はコーチにおまかせ
        </label>
        <div className="text-[0.66rem] text-ink-mute">おまかせを外すと、自分で交代します（退場とケガだけは自動）。</div>
      </div>
    </div>
  )
}
