/**
 * オールスターの週末（主人公が選ばれたシーズン）: 3P コンテスト（タイミングのミニゲーム）・ダンクコンテスト（技を選ぶ）・本戦（観戦か結果だけ）。
 * 乱数: ミニゲームの相手の点は決まった種から（端末の操作で結果が変わるのは主人公の分だけ）。
 */
import { useEffect, useMemo, useRef, useState } from 'react'
import { createRng, hashSeed, ovr, type GameState, type Player } from '../../engine'
import { playerInput } from '../../engine/match/setup'
import { MatchEngine } from '../../engine/match/engine'
import type { MatchSetup } from '../../engine/match/types'
import { DEFAULT_TACTICS } from '../../engine/models/league'
import { useGame, useGameState } from '../../stores/gameStore'
import { useUi } from '../../stores/uiStore'
import { AppShell } from '../layout/AppShell'
import { BoxScore, MatchView } from '../match/MatchView'
import { Initials, Portrait } from '../components/Portrait'
import { Term } from '../components/Term'
import { sound } from '../audio/sound'
import { useMusic } from '../audio/useMusic'
import { playerPhoto } from '../components/playerPhoto'

type Phase = 'menu' | 'three' | 'dunk' | 'game' | 'gameResult'

function allStars(state: GameState, conf: string): Player[] {
  return state.awards
    .filter((a) => a.season === state.season && a.award === 'オールスター')
    .map((a) => state.players[a.playerId])
    .filter((p) => p && state.teams[p.teamId]?.conf === conf)
}

/** 3P コンテスト: 5 ラック × 5 球。マーカーが緑の帯にあるときに押すと入る（5 球目は 2 点） */
function ThreeContest({ me, rivals, seed, onDone }: { me: Player; rivals: Player[]; seed: number; onDone: (won: boolean, score: number) => void }) {
  const [shot, setShot] = useState(0)
  const [score, setScore] = useState(0)
  const [last, setLast] = useState<boolean | null>(null)
  const [pos, setPos] = useState(0)
  const t0 = useRef(0)
  const zone = Math.min(0.3, 0.08 + me.attr.three * 0.0017)
  const center = 0.5
  const speed = 0.9 + Math.floor(shot / 5) * 0.12
  useEffect(() => {
    if (shot >= 25) return
    let raf = 0
    const tick = (now: number) => {
      if (!t0.current) t0.current = now
      const t = ((now - t0.current) / 1000) * speed
      setPos(Math.abs(((t % 2) + 2) % 2 - 1))
      raf = requestAnimationFrame(tick)
    }
    raf = requestAnimationFrame(tick)
    return () => cancelAnimationFrame(raf)
  }, [shot, speed])
  const rivalScores = useMemo(() => {
    const rng = createRng(seed)
    return rivals.map((r) => {
      let s = 0
      for (let i = 0; i < 25; i++) if (rng.chance(Math.min(0.75, 0.32 + (r.attr.three - 60) * 0.012))) s += i % 5 === 4 ? 2 : 1
      return s
    })
  }, [rivals, seed])
  const shoot = () => {
    if (shot >= 25) return
    const make = Math.abs(pos - center) <= zone / 2
    const pts = make ? (shot % 5 === 4 ? 2 : 1) : 0
    sound.play(make ? 'swish' : 'rim')
    setLast(make)
    setScore((s) => s + pts)
    setShot((n) => n + 1)
  }
  const done = shot >= 25
  const best = Math.max(...rivalScores)
  return (
    <div className="absolute inset-0 flex gap-2 p-2">
      <div className="panel flex min-w-0 flex-1 flex-col items-center justify-center gap-3 p-4" onPointerDown={shoot}>
        <div className="text-[0.85rem] text-ink-dim">
          ラック {Math.min(5, Math.floor(shot / 5) + 1)} / 5・{(shot % 5) + 1} 球目{shot % 5 === 4 ? '（マネーボール 2 点）' : ''}
        </div>
        <div className="num text-[3rem] font-black text-gold">{score}</div>
        <div className="relative h-8 w-[80%] overflow-hidden rounded-full bg-black/50">
          <div className="absolute inset-y-0 bg-good/60" style={{ left: `${(center - zone / 2) * 100}%`, width: `${zone * 100}%` }} />
          <div className="absolute inset-y-0 w-1.5 -translate-x-1/2 bg-white shadow-[0_0_8px_white]" style={{ left: `${pos * 100}%` }} />
        </div>
        <div className={`h-6 text-[1.1rem] font-black ${last ? 'text-good' : 'text-bad'}`}>{last === null ? '' : last ? '入った！' : '外れ…'}</div>
        {!done ? <div className="text-[0.8rem] text-ink-mute">画面をタップしてシュート（白い線が緑の帯にあるとき）。3P が高いほど帯が広い</div> : (
          <button
            className="btn btn-gold"
            onPointerDown={(e) => e.stopPropagation()}
            onClick={() => onDone(score > best, score)}
          >
            結果を見る
          </button>
        )}
      </div>
      <div className="panel w-[15rem] shrink-0 p-3 text-[0.8rem]">
        <div className="panel-head mb-1">参加者</div>
        <div className="flex justify-between font-black text-gold">
          <span>{me.short}</span>
          <span className="num">{done ? score : '…'}</span>
        </div>
        {rivals.map((r, i) => (
          <div key={r.id} className="flex justify-between">
            <span>{r.short}</span>
            <span className="num">{done ? rivalScores[i] : '…'}</span>
          </div>
        ))}
      </div>
    </div>
  )
}

const DUNKS = [
  { id: 'easy', name: 'ワンハンド', base: 41, diff: 0 },
  { id: 'mid', name: '360°', base: 45, diff: 0.15 },
  { id: 'hard', name: 'レッグスルー', base: 49, diff: 0.32 },
]

/** ダンクコンテスト: 3 本。技を選ぶ（むずかしいほど高得点だが失敗しやすい） */
function DunkContest({ me, rivals, seed, onDone }: { me: Player; rivals: Player[]; seed: number; onDone: (won: boolean, score: number) => void }) {
  const [round, setRound] = useState(0)
  const [scores, setScores] = useState<number[]>([])
  const [msg, setMsg] = useState('')
  const rng = useMemo(() => createRng(seed), [seed])
  const skill = (me.attr.dunk + me.attr.jump) / 200
  const rivalTotal = useMemo(() => {
    const r = createRng(seed + 1)
    return rivals.map((x) => {
      let s = 0
      for (let i = 0; i < 3; i++) s += r.chance(0.5 + (x.attr.dunk - 70) / 60) ? r.int(42, 50) : r.int(30, 38)
      return s
    })
  }, [rivals, seed])
  const tryDunk = (d: (typeof DUNKS)[number]) => {
    const p = Math.max(0.1, Math.min(0.95, 0.55 + (skill - 0.7) * 1.6 - d.diff))
    const ok = rng.chance(p)
    const s = ok ? Math.min(50, d.base + rng.int(0, 4)) : rng.int(30, 36)
    sound.play(ok ? 'dunk' : 'rim')
    setMsg(ok ? `${d.name}が決まった！ ${s} 点` : `${d.name}は失敗… ${s} 点`)
    setScores((x) => [...x, s])
    setRound((n) => n + 1)
  }
  const total = scores.reduce((a, b) => a + b, 0)
  const done = round >= 3
  return (
    <div className="absolute inset-0 flex gap-2 p-2">
      <div className="panel flex min-w-0 flex-1 flex-col items-center justify-center gap-3 p-4">
        <div className="text-[0.85rem] text-ink-dim">{done ? '3 本終了' : `${round + 1} 本目。技を選んで跳べ！`}</div>
        <div className="num text-[3rem] font-black text-gold">{total}</div>
        <div className="h-6 text-[1rem] font-black">{msg}</div>
        {!done ? (
          <div className="grid w-full grid-cols-3 gap-2">
            {DUNKS.map((d) => {
              const p = Math.max(0.1, Math.min(0.95, 0.55 + (skill - 0.7) * 1.6 - d.diff))
              return (
                <button key={d.id} className="btn btn-ghost !h-auto flex-col !py-2" onClick={() => tryDunk(d)}>
                  <span className="text-[1rem] font-black">{d.name}</span>
                  <span className="text-[0.72rem] font-normal text-ink-dim">
                    最高 {d.base + 4} 点・成功 {Math.round(p * 100)}%
                  </span>
                </button>
              )
            })}
          </div>
        ) : (
          <button className="btn btn-gold" onClick={() => onDone(total > Math.max(...rivalTotal), total)}>
            結果を見る
          </button>
        )}
      </div>
      <div className="panel w-[15rem] shrink-0 p-3 text-[0.8rem]">
        <div className="panel-head mb-1">参加者</div>
        <div className="flex justify-between font-black text-gold">
          <span>{me.short}</span>
          <span className="num">{total}</span>
        </div>
        {rivals.map((r, i) => (
          <div key={r.id} className="flex justify-between">
            <span>{r.short}</span>
            <span className="num">{done ? rivalTotal[i] : '…'}</span>
          </div>
        ))}
        <div className="mt-2 text-[0.7rem] text-ink-mute">審査員の点（50 点満点）× 3 本の合計。ダンクとジャンプ力が高いほど成功しやすい</div>
      </div>
    </div>
  )
}

export function AllStarScreen() {
  const state = useGameState()
  const mutate = useGame((s) => s.mutate)
  const reset = useUi((s) => s.reset)
  const c = state.career!
  const me = state.players[c.playerId]
  const [phase, setPhase] = useState<Phase>('menu')
  const [result, setResult] = useState<string[]>([])
  useMusic('allstar')
  const [engine, setEngine] = useState<MatchEngine | null>(null)
  const [setup, setSetup] = useState<MatchSetup | null>(null)
  const east = allStars(state, 'E')
  const west = allStars(state, 'W')
  const seed = hashSeed(state.seed, state.season, 3232)
  const threeRivals = useMemo(
    () =>
      Object.values(state.players)
        .filter((p) => !p.isPlayer && state.teams[p.teamId]?.league === 'NBA')
        .sort((a, b) => b.attr.three - a.attr.three)
        .slice(0, 5),
    [state],
  )
  const dunkRivals = useMemo(
    () =>
      Object.values(state.players)
        .filter((p) => !p.isPlayer && state.teams[p.teamId]?.league === 'NBA' && ovr(p) < 82)
        .sort((a, b) => b.attr.dunk + b.attr.jump - a.attr.dunk - a.attr.jump)
        .slice(0, 3),
    [state],
  )
  const award = (name: string, line: string) =>
    mutate((st) => {
      st.awards.push({ season: st.season, league: 'NBA', award: name, playerId: me.id, name: me.name, teamName: st.teams[me.teamId]?.name ?? '', line })
      st.career!.fame = Math.min(100, st.career!.fame + 4)
    })
  const finish = () => {
    mutate((st) => void (st.career!.allStarDone = st.season))
    reset({ id: 'home' })
  }
  const makeSetup = (): MatchSetup => {
    const team = (name: string, abbr: string, ps: Player[], primary: string, secondary: string) => ({ teamId: -1, name, short: name, abbr, colors: { primary, secondary }, tactics: { ...DEFAULT_TACTICS, pace: 'fast' as const }, players: ps.map(playerInput) })
    return { home: team('イースト', 'EST', east, '#1d4ed8', '#ffffff'), away: team('ウエスト', 'WST', west, '#b91c1c', '#ffffff'), rules: 'NBA', seed, neutral: true, focusPlayerId: me.id }
  }
  const afterGame = (e: MatchEngine) => {
    const [h, a] = e.teams
    const win = h.score > a.score ? h : a
    const mvp = [...win.players].sort((x, y) => y.box.pts - x.box.pts)[0]
    const lines = [`${h.name} ${h.score} - ${a.score} ${a.name}`, `MVP: ${mvp.name}（${mvp.box.pts} 点）`]
    if (mvp.id === me.id) {
      award('オールスター MVP', `${mvp.box.pts} 点`)
      lines.push('あなたがオールスター MVP！')
    }
    setResult((r) => [...r, ...lines])
    setEngine(e)
    setPhase('gameResult')
  }

  if (phase === 'game' && setup) return <MatchView setup={setup} focusPlayerId={me.id} onFinish={(_s, e) => afterGame(e)} />

  return (
    <AppShell title={<Term id="allStar">オールスターの週末</Term>} current="home" back>
      {phase === 'three' && (
        <ThreeContest
          me={me}
          rivals={threeRivals}
          seed={seed + 3}
          onDone={(won, score) => {
            if (won) award('3P コンテスト優勝', `${score} 点`)
            setResult((r) => [...r, `3P コンテスト: ${score} 点${won ? '・優勝！' : ''}`])
            setPhase('menu')
          }}
        />
      )}
      {phase === 'dunk' && (
        <DunkContest
          me={me}
          rivals={dunkRivals}
          seed={seed + 7}
          onDone={(won, score) => {
            if (won) award('ダンクコンテスト優勝', `${score} 点`)
            setResult((r) => [...r, `ダンクコンテスト: ${score} 点${won ? '・優勝！' : ''}`])
            setPhase('menu')
          }}
        />
      )}
      {(phase === 'menu' || phase === 'gameResult') && (
        <div className="absolute inset-0 flex gap-2 p-2">
          <div className="grid min-w-0 flex-1 grid-cols-2 gap-2">
            {[
              ['イースト', east],
              ['ウエスト', west],
            ].map(([name, list]) => (
              <div key={name as string} className="panel scroll-y p-2">
                <div className="panel-head mb-1">{name as string}</div>
                {(list as Player[]).map((p) => (
                  <div key={p.id} className={`flex items-center gap-2 py-0.5 text-[0.78rem] ${p.isPlayer ? 'font-black text-gold' : ''}`}>
                    <Portrait id={playerPhoto(state, p)} kind="face" className="face-round h-6 w-6" fallback={<Initials name={p.short} className="h-full w-full" />} />
                    <span className="min-w-0 flex-1 truncate">{p.name}</span>
                    <span className="text-ink-dim">{state.teams[p.teamId]?.abbr}</span>
                  </div>
                ))}
              </div>
            ))}
          </div>
          <div className="panel flex w-[17rem] shrink-0 flex-col gap-2 p-3">
            <div className="text-[0.8rem] text-ink-dim">リーグの一流が集まるお祭り。出たい種目を選んでください。</div>
            <button className="btn btn-ghost" disabled={result.some((x) => x.startsWith('3P'))} onClick={() => setPhase('three')}>
              3P コンテスト
            </button>
            <button className="btn btn-ghost" disabled={result.some((x) => x.startsWith('ダンク'))} onClick={() => setPhase('dunk')}>
              ダンクコンテスト
            </button>
            <button
              className="btn btn-blue"
              disabled={phase === 'gameResult'}
              onClick={() => {
                setSetup(makeSetup())
                setPhase('game')
              }}
            >
              オールスターゲームを観戦
            </button>
            <button
              className="btn btn-ghost btn-sm"
              disabled={phase === 'gameResult'}
              onClick={() => {
                const e = new MatchEngine(makeSetup())
                e.simulate()
                afterGame(e)
              }}
            >
              ゲームは結果だけ
            </button>
            <div className="scroll-y min-h-0 flex-1 text-[0.8rem]">
              {result.map((r, i) => (
                <div key={i} className={r.includes('！') ? 'font-black text-gold' : ''}>
                  {r}
                </div>
              ))}
              {engine && phase === 'gameResult' && <BoxScore engine={engine} />}
            </div>
            <button className="btn btn-gold" onClick={finish}>
              週末を終える
            </button>
          </div>
        </div>
      )}
    </AppShell>
  )
}
