/** チームの画面（params.teamId）: ロスター（総合値と成長見込み）・戦力（総合力の見える化）・日程。選手を押すと選手の画面へ。 */
import { ageOf, dateLabel, ovr, rosterOf, teamPower, type GameState, type Player, type Team } from '../../engine'
import { useGameState } from '../../stores/gameStore'
import { useCurrentScreen, useUi } from '../../stores/uiStore'
import { AppShell } from '../layout/AppShell'
import { Flag, OvrBadge, PosBadge, TeamDot } from '../components/common'
import { Initials, Portrait } from '../components/Portrait'
import { Term } from '../components/Term'
import { useScreenState, useScrollMemo } from '../hooks/useScreenState'
import { salaryLabel } from '../money'
import { playerPhoto } from '../components/playerPhoto'
import { OutlookChip } from '../components/Outlook'
import { TeamStrengthView } from '../components/TeamStrength'

type Tab = 'roster' | 'strength' | 'schedule'

const CONTRACT_LABEL: Record<string, string> = { rookie: 'ルーキー', standard: '', max: 'マックス', min: '最低保証', twoWay: '2way', dev: '育成', pro: '', college: '奨学金', none: '' }
const CONTRACT_TERM: Record<string, string> = { rookie: 'rookieContract', max: 'maxContract', min: 'minContract', twoWay: 'twoWay', college: 'scholarship' }

function RosterRow({ state, team, p, onOpen }: { state: GameState; team: Team; p: Player; onOpen: () => void }) {
  const kind = p.contract.kind
  return (
    <tr className="cv-row border-t border-line/30 hover:bg-black/5" onClick={onOpen}>
      <td className="py-1 text-center text-ink-dim">{p.jersey}</td>
      <td>
        <span className="flex items-center gap-2">
          <Portrait id={playerPhoto(state, p)} kind="face" className="face-round h-8 w-8 shrink-0" fallback={<Initials name={p.short} className="h-full w-full" color={team.colors.primary} />} />
          <span className="min-w-0">
            <span className="flex items-center gap-1.5">
              <span className="truncate font-bold">{p.name}</span>
              {p.nation !== 'JP' || team.league === 'NBA' ? <Flag nation={p.nation} /> : null}
            </span>
          </span>
        </span>
      </td>
      <td className="text-center">
        <span className="inline-flex gap-0.5">
          <PosBadge pos={p.pos} />
          {p.pos2 && <PosBadge pos={p.pos2} dim />}
        </span>
      </td>
      <td className="text-center">{ageOf(state, p)}</td>
      <td className="text-center text-ink-dim">{p.heightCm}</td>
      <td className="text-center">
        <OvrBadge value={ovr(p)} size="sm" />
      </td>
      <td className="text-center">
        <OutlookChip p={p} />
      </td>
      <td className="text-right text-ink-dim">{salaryLabel(p.contract.salary, team.league)}</td>
      <td className="pr-2 text-center text-[0.72rem] text-ink-dim">
        {CONTRACT_LABEL[kind] ? (
          CONTRACT_TERM[kind] ? (
            <Term id={CONTRACT_TERM[kind]}>{CONTRACT_LABEL[kind]}</Term>
          ) : (
            CONTRACT_LABEL[kind]
          )
        ) : kind === 'college' ? null : (
          `${p.contract.years}年`
        )}
        {kind === 'college' && p.classYear ? ` ${p.classYear}年生` : ''}
      </td>
    </tr>
  )
}

export function TeamScreen() {
  const state = useGameState()
  const screen = useCurrentScreen()
  const push = useUi((s) => s.push)
  const team = state.teams[Number(screen.params?.teamId ?? 0)]
  const [tab, setTab] = useScreenState<Tab>('tab', 'roster', screen.params?.tab as Tab | undefined)
  const scrollRef = useScrollMemo(`team:${team.id}`)
  const roster = rosterOf(state, team).sort((a, b) => ovr(b) - ovr(a))
  const lg = state.leagues[team.league]
  const fixtures = state.fixtures.filter((f) => f.home === team.id || f.away === team.id)
  const payroll = roster.reduce((s, p) => s + p.contract.salary, 0)
  return (
    <AppShell title={team.name} current="league" back color={team.colors.primary}>
      <div className="absolute inset-0 flex gap-2 p-2">
        {/* 左: チームの情報 */}
        <div className="panel panel-hero flex w-[15rem] shrink-0 flex-col items-center gap-1.5 p-3 text-center">
          <TeamDot colors={team.colors} abbr={team.abbr} className="h-16 w-16 text-[0.95rem]" />
          <div className="text-[1.05rem] font-black leading-tight">{team.name}</div>
          <div className="text-[0.75rem] text-ink-dim">
            {lg.name}
            {team.conf && `・${team.conf === 'E' ? '東' : team.conf === 'W' ? '西' : team.conf}`}
            {team.div && `・${team.div}`}
          </div>
          <div className="mt-1 grid w-full grid-cols-2 gap-1.5 text-[0.75rem]">
            <button className="stat-chip px-2 py-1" onClick={() => setTab('strength')}>
              <div className="text-ink-dim">
                <Term id="teamPower">戦力</Term>
              </div>
              <div className="num text-[1rem] font-black">{teamPower(state, team).toFixed(1)}</div>
            </button>
            <div className="stat-chip px-2 py-1">
              <div className="text-ink-dim">格</div>
              <div className="num text-[1rem] font-black">{team.rep}</div>
            </div>
          </div>
          <div className="w-full text-left text-[0.75rem] leading-relaxed text-ink-dim">
            <div>監督: {team.coach.name}</div>
            <div>本拠地: {team.arena.name}（{team.arena.capacity.toLocaleString()}人）</div>
            {team.league !== 'NCAA' && (
              <div>
                年俸の合計: {salaryLabel(payroll, team.league)}
                {team.league === 'NBA' && (
                  <>
                    （<Term id="salaryCap">キャップ</Term> $150M）
                  </>
                )}
              </div>
            )}
            {team.affiliate !== undefined && (
              <button className="mt-1 font-bold text-accent underline" onClick={() => push({ id: 'team', params: { teamId: team.affiliate } })}>
                {team.league === 'NBA' ? '育成チーム' : '提携先'}: {state.teams[team.affiliate].name}
              </button>
            )}
          </div>
        </div>
        {/* 右: ロスター・日程 */}
        <div className="flex min-w-0 flex-1 flex-col gap-2">
          <div className="seg shrink-0 self-start" role="tablist">
            <button role="tab" aria-selected={tab === 'roster'} onClick={() => setTab('roster')}>
              ロスター {roster.length}
            </button>
            <button role="tab" aria-selected={tab === 'strength'} onClick={() => setTab('strength')}>
              戦力
            </button>
            <button role="tab" aria-selected={tab === 'schedule'} onClick={() => setTab('schedule')}>
              日程 {fixtures.length}
            </button>
          </div>
          <div ref={scrollRef} className="panel scroll-y min-h-0 flex-1">
            {tab === 'strength' ? (
              <TeamStrengthView team={team} />
            ) : tab === 'roster' ? (
              <table className="num w-full text-[0.85rem]">
                <thead className="sticky top-0 z-[1] bg-[#f3f0ea] text-[0.72rem] text-ink-dim">
                  <tr>
                    <th className="w-9 py-1.5">#</th>
                    <th className="text-left">選手</th>
                    <th>POS</th>
                    <th>年齢</th>
                    <th>身長</th>
                    <th>
                      <Term id="ovr">総合</Term>
                    </th>
                    <th>
                      <Term id="growthOutlook">見込み</Term>
                    </th>
                    <th className="text-right">年俸</th>
                    <th>契約</th>
                  </tr>
                </thead>
                <tbody>
                  {roster.map((p) => (
                    <RosterRow key={p.id} state={state} team={team} p={p} onOpen={() => push({ id: 'player', params: { playerId: p.id } })} />
                  ))}
                </tbody>
              </table>
            ) : (
              <table className="num w-full text-[0.85rem]">
                <tbody>
                  {fixtures.map((f) => {
                    const home = f.home === team.id
                    const opp = state.teams[home ? f.away : f.home]
                    const r = f.result
                    const win = r ? (home ? r.hs > r.as : r.as > r.hs) : null
                    return (
                      <tr key={f.id} className="cv-row border-t border-line/30">
                        <td className="w-[11rem] py-1.5 pl-3 text-[0.75rem] text-ink-dim">
                          {dateLabel(state.startYear, state.season, f.week)}・{'月火水木金土日'[f.day]}
                        </td>
                        <td className="w-8 text-center text-[0.75rem] text-ink-dim">{home ? 'vs' : '@'}</td>
                        <td>
                          <button className="flex items-center gap-2" onClick={() => push({ id: 'team', params: { teamId: opp.id } })}>
                            <TeamDot colors={opp.colors} abbr={opp.abbr} className="h-6 w-6 text-[0.5rem]" />
                            <span className="font-bold">{opp.name}</span>
                          </button>
                        </td>
                        <td className="pr-3 text-right">
                          {r ? (
                            <span className={win ? 'font-black text-good' : 'text-ink-dim'}>
                              {win ? '○' : '●'} {home ? r.hs : r.as}-{home ? r.as : r.hs}
                              {r.ot ? ` (OT${r.ot > 1 ? r.ot : ''})` : ''}
                            </span>
                          ) : (
                            <span className="text-ink-mute">-</span>
                          )}
                        </td>
                      </tr>
                    )
                  })}
                </tbody>
              </table>
            )}
          </div>
        </div>
      </div>
    </AppShell>
  )
}
