/** 実況（試合の出来事 → 日本語の 1 行）。観戦の画面の下に流す。 */
import type { GameEvent } from './types'

export interface CommentLine {
  text: string
  /** 強調（得点・ブロック・スティールなど） */
  big?: boolean
  side?: 0 | 1
}

const ZONE: Record<string, string> = { rim: 'ゴール下', paint: 'ペイント内', mid: 'ミドル', three: '3P', corner3: 'コーナーの 3P' }

export function comment(e: GameEvent, name: (id: number) => string, team: (side: 0 | 1) => string, periodName: (p: number) => string): CommentLine | null {
  switch (e.k) {
    case 'period':
      return { text: `${periodName(e.period)}開始`, big: true }
    case 'end':
      return { text: `${periodName(e.period)}終了`, big: true }
    case 'shot': {
      const who = name(e.pid)
      if (e.blk) return { text: `${name(e.blk)}がブロック！ ${who}のシュートを叩き落とす`, big: true, side: e.side === 0 ? 1 : 0 }
      if (e.made) {
        const how = e.dunk ? '豪快なダンク！' : e.zone === 'three' || e.zone === 'corner3' ? `${ZONE[e.zone]}が決まる！` : e.fast ? '速攻で決める' : `${ZONE[e.zone]}を決める`
        const ast = e.ast ? `（アシスト: ${name(e.ast)}）` : ''
        const and = e.fouled ? ' バスケットカウント！' : ''
        const clutch = e.clutch ? '大事な場面で、' : ''
        return { text: `${clutch}${who}の${how}${and}${ast}`, big: e.pts === 3 || !!e.dunk || !!e.fouled || !!e.clutch, side: e.side }
      }
      return { text: `${who}の${ZONE[e.zone]}は外れる${e.fouled ? '（ファウル）' : ''}`, side: e.side }
    }
    case 'ft':
      return { text: `${name(e.pid)} フリースロー ${e.of > 1 ? `${e.n}本目 ` : ''}${e.made ? '成功' : '失敗'}`, side: e.side }
    case 'reb':
      return { text: `${name(e.pid)}が${e.off ? 'オフェンス' : ''}リバウンド`, side: e.side }
    case 'tov':
      if (e.stl) return { text: `${name(e.stl)}がスティール！`, big: true, side: e.side === 0 ? 1 : 0 }
      if (e.kind === 'clock') return { text: `${team(e.side)}、24 秒オーバー`, side: e.side }
      if (e.kind === 'charge') return { text: `${name(e.pid)}のオフェンスファウル`, side: e.side }
      return { text: `${name(e.pid)}のパスミス`, side: e.side }
    case 'foul':
      return { text: `${name(e.pid)}のファウル${e.bonus ? '（フリースロー 2 本）' : ''}`, side: e.side }
    case 'sub':
      return { text: `${team(e.side)} 交代: ${name(e.in)} ⇔ ${name(e.out)}`, side: e.side }
    case 'timeout':
      return { text: `${team(e.side)}がタイムアウト`, side: e.side }
  }
}
