/** つづきから（セーブスロットの選択）。 */
import { useEffect, useState } from 'react'
import { listSlots, type SaveSlotMeta } from '../../persistence/db'
import { flushSave, useGame } from '../../stores/gameStore'
import { useUi } from '../../stores/uiStore'
import { Icon } from '../components/Icon'
import { formatMoneyShort } from '../format'

export function LoadScreen() {
  const pop = useUi((s) => s.pop)
  const reset = useUi((s) => s.reset)
  const load = useGame((s) => s.load)
  const [slots, setSlots] = useState<SaveSlotMeta[] | null>(null)
  const [error, setError] = useState('')

  useEffect(() => {
    void flushSave()
      .then(() => listSlots())
      .then(setSlots)
      .catch(() => setError('セーブデータを読めませんでした'))
  }, [])

  const open = async (id: number) => {
    const ok = await load(id)
    if (ok) reset({ id: 'home' })
    else setError('このセーブデータは開けませんでした')
  }

  return (
    <div className="absolute inset-0 flex flex-col">
      <header className="topbar safe-px flex shrink-0 items-center gap-2" style={{ boxSizing: 'content-box' }}>
        <button className="flex h-10 w-10 items-center justify-center rounded-lg text-ink-dim hover:bg-black/5" onClick={pop} aria-label="戻る">
          <Icon name="back" className="h-5 w-5" />
        </button>
        <h1 className="text-[1.05rem] font-extrabold">つづきから</h1>
      </header>
      <div className="scroll-y safe-px safe-pb min-h-0 flex-1 pt-3">
        {error && <div className="mb-2 rounded-lg bg-bad/15 px-3 py-2 text-[0.85rem] text-bad">{error}</div>}
        {slots && slots.length === 0 && <div className="panel mx-auto max-w-[46rem] p-4 text-center text-[0.9rem] text-ink-dim">セーブデータがありません</div>}
        <div className="mx-auto grid max-w-[46rem] gap-2">
          {slots?.map((s) => (
            <button key={s.id} onClick={() => open(s.id)} className="panel card-hover flex items-center gap-3 p-3 text-left">
              <span className="num flex h-10 w-10 items-center justify-center rounded-lg bg-gold/15 text-[1.1rem] font-black text-gold">{s.id}</span>
              <span className="min-w-0 flex-1">
                <span className="flex items-center gap-1.5">
                  <span className={`shrink-0 rounded px-1.5 text-[0.68rem] font-bold ${s.mode === 'career' ? 'bg-orange/20 text-orange' : 'bg-gold/15 text-gold'}`}>{s.mode === 'career' ? 'キャリア' : 'クラブ'}</span>
                  <span className="truncate text-[1rem] font-black">{s.title}</span>
                </span>
                <span className="block text-[0.75rem] text-ink-dim">
                  {s.dateLabel}
                  {s.leagueName && `・${s.leagueName}`}
                  {s.rank ? ` ${s.rank}位` : ''}
                </span>
              </span>
              <span className="num text-[0.85rem] font-bold text-gold">
                {s.mode === 'career' && <span className="mr-1 text-[0.68rem] opacity-80">貯金</span>}
                {formatMoneyShort(s.money)}円
              </span>
            </button>
          ))}
        </div>
      </div>
    </div>
  )
}
