/**
 * 用語の解説（ユーザーの要望）。<Term id="draft">ドラフト</Term> は点線の下線つきの言葉で、タップすると解説の小窓。
 * <TermHelp id="draft" /> は小さな「？」。どちらも #overlay-root に描く（回転表示でも一緒に回る）。
 * 中身は engine/data/glossary.ts。設定の「用語の下線」を切ると、下線だけ消える（タップはできる）。
 */
import { useState, type ReactNode } from 'react'
import { createPortal } from 'react-dom'
import { GLOSSARY_BY_ID } from '../../engine/data/glossary'
import { useSettings } from '../../stores/settingsStore'
import { useUi } from '../../stores/uiStore'
import { useOverlayRoot } from '../stage/overlayRoot'
import { Icon } from './Icon'

function TermPopup({ id, onClose }: { id: string; onClose: () => void }) {
  const root = useOverlayRoot()
  const [cur, setCur] = useState(id)
  const g = GLOSSARY_BY_ID[cur]
  if (!root || !g) return null
  return createPortal(
    <div className="anim-fade absolute inset-0 z-[65] flex items-center justify-center bg-black/55 p-4" onClick={onClose}>
      <div className="panel panel-solid flex max-h-full w-[30rem] max-w-full flex-col p-4" onClick={(e) => e.stopPropagation()} role="dialog" aria-label={g.term}>
        <div className="flex items-start gap-2">
          <Icon name="book" className="mt-0.5 h-5 w-5 shrink-0 text-gold" />
          <div className="min-w-0 flex-1">
            <div className="text-[1.05rem] font-black">{g.term}</div>
            {g.sub && <div className="text-[0.72rem] text-ink-mute">{g.sub}</div>}
            <div className="mt-0.5 text-[0.85rem] font-bold text-orange">{g.short}</div>
          </div>
          <button className="-mr-1 -mt-1 flex h-9 w-9 items-center justify-center rounded-lg text-ink-dim hover:bg-black/5" onClick={onClose} aria-label="閉じる">
            <Icon name="close" className="h-5 w-5" />
          </button>
        </div>
        <div className="scroll-y mt-2 min-h-0 whitespace-pre-line text-[0.85rem] leading-relaxed">{g.body}</div>
        {g.see && g.see.length > 0 && (
          <div className="mt-2 flex flex-wrap gap-1.5">
            {g.see.map((s) => (
              <button key={s} className="rounded-full border border-line px-2.5 py-1 text-[0.75rem] font-bold text-ink-dim" onClick={() => setCur(s)}>
                {GLOSSARY_BY_ID[s]?.term ?? s}
              </button>
            ))}
          </div>
        )}
        <div className="mt-3 flex gap-2">
          <button
            className="btn btn-ghost btn-sm flex-1"
            onClick={() => {
              onClose()
              useUi.getState().push({ id: 'glossary', params: { id: cur } })
            }}
          >
            用語集で見る
          </button>
          <button className="btn btn-gold btn-sm flex-1" onClick={onClose}>
            わかった
          </button>
        </div>
      </div>
    </div>,
    root,
  )
}

/** 点線の下線つきの用語（タップで解説） */
export function Term({ id, children, className = '' }: { id: string; children: ReactNode; className?: string }) {
  const hints = useSettings((s) => s.termHints)
  const [open, setOpen] = useState(false)
  if (!GLOSSARY_BY_ID[id]) return <>{children}</>
  return (
    <>
      <span
        role="button"
        tabIndex={0}
        className={`cursor-help ${hints ? 'underline decoration-dotted decoration-[0.08em] underline-offset-[0.22em] decoration-ink-mute' : ''} ${className}`}
        onClick={(e) => {
          e.stopPropagation()
          setOpen(true)
        }}
      >
        {children}
      </span>
      {open && <TermPopup id={id} onClose={() => setOpen(false)} />}
    </>
  )
}

/** 小さな「？」（用語の横に置く） */
export function TermHelp({ id, className = '' }: { id: string; className?: string }) {
  const [open, setOpen] = useState(false)
  if (!GLOSSARY_BY_ID[id]) return null
  return (
    <>
      <button
        type="button"
        className={`inline-flex h-[1.3rem] w-[1.3rem] shrink-0 items-center justify-center rounded-full border border-ink-mute/60 text-[0.72rem] font-black text-ink-dim hover:text-gold ${className}`}
        onClick={(e) => {
          e.stopPropagation()
          setOpen(true)
        }}
        aria-label="解説"
      >
        ?
      </button>
      {open && <TermPopup id={id} onClose={() => setOpen(false)} />}
    </>
  )
}
