/**
 * 解除した実績（端末に残す。セーブとは別なので、どのスロットで解除しても一覧に残る）。
 * localStorage が使えない環境（プライベートブラウズなど）では、その場かぎりで覚える。
 */
import { create } from 'zustand'

const KEY = 'court-crown-achievements'

export interface UnlockRecord {
  /** 解除した日（表示用） */
  at: string
}

function load(): Record<string, UnlockRecord> {
  try {
    return JSON.parse(localStorage.getItem(KEY) ?? '{}') as Record<string, UnlockRecord>
  } catch {
    return {}
  }
}

interface AchievementStore {
  unlocked: Record<string, UnlockRecord>
  unlock: (ids: string[]) => void
}

export const useAchievements = create<AchievementStore>((set, get) => ({
  unlocked: load(),
  unlock: (ids) => {
    if (!ids.length) return
    const at = new Date().toISOString().slice(0, 10)
    const next = { ...get().unlocked }
    for (const id of ids) next[id] ??= { at }
    set({ unlocked: next })
    try {
      localStorage.setItem(KEY, JSON.stringify(next))
    } catch {
      // 保存できなくても、この場では解除したことにする
    }
  },
}))
