/**
 * ワールドのホーム（キャリアモードができるまでの確認用。「ワールドを見る」から）: 日付・週を進める・ニュース・優勝と表彰・ドラフト。
 * キャリアモード（M4）からは CareerHome がホームになる。
 */
import { PHASE_LABEL, dateLabel, phaseOfWeek, seasonLabel } from '../../engine'
import { useGame, useGameState } from '../../stores/gameStore'
import { useUi } from '../../stores/uiStore'
import { AppShell } from '../layout/AppShell'
import { Icon } from '../components/Icon'
import { Term } from '../components/Term'

export function WorldHomeScreen() {
  const state = useGameState()
  const advance = useGame((s) => s.advance)
  const busy = useGame((s) => !!s.progress)
  const push = useUi((s) => s.push)
  const news = [...state.news].reverse().slice(0, 12)
  const lastSeason = state.season - 1
  const champs = state.champions.filter((c) => c.season === lastSeason || c.season === state.season)
  const awards = state.awards.filter((a) => a.season === lastSeason && (a.league !== 'NBA' || !a.award.startsWith('オール')))
  return (
    <AppShell
      title="ワールド（確認用）"
      current="home"
      right={
        <span className="num text-[0.85rem] font-bold">
          {dateLabel(state.startYear, state.season, state.week)}
          <span className="ml-2 text-ink-dim">{PHASE_LABEL[phaseOfWeek(state.week)]}</span>
        </span>
      }
    >
      <div className="absolute inset-0 flex gap-2 p-2">
        <div className="flex min-w-0 flex-1 flex-col gap-2">
          <div className="panel panel-hero p-3">
            <div className="panel-head">{seasonLabel(state.startYear, state.season)} シーズン</div>
            <p className="mt-1 text-[0.8rem] leading-relaxed text-ink-dim">
              キャリアモードができるまでの確認用のワールドです（保存されません）。週を進めると、NBA・国内リーグ・大学の試合が行われ、
              <Term id="playoffs">プレーオフ</Term>・<Term id="draft">ドラフト</Term>・<Term id="freeAgent">FA</Term>・<Term id="promotion">昇格と降格</Term>まで進みます。
            </p>
            <div className="mt-2 flex flex-wrap gap-2">
              <button className="btn btn-ghost btn-sm" onClick={() => push({ id: 'league' })}>
                <Icon name="calendar" className="h-4 w-4" />
                リーグ・順位
              </button>
              <button className="btn btn-ghost btn-sm" onClick={() => push({ id: 'matchLab' })}>
                <Icon name="ball" className="h-4 w-4" />
                練習試合
              </button>
            </div>
          </div>
          <div className="panel scroll-y min-h-0 flex-1 p-3">
            <div className="panel-head mb-1">ニュース</div>
            {news.length === 0 && <div className="text-[0.8rem] text-ink-dim">まだニュースはありません。</div>}
            {news.map((n, i) => (
              <div key={i} className={`border-b border-line/30 py-1 text-[0.8rem] ${n.big ? 'font-bold text-gold' : ''}`}>
                <span className="num mr-2 text-[0.7rem] text-ink-mute">{dateLabel(state.startYear, n.season, n.week)}</span>
                {n.text}
              </div>
            ))}
          </div>
        </div>
        <div className="flex w-[19rem] shrink-0 flex-col gap-2">
          <div className="panel scroll-y min-h-0 flex-1 p-3">
            <div className="panel-head mb-1">優勝</div>
            {champs.length === 0 && <div className="text-[0.78rem] text-ink-dim">シーズンの終わりに決まります。</div>}
            {champs.map((c, i) => (
              <div key={i} className="text-[0.78rem]">
                <span className="text-ink-dim">{state.leagues[c.league].name}: </span>
                <span className="font-bold">{c.teamName}</span>
              </div>
            ))}
            {awards.length > 0 && <div className="panel-head mb-1 mt-3"><Term id="awards">前のシーズンの表彰</Term></div>}
            {awards.map((a, i) => (
              <div key={i} className="text-[0.75rem] leading-snug">
                <span className="text-gold">{a.league === 'NBA' ? '' : `${state.leagues[a.league].short} `}{a.award}</span> {a.name}
                <span className="text-ink-mute">（{a.teamName}）</span>
              </div>
            ))}
            {state.draftLog.length > 0 && (
              <>
                <div className="panel-head mb-1 mt-3"><Term id="draft">ドラフト</Term> 上位</div>
                {state.draftLog.slice(0, 10).map((d) => (
                  <button key={d.pick} className="block text-left text-[0.75rem]" onClick={() => push({ id: 'player', params: { playerId: d.playerId } })}>
                    <span className="num text-ink-mute">{d.pick}位 </span>
                    {d.name}
                    <span className="text-ink-mute">（{state.teams[d.teamId].short}）</span>
                  </button>
                ))}
              </>
            )}
          </div>
          <div className="grid grid-cols-3 gap-2">
            <button className="btn btn-ghost btn-sm" disabled={busy} onClick={() => void advance(4)}>
              1か月
            </button>
            <button className="btn btn-ghost btn-sm" disabled={busy} onClick={() => void advance(52)}>
              シーズン末
            </button>
            <button className="btn btn-gold btn-sm" disabled={busy} onClick={() => void advance(1)}>
              次へ進む
            </button>
          </div>
        </div>
      </div>
    </AppShell>
  )
}
