/** リーグ・順位表（NBA の東西・国内 1〜3 部・大学・育成リーグ）。チームを押すとチームの画面へ。 */
import { emptyStanding, gamesBehind, sortedStandings, teamPower, winPct, type LeagueId } from '../../engine'
import { useGameState } from '../../stores/gameStore'
import { useCurrentScreen, useUi } from '../../stores/uiStore'
import { AppShell } from '../layout/AppShell'
import { TeamDot } from '../components/common'
import { Term } from '../components/Term'
import { useScreenState } from '../hooks/useScreenState'
import { CupView, EaccView } from '../league/CupViews'

type Tab = 'E' | 'W' | 'JBL1' | 'JBL2' | 'JBL3' | 'NCAA' | 'DEV' | 'PO' | 'CUP' | 'EACC'

const TABS: [Tab, string][] = [
  ['E', 'NBA 東'],
  ['W', 'NBA 西'],
  ['JBL1', 'JBL 1部'],
  ['JBL2', 'JBL 2部'],
  ['JBL3', 'JBL 3部'],
  ['NCAA', '大学'],
  ['DEV', '育成'],
  ['PO', 'プレーオフ'],
  ['CUP', '全日本選手権'],
  ['EACC', '東アジア'],
]

/** プレーオフのシリーズの一覧（リーグ・回戦の順） */
function PlayoffList() {
  const state = useGameState()
  const push = useUi((s) => s.push)
  const order: LeagueId[] = ['NBA', 'JBL1', 'JBL2', 'JBL3', 'NCAA']
  const list = [...state.series].sort((a, b) => order.indexOf(a.league) - order.indexOf(b.league) || b.round - a.round || a.id - b.id)
  if (!list.length) return <div className="p-4 text-[0.85rem] text-ink-dim">プレーオフはまだ始まっていません（NBA は 4 月の終わりのプレーインから、国内は 5 月、大学は 3 月）。</div>
  return (
    <div className="grid grid-cols-2 gap-2 p-2">
      {list.map((s) => {
        const hi = state.teams[s.hi]
        const lo = state.teams[s.lo]
        return (
          <div key={s.id} className="panel-flat p-2 text-[0.8rem]">
            <div className="mb-1 text-[0.7rem] font-bold text-ink-dim">
              {state.leagues[s.league].short} {s.name}
              {s.bestOf > 1 && `（${s.bestOf} 戦 ${Math.ceil(s.bestOf / 2)} 勝）`}
            </div>
            {[hi, lo].map((t, i) => (
              <button key={t.id} className={`flex w-full items-center gap-2 py-0.5 text-left ${s.winner === t.id ? 'font-black text-gold' : s.winner !== undefined ? 'text-ink-mute' : ''}`} onClick={() => push({ id: 'team', params: { teamId: t.id } })}>
                <TeamDot colors={t.colors} abbr={t.abbr} className="h-5 w-5 text-[0.45rem]" />
                <span className="min-w-0 flex-1 truncate">{t.name}</span>
                <span className="num text-[0.95rem] font-black">{s.wins[i]}</span>
              </button>
            ))}
          </div>
        )
      })}
    </div>
  )
}

function marker(tab: Tab, rank: number, n: number, champ = false): { color: string; label: string } | null {
  if (tab === 'E' || tab === 'W') return rank <= 6 ? { color: '#f5c542', label: 'プレーオフ' } : rank <= 10 ? { color: '#ff7a1a', label: 'プレーイン' } : null
  if (tab === 'JBL1' || tab === 'JBL2' || tab === 'JBL3') {
    // 昇格: レギュラーシーズンの 1 位と、チャンピオンシップの優勝クラブ（promotion.ts）
    if (tab !== 'JBL1' && (rank === 1 || champ)) return { color: '#22a35a', label: '昇格' }
    if (rank <= 8) return { color: '#f5c542', label: 'チャンピオンシップ' }
    if (tab !== 'JBL3' && rank > n - 2) return { color: '#ff5a5f', label: '降格' }
  }
  if (tab === 'NCAA' && rank <= 16) return { color: '#f5c542', label: '全米大学選手権' }
  return null
}

export function LeagueScreen() {
  const state = useGameState()
  const push = useUi((s) => s.push)
  const screen = useCurrentScreen()
  const [tab, setTab] = useScreenState<Tab>('tab', 'E', screen.params?.tab as Tab | undefined)
  const leagueId: LeagueId = tab === 'E' || tab === 'W' || tab === 'PO' || tab === 'CUP' || tab === 'EACC' ? 'NBA' : tab
  const lg = state.leagues[leagueId]
  const ids = tab === 'E' || tab === 'W' ? lg.teamIds.filter((id) => state.teams[id].conf === tab) : lg.teamIds
  const order = sortedStandings(lg, ids)
  const lead = lg.standings[order[0]] ?? emptyStanding()
  return (
    <AppShell title="リーグ・順位" current="league" back>
      <div className="absolute inset-0 flex flex-col gap-2 p-2">
        <div className="seg scroll-x shrink-0 self-start" role="tablist">
          {TABS.map(([id, label]) => (
            <button key={id} role="tab" aria-selected={tab === id} onClick={() => setTab(id)}>
              {label}
            </button>
          ))}
        </div>
        {tab === 'CUP' || tab === 'EACC' ? (
          <div className="panel scroll-y min-h-0 flex-1">{tab === 'CUP' ? <CupView /> : <EaccView />}</div>
        ) : tab === 'PO' ? (
          <div className="panel scroll-y min-h-0 flex-1">
            <PlayoffList />
          </div>
        ) : (
        <div className="panel scroll-y min-h-0 flex-1">
          <table className="num w-full text-[0.85rem]">
            <thead className="sticky top-0 z-[1] bg-[#f3f0ea] text-[0.72rem] text-ink-dim">
              <tr>
                <th className="w-9 py-1.5">#</th>
                <th className="text-left">チーム</th>
                {(tab === 'E' || tab === 'W' || tab === 'NCAA') && <th className="text-left">{tab === 'NCAA' ? 'カンファレンス' : 'ディビジョン'}</th>}
                <th>勝</th>
                <th>敗</th>
                <th>勝率</th>
                <th>差</th>
                <th>得失点</th>
                <th>連勝</th>
                <th>
                  <Term id="ovr">戦力</Term>
                </th>
              </tr>
            </thead>
            <tbody>
              {order.map((id, i) => {
                const t = state.teams[id]
                const s = lg.standings[id] ?? emptyStanding()
                const m = marker(tab, i + 1, order.length, state.champions.some((x) => x.season === state.season && x.league === tab && x.teamId === id))
                return (
                  <tr key={id} className="cv-row border-t border-line/30 hover:bg-black/5" onClick={() => push({ id: 'team', params: { teamId: id } })}>
                    <td className="py-1.5 text-center font-black" style={{ boxShadow: m ? `inset 3px 0 0 ${m.color}` : undefined }}>
                      {i + 1}
                    </td>
                    <td>
                      <span className="flex items-center gap-2">
                        <TeamDot colors={t.colors} abbr={t.abbr} />
                        <span className="truncate font-bold">{t.name}</span>
                      </span>
                    </td>
                    {(tab === 'E' || tab === 'W' || tab === 'NCAA') && <td className="text-[0.75rem] text-ink-dim">{t.div ?? t.conf}</td>}
                    <td className="text-center">{s.w}</td>
                    <td className="text-center">{s.l}</td>
                    <td className="text-center">{winPct(s).toFixed(3).replace(/^0/, '')}</td>
                    <td className="text-center text-ink-dim">{i === 0 ? '-' : gamesBehind(lead, s).toFixed(1)}</td>
                    <td className="text-center text-ink-dim">{s.pf - s.pa > 0 ? '+' : ''}{s.pf - s.pa}</td>
                    <td className="text-center text-ink-dim">{s.streak > 0 ? `${s.streak}連勝` : s.streak < 0 ? `${-s.streak}連敗` : '-'}</td>
                    <td className="text-center font-bold">{teamPower(state, t).toFixed(1)}</td>
                  </tr>
                )
              })}
            </tbody>
          </table>
        </div>
        )}
        <div className="flex shrink-0 flex-wrap gap-x-4 gap-y-1 px-1 text-[0.72rem] text-ink-dim">
          {tab === 'E' || tab === 'W' ? (
            <>
              <span>
                <span className="mr-1 inline-block h-2.5 w-2.5 rounded-sm bg-gold" />
                <Term id="playoffs">プレーオフ</Term>（1〜6 位）
              </span>
              <span>
                <span className="mr-1 inline-block h-2.5 w-2.5 rounded-sm bg-orange" />
                <Term id="playIn">プレーイン</Term>（7〜10 位）
              </span>
            </>
          ) : tab === 'NCAA' ? (
            <span>
              <span className="mr-1 inline-block h-2.5 w-2.5 rounded-sm bg-gold" />
              <Term id="collegeTournament">全米大学選手権</Term>（上位 16 校）
            </span>
          ) : tab === 'CUP' || tab === 'EACC' ? (
            <span>
              <Term id={tab === 'CUP' ? 'allJapan' : 'eacc'}>{tab === 'CUP' ? '全日本選手権' : '東アジアのクラブ選手権'}</Term>（架空の大会）
            </span>
          ) : tab === 'PO' ? (
            <span>
              <Term id="playoffs">プレーオフ</Term>・<Term id="playIn">プレーイン</Term>・<Term id="championship">チャンピオンシップ</Term>・<Term id="collegeTournament">全米大学選手権</Term>
            </span>
          ) : tab === 'DEV' ? (
            <span>
              <Term id="devLeague">育成リーグ</Term>: NBA の各チームの下部チーム
            </span>
          ) : (
            <>
              <span>
                <span className="mr-1 inline-block h-2.5 w-2.5 rounded-sm bg-gold" />
                <Term id="championship">チャンピオンシップ</Term>（上位 8）
              </span>
              {tab !== 'JBL1' && (
                <span>
                  <span className="mr-1 inline-block h-2.5 w-2.5 rounded-sm bg-[#22a35a]" />
                  <Term id="promotion">昇格</Term>（1 位とチャンピオンシップの優勝クラブ。1 位が優勝したら 2 位も。上の部の<Term id="license">ライセンス</Term>が要る）
                </span>
              )}
              {tab !== 'JBL3' && (
                <span>
                  <span className="mr-1 inline-block h-2.5 w-2.5 rounded-sm bg-bad" />
                  <Term id="promotion">降格</Term>（下位 2）
                </span>
              )}
            </>
          )}
        </div>
      </div>
    </AppShell>
  )
}
