import type { MatchSetup, MatchSummary } from '../../engine/match/types'
import type { WeekReport } from '../../engine/core/advanceWeek'
import { useGame, useGameState } from '../../stores/gameStore'
import { useUi } from '../../stores/uiStore'
import { AppShell } from '../layout/AppShell'
import { FirstSteps } from '../layout/FirstSteps'
import { MatchView } from '../match/MatchView'
import { TeamDot } from '../components/common'
import { Term } from '../components/Term'
import { Icon } from '../components/Icon'
