import { boardOpen } from '../../engine/club/draftBoard'
import { ClubTalkScene } from '../club/ClubTalkScene'
import { ClubSeasonReview } from '../club/ClubSeasonReview'
import { moodFace, teamMood } from '../../engine/club/storyTalks'
import { CUP_NAME, CUP_ROUNDS, CUP_WEEKS, fixtureLabel } from '../../engine/competition/cup'
