const yen = (man: number) => `${formatMoneyShort(Math.round(man))}円`
const DAY = ['月', '火', '水', '木', '金', '土', '日']

function FixtureRow({ f }: { f: Fixture }) {
  const state = useGameState()
  const id = state.club!.teamId
  const home = f.home === id
  const opp = state.teams[home ? f.away : f.home]
  const lg = state.leagues[opp.league]
  const st = lg.standings[opp.id]
  return (
    <div className="flex items-center gap-2 py-1 text-[0.85rem]">
      <span className="w-6 text-center text-[0.72rem] font-bold text-ink-dim">{DAY[f.day]}</span>
      <span className={`rounded px-1.5 text-[0.68rem] font-black ${home ? 'bg-orange/25 text-orange' : 'bg-black/10 text-ink-dim'}`}>{home ? 'ホーム' : 'アウェイ'}</span>
      <TeamDot colors={opp.colors} abbr={opp.abbr} className="h-6 w-6 text-[0.5rem]" />
      <span className="min-w-0 flex-1 truncate font-bold">{opp.name}</span>
      {fixtureLabel(state, f) && <span className="rounded bg-gold/20 px-1.5 text-[0.68rem] font-black text-gold">{fixtureLabel(state, f)}</span>}
      <span className="num text-[0.72rem] text-ink-dim">{st ? `${st.w}勝${st.l}敗` : ''}</span>
    </div>
  )
}

/** 今週の東アジアのクラブ選手権の試合（水曜。準決勝・決勝は中立地） */
function EaccRow({ f }: { f: EaccFixture }) {
  const state = useGameState()
  const e = state.eacc!
  const id = state.club!.teamId
  const home = f.home.team === id
  const opp = home ? f.away : f.home
  const neutral = f.stage === 'SF' || f.stage === 'F'
  const t = opp.team !== undefined ? state.teams[opp.team] : undefined
  const fr = opp.foreign !== undefined ? e.foreign[opp.foreign] : undefined
  return (
    <div className="flex items-center gap-2 py-1 text-[0.85rem]">
      <span className="w-6 text-center text-[0.72rem] font-bold text-ink-dim">水</span>
      <span className={`rounded px-1.5 text-[0.68rem] font-black ${neutral ? 'bg-gold/20 text-gold' : home ? 'bg-orange/25 text-orange' : 'bg-black/10 text-ink-dim'}`}>{neutral ? '中立地' : home ? 'ホーム' : 'アウェイ'}</span>
      <TeamDot colors={t?.colors ?? { primary: fr!.color, secondary: '#ffffff' }} abbr={t?.abbr ?? fr!.abbr} className="h-6 w-6 text-[0.5rem]" />
      <span className="min-w-0 flex-1 truncate font-bold">{sideName(state, e, opp)}</span>
      <span className="rounded bg-gold/20 px-1.5 text-[0.68rem] font-black text-gold">東アジア・{eaccStageLabel(f.stage)}</span>
    </div>
  )
}

interface Summary {
  r: WeekReport
  money0: number
  fans0: number
  pop0: number
}

function WeekSummary({ s, onClose }: { s: Summary; onClose: () => void }) {
  const state = useGameState()
  const c = state.club!
  const res = c.lastResults ?? []
  const dm = c.money - s.money0
  return (
    <div className="anim-fade absolute inset-0 z-40 flex items-center justify-center bg-black/60 p-4" onClick={onClose}>
      <div className="panel panel-solid w-[32rem] max-w-full p-4" onClick={(e) => e.stopPropagation()}>
        <div className="text-[1rem] font-black">今週のまとめ</div>
        {res.length > 0 && (
          <div className="mt-2">
            {res.map((x) => (
              <div key={x.fixtureId} className="flex items-center gap-2 text-[0.88rem]">
                <span className={`w-5 font-black ${x.us > x.them ? 'text-good' : 'text-bad'}`}>{x.us > x.them ? '○' : '●'}</span>
                <span className="min-w-0 flex-1 truncate">
                  {x.home ? 'vs' : '@'} {x.opp}
                </span>
                <span className="num font-bold">
                  {x.us} - {x.them}
                </span>
              </div>
            ))}
            {(() => {
              const last = res[res.length - 1]
              const f = last && state.fixtures.find((g) => g.id === last.fixtureId)
              return f ? <FlowGraph state={state} f={f} teamId={c.teamId} /> : null
            })()}
          </div>
        )}
        <div className="num mt-2 grid grid-cols-3 gap-2 text-[0.82rem]">
          <div className="stat-chip px-2 py-1">
            資金 <span className={`font-black ${dm >= 0 ? 'text-good' : 'text-bad'}`}>{dm >= 0 ? '+' : ''}{yen(dm)}</span>
          </div>
          <div className="stat-chip px-2 py-1">
            ファン <span className="font-black">{c.fans - s.fans0 >= 0 ? '+' : ''}{(c.fans - s.fans0).toLocaleString()}</span>
          </div>
          <div className="stat-chip px-2 py-1">
            人気 {Math.round(s.pop0)} → <span className="font-black text-gold">{Math.round(c.popularity)}</span>
          </div>
        </div>
        {s.r.news.length > 0 && (
          <div className="mt-2 max-h-[7rem] overflow-hidden text-[0.75rem] text-ink-dim">
            {s.r.news.slice(-5).map((n, i) => (
              <div key={i} className={n.big ? 'font-bold text-gold' : ''}>
                ・{n.text}
              </div>
            ))}
          </div>
        )}
        <button className="btn btn-gold mt-3 w-full" onClick={onClose}>
          OK
        </button>
      </div>
    </div>
  )
}

export function ClubHomeScreen() {
  const state = useGameState()
  const playWeek = useGame((s) => s.playWeek)
  const advance = useGame((s) => s.advance)
  const close = useGame((s) => s.close)
  const busy = useGame((s) => !!s.progress)
  const push = useUi((s) => s.push)
  const reset = useUi((s) => s.reset)
  const c = state.club!
  const team = clubTeam(state)
  const lg = state.leagues[team.league]
  const st = lg.standings[team.id]
  const rank = rankIn(lg, team.id)
  const town = HOMETOWN_BY_ID[c.hometown]
  const fixtures = clubFixtures(state)
  const featured = fixtures[0]
  // 東アジアのクラブ選手権の試合（観戦できる）
  const eg = teamEaccFixture(state, c.teamId)
  const hasGame = !!featured || !!eg
  const [matchStep, setMatchStep] = useState<'none' | 'ask' | 'watch'>('none')
  const [setup, setSetup] = useState<MatchSetup | null>(null)
  // 観戦する試合: 結果を渡す鍵（日程の試合の id か EACC_PLAYED）と、指示を出す側
  const [watching, setWatching] = useState<{ key: number; control: 0 | 1 } | null>(null)
  const [summary, setSummary] = useState<Summary | null>(null)
  const out = yearlyOutlook(state)

  const doWeek = (played?: Map<number, MatchSummary>) => {
    const s0 = { money0: c.money, fans0: c.fans, pop0: c.popularity }
    const r = playWeek(played)
    if (r) setSummary({ r, ...s0 })
  }

  const watchGame = (kind: 'league' | 'eacc') => {
    if (kind === 'eacc' && eg) {
      setSetup(eaccSetup(state, eg))
      setWatching({ key: EACC_PLAYED, control: eg.home.team === team.id ? 0 : 1 })
    } else if (featured) {
      setSetup({ ...fixtureSetup(state, featured), neutral: isNeutral(state, featured) })
      setWatching({ key: featured.id, control: featured.home === team.id ? 0 : 1 })
    } else return
    setMatchStep('watch')
  }

  if (matchStep === 'watch' && setup && watching)
    return (
      <MatchView
        setup={setup}
        control={watching.control}
        onFinish={(sum) => {
          setMatchStep('none')
          doWeek(new Map([[watching.key, sum]]))
        }}
      />
    )

  if (c.gameOver)
    return (
      <AppShell title={team.name} current="home" tip={false}>
        <div className="flex h-full items-center justify-center">
          <div className="panel panel-hero max-w-[30rem] p-5 text-center">
            <div className="text-[1.1rem] font-black">オーナーがクラブを手放した</div>
            <p className="mt-1 text-[0.85rem] text-ink-dim">{c.owner.trust <= 0 ? 'オーナーの目標に届かないシーズンが続き' : '資金難が続き'}、クラブの経営から離れることになりました。{c.history.length} シーズン、おつかれさまでした。</p>
            <button
              className="btn btn-gold mt-3"
              onClick={() => {
                close()
                reset({ id: 'title' })
              }}
            >
              タイトルへ
            </button>
          </div>
        </div>
      </AppShell>
    )

  const alerts: { text: string; onClick: () => void; tone?: 'bad' | 'gold' }[] = []
  if (c.sponsorOffers.length) alerts.push({ text: `スポンサーの話が ${new Set(c.sponsorOffers.map((o) => o.slot)).size} 枠`, onClick: () => push({ id: 'club', params: { tab: 'sponsor' } }), tone: 'gold' })
  if (c.money < 0) alerts.push({ text: `資金がマイナス（${c.negWeeks} 週目）`, onClick: () => push({ id: 'club', params: { tab: 'money' } }), tone: 'bad' })
  if (!c.staff.asst || !c.staff.sc) alerts.push({ text: 'スタッフに空きがある', onClick: () => push({ id: 'club', params: { tab: 'staff' } }) })
  if (c.bids.length) alerts.push({ text: `移籍の申し入れが ${c.bids.length} 件`, onClick: () => push({ id: 'transfer', params: { tab: 'bids' } }), tone: 'gold' })
  const exp = expiring(state).length
  if (state.week >= 36 && state.week < 51 && exp > 0) alerts.push({ text: `今季で契約が切れる選手が ${exp} 人`, onClick: () => push({ id: 'transfer', params: { tab: 'renew' } }) })
  if (c.rookies.length && windowOpen(state)) alerts.push({ text: `新人の候補が ${c.rookies.length} 人、練習に来ている`, onClick: () => push({ id: 'transfer', params: { tab: 'fa' } }) })
  if (boardOpen(state)) alerts.push({ text: c.draftBoard?.length ? `NBA ドラフト（第 51 週）: 指名リスト ${c.draftBoard.length} 人` : 'NBA ドラフトの候補が決まった。指名したい選手を並べる', onClick: () => push({ id: 'transfer', params: { tab: 'draft' } }), tone: c.draftBoard?.length ? undefined : 'gold' })
  // NBA: ぜいたく税の見込み・返事待ちの大物 FA
  if (team.league === 'NBA') {
    const over = payroll(state, team) - NBA_TAX
    if (over > 0) alerts.push({ text: `年俸の合計がぜいたく税の線を超えている（シーズンの終わりに約 ${formatMoneyShort(Math.round(over * 1.5))}円）`, onClick: () => push({ id: 'transfer', params: { tab: 'squad' } }), tone: 'bad' })
    for (const b of c.faBids ?? []) alerts.push({ text: `${state.players[b.playerId]?.name ?? 'FA'}の返事待ち（次の週のはじめ）`, onClick: () => push({ id: 'transfer', params: { tab: 'fa' } }) })
  }
  // 全日本選手権・東アジアのクラブ選手権
  const cup = state.cup?.season === state.season ? state.cup : undefined
  if (cup && cup.alive.includes(c.teamId) && cup.round < 5 && state.week <= CUP_WEEKS[cup.round + 1]) alerts.push({ text: `${CUP_NAME} ${CUP_ROUNDS[cup.round + 1]}に進出（第 ${CUP_WEEKS[cup.round + 1]} 週）`, onClick: () => push({ id: 'league', params: { tab: 'CUP' } }), tone: 'gold' })
  if (inEacc(state, c.teamId) && state.week <= EACC_TITLE_WEEK) alerts.push({ text: `${EACC_NAME}に出場中`, onClick: () => push({ id: 'league', params: { tab: 'EACC' } }), tone: 'gold' })
  if (state.eaccQual?.season === state.season + 1 && state.eaccQual.teams.includes(c.teamId)) alerts.push({ text: `来季の${EACC_NAME}の出場権を得た`, onClick: () => push({ id: 'league', params: { tab: 'EACC' } }), tone: 'gold' })
  if (draftOpen(state)) alerts.push({ text: `エクスパンションドラフト（第 ${EXPANSION_DRAFT_UNTIL} 週まで）`, onClick: () => push({ id: 'transfer', params: { tab: 'expansion' } }), tone: 'gold' })
  if (overRoster(state) > 0) alerts.push({ text: `登録が ${overRoster(state)} 人多い（放出する）`, onClick: () => push({ id: 'transfer', params: { tab: 'squad' } }), tone: 'bad' })
  // 昇格のライセンス（席数）: 足りないうちはずっと出す。上位にいるのに足りない・今季に間に合わないときは赤
  const lic = licenseOutlook(state)
  // いちばん大事な知らせなので、いちばん上に
  if (lic)
    alerts.unshift(
      lic.building !== undefined
        ? { text: `増席の工事中（第 ${lic.building} 週に完成）。完成すれば昇格のライセンス（${lic.need.toLocaleString()} 席）を満たす`, onClick: () => push({ id: 'club', params: { tab: 'arena' } }) }
        : {
            text: lic.late ? `昇格には ${lic.need.toLocaleString()} 席が要る（今 ${lic.seats.toLocaleString()} 席）。今から増席しても今季には間に合わない` : `昇格には ${lic.need.toLocaleString()} 席のライセンスが要る（今 ${lic.seats.toLocaleString()} 席）→ アリーナを増席する`,
            onClick: () => push({ id: 'club', params: { tab: 'arena' } }),
            tone: rank <= 4 || lic.late ? 'bad' : 'gold',
          },
    )
  if (team.league !== 'NBA' && canApply(state)) alerts.push({ text: 'NBA への参入を申請できる！', onClick: () => push({ id: 'club', params: { tab: 'nba' } }), tone: 'gold' })
  // 自分で並べている序列の先発にケガ人
  if (!depthAuto(state) && clubDepth(state).slice(0, 5).some((id) => state.players[id].injury)) alerts.push({ text: '先発にケガをしている選手がいる（序列を見直す）', onClick: () => push({ id: 'tactics' }), tone: 'bad' })
  if (team.roster.length < 12) alerts.push({ text: `選手が ${team.roster.length} 人しかいない`, onClick: () => push({ id: 'roster' }), tone: 'bad' })
  const recent = state.news.filter((n) => n.season === state.season || n.big).slice(-6).reverse()

  return (
    <AppShell
      title={team.name}
      current="home"
      // 週のまとめ・試合の確認が開いているあいだは、説明を出さない
      tip={!summary && matchStep === 'none'}
      color={team.colors.primary}
      right={
        <span className="num text-[0.82rem] font-bold">
          {dateLabel(state.startYear, state.season, state.week)}
          <span className="ml-2 text-ink-dim">{PHASE_LABEL[phaseOfWeek(state.week)]}</span>
        </span>
      }
    >
      <div className="absolute inset-0 flex gap-2 p-2">
        {/* 左: クラブ */}
        <div className="panel panel-hero scroll-y flex w-[16.5rem] shrink-0 flex-col gap-2 p-3">
          <div className="flex items-center gap-2">
            <div className="flex h-14 w-14 shrink-0 items-center justify-center rounded-2xl text-[0.95rem] font-black" style={{ background: team.colors.primary, color: team.colors.secondary }}>
              {team.abbr}
            </div>
            <div className="min-w-0">
              <div className="truncate text-[1rem] font-black">{team.name}</div>
              <div className="text-[0.72rem] text-ink-dim">
                {town.pref}
                {subTownsOf(state).length > 0 && `（＋${subTownsOf(state).map((t) => t.city).join('・')}）`}・HC {team.coach.name}
                {c.relocation && <span className="ml-1 whitespace-nowrap font-bold text-orange">{HOMETOWN_BY_ID[c.relocation.to].city}へ移転予定</span>}
              </div>
            </div>
          </div>
          <button className="stat-chip flex items-center justify-between px-2 py-1.5 text-left" onClick={() => push({ id: 'league', params: { tab: team.league } })}>
            <span className="text-[0.78rem] font-bold">{lg.name}</span>
            <span className="num text-[0.82rem]">
              {st?.w ?? 0}勝{st?.l ?? 0}敗{(st?.w ?? 0) + (st?.l ?? 0) > 0 && <>・<span className="font-black text-gold">{rank}位</span></>}
            </span>
          </button>
          <TeamStrengthChip team={team} />
          <div className="num grid grid-cols-2 gap-1.5 text-[0.75rem]">
            <div className={`stat-chip px-2 py-1 ${c.money < 0 ? 'text-bad' : ''}`}>
              資金 <span className="font-black">{yen(c.money)}</span>
            </div>
            <div className="stat-chip px-2 py-1">
              1 年 <span className={`font-black ${out.net >= 0 ? 'text-good' : 'text-bad'}`}>{out.net >= 0 ? '+' : ''}{yen(out.net)}</span>
            </div>
            <div className="stat-chip px-2 py-1">
              <Term id="fans">ファン</Term> <span className="font-black">{c.fans.toLocaleString()}</span>
              {nearFanCeiling(state) && <span className="ml-1 text-[0.62rem] font-bold text-orange">天井</span>}
            </div>
            <div className="stat-chip px-2 py-1">
              人気 <span className="font-black text-orange">{Math.round(c.popularity)}</span>
            </div>
            <div className="stat-chip col-span-2 px-2 py-1">
              {team.arena.name}・{team.arena.capacity.toLocaleString()} 席（観客の見込み {out.perGame.toLocaleString()} 人）
            </div>
          </div>
          {c.owner.goal && (
            <div className="stat-chip px-2 py-1.5 text-[0.75rem]">
              <span className="text-ink-dim">オーナーの目標</span> <span className="font-black text-gold">{c.owner.goal.text}</span>
              <div className="mt-0.5 flex items-center gap-1 text-[0.68rem] text-ink-dim">
                信頼
                <span className="h-1.5 flex-1 overflow-hidden rounded-full bg-black/10">
                  <span className="block h-full rounded-full" style={{ width: `${c.owner.trust}%`, background: c.owner.trust >= 40 ? '#3ddc84' : '#ff5a5f' }} />
                </span>
                <span className="num font-bold">{c.owner.trust}</span>
              </div>
            </div>
          )}
          {(() => {
            const m = teamMood(state)
            const f = moodFace(m)
            return (
              <div className="stat-chip px-2 py-1 text-[0.75rem]">
                <Term id="playerMood">選手の気持ち</Term> <span className={`font-black ${f.tone === 'good' ? 'text-good' : f.tone === 'bad' ? 'text-bad' : ''}`}>{f.face} {f.label}</span>
                <span className="num ml-1 text-ink-dim">（主力 10 人の平均 {Math.round(m)}）</span>
              </div>
            )
          })()}
          {c.building.length > 0 && (
            <div className="text-[0.72rem] text-ink-dim">
              {c.building.map((b) => (
                <div key={b.label}>
                  工事中: {b.label}（あと {Math.max(0, b.doneAbs - (state.season * 52 + state.week))} 週）
                </div>
              ))}
            </div>
          )}
          {alerts.map((a) => (
            <button key={a.text} className={`btn btn-sm !h-auto !min-h-[2.2rem] !whitespace-normal !py-1 ${a.tone === 'bad' ? 'btn-ghost !text-bad' : a.tone === 'gold' ? 'btn-blue' : 'btn-ghost'}`} onClick={a.onClick}>
              {/* 長い知らせは 2 行に折り返す */}
              <span className="text-[0.74rem] leading-snug">{a.text}</span>
            </button>
          ))}
        </div>
        {/* 中: 今週 */}
        <div className="flex min-w-0 flex-1 flex-col gap-2">
          <div className="panel p-3">
            <div className="panel-head mb-1">今週の試合</div>
            {eg && <EaccRow f={eg} />}
            {fixtures.length === 0 && !eg ? <div className="text-[0.8rem] text-ink-dim">試合はありません。練習と経営を進めよう。</div> : fixtures.map((f) => <FixtureRow key={f.id} f={f} />)}
          </div>
          {(c.lastResults ?? []).length > 0 && (
            <div className="panel p-3">
              <div className="panel-head mb-1">先週の結果</div>
              <div className="flex flex-wrap gap-x-4 text-[0.82rem]">
                {c.lastResults!.map((x) => (
                  <span key={x.fixtureId}>
                    <span className={`font-black ${x.us > x.them ? 'text-good' : 'text-bad'}`}>{x.us > x.them ? '○' : '●'}</span> {x.home ? 'vs' : '@'} {x.opp} <span className="num font-bold">{x.us}-{x.them}</span>
                  </span>
                ))}
              </div>
            </div>
          )}
          <div className="panel scroll-y min-h-0 flex-1 p-3">
            <div className="panel-head mb-1">ニュース</div>
            {recent.map((n, i) => (
              <div key={i} className={`text-[0.78rem] leading-snug ${n.big ? 'font-bold text-gold' : 'text-ink-dim'}`}>
                ・{n.text}
              </div>
            ))}
          </div>
        </div>
        {/* 右: はじめの一歩・進める */}
        <div className="flex w-[11.5rem] shrink-0 flex-col justify-end gap-2">
          <FirstSteps />
          {/* 補強: 登録の締め切りまでは、手薄なポジションに絞って所属なしの選手の一覧へ */}
          <button className="btn btn-blue btn-sm" onClick={() => push(windowOpen(state) ? { id: 'transfer', params: { tab: 'fa', pos: weakestPosition(state).pos } } : { id: 'transfer' })}>
            {windowOpen(state) ? `補強する（手薄: ${weakestPosition(state).pos}）` : '補強・編成'}
          </button>
          <button className="btn btn-ghost btn-sm" onClick={() => push({ id: 'tactics' })}>
            作戦と序列
          </button>
          <button className="btn btn-ghost btn-sm" disabled={busy} onClick={() => void advance(4)}>
            1か月オート
          </button>
          <button className="btn btn-gold h-[3.6rem]" disabled={busy} onClick={() => (hasGame ? setMatchStep('ask') : doWeek())}>
            <Icon name={hasGame ? 'play' : 'forward'} className="h-5 w-5" />
            {hasGame ? '試合へ' : '次へ進む'}
          </button>
        </div>
      </div>
      {matchStep === 'ask' && hasGame && (
        <div className="anim-fade absolute inset-0 z-40 flex items-center justify-center bg-black/60 p-4" onClick={() => setMatchStep('none')}>
          <div className="panel panel-solid w-[32rem] max-w-full p-4" onClick={(e) => e.stopPropagation()}>
            <div className="text-[1rem] font-black">今週の注目の試合</div>
            <div className="mt-0.5 text-[0.74rem] text-ink-dim">
              観戦できるのは 1 試合です。観戦すると、<Term id="timeout">タイムアウト</Term>・交代・作戦を指示できます。ほかの試合は結果だけになります。
            </div>
            {eg && (
              <div className="panel-flat mt-2 flex items-center gap-2 p-2">
                <div className="min-w-0 flex-1">
                  <EaccRow f={eg} />
                </div>
                <button className="btn btn-gold btn-sm shrink-0" onClick={() => watchGame('eacc')}>
                  <Icon name="play" className="h-4 w-4" />
                  観戦する
                </button>
              </div>
            )}
            {featured && (
              <div className="panel-flat mt-2 flex items-center gap-2 p-2">
                <div className="min-w-0 flex-1">
                  <FixtureRow f={featured} />
                </div>
                <button className="btn btn-gold btn-sm shrink-0" onClick={() => watchGame('league')}>
                  <Icon name="play" className="h-4 w-4" />
                  観戦する
                </button>
              </div>
            )}
            {fixtures.length > 1 && <div className="mt-1 text-[0.72rem] text-ink-dim">ほかに {fixtures.length - 1} 試合あります（結果だけ）。</div>}
            <button
              className="btn btn-ghost mt-3 w-full"
              onClick={() => {
                setMatchStep('none')
                doWeek()
              }}
            >
              {eg && featured ? 'どれも結果だけ' : '結果だけ'}
            </button>
          </div>
        </div>
      )}
      {summary && <WeekSummary s={summary} onClose={() => setSummary(null)} />}
      {!summary && <Celebration />}
      {!summary && <ClubSeasonReview />}
      {!summary && <ClubTalkScene />}
    </AppShell>
  )
}
