/**
 * はじめの一歩: ホームの右上に、最初にやってみてほしいことを 1 つずつ（今の手順・説明・次の手順）。
 * 今週できない手順（試合のない週の観戦）は飛ばして、できる週に戻ってくる。
 */
import { careerFixtures } from '../../engine/career/week'
import { clubFixtures } from '../../engine/club/manage'
import type { GameState } from '../../engine'
import { useGame, useGameState } from '../../stores/gameStore'
import { useSettings } from '../../stores/settingsStore'
import { useUi } from '../../stores/uiStore'
import { CAREER_STEPS, CLUB_STEPS, type StepDef } from './steps'

/** 今週できる手順か（観戦は試合のある週だけ） */
function doable(state: GameState, s: StepDef): boolean {
  if (s.id !== 'watch') return true
  return (state.club ? clubFixtures(state) : careerFixtures(state)).length > 0
}

export function FirstSteps() {
  const state = useGameState()
  const mutate = useGame((s) => s.mutate)
  const push = useUi((s) => s.push)
  const showTips = useSettings((s) => s.showTips)
  const t = state.tutorial
  if (!showTips || t?.closed) return null
  const steps = state.mode === 'club' ? CLUB_STEPS : CAREER_STEPS
  const done = new Set(t?.done ?? [])
  const left = steps.filter((s) => !done.has(s.id))
  const now = left.find((s) => doable(state, s)) ?? left[0]
  const after = left.find((s) => s !== now)
  const close = () => mutate((st) => void (st.tutorial = { done: st.tutorial?.done ?? [], closed: true }))
  return (
    <div className="panel min-h-0 shrink-0 p-2 text-[0.7rem]">
      <div className="mb-1 flex items-center gap-1">
        <span className="font-black text-gold">はじめの一歩</span>
        <span className="num text-ink-dim">
          {steps.length - left.length}/{steps.length}
        </span>
        <button className="ml-auto px-1 text-[0.85rem] leading-none text-ink-mute" onClick={close} aria-label="案内を閉じる">
          ×
        </button>
      </div>
      {now ? (
        <>
          <div className="flex items-start gap-1 font-black leading-snug">
            <span className="shrink-0 text-orange">▶</span>
            <span>{now.title}</span>
          </div>
          <div className="mt-0.5 leading-snug text-ink-dim">{doable(state, now) ? now.hint : `${now.hint}（今週は試合がありません）`}</div>
          {now.screen && (
            <button className="btn btn-ghost btn-sm mt-1 w-full" onClick={() => push({ id: now.screen! })}>
              開く
            </button>
          )}
          {after && <div className="mt-1 truncate text-ink-mute">つぎ: {after.title}</div>}
        </>
      ) : (
        <>
          <div className="leading-snug">基本はばっちり。分からない言葉は、点線の下線か用語集で調べられます。</div>
          <button className="btn btn-gold btn-sm mt-1 w-full" onClick={close}>
            閉じる
          </button>
        </>
      )}
    </div>
  )
}
