/**
 * 特殊能力のタブ（育成の画面）: 持っている特殊能力と、身につけられる特殊能力の条件・今季の成績での進み具合。
 * 判定は engine の career/traits.ts（同じ条件の式を画面にも出す）
 */
import { SKILL_CATS, SKILL_DEFS, type SkillId } from '../../engine/data/skills'
import { MAX_GOOD, MIN_GAMES, meterOk, meterRate, skillProgress, type Meter } from '../../engine/career/traits'
import type { GameState } from '../../engine/models/game'
import { TermHelp } from '../components/Term'

type Row = ReturnType<typeof skillProgress>[number]

/** 条件の値の書き方（率は小数 1 桁・能力と年齢と試合は整数・1 試合あたりは小数 1 桁） */
function num(m: Meter, v: number): string {
  if (m.label.endsWith('の能力') || m.unit === '歳' || m.unit === '試合' || (m.unit === '回' && m.label.includes('見せ場'))) return String(Math.round(v))
  if (Number.isInteger(v)) return String(v)
  return v.toFixed(1)
}

function MeterRow({ m }: { m: Meter }) {
  const done = meterOk(m)
  return (
    <div className="mt-1">
      <div className="flex items-baseline gap-1 text-[0.66rem] leading-tight">
        <span className="min-w-0 flex-1 truncate text-ink-dim">{m.label}</span>
        <span className={`num shrink-0 font-bold ${done ? 'text-good' : ''}`}>
          {num(m, m.now)}
          {m.unit}
          <span className="font-normal text-ink-mute">
            {' '}
            / {num(m, m.target)}
            {m.unit}
            {m.lower ? ' 未満' : ''}
          </span>
        </span>
      </div>
      <div className="mt-0.5 h-1 overflow-hidden rounded-full bg-black/10">
        <div className={`h-full rounded-full ${done ? 'bg-[#22a35a]' : 'bg-orange'}`} style={{ width: `${Math.round(meterRate(m) * 100)}%` }} />
      </div>
    </div>
  )
}

function SkillCard({ r, capped }: { r: Row; capped: boolean }) {
  const def = SKILL_DEFS[r.id]
  return (
    <div className={`panel-flat p-2 ${r.ready && !capped ? 'border-gold/70 bg-gold/10' : ''} ${capped ? 'opacity-60' : ''}`}>
      <div className="flex items-center gap-1">
        <span className="min-w-0 flex-1 truncate text-[0.8rem] font-black">{def.name}</span>
        <TermHelp id={`skill:${r.id}`} />
      </div>
      <div className="text-[0.62rem] leading-snug text-ink-mute">{def.desc}</div>
      {r.meters.map((m) => (
        <MeterRow key={m.label} m={m} />
      ))}
      {r.ready && !capped && <div className="mt-1 text-[0.64rem] font-black text-gold">{def.bad ? '付きそう（気をつけて）' : '条件クリア（次の判定で身につく）'}</div>}
    </div>
  )
}

export function SkillTab({ state }: { state: GameState }) {
  const c = state.career!
  const p = state.players[c.playerId]
  const rows = skillProgress(state)
  const byId = new Map(rows.map((r) => [r.id, r]))
  const owned = p.skills
  const good = owned.filter((k) => !SKILL_DEFS[k].bad).length
  const capped = good >= MAX_GOOD
  const nextCheck = state.week <= 26 ? '第 26 週のあと（今季ここまでの成績）' : 'シーズンの終わり（今季の成績）'
  const open = (id: SkillId) => !owned.includes(id)
  return (
    <div className="flex min-h-0 flex-1 gap-2">
      {/* 左: しくみと、持っている特殊能力 */}
      <div className="panel scroll-y flex w-[15.5rem] shrink-0 flex-col gap-2 p-2.5">
        <div className="text-[0.72rem] leading-snug text-ink-dim">
          特殊能力は<span className="font-black text-ink">試合の成績</span>
          で身につきます。下の一覧の条件を、シーズンの成績でそろえてください。
          <div className="mt-1">
            ・判定は年 2 回: 第 26 週のあとと、シーズンの終わり
            <br />
            ・その季に {MIN_GAMES} 試合以上出ていること
            <br />
            ・1 回の判定で身につくのは 1 つ
            <br />
            ・長所は {MAX_GOOD} つまで
            <br />
            ・成績が悪いと短所が付きます。良くなると消えます
          </div>
        </div>
        <div className="grid grid-cols-2 gap-1.5 text-[0.7rem]">
          <div className="stat-chip px-2 py-1">
            長所 <span className="num font-black">{good}</span> / {MAX_GOOD}
          </div>
          <div className="stat-chip px-2 py-1">
            今季 <span className={`num font-black ${p.stats.gp >= MIN_GAMES ? 'text-good' : ''}`}>{p.stats.gp}</span> 試合
          </div>
        </div>
        <div className="stat-chip px-2 py-1 text-[0.7rem]">
          次の判定: <span className="font-black">{nextCheck}</span>
        </div>
        <div className="mt-1 text-[0.78rem] font-black">持っている特殊能力</div>
        {owned.length === 0 && <div className="text-[0.72rem] text-ink-dim">まだありません。右の条件を満たすと、代理人の藤堂さんが知らせてくれます。</div>}
        {owned.map((k) => {
          const def = SKILL_DEFS[k]
          const r = byId.get(k)
          const why = c.traitWhy?.[k]
          return (
            <div key={k} className={`panel-flat p-2 ${def.bad ? 'border-bad/40' : 'border-gold/50'}`}>
              <div className="flex items-center gap-1">
                <span className={`rounded px-1.5 text-[0.62rem] font-black ${def.bad ? 'bg-bad/20 text-bad' : 'bg-gold/20 text-gold'}`}>{def.bad ? '短所' : '長所'}</span>
                <span className="min-w-0 flex-1 truncate text-[0.8rem] font-black">{def.name}</span>
                <TermHelp id={`skill:${k}`} />
              </div>
              <div className="text-[0.64rem] leading-snug text-ink-dim">{def.desc}</div>
              {why && !def.bad && <div className="mt-0.5 text-[0.62rem] text-ink-mute">決め手: {why}</div>}
              {def.bad && r && r.kind === 'lose' && (
                <>
                  <div className="mt-1 text-[0.64rem] font-black text-ink">消える条件</div>
                  {r.meters.map((m) => (
                    <MeterRow key={m.label} m={m} />
                  ))}
                </>
              )}
              {def.bad && !r && <div className="mt-0.5 text-[0.62rem] text-ink-mute">成績では消えません（ケアのサービスで体を守りましょう）。</div>}
            </div>
          )
        })}
      </div>
      {/* 右: 身につけられる特殊能力（分類ごと） */}
      <div className="scroll-y min-h-0 flex-1">
        {capped && <div className="panel-flat mb-2 p-2 text-[0.72rem] text-ink-dim">長所が {MAX_GOOD} つそろっています。これ以上は身につきません（短所は付いたり消えたりします）。</div>}
        {SKILL_CATS.map((cat) => {
          const list = rows.filter((r) => SKILL_DEFS[r.id].cat === cat.id && open(r.id))
          if (list.length === 0) return null
          const bad = cat.id === 'bad'
          return (
            <div key={cat.id} className="mb-2">
              <div className={`mb-1 text-[0.74rem] font-black ${bad ? 'text-bad' : 'text-gold'}`}>{bad ? '短所（成績が悪いと付く）' : cat.label}</div>
              <div className="grid grid-cols-3 gap-1.5">
                {list.map((r) => (
                  <SkillCard key={r.id} r={r} capped={capped && !bad} />
                ))}
              </div>
            </div>
          )
        })}
      </div>
    </div>
  )
}
