/**
 * メニュー（M18）: すべての画面とタブを大きなタイルで並べる。返事を待っているものにはバッジ。
 * ナビの「メニュー」から開く。タイルを押すと、その画面のそのタブへ。
 */
import { useEffect } from 'react'
import { createPortal } from 'react-dom'
import { Icon } from '../components/Icon'
import { useGame } from '../../stores/gameStore'
import { useUi } from '../../stores/uiStore'
import { badgesOf, menuGroups } from './menu'

export function MenuSheet({ open, onClose }: { open: boolean; onClose: () => void }) {
  // タイトルから開いた設定など、ゲームが始まっていない画面でも置けるように
  const state = useGame((s) => s.state)
  useGame((s) => s.version)
  const switchTab = useUi((s) => s.switchTab)
  useEffect(() => {
    if (!open) return
    const onKey = (e: KeyboardEvent) => e.key === 'Escape' && onClose()
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [open, onClose])
  const root = open ? document.getElementById('overlay-root') : null
  if (!root || !state) return null
  const badges = badgesOf(state)
  const go = (screen: Parameters<typeof switchTab>[0], tab?: string) => {
    onClose()
    if (tab) useUi.getState().reset({ id: screen, params: { tab } })
    else switchTab(screen)
  }
  return createPortal(
    <div className="absolute inset-0 z-40">
      <div className="anim-fade absolute inset-0 bg-black/70" onClick={onClose} />
      <section className="anim-rise panel safe-px absolute inset-2 flex flex-col overflow-hidden bg-[#f7f5f0]" role="dialog" aria-label="メニュー">
        <header className="flex h-[3rem] shrink-0 items-center gap-2 border-b border-gold/20 px-1">
          <Icon name="grid" className="h-5 w-5 text-gold" />
          <div className="flex-1 text-[1.05rem] font-black tracking-wide">メニュー</div>
          <button
            className="btn btn-ghost btn-sm"
            onClick={() => {
              onClose()
              useUi.getState().reset({ id: 'title' })
            }}
          >
            <Icon name="ball" className="h-4 w-4" />
            タイトルへ
          </button>
          <button className="flex h-10 w-10 items-center justify-center rounded-lg text-ink-dim hover:bg-black/5" onClick={onClose} aria-label="閉じる">
            <Icon name="close" className="h-5 w-5" />
          </button>
        </header>
        <div className="scroll-y min-h-0 flex-1 space-y-3 py-2">
          {menuGroups(state).map((g) => (
            <div key={g.title}>
              <div className="panel-head mb-1.5">{g.title}</div>
              <div className="grid grid-cols-4 gap-2">
                {g.items.map((it) => {
                  const n = badges[it.tab ? `${it.screen}:${it.tab}` : it.screen] ?? 0
                  return (
                    <button key={`${it.screen}:${it.tab ?? ''}:${it.label}`} className="menu-tile" onClick={() => go(it.screen, it.tab)}>
                      <Icon name={it.icon} className="h-6 w-6 shrink-0 text-gold" />
                      <span className="min-w-0">
                        <span className="block truncate text-[0.9rem] font-black">{it.label}</span>
                        <span className="block truncate text-[0.7rem] text-ink-dim">{it.desc}</span>
                      </span>
                      {n > 0 && <span className="nav-badge !right-1.5 !top-1.5">{n}</span>}
                    </button>
                  )
                })}
              </div>
            </div>
          ))}
        </div>
      </section>
    </div>,
    root,
  )
}
