/**
 * クラブ経営 ── クラブを作る: ホームタウン → 愛称と色 → 難易度と保存先。
 * 国内 3 部のいちばん格の低いクラブと入れ替わり、3 部から始まる（engine/club/create.ts）。
 */
import { useState } from 'react'
import { CLUB_COLORS, DIFFICULTY_DEFS, HOMETOWNS, HOMETOWN_BY_ID, NICKNAME_IDEAS } from '../../engine/data/club'
import { SlotPicker } from '../components/SlotPicker'
import { useSlotChoice } from '../hooks/useSlotChoice'
import { useGame } from '../../stores/gameStore'
import { useUi } from '../../stores/uiStore'
import { Icon } from '../components/Icon'
import { Term } from '../components/Term'

const STEPS = ['ホームタウン', '愛称と色', 'はじめる'] as const
type Step = 0 | 1 | 2
type Difficulty = keyof typeof DIFFICULTY_DEFS

function Dots({ n }: { n: number }) {
  return <span className="tracking-[-0.1em] text-orange">{'●'.repeat(n)}<span className="text-ink-mute">{'●'.repeat(5 - n)}</span></span>
}

export function ClubNewScreen() {
  const pop = useUi((s) => s.pop)
  const reset = useUi((s) => s.reset)
  const newClub = useGame((s) => s.newClub)
  const [step, setStep] = useState<Step>(0)
  const [town, setTown] = useState(HOMETOWNS[0].id)
  const [nick, setNick] = useState(NICKNAME_IDEAS[0])
  const [colors, setColors] = useState<[string, string]>(CLUB_COLORS[0])
  const [diff, setDiff] = useState<Difficulty>('normal')
  const { slots, slot, setSlot, current: slotCurrent, go, dialog: slotDialog } = useSlotChoice()
  const [busy, setBusy] = useState(false)
  const h = HOMETOWN_BY_ID[town]
  const name = `${h.city}・${nick.trim() || NICKNAME_IDEAS[0]}`

  const start = () =>
    go(() => {
      setBusy(true)
      // 画面に「作っています」を出してから重い処理
      setTimeout(() => {
        newClub({ seed: Math.floor(Math.random() * 1_000_000_000), hometown: town, nickname: nick.trim() || NICKNAME_IDEAS[0], colors, difficulty: diff }, slot)
        reset({ id: 'home' })
      }, 30)
    })

  return (
    <div className="absolute inset-0 flex flex-col">
      <header className="topbar safe-px flex shrink-0 items-center gap-2" style={{ boxSizing: 'content-box' }}>
        <button className="flex h-10 w-10 items-center justify-center rounded-lg text-ink-dim hover:bg-black/5" onClick={() => (step > 0 ? setStep((step - 1) as Step) : pop())} aria-label="戻る">
          <Icon name="back" className="h-5 w-5" />
        </button>
        <h1 className="text-[1.05rem] font-extrabold">クラブ経営 ── クラブを作る</h1>
        <div className="ml-auto flex gap-1">
          {STEPS.map((s, i) => (
            <button key={s} onClick={() => setStep(i as Step)} className={`rounded-full px-2.5 py-1 text-[0.75rem] font-bold ${i === step ? 'bg-gold text-[#2a1a00]' : i < step ? 'bg-gold/20 text-gold' : 'bg-black/[0.06] text-ink-mute'}`}>
              {i + 1}. {s}
            </button>
          ))}
        </div>
      </header>
      <div className="safe-px safe-pb flex min-h-0 flex-1 gap-2 pt-2">
        <div className="scroll-y min-w-0 flex-1 pr-1">
          {step === 0 && (
            <>
              <p className="mb-2 text-[0.82rem] text-ink-dim">
                クラブを置く街を選びます。人口が多い街はファンとスポンサーの伸びしろが大きく（上の部に上がって勝つと、街の外にもファンが広がる）、バスケの熱が高い街はファンが増えやすく、観客がよく入ります。はじめは <Term id="jbl">JBL</Term> 3 部から。
              </p>
              <div className="grid grid-cols-2 gap-2">
                {HOMETOWNS.map((t) => (
                  <button key={t.id} onClick={() => setTown(t.id)} className={`rounded-xl border px-3 py-2 text-left ${town === t.id ? 'border-gold bg-gold/12' : 'border-line/50 bg-black/[0.05] hover:bg-black/5'}`}>
                    <div className="flex items-baseline gap-2">
                      <span className="text-[1rem] font-black">{t.city}</span>
                      <span className="text-[0.72rem] text-ink-dim">{t.pref}</span>
                      <span className="num ml-auto text-[0.72rem] text-ink-dim">人口 {t.pop} 万</span>
                    </div>
                    <div className="text-[0.72rem]">
                      バスケの熱 <Dots n={t.passion} />
                    </div>
                    <div className="text-[0.72rem] leading-snug text-ink-dim">{t.desc}</div>
                  </button>
                ))}
              </div>
            </>
          )}
          {step === 1 && (
            <>
              <p className="mb-2 text-[0.82rem] text-ink-dim">クラブの愛称とチームの色。愛称は自由に入力できます（12 文字まで）。</p>
              <div className="mb-1 text-[0.9rem] font-black">愛称</div>
              <div className="mb-2 flex items-center gap-2">
                <span className="text-[1rem] font-black">{h.city}・</span>
                <input value={nick} onChange={(e) => setNick(e.target.value)} maxLength={12} className="min-w-0 flex-1 rounded-lg border border-line bg-black/[0.06] px-3 py-2 text-[1rem] font-bold outline-none focus:border-gold" />
              </div>
              <div className="mb-3 flex flex-wrap gap-1.5">
                {NICKNAME_IDEAS.map((n) => (
                  <button key={n} onClick={() => setNick(n)} className={`rounded-full border px-2.5 py-1 text-[0.78rem] font-bold ${nick === n ? 'border-gold text-gold' : 'border-line/60 text-ink-dim'}`}>
                    {n}
                  </button>
                ))}
              </div>
              <div className="mb-1 text-[0.9rem] font-black">チームの色</div>
              <div className="grid grid-cols-8 gap-2">
                {CLUB_COLORS.map(([a, b]) => {
                  const sel = colors[0] === a && colors[1] === b
                  return (
                    <button key={a + b} onClick={() => setColors([a, b])} className={`flex h-12 items-center justify-center rounded-xl border-2 ${sel ? 'border-gold' : 'border-transparent'}`} style={{ background: a }} aria-label="色">
                      <span className="h-4 w-8 rounded" style={{ background: b }} />
                    </button>
                  )
                })}
              </div>
            </>
          )}
          {step === 2 && (
            <>
              <div className="mb-1 text-[0.9rem] font-black">難易度</div>
              <div className="mb-3 grid grid-cols-3 gap-2">
                {(Object.keys(DIFFICULTY_DEFS) as Difficulty[]).map((d) => (
                  <button key={d} onClick={() => setDiff(d)} className={`rounded-xl border px-3 py-2 text-left ${diff === d ? 'border-gold bg-gold/12' : 'border-line/50 bg-black/[0.05]'}`}>
                    <div className="text-[1rem] font-black">{DIFFICULTY_DEFS[d].name}</div>
                    <div className="text-[0.72rem] leading-snug text-ink-dim">{DIFFICULTY_DEFS[d].desc}</div>
                  </button>
                ))}
              </div>
              <div className="panel-flat mb-3 p-3 text-[0.78rem] leading-relaxed">
                <div className="font-black text-gold">目標</div>
                3 部で勝って 2 部へ、1 部へ。日本一になったら、その先は NBA への<Term id="expansion">拡張参入</Term>。
                上の部に上がるには、アリーナの席数（<Term id="license">ライセンス</Term>: 2 部 3,000 席・1 部 5,000 席）も要ります。
                <br />
                資金がマイナスのまま 8 週続くとオーナーが立て直しますが、3 回目はクラブを手放すことになります。
              </div>
              <div className="mb-1 text-[0.9rem] font-black">保存先</div>
              <SlotPicker slots={slots} slot={slot} onChange={setSlot} />
            </>
          )}
        </div>
        {/* 右: できあがり */}
        <div className="panel panel-hero flex w-[17rem] shrink-0 flex-col gap-2 p-3">
          <div className="flex items-center gap-3">
            <div className="flex h-16 w-16 shrink-0 items-center justify-center rounded-2xl text-[1.1rem] font-black" style={{ background: colors[0], color: colors[1] }}>
              {town.slice(0, 3).toUpperCase()}
            </div>
            <div className="min-w-0">
              <div className="truncate text-[1.05rem] font-black">{name}</div>
              <div className="text-[0.75rem] text-ink-dim">
                {h.pref}・JBL 3 部
              </div>
            </div>
          </div>
          <div className="text-[0.75rem] leading-snug text-ink-dim">{h.desc}</div>
          <div className="num grid grid-cols-2 gap-1.5 text-[0.75rem]">
            <div className="stat-chip px-2 py-1">はじめの資金 {(DIFFICULTY_DEFS[diff].money / 10000).toFixed(1)} 億円</div>
            <div className="stat-chip px-2 py-1">アリーナ 1,500 席</div>
          </div>
          <div className="mt-auto flex flex-col gap-2">
            {step < 2 ? (
              <button className="btn btn-gold h-[3.2rem]" onClick={() => setStep((step + 1) as Step)}>
                次へ
                <Icon name="forward" className="h-5 w-5" />
              </button>
            ) : (
              <>
                <div className="text-[0.72rem] text-ink-dim">
                  保存先: スロット {slot}
                  {slotCurrent ? <span className="ml-1 font-bold text-bad">（「{slotCurrent.title}」を上書き）</span> : <span className="ml-1 font-bold text-good">（空き）</span>}
                </div>
                <button className="btn btn-gold h-[3.2rem]" disabled={busy} onClick={start}>
                  {busy ? 'クラブを作っています…' : 'このクラブで始める'}
                </button>
              </>
            )}
          </div>
        </div>
      </div>
      {slotDialog}
    </div>
  )
}
