/**
 * 制度の「初めて」の説明: その制度に初めて出会ったとき（ゲームの状態で判定）、ホームで 1 回だけ出す。中身は tips.ts の sys:*。
 * 見たものは端末に覚える（設定の tipsSeen。画面の説明と同じ）。画面の説明が先、会話や場面が積まれているあいだは出さない（AppShell）。
 */
import type { GameState } from '../../engine'
import { LICENSE_SEATS } from '../../engine/data/club'
import { NBA_CAP } from '../../engine/economy/salary'
import { clubTeam } from '../../engine/club/manage'
import { payroll } from '../../engine/club/nba'
import { windowOpen } from '../../engine/club/transfer'
import { moodOf } from '../../engine/club/story'
import { nearFanCeiling } from '../../engine/club/fans'
import { subTownSlots } from '../../engine/club/hometown'
import { inEacc } from '../../engine/competition/eacc'
import { datable } from '../../engine/career/romance'

interface SysTip {
  id: string
  mode: 'career' | 'club'
  when: (s: GameState) => boolean
}

const myTeam = (s: GameState) => {
  const p = s.players[s.career!.playerId]
  return p.teamId >= 0 ? s.teams[p.teamId] : undefined
}
const inSeries = (s: GameState, teamId: number) => s.series.some((x) => x.hi === teamId || x.lo === teamId)

/** 出す順（上ほど先） */
const SYS_TIPS: SysTip[] = [
  // ---- キャリア
  { id: 'sys:declare', mode: 'career', when: (s) => s.career!.nbaInterest >= 25 && myTeam(s)?.league !== 'NBA' && myTeam(s)?.league !== 'DEV' },
  { id: 'sys:dev', mode: 'career', when: (s) => myTeam(s)?.league === 'DEV' },
  { id: 'sys:fa', mode: 'career', when: (s) => !myTeam(s) && !!s.career!.path && s.career!.log.length > 0 },
  { id: 'sys:playoffs', mode: 'career', when: (s) => !!myTeam(s) && inSeries(s, myTeam(s)!.id) },
  { id: 'sys:trade', mode: 'career', when: (s) => myTeam(s)?.league === 'NBA' && s.week >= 20 && s.week <= 31 },
  { id: 'sys:extension', mode: 'career', when: (s) => myTeam(s)?.league === 'NBA' && s.players[s.career!.playerId].contract.years <= 1 && s.week >= 18 },
  { id: 'sys:cupCareer', mode: 'career', when: (s) => !!myTeam(s)?.league.startsWith('JBL') && s.week >= 14 && s.week <= 31 },
  { id: 'sys:national', mode: 'career', when: (s) => (s.career!.national?.caps ?? 0) > 0 },
  { id: 'sys:date', mode: 'career', when: (s) => datable(s).length > 0 },
  // ---- クラブ
  { id: 'sys:license', mode: 'club', when: (s) => { const t = clubTeam(s); const up = t.league === 'JBL3' ? 'JBL2' : t.league === 'JBL2' ? 'JBL1' : null; return !!up && s.week >= 8 && t.arena.capacity < (LICENSE_SEATS[up] ?? 0) } },
  { id: 'sys:subTown', mode: 'club', when: (s) => clubTeam(s).league !== 'NBA' && s.week >= 2 && (s.club!.subTowns?.length ?? 0) < subTownSlots(s) },
  { id: 'sys:fanCap', mode: 'club', when: (s) => clubTeam(s).league !== 'NBA' && nearFanCeiling(s) },
  { id: 'sys:mood', mode: 'club', when: (s) => clubTeam(s).roster.some((id) => moodOf(s, id) < 38) },
  { id: 'sys:bids', mode: 'club', when: (s) => s.club!.bids.length > 0 },
  { id: 'sys:deadline', mode: 'club', when: (s) => clubTeam(s).league !== 'NBA' && s.week >= 27 && windowOpen(s) },
  { id: 'sys:cupClub', mode: 'club', when: (s) => clubTeam(s).league.startsWith('JBL') && s.week >= 14 && s.week <= 31 },
  { id: 'sys:eacc', mode: 'club', when: (s) => inEacc(s, s.club!.teamId) },
  { id: 'sys:expansion', mode: 'club', when: (s) => clubTeam(s).league === 'JBL1' },
  { id: 'sys:luxury', mode: 'club', when: (s) => clubTeam(s).league === 'NBA' && payroll(s, clubTeam(s)) > NBA_CAP },
]

/** 今出す制度の説明（なければ undefined） */
export function firstSysTip(state: GameState, seen: string[]): string | undefined {
  const mode = state.club ? 'club' : state.career ? 'career' : null
  if (!mode || (mode === 'career' && state.career!.retiredAt !== undefined)) return undefined
  return SYS_TIPS.find((t) => t.mode === mode && !seen.includes(t.id) && t.when(state))?.id
}
