function Bar({ value, color, label, term }: { value: number; color: string; label: string; term?: string }) {
  return (
    <div className="text-[0.72rem]">
      <div className="flex justify-between">
        <span className="text-ink-dim">{term ? <Term id={term}>{label}</Term> : label}</span>
        <span className="num font-bold">{Math.round(value)}</span>
      </div>
      <div className="h-1.5 overflow-hidden rounded-full bg-black/10">
        <div className="h-full rounded-full" style={{ width: `${Math.max(0, Math.min(100, value))}%`, background: color }} />
      </div>
    </div>
  )
}

/** 入団前: 進路と話 */
function PathChoice() {
  const state = useGameState()
  const mutate = useGame((s) => s.mutate)
  const c = state.career!
  const cols = [
    ['pro', c.offers.filter((o) => o.kind === 'rookie')],
    ['college', c.offers.filter((o) => o.kind === 'college')],
  ] as const
  const ROLE: Record<string, string> = { star: 'エース', starter: 'スタメン', rotation: 'ローテーション', bench: 'ベンチから' }
  return (
    <div className="absolute inset-0 grid grid-cols-2 gap-2 p-2">
      {cols.map(([path, offers]) => {
        const d = PATH_DEFS[path]
        return (
          <div key={path} className="panel scroll-y flex flex-col gap-2 p-3">
            <div>
              <div className="text-[1.1rem] font-black">{path === 'pro' ? <Term id="jbl">{d.name}</Term> : <Term id="ncaa">{d.name}</Term>}</div>
              <div className="text-[0.85rem] font-bold text-orange">{d.catch}</div>
            </div>
            <div className="text-[0.75rem] leading-snug">
              {d.pros.map((x) => (
                <div key={x} className="text-good">
                  ＋ <span className="text-ink">{x}</span>
                </div>
              ))}
              {d.cons.map((x) => (
                <div key={x} className="text-bad">
                  − <span className="text-ink-dim">{x}</span>
                </div>
              ))}
            </div>
            <div className="panel-head">届いている話</div>
            {offers.map((o) => {
              const t = state.teams[o.teamId]
              return (
                <div key={o.id} className="panel-flat flex items-center gap-2 p-2">
                  <TeamDot colors={t.colors} abbr={t.abbr} className="h-9 w-9 text-[0.6rem]" />
                  <div className="min-w-0 flex-1">
                    <div className="truncate text-[0.9rem] font-black">{t.name}</div>
                    <div className="text-[0.7rem] text-ink-dim">
                      {state.leagues[t.league].name}・格 {t.rep}・{ROLE[o.role]}・{o.kind === 'college' ? <Term id="scholarship">奨学金</Term> : `年俸 ${salaryLabel(o.salary, t.league)}・${o.years}年`}
                    </div>
                    <div className="truncate text-[0.7rem] italic text-ink-mute">「{o.pitch}」</div>
                  </div>
                  <button className="btn btn-gold btn-sm" onClick={() => mutate((st) => acceptOffer(st, o.id))}>
                    決める
                  </button>
                </div>
              )
            })}
          </div>
        )
      })}
    </div>
  )
}

function FixtureRow({ f, me }: { f: Fixture; me: Player }) {
  const state = useGameState()
  const home = f.home === me.teamId
  const opp = state.teams[home ? f.away : f.home]
  const s = state.series.find((x) => x.id === f.seriesId)
  return (
    <div className="flex items-center gap-2 py-1 text-[0.8rem]">
      <span className="w-6 text-ink-dim">{'月火水木金土日'[f.day]}</span>
      <span className="w-6 text-ink-dim">{home ? 'vs' : '@'}</span>
      <TeamDot colors={opp.colors} abbr={opp.abbr} className="h-6 w-6 text-[0.5rem]" />
      <span className="min-w-0 flex-1 truncate font-bold">{opp.name}</span>
      {s && <span className="text-[0.68rem] text-gold">{s.name}</span>}
      {f.kind === 'cup' && <span className="text-[0.68rem] text-gold">{fixtureLabel(state, f)}</span>}
    </div>
  )
}

/** 週のまとめ（進めたあと） */
function WeekSummary({ report, before, onClose }: { report: { r: WeekReport; ovr0: number; trust0: number; moments?: MomentResult; stats0: Player['stats'] }; before?: unknown; onClose: () => void }) {
  void before
  const state = useGameState()
  const c = state.career!
  const p = state.players[c.playerId]
  const d = { gp: p.stats.gp - report.stats0.gp, pts: p.stats.pts - report.stats0.pts, reb: p.stats.oreb + p.stats.dreb - report.stats0.oreb - report.stats0.dreb, ast: p.stats.ast - report.stats0.ast, min: p.stats.min - report.stats0.min }
  const games = state.fixtures.filter((f) => f.week === report.r.week && f.result && (f.home === p.teamId || f.away === p.teamId))
  const o1 = ovr(p)
  return (
    <div className="anim-fade absolute inset-0 z-40 flex items-center justify-center bg-black/60 p-4" onClick={onClose}>
      <div className="panel panel-solid w-[34rem] max-w-full p-4" onClick={(e) => e.stopPropagation()}>
        <div className="text-[1rem] font-black">今週のまとめ</div>
        {games.length > 0 && (
          <div className="mt-2">
            {games.map((f) => {
              const home = f.home === p.teamId
              const win = home ? f.result!.hs > f.result!.as : f.result!.as > f.result!.hs
              const opp = state.teams[home ? f.away : f.home]
              return (
                <div key={f.id} className="flex items-center gap-2 text-[0.85rem]">
                  <span className={`w-5 font-black ${win ? 'text-good' : 'text-bad'}`}>{win ? '○' : '●'}</span>
                  <span className="min-w-0 flex-1 truncate">
                    {home ? 'vs' : '@'} {opp.name}
                  </span>
                  <span className="num font-bold">
                    {home ? f.result!.hs : f.result!.as} - {home ? f.result!.as : f.result!.hs}
                  </span>
                </div>
              )
            })}
            {/* 最後の試合の流れ */}
            {games.length > 0 && <FlowGraph state={state} f={games[games.length - 1]} teamId={p.teamId} />}
            {d.gp > 0 ? (
              <div className="num mt-1 text-[0.85rem] text-gold">
                {p.short}: {d.gp} 試合 平均 {(d.pts / d.gp).toFixed(1)} 点・{(d.reb / d.gp).toFixed(1)} リバウンド・{(d.ast / d.gp).toFixed(1)} アシスト（{(d.min / d.gp).toFixed(0)} 分）
              </div>
            ) : (
              <div className="mt-1 text-[0.8rem] text-ink-dim">今週は出番がなかった。練習で監督の評価を上げよう。</div>
            )}
          </div>
        )}
        {report.moments && report.moments.tried > 0 && (
          <div className="mt-1 text-[0.8rem]">
            見せ場: {report.moments.tried} 回中 <span className="font-black text-gold">{report.moments.won} 回成功</span>
          </div>
        )}
        <div className="mt-2 grid grid-cols-2 gap-2 text-[0.85rem]">
          <div className="stat-chip px-2 py-1">
            <Term id="ovr">総合値</Term> {report.ovr0} → <span className="font-black text-gold">{o1}</span>
          </div>
          <div className="stat-chip px-2 py-1">
            監督の評価 {Math.round(report.trust0)} → <span className={`font-black ${c.trust >= report.trust0 ? 'text-good' : 'text-bad'}`}>{Math.round(c.trust)}</span>
          </div>
        </div>
        {report.r.news.length > 0 && (
          <div className="mt-2 max-h-[7rem] overflow-hidden text-[0.75rem] text-ink-dim">
            {report.r.news.slice(-4).map((n, i) => (
              <div key={i} className={n.big ? 'font-bold text-gold' : ''}>
                ・{n.text}
              </div>
            ))}
          </div>
        )}
        <button className="btn btn-gold mt-3 w-full" onClick={onClose}>
          OK
        </button>
      </div>
    </div>
  )
}

export function CareerHomeScreen() {
  const state = useGameState()
  const mutate = useGame((s) => s.mutate)
  const playWeek = useGame((s) => s.playWeek)
  const advance = useGame((s) => s.advance)
  const busy = useGame((s) => !!s.progress)
  const push = useUi((s) => s.push)
  const c = state.career!
  const p = state.players[c.playerId]
  const team = p.teamId >= 0 ? state.teams[p.teamId] : undefined
  const fixtures = careerFixtures(state)
  const [matchStep, setMatchStep] = useState<'none' | 'ask' | 'watch'>('none')
  const [summary, setSummary] = useState<{ r: WeekReport; ovr0: number; trust0: number; moments?: MomentResult; stats0: Player['stats'] } | null>(null)
  const featured = fixtures[0]
  const [setup, setSetup] = useState<MatchSetup | null>(null)
  const [faceOpen, setFaceOpen] = useState(false)
  const action = c.action ?? autoAction(state)
  const region = regionOf(state)
  const places = PLACES.filter((x) => x.region === region)

  const doWeek = (played?: Map<number, MatchSummary>, moments?: MomentResult) => {
    const ovr0 = ovr(p)
    const trust0 = c.trust
    const stats0 = { ...p.stats }
    if (moments) {
      // 見せ場の結果: 成功は監督の評価と知名度に
      mutate((st) => {
        const cc = st.career!
        cc.moments.tried += moments.tried
        cc.moments.won += moments.won
        cc.trust = Math.min(100, cc.trust + moments.won * 0.8 - (moments.tried - moments.won) * 0.3)
        cc.fame = Math.min(100, cc.fame + moments.won * 0.3)
      })
    }
    const r = playWeek(played)
    if (r) setSummary({ r, ovr0, trust0, moments, stats0 })
  }

  if (!team && c.offers.length && !c.path)
    return (
      <AppShell title="18 歳の進路" current="home" tip={false}>
        <PathChoice />
        <TalkScene />
      </AppShell>
    )

  // 引退した: 会話が済んだら総括へ
  if (c.retiredAt !== undefined)
    return (
      <AppShell title="引退" current="home" tip={false}>
        <div className="flex h-full items-center justify-center">
          <div className="panel panel-hero max-w-[30rem] p-5 text-center">
            <div className="text-[1.1rem] font-black">{p.name}、現役引退</div>
            <p className="mt-1 text-[0.85rem] text-ink-dim">長いキャリアを振り返りましょう。</p>
            <button className="btn btn-gold mt-3" disabled={c.talks.length > 0} onClick={() => push({ id: 'careerEnd' })}>
              キャリアを振り返る
            </button>
          </div>
        </div>
        <TalkScene />
      </AppShell>
    )

  if (matchStep === 'watch' && setup && featured)
    return (
      <MatchView
        setup={setup}
        focusPlayerId={p.id}
        onFinish={(sum, _e, moments) => {
          setMatchStep('none')
          doWeek(new Map([[featured.id, sum]]), moments)
        }}
      />
    )

  const lg = team ? state.leagues[team.league] : undefined
  const rank = team && lg ? rankIn(lg, team.id, team.league === 'NBA' ? lg.teamIds.filter((id) => state.teams[id].conf === team.conf) : undefined) : 0
  const mock = c.path === 'college' || (team && team.league.startsWith('JBL')) ? mockRank(state) : null

  return (
    <AppShell
      title={team ? team.name : '所属なし'}
      current="home"
      // 週のまとめ・試合の確認・顔を選ぶ小窓が開いているあいだは、説明を出さない
      tip={!summary && matchStep === 'none' && !faceOpen}
      color={team?.colors.primary}
      right={
        <span className="num text-[0.82rem] font-bold">
          {dateLabel(state.startYear, state.season, state.week)}
          <span className="ml-2 text-ink-dim">{PHASE_LABEL[phaseOfWeek(state.week)]}</span>
        </span>
      }
    >
      <div className="absolute inset-0 flex gap-2 p-2">
        {/* 左: 主人公 */}
        <div className="panel panel-hero scroll-y flex w-[16.5rem] shrink-0 flex-col gap-2 p-3">
          <div className="flex gap-2">
            {/* 写真を押すと顔を選び直せる（写真が外れていたら、選ぶように知らせる） */}
            <button className="relative shrink-0" onClick={() => setFaceOpen(true)} aria-label="顔の写真を選ぶ">
              <Portrait id={playerPhoto(state, p)} kind="face" className="h-[4.6rem] w-[4.6rem] rounded-xl" fallback={<Initials name={p.short} className="h-full w-full" />} />
              {!isProtagFace(p.photo) && <span className="absolute inset-x-0 bottom-0 rounded-b-xl bg-gold/90 py-0.5 text-center text-[0.6rem] font-black text-[#2a1a00]">顔を選ぶ</span>}
            </button>
            <div className="min-w-0 flex-1">
              <div className="truncate text-[1rem] font-black">{p.name}</div>
              <div className="flex items-center gap-1 text-[0.72rem] text-ink-dim">
                <PosBadge pos={p.pos} /> {p.contract.kind === 'college' ? `${p.classYear ?? 1}年生` : `#${p.jersey}`}
              </div>
              <div className="mt-0.5 flex items-center gap-1 text-[0.72rem]">
                <ConditionArrow value={p.condition} /> 調子
                {p.injury && <span className="ml-1 font-bold text-bad">ケガ（あと {p.injury.weeks} 週）</span>}
              </div>
            </div>
            <OvrBadge value={ovr(p)} size="lg" />
          </div>
          <Bar label="疲れ" value={p.fatigue} color="linear-gradient(90deg,#3ddc84,#ffb020,#ff5a5f)" />
          <Bar label="監督の評価" value={c.trust} color="#3aa0ff" term="trust" />
          <div className="text-[0.72rem]">
            <div className="flex justify-between">
              <span className="flex items-center gap-1 text-ink-dim">
                NBA の注目度 <TermHelp id="nbaInterest" />
              </span>
              <span className="num font-bold text-orange">{Math.round(c.nbaInterest)}</span>
            </div>
            <div className="h-1.5 overflow-hidden rounded-full bg-black/10">
              <div className="h-full rounded-full bg-gradient-to-r from-orange to-gold" style={{ width: `${c.nbaInterest}%` }} />
            </div>
          </div>
          {mock !== null && (
            <div className="stat-chip px-2 py-1 text-[0.75rem]">
              <Term id="mockDraft">モックドラフト</Term>: <span className="font-black text-gold">{mock} 位前後</span>
            </div>
          )}
          <div className="grid grid-cols-2 gap-1.5 text-[0.72rem]">
            <div className="stat-chip px-2 py-1">
              <Term id="fame">知名度</Term> <span className="num font-black">{Math.round(c.fame)}</span>
            </div>
            <div className="stat-chip px-2 py-1">
              貯金 <span className="num font-black">{formatMoneyShort(c.money)}円</span>
            </div>
          </div>
          <SkillChips />
          {team && lg && (
            <button className="stat-chip flex items-center gap-2 px-2 py-1.5 text-left" onClick={() => push({ id: 'team', params: { teamId: team.id } })}>
              <TeamDot colors={team.colors} abbr={team.abbr} />
              <span className="min-w-0 text-[0.75rem]">
                <span className="block truncate font-bold">{lg.name}</span>
                <span className="text-ink-dim">
                  {lg.standings[team.id]?.w ?? 0}勝{lg.standings[team.id]?.l ?? 0}敗・{rank}位
                </span>
              </span>
            </button>
          )}
          <div className="flex items-center gap-2 text-[0.75rem]">
            <span className="num rounded-md px-2 py-0.5 text-[1rem] font-black text-[#0b1320]" style={{ background: RANK_DEFS[careerRank(state)].color }}>
              {careerRank(state)}
            </span>
            <span className="text-ink-dim">ランク: {RANK_DEFS[careerRank(state)].label}</span>
          </div>
          {c.offers.length > 0 && (
            <button className="btn btn-blue btn-sm" onClick={() => push({ id: 'career', params: { tab: 'offers' } })}>
              契約の話が {c.offers.length} 件
            </button>
          )}
          {c.allStar === state.season && c.allStarDone !== state.season && state.week === NBA_ALLSTAR_WEEK && (
            <button className="btn btn-gold btn-sm shine-sweep" onClick={() => push({ id: 'allStar' })}>
              オールスターの週末へ
            </button>
          )}
        </div>
        {/* 中: 今週 */}
        <div className="flex min-w-0 flex-1 flex-col gap-2">
          <div className="panel p-3">
            <div className="panel-head mb-1">今週の試合</div>
            {fixtures.length === 0 ? <div className="text-[0.8rem] text-ink-dim">試合はありません。練習に集中しよう。</div> : fixtures.map((f) => <FixtureRow key={f.id} f={f} me={p} />)}
          </div>
          <div className="panel scroll-y min-h-0 flex-1 p-3">
            <div className="panel-head mb-1">今週の過ごし方</div>
            <div className="grid grid-cols-3 gap-1.5">
              {ACTIONS.filter((a) => a !== 'camp' || campOpen(state)).map((a: ActionId) => {
                const d = ACTION_DEFS[a]
                const sel = action === a
                return (
                  <button key={a} onClick={() => mutate((st) => void (st.career!.action = a))} className={`rounded-lg border px-2 py-1.5 text-left ${sel ? 'border-gold bg-gold/15' : 'border-line/50 bg-black/[0.04] hover:bg-black/5'}`}>
                    <div className="text-[0.82rem] font-black">{d.name}</div>
                    <div className="line-clamp-2 text-[0.66rem] leading-tight text-ink-dim">{d.desc}</div>
                  </button>
                )
              })}
            </div>
            {action === 'outing' && (
              <div className="mt-2">
                <div className="mb-1 text-[0.75rem] font-bold text-gold">行き先</div>
                <div className="grid grid-cols-3 gap-1.5">
                  {places.map((pl) => {
                    const sel = (c.place ?? places[0].id) === pl.id
                    const who = peopleAt(state, pl.id)
                    return (
                      <button key={pl.id} onClick={() => mutate((st) => void (st.career!.place = pl.id))} className={`rounded-lg border px-2 py-1.5 text-left ${sel ? 'border-orange bg-orange/15' : 'border-line/50 bg-black/[0.04]'}`}>
                        <div className="text-[0.8rem] font-black">{pl.name}</div>
                        <div className="truncate text-[0.64rem] text-ink-dim">{who.map((id) => (c.met.includes(id) ? CAST_BY_ID[id].name.split(/[・ ]/)[0] : '？')).join('・')}</div>
                      </button>
                    )
                  })}
                </div>
              </div>
            )}
            {action === 'date' && (
              <div className="mt-2">
                <div className="mb-1 text-[0.75rem] font-bold text-pink">誘う人</div>
                {datable(state).length === 0 ? (
                  <div className="text-[0.72rem] text-ink-dim">誘える人がいません（おでかけで会って絆 30 になった、恋愛が進められる人。日本とアメリカの人は、今いる地域の人だけ。オフのキャンプ前の試合のない週は、会いに行ける）。</div>
                ) : (
                  <div className="grid grid-cols-4 gap-1.5">
                    {datable(state).map((id) => {
                      const sel = dateTarget(state) === id
                      const travel = dateTravel(state, id)
                      return (
                        <button key={id} onClick={() => mutate((st) => void (st.career!.dateWith = id))} className={`flex items-center gap-1.5 rounded-lg border px-1.5 py-1 text-left ${sel ? 'border-pink-400 bg-pink-500/15' : 'border-line/50 bg-black/[0.04]'}`}>
                          <Portrait id={id} kind="face" className="face-round h-7 w-7 shrink-0" fallback={<Initials name={CAST_BY_ID[id].name} className="h-full w-full" />} />
                          <span className="min-w-0">
                            <span className="block truncate text-[0.72rem] font-black">{CAST_BY_ID[id].name}</span>
                            <span className="text-[0.62rem] text-ink-dim">
                              絆 {Math.round(c.bonds[id] ?? 0)}
                              {travel > 0 && `・渡航 ${travel} 万円`}
                            </span>
                          </span>
                        </button>
                      )
                    })}
                  </div>
                )}
              </div>
            )}
            {action === 'date' &&
              (() => {
                const who = dateTarget(state)
                if (!who) return null
                const spots = dateSpots(state, who)
                if (!spots.length) return null
                const known = (c.bonds[who] ?? 0) >= 50
                const cur = defaultSpot(state, who)
                return (
                  <div className="mt-2">
                    <div className="mb-1 text-[0.75rem] font-bold text-pink">行き先（♥ はその人の好きな場所。絆 50 から分かる）</div>
                    <div className="grid grid-cols-3 gap-1.5">
                      {spots.map((sp) => {
                        const liked = known && likesSpot(who, sp.id)
                        const sel = cur === sp.id
                        return (
                          <button key={sp.id} onClick={() => mutate((st) => void (st.career!.dateSpot = sp.id))} className={`rounded-lg border px-1.5 py-1 text-left ${sel ? 'border-pink bg-pink/15' : 'border-line/50 bg-black/[0.04]'}`}>
                            <span className="block truncate text-[0.74rem] font-black">
                              {liked && <span className="text-pink">♥ </span>}
                              {sp.name}
                            </span>
                            <span className="text-[0.62rem] text-ink-dim">{sp.cost ? `${sp.cost} 万円` : 'お金はかからない'}</span>
                          </button>
                        )
                      })}
                    </div>
                  </div>
                )
              })()}
            {action === 'camp' && (
              <div className="mt-2">
                <div className="mb-1 text-[0.75rem] font-bold text-orange">合宿の行き先（アメリカと日本の行き来は渡航費がかかる）</div>
                <div className="grid grid-cols-2 gap-1.5">
                  {CAMPS.map((cp) => {
                    const locked = !!cp.minFame && c.fame < cp.minFame
                    const cost = campCost(state, cp.id)
                    const sel = (c.camp ?? campsFor(state)[0]?.id) === cp.id
                    return (
                      <button key={cp.id} disabled={locked || c.money < cost} onClick={() => mutate((st) => void (st.career!.camp = cp.id))} className={`rounded-lg border px-2 py-1 text-left disabled:opacity-45 ${sel ? 'border-orange bg-orange/12' : 'border-line/50 bg-black/[0.04]'}`}>
                        <div className="flex items-baseline gap-1">
                          <span className="truncate text-[0.78rem] font-black">{cp.name}</span>
                          <span className="num ml-auto shrink-0 text-[0.66rem] font-bold text-gold">{formatMoneyShort(cost)}円</span>
                        </div>
                        <div className="truncate text-[0.62rem] text-ink-dim">{locked ? `知名度 ${cp.minFame} から` : cp.desc}</div>
                        <div className="text-[0.62rem] text-good">{Object.entries(cp.exp).map(([k, v]) => `${EXP_LABEL[k]} +${v}`).join('・')}</div>
                      </button>
                    )
                  })}
                </div>
              </div>
            )}
            {!c.action && <div className="mt-1 text-[0.68rem] text-ink-mute">選ばなければ、おまかせ（練習の予定）になります。</div>}
          </div>
        </div>
        {/* 右: はじめの一歩・進める */}
        <div className="flex w-[11.5rem] shrink-0 flex-col justify-end gap-2">
          <FirstSteps />
          <div className="panel shrink-0 p-2 text-[0.72rem] text-ink-dim">
            経験点
            {Object.entries(c.exp).map(([k, v]) => (
              <div key={k} className="num flex justify-between">
                <span>{{ shoot: 'シュート', skill: 'テクニック', phys: 'フィジカル', def: 'ディフェンス', mind: 'メンタル' }[k]}</span>
                <span className="font-bold text-ink">{Math.floor(v)}</span>
              </div>
            ))}
            {c.growthMode === 'careful' && (
              <button className="btn btn-ghost btn-sm mt-1 w-full" onClick={() => push({ id: 'growth' })}>
                能力を上げる
              </button>
            )}
          </div>
          <button className="btn btn-ghost btn-sm" disabled={busy || !team} onClick={() => void advance(4)}>
            1か月オート
          </button>
          <button className="btn btn-gold h-[3.6rem]" disabled={busy || !team} onClick={() => (fixtures.length ? setMatchStep('ask') : doWeek())}>
            <Icon name={fixtures.length ? 'play' : 'forward'} className="h-5 w-5" />
            {fixtures.length ? '試合へ' : '次へ進む'}
          </button>
        </div>
      </div>
      {faceOpen && <FacePicker onClose={() => setFaceOpen(false)} />}
      {matchStep === 'ask' && featured && (
        <div className="anim-fade absolute inset-0 z-40 flex items-center justify-center bg-black/60 p-4" onClick={() => setMatchStep('none')}>
          <div className="panel panel-solid w-[30rem] max-w-full p-4" onClick={(e) => e.stopPropagation()}>
            <div className="text-[1rem] font-black">今週の注目の試合</div>
            <FixtureRow f={featured} me={p} />
            {fixtures.length > 1 && <div className="text-[0.72rem] text-ink-dim">ほかの {fixtures.length - 1} 試合は結果だけになります。</div>}
            <div className="mt-1 text-[0.75rem] text-ink-dim">観戦すると、ボールが回ってきた大事な場面（見せ場）で、どうするかを選べます。</div>
            <div className="mt-3 flex gap-2">
              <button className="btn btn-ghost flex-1" onClick={() => { setMatchStep('none'); doWeek() }}>
                結果だけ
              </button>
              <button
                className="btn btn-gold flex-1"
                onClick={() => {
                  setSetup({ ...fixtureSetup(state, featured, { focusPlayerId: p.id }), neutral: isNeutral(state, featured) })
                  setMatchStep('watch')
                }}
              >
                <Icon name="play" className="h-5 w-5" />
                観戦する
              </button>
            </div>
          </div>
        </div>
      )}
      {summary && <WeekSummary report={summary} onClose={() => setSummary(null)} />}
      <TalkScene />
      <AwardsCeremony />
      <DraftNight />
    </AppShell>
  )
}

/** ホームの主人公の欄: 持っている特殊能力と、いちばん近い長所。押すと育成の「特殊能力」タブ */
function SkillChips() {
  const state = useGameState()
  const push = useUi((s) => s.push)
  const p = state.players[state.career!.playerId]
  const near = nearestSkill(state)
  // いちばん足りない条件
  const need = near?.meters.filter((m) => !meterOk(m)).sort((a, b) => meterRate(a) - meterRate(b))[0]
  return (
    <button className="stat-chip px-2 py-1.5 text-left text-[0.72rem]" onClick={() => push({ id: 'growth', params: { tab: 'skill' } })}>
      <div className="flex items-center justify-between">
        <span className="text-[0.72rem] text-ink-dim">特殊能力</span>
        <span className="text-[0.66rem] text-ink-mute">条件を見る ›</span>
      </div>
      <div className="mt-1 flex flex-wrap gap-1">
        {p.skills.length === 0 && <span className="text-[0.66rem] text-ink-mute">まだありません（試合の成績で身につきます）</span>}
        {p.skills.map((k) => (
          <span key={k} className={`rounded px-1.5 py-[0.05rem] text-[0.64rem] font-black ${SKILL_DEFS[k].bad ? 'bg-bad/15 text-bad' : 'bg-gold/20 text-gold'}`}>
            {SKILL_DEFS[k].name}
          </span>
        ))}
      </div>
      {near && (
        <div className="mt-1 truncate text-[0.64rem] text-ink-dim">
          {near.ready ? '次の判定で' : 'あと少し'}: <span className="font-black text-ink">{SKILL_DEFS[near.id].name}</span>
          {!near.ready && need && <span className="text-ink-mute">（{need.label.replace('（1 試合）', '')}）</span>}
        </div>
      )}
    </button>
  )
}
