/** スタッフ・オーナーの写真（生成写真の staffJ・staffU から、名前で決まる。外国の名前は「・」入り） */
import { FACE_POOL } from '../../engine/data/facePool.generated'

export function staffPhoto(name: string): string {
  const pool = FACE_POOL[name.includes('・') ? 'staffU' : 'staffJ'] ?? []
  let h = 0
  for (const ch of name) h = (h * 31 + ch.charCodeAt(0)) >>> 0
  return pool.length ? pool[h % pool.length] : ''
}
