/**
 * ゲーム中の基本レイアウト（横向き）。
 *   [safe-left][ナビ][上部バー + 本文][safe-right]
 * ナビは左手の親指、主要な操作（「進む」など）は各画面の右下に置く。
 */
import { useEffect, useState, type ReactNode } from 'react'
import { sound } from '../audio/sound'
import { Tip } from './Tip'
import { TIPS } from './tips'
import { firstSysTip } from './sysTips'
import { useSettings } from '../../stores/settingsStore'
import { Icon, type IconName } from '../components/Icon'
import { useUi, type ScreenId } from '../../stores/uiStore'
import { useGame } from '../../stores/gameStore'
import { SceneBackground } from './SceneBackground'
import { MenuSheet } from './MenuSheet'
import { badgesOf } from './menu'
import { screenStep } from './steps'
import { markStep } from '../../engine/models/game'

/** キャリアモードのナビ */
const CAREER_NAV: { id: ScreenId; label: string; icon: IconName }[] = [
  { id: 'home', label: 'ホーム', icon: 'home' },
  { id: 'growth', label: '育成', icon: 'growth' },
  { id: 'life', label: 'くらし', icon: 'life' },
  { id: 'people', label: '人間関係', icon: 'story' },
  { id: 'schedule', label: '日程', icon: 'calendar' },
  { id: 'roster', label: '所属', icon: 'squad' },
  { id: 'career', label: 'キャリア', icon: 'trophy' },
]

/** クラブモードのナビ */
const CLUB_NAV: { id: ScreenId; label: string; icon: IconName }[] = [
  { id: 'home', label: 'ホーム', icon: 'home' },
  { id: 'roster', label: '選手', icon: 'squad' },
  { id: 'training', label: '練習', icon: 'whistle' },
  { id: 'tactics', label: '作戦', icon: 'tactics' },
  { id: 'schedule', label: '日程', icon: 'calendar' },
  { id: 'club', label: 'クラブ', icon: 'club' },
  { id: 'transfer', label: '補強・編成', icon: 'transfer' },
]

export function AppShell({
  title,
  right,
  children,
  current,
  back,
  scene,
  color,
  tip = true,
}: {
  title: ReactNode
  /** 上部バー右側（お金・日付など） */
  right?: ReactNode
  children: ReactNode
  /** ナビで強調するタブ */
  current?: ScreenId
  /** 戻るボタンを出す */
  back?: boolean
  /** 背景の写真（省略時は current から。menu.ts の SCENE_OF） */
  scene?: string
  /** 背景の光の色（チームの色） */
  color?: string
  /** 画面の説明（Tip）を出す（進路を選ぶ画面などは出さない） */
  tip?: boolean
}) {
  const switchTab = useUi((s) => s.switchTab)
  // ゲーム中の画面はメニューの BGM（試合の画面は別に切り替える）
  useEffect(() => sound.setScene('menu'), [])
  const pop = useUi((s) => s.pop)
  // 返事を待っているもの（オファー・申し出など）の数
  // （選択子で新しいオブジェクトを返すと描画が止まらなくなるので、状態と版を読んでから数える）
  const gameState = useGame((s) => s.state)
  useGame((s) => s.version)
  const club = gameState?.mode === 'club'
  const nav = club ? CLUB_NAV : CAREER_NAV
  const showTips = useSettings((s) => s.showTips)
  const tipsSeen = useSettings((s) => s.tipsSeen)
  const screenTip = current ? (club && TIPS[`club:${current}`] ? `club:${current}` : current) : undefined
  const busyTalk = !!gameState?.career?.talks.length || !!gameState?.club?.scenes?.length
  const sysTip = gameState && showTips && !busyTalk && (!screenTip || !TIPS[screenTip] || tipsSeen.includes(screenTip)) ? firstSysTip(gameState, tipsSeen) : undefined
  // はじめの一歩: この画面を開くと済む手順
  const step = gameState?.career || gameState?.club ? screenStep(club, current) : undefined
  const stepDone = !step || !!gameState?.tutorial?.done.includes(step)
  useEffect(() => {
    if (step && !stepDone) useGame.getState().mutate((st) => markStep(st, step))
  }, [step, stepDone])
  const badges = gameState ? badgesOf(gameState) : {}
  const [menu, setMenu] = useState(false)
  return (
    <div className="absolute inset-0 flex">
      <SceneBackground screen={current} scene={scene} color={color} />
      <nav className="navrail safe-l flex shrink-0 flex-col pt-1" aria-label="メニュー" style={{ boxSizing: 'content-box' }}>
        {/* メニュー（すべての画面とタブ・タイトルへ）。ゲームが始まっていなければタイトルへ */}
        {gameState ? (
          <button onClick={() => setMenu(true)} className="!text-gold/90">
            <Icon name="grid" />
            メニュー
          </button>
        ) : (
          <button onClick={() => useUi.getState().reset({ id: 'title' })} aria-label="タイトルへ">
            <Icon name="ball" className="text-orange" />
            タイトル
          </button>
        )}
        <div className="scroll-y flex-1">
          {gameState &&
            nav.map((n) => (
              <button key={n.id} aria-current={current === n.id ? 'page' : undefined} onClick={() => switchTab(n.id)}>
                <Icon name={n.icon} />
                {n.label}
                {(badges[n.id] ?? 0) > 0 && <span className="nav-badge">{badges[n.id]}</span>}
              </button>
            ))}
        </div>
        <button aria-current={current === 'glossary' ? 'page' : undefined} onClick={() => switchTab('glossary')}>
          <Icon name="book" />
          用語集
        </button>
        <button aria-current={current === 'settings' ? 'page' : undefined} onClick={() => switchTab('settings')} className="safe-b">
          <Icon name="settings" />
          設定
        </button>
      </nav>
      <div className="relative z-[1] flex min-w-0 flex-1 flex-col">
        <header className="topbar safe-pr safe-t flex shrink-0 items-center gap-2 pl-3" style={{ boxSizing: 'content-box' }}>
          {back && (
            <button className="-ml-1 flex h-10 w-10 items-center justify-center rounded-lg text-ink-dim hover:bg-black/5" onClick={pop} aria-label="戻る">
              <Icon name="back" className="h-5 w-5" />
            </button>
          )}
          <h1 className="min-w-0 truncate text-[1.05rem] font-extrabold tracking-wide">{title}</h1>
          <div className="ml-auto flex items-center gap-3 text-sm">{right}</div>
        </header>
        <main className="safe-r safe-b screen-enter relative min-h-0 flex-1">{children}</main>
        {/* 画面の説明は、会話（キャリアの話・クラブの場面）が終わってから */}
        {current && tip && (gameState?.career || gameState?.club) && !gameState?.career?.talks.length && !gameState?.club?.scenes?.length && <Tip id={current} club={club} />}
        {/* 制度の「初めて」の説明（ホームだけ。画面の説明を見終わってから） */}
        {current === 'home' && tip && sysTip && <Tip id={sysTip} club={club} />}
      </div>
      <MenuSheet open={menu} onClose={() => setMenu(false)} />
    </div>
  )
}
