/**
 * セーブの保存先を選ぶ（新しく始める画面・セーブの読み込み）。スロットごとに中身（空き・モード・名前・ゲームの日付・保存した日時）を出す。
 * 選ぶ状態と上書きの確認は hooks/useSlotChoice.tsx。
 */
import { SLOT_COUNT, type SaveSlotMeta } from '../../persistence/db'

const when = (t: number) => {
  const d = new Date(t)
  return `${d.getMonth() + 1}/${d.getDate()} ${d.getHours()}:${String(d.getMinutes()).padStart(2, '0')}`
}

export function SlotPicker({ slots, slot, onChange }: { slots: SaveSlotMeta[] | null; slot: number; onChange: (n: number) => void }) {
  const used = new Map((slots ?? []).map((s) => [s.id, s]))
  return (
    <div className="grid gap-1.5">
      {Array.from({ length: SLOT_COUNT }, (_, i) => i + 1).map((n) => {
        const s = used.get(n)
        const sel = slot === n
        return (
          <button key={n} onClick={() => onChange(n)} className={`flex items-center gap-2.5 rounded-lg border px-2.5 py-1.5 text-left ${sel ? 'border-gold bg-gold/15' : 'border-line/60 bg-black/[0.03] hover:bg-black/5'}`}>
            <span className={`num flex h-8 w-8 shrink-0 items-center justify-center rounded-md text-[0.95rem] font-black ${sel ? 'bg-gold text-[#2a1a00]' : 'bg-black/[0.06] text-ink-dim'}`}>{n}</span>
            {s ? (
              <>
                <span className={`shrink-0 rounded px-1.5 text-[0.66rem] font-bold ${s.mode === 'career' ? 'bg-orange/20 text-orange' : 'bg-accent/15 text-accent'}`}>{s.mode === 'career' ? 'キャリア' : 'クラブ'}</span>
                <span className="min-w-0 flex-1">
                  <span className="block truncate text-[0.85rem] font-black">{s.title}</span>
                  <span className="block truncate text-[0.68rem] text-ink-dim">
                    {s.dateLabel}
                    {s.leagueName && `・${s.leagueName}`}
                  </span>
                </span>
                <span className="num shrink-0 text-right text-[0.66rem] text-ink-mute">
                  保存
                  <br />
                  {when(s.updatedAt)}
                </span>
                {sel && <span className="shrink-0 rounded bg-bad/15 px-1.5 text-[0.66rem] font-black text-bad">上書き</span>}
              </>
            ) : (
              <span className="flex-1 text-[0.85rem] font-bold text-good">空き</span>
            )}
          </button>
        )
      })}
      {!slots && <div className="text-[0.7rem] text-ink-mute">セーブデータを調べています…</div>}
    </div>
  )
}
