/**
 * 会話の画面（予約された会話 state.career.talks を順に出す）。タップで次の台詞、最後に選択肢があれば選ぶ。
 * {name}・{team}・{mock}（モックドラフトの予想）・{draft}（指名の結果）を置き換える。
 */
import { useEffect, useState } from 'react'
import { createPortal } from 'react-dom'
import { CAST_BY_ID } from '../../engine/data/cast'
import { applyTalkChoice, talkOf, type TalkChoice } from '../../engine/career/talks'
import { mockRank } from '../../engine/career/week'
import { useGame, useGameState } from '../../stores/gameStore'
import { useOverlayRoot } from '../stage/overlayRoot'
import { Initials, Portrait } from '../components/Portrait'
import { playerPhoto } from '../components/playerPhoto'
import { genPhotoFor } from '../components/portraits'

export function TalkScene() {
  const state = useGameState()
  const mutate = useGame((s) => s.mutate)
  const root = useOverlayRoot()
  const [i, setI] = useState(0)
  const [reply, setReply] = useState<string | null>(null)
  const [chosen, setChosen] = useState(false)
  const c = state.career
  const pending = c?.talks[0]
  const talk = pending ? talkOf(pending.id, state) : null
  // 中身のない会話（古い id など）は捨てる
  useEffect(() => {
    if (pending && !talk) mutate((st) => void st.career!.talks.shift())
  }, [pending, talk, mutate])
  if (!c || !pending || !root || !talk) return null
  const p = state.players[c.playerId]
  const team = p.teamId >= 0 ? state.teams[p.teamId] : undefined
  const fill = (s: string) => {
    const rank = s.includes('{mock}') ? mockRank(state) : null
    const d = p.draft
    return s
      .replace(/\{name\}/g, p.short)
      .replace(/\{team\}/g, team?.name ?? '')
      .replace(/\{mock\}/g, rank ? `${rank} 位前後。${rank <= 14 ? 'ロッタリーの指名もありうるわ' : rank <= 30 ? '1 巡目の指名が見えている' : '2 巡目の指名になりそう'}` : '60 位の外。まだ呼ばれるのは難しそう')
      .replace(/\{draft\}/g, d ? `${state.teams[d.teamId].name}、${d.round} 巡目 ${d.pick} 位指名よ` : '')
      .replace(/\{combine\}/g, combineText())
      .replace(/\{summer\}/g, c.summer ?? '')
      .replace(/\{trade\}/g, c.lastTrade ?? '')
      .replace(/\{national\}/g, c.lastNational ?? '')
      .replace(/\{child\}/g, pending.id.startsWith('child:') ? pending.id.split(':')[1] : '')
  }
  const combineText = () => {
    const x = c.combine
    if (!x) return ''
    const grade = x.grade > 0 ? `上がったわ（+${x.grade}）` : x.grade < 0 ? `少し下がった（${x.grade}）` : '変わらず'
    return `垂直跳び ${x.vertical}cm・コート走 ${x.sprint.toFixed(2)} 秒・指高 ${x.reach}cm。評価は${grade}`
  }
  const finish = () => {
    mutate((st) => {
      const cc = st.career!
      const t = cc.talks.shift()
      if (t) cc.seen.push(t.id)
    })
    setI(0)
    setReply(null)
    setChosen(false)
  }
  const choose = (ch: TalkChoice) => {
    setChosen(true)
    setReply(ch.reply)
    mutate((st) => applyTalkChoice(st, pending.id, ch.effect))
  }
  const lines = talk.lines
  const line = lines[Math.min(i, lines.length - 1)]
  const atEnd = i >= lines.length - 1
  const parent = state.career?.lineage?.[state.career.lineage.length - 1]
  const speaker = line.who === 'me' ? null : line.who === 'parent' ? { name: `父・${parent?.name ?? ''}` } : CAST_BY_ID[line.who]
  const showChoices = atEnd && talk.choices && !chosen
  const next = () => {
    if (reply !== null) return finish()
    if (!atEnd) setI(i + 1)
    else if (!talk.choices) finish()
  }
  return createPortal(
    <div className="anim-fade absolute inset-0 z-50 flex flex-col justify-end bg-black/55" onClick={next}>
      <div className="safe-px safe-pb relative flex items-end gap-3 pb-3">
        {/* 話し手の写真 */}
        <div className="anim-rise relative h-[15rem] w-[11.5rem] shrink-0 overflow-hidden rounded-2xl border border-gold/40 shadow-2xl">
          {line.who === 'me' ? (
            <Portrait id={playerPhoto(state, p)} kind="bust" className="h-full w-full" position="50% 15%" fallback={<Initials name={p.short} className="h-full w-full" />} />
          ) : (
            <Portrait id={line.who === 'parent' ? (parent?.photo ? genPhotoFor(parent.photo, 40) : '') : line.who} kind="bust" className="h-full w-full" position="50% 15%" fallback={<Initials name={speaker?.name ?? '?'} className="h-full w-full" />} />
          )}
        </div>
        <div className="panel panel-solid min-w-0 flex-1 p-4" onClick={(e) => (showChoices ? e.stopPropagation() : undefined)}>
          <div className="mb-1 flex items-center gap-2">
            <span className="text-[0.75rem] font-bold text-ink-mute">{talk.title}</span>
            <span className="ml-auto text-[0.7rem] text-ink-mute">
              {Math.min(i + 1, lines.length)} / {lines.length}
            </span>
          </div>
          <div className="text-[0.9rem] font-black text-gold">{line.who === 'me' ? p.name : (speaker?.name ?? '')}</div>
          <p className="mt-1 min-h-[3.2rem] text-[1rem] leading-relaxed">{fill(reply ?? line.text)}</p>
          {showChoices ? (
            <div className="mt-2 flex gap-2">
              {talk.choices!.map((ch) => (
                <button
                  key={ch.label}
                  className="btn btn-gold btn-sm flex-1"
                  onClick={(e) => {
                    e.stopPropagation()
                    choose(ch)
                  }}
                >
                  {ch.label}
                </button>
              ))}
            </div>
          ) : (
            <div className="mt-1 text-right text-[0.72rem] text-ink-mute">タップで次へ ▶</div>
          )}
        </div>
      </div>
    </div>,
    root,
  )
}
