/**
 * シーズンのまとめ（クラブ経営）: 新しいシーズンのホームで 1 回だけ。晴れ舞台（Celebration）を閉じてから出す。
 */
import { createPortal } from 'react-dom'
import { useGame, useGameState } from '../../stores/gameStore'
import { useOverlayRoot } from '../stage/overlayRoot'
import { formatMoneyShort } from '../format'
import { momentOf } from './moment'

const yen = (man: number) => `${formatMoneyShort(Math.round(man))}円`

export function ClubSeasonReview() {
  const state = useGameState()
  const mutate = useGame((s) => s.mutate)
  const root = useOverlayRoot()
  const c = state.club
  const r = c?.review
  if (!c || !r || !root || r.season !== state.season - 1 || c.reviewSeen === r.season || c.gameOver || momentOf(state)) return null
  const close = () => mutate((st) => void (st.club!.reviewSeen = r.season))
  const net = r.income - r.expense
  const fansDiff = r.fans[1] - r.fans[0]
  return createPortal(
    <div className="anim-fade absolute inset-0 z-[55] flex items-center justify-center bg-black/60 p-4" onClick={close}>
      <div className="panel panel-solid panel-hero w-[36rem] max-w-full p-4" onClick={(e) => e.stopPropagation()}>
        <div className="text-[0.75rem] font-bold text-ink-mute">{state.startYear + r.season} 年度のまとめ</div>
        <div className="mt-0.5 flex items-baseline gap-2">
          <span className="text-[1.3rem] font-black">
            {r.league} {r.rank} 位
          </span>
          <span className="num text-[0.9rem] text-ink-dim">
            （{r.teams} チーム中）{r.w} 勝 {r.l} 敗
          </span>
        </div>
        {r.notes.length > 0 && <div className="mt-1 text-[0.85rem] font-black text-gold">{r.notes.join('・')}</div>}
        {r.owner && <div className="mt-1 rounded-lg bg-black/[0.04] px-2 py-1 text-[0.78rem] leading-snug">オーナー: {r.owner}</div>}
        <div className="num mt-2 grid grid-cols-3 gap-2 text-[0.8rem]">
          <div className="stat-chip px-2 py-1.5">
            収入 <b>{yen(r.income)}</b>
          </div>
          <div className="stat-chip px-2 py-1.5">
            支出 <b>{yen(r.expense)}</b>
          </div>
          <div className="stat-chip px-2 py-1.5">
            収支 <b className={net >= 0 ? 'text-good' : 'text-bad'}>{net >= 0 ? '+' : ''}{yen(net)}</b>
          </div>
          <div className="stat-chip col-span-3 px-2 py-1.5">
            ファン {r.fans[0].toLocaleString()} → <b>{r.fans[1].toLocaleString()} 人</b>
            <span className={`ml-1 ${fansDiff >= 0 ? 'text-good' : 'text-bad'}`}>
              （{fansDiff >= 0 ? '+' : ''}
              {fansDiff.toLocaleString()}）
            </span>
          </div>
        </div>
        {r.leaders.length > 0 && (
          <div className="mt-2">
            <div className="panel-head mb-0.5">チームの 1 位（1 試合あたり）</div>
            <div className="grid grid-cols-3 gap-2 text-[0.78rem]">
              {r.leaders.map((x) => (
                <div key={x.label} className="rounded-lg bg-black/[0.04] px-2 py-1">
                  <div className="text-[0.66rem] text-ink-dim">{x.label}</div>
                  <div className="truncate font-black">{x.name}</div>
                  <div className="num text-gold">{x.value}</div>
                </div>
              ))}
            </div>
          </div>
        )}
        {r.riser && (
          <div className="mt-2 text-[0.8rem]">
            いちばん伸びた選手: <b>{r.riser.name}</b>（総合 {r.riser.from} → <b className="text-good">{r.riser.to}</b>）
          </div>
        )}
        <button className="btn btn-gold mt-3 w-full" onClick={close}>
          新しいシーズンへ
        </button>
      </div>
    </div>,
    root,
  )
}
