/**
 * コートの描画（Canvas）。上から見下ろし。座標はメートル（engine/match/choreo.ts と同じ）。
 * 選手はチームの色の丸と背番号。ボールは高さで大きく、地面に影。ロゴは描かない。
 */
import type { RuleSet } from '../../engine'
import type { Beat } from '../../engine/match/types'
import { RIM_FROM_BASELINE } from '../../engine/match/choreo'

export interface DrawTeam {
  primary: string
  secondary: string
  numbers: number[]
}

export interface DrawState {
  /** 10 人の位置（x, y） */
  pos: number[]
  /** ボール [x, y, 高さ] */
  ball: [number, number, number]
  holder: number
  /** 強調する選手（lineup の添字。主人公など） */
  focus: number
  /** 背番号（10 人分） */
  numbers: number[]
}

/** 2 つの色が近いか（アウェイの色を替えるため） */
export function colorsClash(a: string, b: string): boolean {
  const rgb = (h: string) => [1, 3, 5].map((i) => parseInt(h.slice(i, i + 2), 16))
  if (!/^#[0-9a-f]{6}$/i.test(a) || !/^#[0-9a-f]{6}$/i.test(b)) return false
  const [x, y] = [rgb(a), rgb(b)]
  return Math.hypot(x[0] - y[0], x[1] - y[1], x[2] - y[2]) < 110
}

export class CourtRenderer {
  private ctx: CanvasRenderingContext2D
  private rules: RuleSet
  private home: DrawTeam
  private away: DrawTeam
  private scale = 1
  private ox = 0
  private oy = 0
  private floor: CanvasPattern | CanvasGradient | null = null

  constructor(canvas: HTMLCanvasElement, rules: RuleSet, home: DrawTeam, away: DrawTeam) {
    this.ctx = canvas.getContext('2d')!
    this.rules = rules
    this.home = home
    this.away = away
  }

  /** キャンバスの大きさ（CSS px と端末の倍率）に合わせる */
  resize(canvas: HTMLCanvasElement, w: number, h: number, dpr: number) {
    canvas.width = Math.round(w * dpr)
    canvas.height = Math.round(h * dpr)
    this.ctx.setTransform(dpr, 0, 0, dpr, 0, 0)
    const L = this.rules.courtLen
    const W = this.rules.courtWid
    this.scale = Math.min(w / (L + 1.6), h / (W + 1.2))
    this.ox = (w - L * this.scale) / 2
    this.oy = (h - W * this.scale) / 2
    this.floor = null
  }

  private X(x: number) {
    return this.ox + x * this.scale
  }
  private Y(y: number) {
    return this.oy + y * this.scale
  }

  draw(s: DrawState, cw: number, ch: number) {
    const c = this.ctx
    const L = this.rules.courtLen
    const W = this.rules.courtWid
    const k = this.scale
    c.clearRect(0, 0, cw, ch)
    // 場内の暗がり
    c.fillStyle = '#dfe5ec'
    c.fillRect(0, 0, cw, ch)
    // 床（木目）
    if (!this.floor) {
      const g = c.createLinearGradient(0, this.Y(0), 0, this.Y(W))
      g.addColorStop(0, '#b97b45')
      g.addColorStop(0.5, '#c98a50')
      g.addColorStop(1, '#a96c39')
      this.floor = g
    }
    c.fillStyle = this.floor
    c.fillRect(this.X(-0.6), this.Y(-0.5), (L + 1.2) * k, (W + 1.0) * k)
    c.strokeStyle = 'rgba(90, 50, 20, 0.18)'
    c.lineWidth = 1
    for (let y = 0; y <= W; y += 0.5) {
      c.beginPath()
      c.moveTo(this.X(-0.6), this.Y(y))
      c.lineTo(this.X(L + 0.6), this.Y(y))
      c.stroke()
    }
    // ペイントエリア（チームの色をうすく）
    const laneW = this.rules.name === 'NBA ルール' ? 4.88 : 4.9
    const laneL = 5.8
    for (const [right, team] of [
      [false, this.away],
      [true, this.home],
    ] as const) {
      const x0 = right ? L - laneL : 0
      c.fillStyle = team.primary + '55'
      c.fillRect(this.X(x0), this.Y(W / 2 - laneW / 2), laneL * k, laneW * k)
    }
    // ライン
    c.strokeStyle = 'rgba(255, 250, 240, 0.9)'
    c.lineWidth = Math.max(1.2, k * 0.06)
    c.strokeRect(this.X(0), this.Y(0), L * k, W * k)
    c.beginPath()
    c.moveTo(this.X(L / 2), this.Y(0))
    c.lineTo(this.X(L / 2), this.Y(W))
    c.stroke()
    c.beginPath()
    c.arc(this.X(L / 2), this.Y(W / 2), 1.8 * k, 0, Math.PI * 2)
    c.stroke()
    for (const right of [false, true]) {
      const dir = right ? -1 : 1
      const bx = right ? L : 0
      const rimX = bx + dir * RIM_FROM_BASELINE
      // ペイントとフリースローの円
      c.strokeRect(this.X(right ? L - laneL : 0), this.Y(W / 2 - laneW / 2), laneL * k, laneW * k)
      c.beginPath()
      c.arc(this.X(bx + dir * laneL), this.Y(W / 2), 1.8 * k, 0, Math.PI * 2)
      c.stroke()
      // 3P ライン（角はまっすぐ）
      const r = this.rules.threeDist
      const cy = this.rules.threeCorner
      const cornerLen = Math.sqrt(Math.max(0, r * r - cy * cy))
      c.beginPath()
      c.moveTo(this.X(bx), this.Y(W / 2 - cy))
      c.lineTo(this.X(rimX + dir * cornerLen), this.Y(W / 2 - cy))
      const a0 = Math.atan2(-cy, dir * cornerLen)
      const a1 = Math.atan2(cy, dir * cornerLen)
      c.arc(this.X(rimX), this.Y(W / 2), r * k, a0, a1, right)
      c.lineTo(this.X(bx), this.Y(W / 2 + cy))
      c.stroke()
      // 制限区域の円・ボード・リング
      c.beginPath()
      c.arc(this.X(rimX), this.Y(W / 2), 1.25 * k, right ? Math.PI / 2 : -Math.PI / 2, right ? (Math.PI * 3) / 2 : Math.PI / 2, false)
      c.stroke()
      c.save()
      c.strokeStyle = '#e5e7eb'
      c.lineWidth = Math.max(2, k * 0.1)
      c.beginPath()
      c.moveTo(this.X(bx + dir * 1.2), this.Y(W / 2 - 0.9))
      c.lineTo(this.X(bx + dir * 1.2), this.Y(W / 2 + 0.9))
      c.stroke()
      c.strokeStyle = '#ff7a1a'
      c.lineWidth = Math.max(1.5, k * 0.07)
      c.beginPath()
      c.arc(this.X(rimX), this.Y(W / 2), 0.23 * k, 0, Math.PI * 2)
      c.stroke()
      c.restore()
    }
    // 選手
    const r = Math.max(7, 0.42 * k)
    for (let i = 0; i < 10; i++) {
      const team = i < 5 ? this.home : this.away
      const x = this.X(s.pos[i * 2])
      const y = this.Y(s.pos[i * 2 + 1])
      c.fillStyle = 'rgba(0,0,0,0.35)'
      c.beginPath()
      c.ellipse(x + r * 0.15, y + r * 0.35, r, r * 0.7, 0, 0, Math.PI * 2)
      c.fill()
      if (i === s.focus) {
        c.fillStyle = 'rgba(255, 214, 90, 0.35)'
        c.beginPath()
        c.arc(x, y, r * 1.7, 0, Math.PI * 2)
        c.fill()
      }
      c.fillStyle = team.primary
      c.strokeStyle = i === s.focus ? '#ffd65a' : team.secondary
      c.lineWidth = i === s.focus ? Math.max(2.5, r * 0.28) : Math.max(1.5, r * 0.18)
      c.beginPath()
      c.arc(x, y, r, 0, Math.PI * 2)
      c.fill()
      c.stroke()
      c.fillStyle = team.secondary
      c.font = `900 ${Math.round(r * 1.05)}px system-ui, sans-serif`
      c.textAlign = 'center'
      c.textBaseline = 'middle'
      c.fillText(String(s.numbers[i] ?? ''), x, y + 0.5)
    }
    // ボール（高さで大きく、影は地面）
    const [bx, by, bh] = s.ball
    const br = Math.max(4, 0.2 * k) * (1 + Math.min(1.4, bh * 0.12))
    c.fillStyle = 'rgba(0,0,0,0.3)'
    c.beginPath()
    c.ellipse(this.X(bx), this.Y(by), br * 0.8, br * 0.5, 0, 0, Math.PI * 2)
    c.fill()
    const lift = bh * k * 0.18
    const g = c.createRadialGradient(this.X(bx) - br * 0.3, this.Y(by) - lift - br * 0.3, br * 0.2, this.X(bx), this.Y(by) - lift, br)
    g.addColorStop(0, '#ffb070')
    g.addColorStop(1, '#d9541a')
    c.fillStyle = g
    c.beginPath()
    c.arc(this.X(bx), this.Y(by) - lift, br, 0, Math.PI * 2)
    c.fill()
    c.strokeStyle = 'rgba(60, 20, 5, 0.7)'
    c.lineWidth = 1
    c.stroke()
  }
}

/** 2 つのコマの間を線形に補う */
export function lerpBeat(a: Beat, b: Beat, t: number): { pos: number[]; ball: [number, number, number]; holder: number } {
  const span = b.t - a.t
  const f = span <= 0 ? 1 : Math.max(0, Math.min(1, (t - a.t) / span))
  // 動きは少しなめらかに（はじめと終わりをゆっくり）
  const e = f * f * (3 - 2 * f)
  const pos = a.pos.map((v, i) => v + (b.pos[i] - v) * e)
  const ball: [number, number, number] = [a.ball[0] + (b.ball[0] - a.ball[0]) * f, a.ball[1] + (b.ball[1] - a.ball[1]) * f, a.ball[2] + (b.ball[2] - a.ball[2]) * f]
  // 持っている選手がいれば、ボールはその選手の手元（ドリブルで少し上下）
  const holder = f < 0.5 ? a.holder : b.holder
  if (a.holder >= 0 && a.holder === b.holder) {
    const i = a.holder
    ball[0] = pos[i * 2] + 0.3
    ball[1] = pos[i * 2 + 1] + 0.25
    ball[2] = 0.5 + Math.abs(Math.sin(t * 9)) * 0.6
  }
  return { pos, ball, holder }
}
